UPDATE exercises SET name = '3/4 シットアップ', instructions = '["床に横になり、足を固定します。足は膝のところで曲げる必要があります。", "手を頭の後ろまたは横に置きます。地面に背を向けた状態から始めます。これが開始位置になります。", "腰と背骨を曲げて胴体を膝に向かって持ち上げます。", "収縮の頂点では、胴体が地面に対して垂直になる必要があります。動きを逆にして、3/4 だけ下に進みます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = '3_4_Sit-Up';
UPDATE exercises SET name = '90/90 ハムストリング', instructions = '["仰向けになり、片足をまっすぐに伸ばします。", "もう一方の脚で、股関節と膝を90度に曲げます。必要に応じて、手で脚を支えても構いません。これが開始位置になります。", "脚を真っすぐに空中に伸ばし、頂上で少し止まります。脚を開始位置に戻します。", "10〜20回繰り返したら、もう一方の脚に切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = '90_90_Hamstring';
UPDATE exercises SET name = 'アブクランチマシン', instructions = '["軽い負荷を選択し、腹筋マシンに座り、付属のパッドの下に足を置き、上部のハンドルを握ります。付属のパッドの上に上腕三頭筋を置きながら、腕を 90 度の角度に曲げる必要があります。これが開始位置になります。", "At the same time, begin to lift the legs up as you crunch your upper torso.この動きをしながら息を吐きます。 Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "2 回目の停止の後、息を吸いながらゆっくりと開始位置に戻ります。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Ab_Crunch_Machine';
UPDATE exercises SET name = 'アブローラー', instructions = '["アブローラーを両手で持ち、床にひざまずきます。", "次に、腹筋ローラーを体の前の床に置き、両手と膝をすべて立てるようにします（ひざまずいて腕立て伏せの姿勢のように）。これが開始位置になります。", "腹筋ローラーをゆっくりと前方に回転させ、体をまっすぐな位置に伸ばします。ヒント: 体が床に触れないようにできるだけ深く降ります。動きのこの部分で息を吸います。", "伸ばした位置で一時停止した後、息を吐きながら開始位置に体を戻し始めます。ヒント: ゆっくりと腹筋を常に引き締めてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Ab_Roller';
UPDATE exercises SET name = '内転筋', instructions = '["片足をフォームロールの上にうつ伏せに寝ます。", "フォームロールが太ももの内側に接触するように脚を回転させます。許容できる範囲でフォームロールに体重を乗せます。", "太ももの内側の筋肉をリラックスさせながら、腰と膝の間のフォームの上を転がり、緊張した部分を 10 ～ 30 秒間保持します。もう一方の脚でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Adductor';
UPDATE exercises SET name = '内転筋/鼠径部', instructions = '["仰向けになり、足を天井に向かって上げます。", "パートナーに足または足首を抱いてもらいます。脚をできるだけ遠くに外転させます。これが開始位置になります。", "パートナーがそれを妨げている間、10 秒以上両足を締めてみましょう。", "次に、パートナーが足を押し広げながら、足の筋肉をリラックスさせ、心地よい範囲でストレッチします。過度のストレッチや怪我を防ぐために、ストレッチが適切であることを必ずパートナーに知らせてください。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Adductor_Groin';
UPDATE exercises SET name = '高度なケトルベル風車', instructions = '["片腕でケトルベルを頭上から拭き、押します。", "ケトルベルを常にロックアウトした状態で、ロックアウトされたケトルベルの方向にお尻を押し出します。動かしていない腕を背中の後ろに置き、ケトルベルを持った腕から足を45度の角度で外に向けます。", "できるだけ体を下げてください。", "少し停止して、動きを逆に開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Advanced_Kettlebell_Windmill';
UPDATE exercises SET name = 'エアバイク', instructions = '["床に平らになり、腰を地面に押しつけます。この演習では、手を頭の横に置く必要があります。ただし、実行するときに首に負担をかけないように注意してください。次に肩を上げてクランチポジションにします。", "膝を床と垂直になる位置まで上げ、下肢は床と平行にします。これが開始位置になります。", "同時に、右脚で前に蹴り、左脚の膝を引き寄せるサイクルペダルの動作をゆっくりと実行します。息を吐きながら、右肘を横にしゃがんで左膝に近づけます。", "息を吸いながら最初の姿勢に戻ります。", "脚を動かしながら反対側にクランチし、左肘を右膝に近づけて息を吐きます。", "両側で推奨される繰り返しがすべて完了するまで、この方法で交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Air_Bike';
UPDATE exercises SET name = '四つん這い大腿四頭筋ストレッチ', instructions = '["手と膝をついて始めて、足を床から持ち上げて手で足を支えます。", "手で足または足首を持ち、膝を完全に曲げた状態に保ち、大腿四頭筋と股関節屈筋を伸ばします。", "腰を伸ばすことに集中して、床に向かって突き出します。 10〜20秒間保持してから、側を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'All_Fours_Quad_Stretch';
UPDATE exercises SET name = 'オルタナティブハンマーカール', instructions = '["胴体を直立させ、両手にダンベルを腕の長さで持ちながら立ちます。肘は胴体の近くにある必要があります。", "手のひらは胴体の方を向くようにします。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、適切なウェイトを前方に曲げます。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。ヒント: 前腕のみを動かす必要があります。", "息を吸いながらゆっくりとダンベルを開始位置に戻し始めます。", "左手でも同じ動きを繰り返します。これは 1 回の繰り返しに相当します。", "この方法を交互に推奨回数繰り返し続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Alternate_Hammer_Curl';
UPDATE exercises SET name = 'オルタネイトヒールタッチャー', instructions = '["膝を曲げて床に横になり、足を約18〜24インチ離して床に置きます。腕は体の横に伸ばす必要があります。これが開始位置になります。", "胴体を前方にしゃがみ、右側に約 3 ～ 4 インチ上に上げ、収縮を 1 秒間保持しながら右かかとに触れます。この動きをしながら息を吐きます。", "次に、息を吸いながらゆっくりと開始位置に戻ります。", "次に、胴体を前方にしゃがんで左側約 3 ～ 4 インチ上に上げ、収縮を 1 秒間保持しながら左かかとに触れます。この動きをしながら息を吐き、息を吸いながら開始位置に戻ります。両方のかかとに触れたので、それが 1 回の繰り返しとみなされます。", "規定の繰り返しがすべて完了するまで、この方法で両側を交互に続けます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Alternate_Heel_Touchers';
UPDATE exercises SET name = '交互インクライン ダンベル カール', instructions = '["インクラインベンチに座り、両手にダンベルを腕の長さで持ちます。ヒント: 肘を胴体の近くに保ちます。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、適切なウェイトを前方に曲げます。このとき、手のひらが上を向くように手を回転させます。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。ヒント: 前腕のみを動かします。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。", "左手でも同じ動きを繰り返します。これは 1 回の繰り返しに相当します。", "この方法を交互に推奨回数繰り返し続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Alternate_Incline_Dumbbell_Curl';
UPDATE exercises SET name = '交互レッグ ダイアゴナル バウンド', instructions = '["片足をもう一方の足を少し前に出して快適な姿勢をとります。", "まず前脚で蹴り出し、着地する前に反対側の膝を前方にできるだけ高く上げます。各境界で両側までできるだけ多くの距離をカバーするようにしてください。", "地面に線を引いて左右の距離を測ると役立つ場合があります。", "もう一方の脚でも同じ手順を繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Alternate_Leg_Diagonal_Bound';
UPDATE exercises SET name = '交互ケーブルショルダープレス', instructions = '["ケーブルをタワーの底部に移動し、適切な重量を選択します。", "ケーブルを掴み、手のひらを前に向けて肩の高さで持ちます。これが開始位置になります。", "頭と胸を上げたまま、肘を通って片側を頭の真上に押します。", "上部で停止した後、開始位置に戻り、反対側で繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Alternating_Cable_Shoulder_Press';
UPDATE exercises SET name = '交互三角筋レイズ', instructions = '["立った姿勢で、ダンベルを体の横に持ちます。", "肘を軽く曲げたまま、スイングやごまかしを避けて、目の前のウェイトを肩の高さまで上げます。", "ウェイトを自分側に戻します。", "次の繰り返しでは、ウェイトを横方向に持ち上げて、肩の高さくらいまで横に持ち上げます。", "ウェイトを開始位置に戻し、正面と側面を交互に続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Alternating_Deltoid_Raise';
UPDATE exercises SET name = '交互フロアプレス', instructions = '["床に横になり、2 つのケトルベルを肩の横に置きます。", "1 つを胸の所定の位置に置き、次にもう 1 つを置き、手のひらを前に向けてハンドルのケトルベルを握ります。", "ケトルベルが胸の上に来るように両腕を伸ばします。ケトルベルを 1 つ下げて胸に近づけ、ロックアウトされたケトルベルの方向に手首を回します。", "ケトルベルを上げて反対側でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Alternating_Floor_Press';
UPDATE exercises SET name = '交互ハングクリーン', instructions = '["2つのケトルベルを足の間に置きます。開始位置に立つには、お尻を後ろに押し出し、まっすぐ前を見てください。", "一方のケトルベルを肩に当て、もう一方のケトルベルをぶら下げた状態で持ちます。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。", "掃除したケトルベルを吊り下げ位置に下げ、代わりのケトルベルを掃除します。繰り返す。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Alternating_Hang_Clean';
UPDATE exercises SET name = '交互ケトルベルプレス', instructions = '["2 つのケトルベルを肩まできれいにします。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。", "片方のケトルベルを肘から伸ばして頭の真上に押し、もう片方のケトルベルを動かさずに手のひらが前を向くように回転させます。", "押したケトルベルを開始位置まで下げ、すぐにもう一方の腕で押します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Alternating_Kettlebell_Press';
UPDATE exercises SET name = 'ケトルベル交互列', instructions = '["2つのケトルベルを足の前に置きます。膝を軽く曲げ、お尻をできるだけ突き出します。開始位置に入るためにかがむときに、両方のケトルベルのハンドルをつかみます。", "一方のケトルベルを床から引き離し、もう一方のケトルベルをつかみます。肘を曲げながら、作業側の肩甲骨を引き込み、ケトルベルを胃または胸郭に向かって引き寄せます。", "作業中の腕でケトルベルを下げ、もう一方の腕でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Alternating_Kettlebell_Row';
UPDATE exercises SET name = '交互のレネゲイド列', instructions = '["2 つのケトルベルを肩幅ほど離して床に置きます。腕立て伏せをしているかのように、つま先と手をついて体をまっすぐに伸ばした姿勢をとります。ケトルベルのハンドルを使って上半身を支えます。サポートのために足を幅広に配置する必要がある場合があります。", "一方のケトルベルを床に押し込み、もう一方のケトルベルを漕いで、肘を曲げながら作業側の肩甲骨を引っ込め、肘を自分の側に引き寄せます。", "次にケトルベルを床に下げ、反対側の手でケトルベルを持ち始めます。数回繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Alternating_Renegade_Row';
UPDATE exercises SET name = '足首サークル', instructions = '["スクワットラックなどの頑丈な物を使用して体を支えてください。", "右脚を空中に持ち上げ（床からわず​​か約2インチ）、足の親指で円を描くように動かします。大きな円を描いているふりをしてください。ヒント: 1 つの円は 1 回の繰り返しに相当します。動きを実行するときは、普通に呼吸してください。", "右足での作業が完了したら、左足で繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Ankle_Circles';
UPDATE exercises SET name = '足首を膝の上に置く', instructions = '["横たわった姿勢から、膝を曲げて足を床に置きます。", "片足の足首を反対側の膝の上に置きます。", "下の脚の太ももまたは膝をつかみ、両脚を胸に引き寄せます。首と肩をリラックスさせます。 10〜20秒間保持してから、側を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Ankle_On_The_Knee';
UPDATE exercises SET name = '前脛骨筋-SMR', instructions = '["足を曲げて床に座り始めます。", "マッスルローラーまたは麺棒を使用して、すねの外側の筋肉に圧力を加えます。膝のすぐ下から足首の上まで作業し、緊張した箇所で 10 ～ 30 秒間停止します。もう一方の脚でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Anterior_Tibialis-SMR';
UPDATE exercises SET name = '反重力プレス', instructions = '["インクラインベンチの頭の後ろの地面にバーを置きます。", "ベンチにうつ伏せになって横になります。プロネーショングリップでバーベルを床から持ち上げます。肘を曲げて逆カールを行い、バーを胸の近くに持ってきます。これが開始位置になります。", "まず、肘を伸ばしてバーベルを頭の前に押し出します。動作中は腕を地面と平行に保ちます。", "開始位置に戻り、これを繰り返してセットを完了します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Anti-Gravity_Press';
UPDATE exercises SET name = 'アームサークル', instructions = '["立ち上がって腕を横にまっすぐ伸ばします。腕は床と平行で、胴体に対して垂直（90度の角度）である必要があります。これが開始位置になります。", "伸ばした腕でゆっくりと直径約1フィートの円を描き始めます。動きを実行するときは、普通に呼吸してください。", "伸ばした腕の円運動を約10秒間続けます。次に、動きを逆にして、反対方向に進みます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Arm_Circles';
UPDATE exercises SET name = 'アーノルドダンベルプレス', instructions = '["背中をサポートしてエクササイズベンチに座り、手のひらを体に向けて肘を曲げ、胸の上くらいの高さで前に2つのダンベルを持ちます。ヒント: 腕は胴体の隣にある必要があります。開始位置は、ダンベル カールの収縮した部分のように見えるはずです。", "この動きを実行するには、手のひらが前を向くまで回転させながらダンベルを上げます。", "腕がまっすぐな位置で体の上に伸びるまでダンベルを持ち上げ続けます。動きのこの部分を実行するときに息を吐きます。", "トップでもう一度停止した後、手のひらを手前に回転させてダンベルを元の位置まで下げ始めます。ヒント: 左腕は反時計回りに回転し、右腕は時計回りに回転します。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Arnold_Dumbbell_Press';
UPDATE exercises SET name = '世界一周', instructions = '["平らなベンチに横になり、両手にダンベルを持ち、手のひらを天井に向けます。ヒント: 腕は床と平行で、太ももの横に置く必要があります。怪我を避けるために、肘を軽く曲げたままにしてください。これが開始位置になります。", "次に、ダンベルを最初の位置から頭の上に移動しながら、半円を描くように移動します。すべての動きは常に腕が床と平行な状態で行う必要があります。動きのこの部分を実行するときに息を吸います。", "息を吐きながら、動きを逆にして体重を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Around_The_Worlds';
UPDATE exercises SET name = 'アトラスストーントレーナー', instructions = '["このトレーナーは、石を手に入れることができない人にとってアトラス ストーンの筋力を高めるのに効果的で、通常はバーエンドや重いパイプで作られています。", "まず、バーに希望の重量を載せます。ウェイトにまたがり、腕を器具に巻き付け、腰を曲げます。", "まず、体重を膝を超えて腰まで引き上げます。体重が膝を越えたら、太ももの上に置き、胸にしっかりと抱きしめて座って、ラップすることができます。", "動きの最後に腰と膝を伸ばして体重をできるだけ高く上げます。連続して繰り返す場合は、体重を膝または地面に戻すことができます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Atlas_Stone_Trainer';
UPDATE exercises SET name = 'アトラスストーン', instructions = '["足の間にあるアトラスストーンから始めます。腰を曲げてアトラス ストーンに腕を垂直に巻き付け、石の下に指が入るようにします。多くの石には底に小さな平らな部分があり、石を持ちやすくなります。", "石を胴体に引き込み、足の後ろ半分を通って石を地面から引き抜きます。", "石が膝を通過したら、後ろ向きに座り、石を太ももの上に引っ張りながら周回します。", "低く座り、石を胸の高さまで持ち上げながら、握り方を変えて石の上に手を伸ばします。立ち、腰で走り抜けます。荷台までの距離を近づけ、石をできるだけ高く持ち上げるために腰を伸ばして後ろにもたれかかります。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Atlas_Stones';
UPDATE exercises SET name = 'アクスルデッドリフト', instructions = '["バーが足の中心に来るようにバーに近づきます。足は腰幅程度に開く必要があります。腰を曲げて肩幅でバーを握り、肩甲骨を突き出します。通常は、オーバー/アンダー グリップを使用します。", "足とグリップをセットしたら、大きく息を吸い、腰を下げ、すねがバーに触れるまで膝を曲げます。頭を前に向け、胸を張り、背中を反らせた状態を保ち、かかとから体重を上に移動し始めます。", "バーが膝を通過したら、積極的にバーを後ろに引き、肩甲骨を寄せながら腰を前方にバーに押し込みます。", "腰を曲げてバーを床に誘導してバーを下げます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Axle_Deadlift';
UPDATE exercises SET name = 'バックフライ - バンド付き', instructions = '["スクワットラックのような固定支柱の周りにバンドを巻きます。", "バンドのハンドルを掴んで後ろに立ち、バンドの張力を高めます。", "腕をまっすぐ前に伸ばして持ち上げます。ヒント: 腕はまっすぐにして床と平行にし、胴体に対して垂直にする必要があります。足は肩幅に広げて床にしっかりと置きます。これが開始位置になります。", "息を吐きながら、腕を横と後ろに動かします。腕を伸ばして床と平行に保ちます。腕が体の横に伸びるまで動きを続けます。", "一時停止した後、息を吸いながら元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Back_Flyes_-_With_Bands';
UPDATE exercises SET name = '後方ドラッグ', instructions = '["スレッドに希望の重量を積み込み、つかまるロープやストラップをスレッドに取り付けます。", "指定された距離だけ後方に移動してエクササイズを開始します。背中に寄りかかり、足を伸ばして短いステップでできるだけ早く移動します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Backward_Drag';
UPDATE exercises SET name = 'メディシンボール後方投げ', instructions = '["この演習はパートナーと一緒に行うのが最適です。パートナーがいない場合は、ボールを投げて回収したり、壁に向かって投げたりすることができます。", "パートナーの数メートル前に立って、両方とも同じ方向を向きます。足の間にボールを持ち始めます。", "しゃがみ、力強く方向を変えて完全に伸ばし、頭の上にボールをパートナーに投げます。", "その後、パートナーはボールをあなたのところに転がすことができます。必要な回数だけ繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Backward_Medicine_Ball_Throw';
UPDATE exercises SET name = 'バランスボード', instructions = '["バランスボードを前に置きます。", "その上に立ち、バランスをとってみてください。", "必要なだけバランスを保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Balance_Board';
UPDATE exercises SET name = 'ボールレッグカール', instructions = '["床に仰向けになり、足をボールの上に置きます。", "足を伸ばしたときに足首がボールの上に来るようにボールを置きます。これが開始位置になります。", "肩甲骨と足に体重をかけたまま、腰を地面から持ち上げます。", "膝を曲げてボールをできるだけ自分に近づけ、ハムストリングを収縮させます。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Ball_Leg_Curl';
UPDATE exercises SET name = 'バンドアシスト懸垂', instructions = '["懸垂バーの中心付近でバンドをチョークします。さまざまなバンドを使用して、さまざまなレベルの支援を提供できます。", "バンドの端を引き下げ、片方の膝を曲げて輪の中に入れ、滑り落ちないようにします。バーを中程度から幅広のグリップで握ります。これが開始位置になります。", "肘を曲げながら広背筋を収縮させて体を上に引き上げます。肘は体の横に寄せる必要があります。前に引いて、顎をバーの上にかけるようにします。揺れたり、けいれんしたりする動きは避けてください。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Band_Assisted_Pull-Up';
UPDATE exercises SET name = 'バンド「グッドモーニング」', instructions = '["41 インチのバンドを使用して、片方の端に立ち、足を少し広げます。腰を曲げてバンドの端を首の後ろで輪にします。これが開始位置になります。", "脚をまっすぐに保ち、腰を通って垂直に近い位置まで伸ばします。", "開始位置に戻るときに背中が丸まらないように注意してください。"]'::jsonb, category = 'パワーリフティング', equipment = 'チューブ・バンド' WHERE id = 'Band_Good_Morning';
UPDATE exercises SET name = 'バンドグッドモーニング (プルスルー)', instructions = '["バンドをポストに巻き付けます。少し離れたところに立って、反対側の端を首に巻き付けます。手でバンドを所定の位置に保持できます。", "腰を曲げて、お尻をできるだけ後ろに戻すことから始めます。背中を平らに保ち、前に約90度曲げます。膝はほんの少しだけ曲がっているはずです。", "開始位置に戻り、腰を動かして立った位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'チューブ・バンド' WHERE id = 'Band_Good_Morning_Pull_Through';
UPDATE exercises SET name = 'バンドヒップアダクション', instructions = '["頑丈な柱やその他のオブジェクトの周りにバンドを固定します。", "左側をポストに向けて立ち、右足をバンドに通して足首に巻きます。", "必要に応じてまっすぐに立ち、支柱をつかみます。これが開始位置になります。", "膝をまっすぐに保ち、右脚をできるだけ横に上げます。", "開始位置に戻り、必要な繰り返し数まで繰り返します。", "サイドを切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Band_Hip_Adductions';
UPDATE exercises SET name = 'バンドを引き離す', instructions = '["腕を前にまっすぐに伸ばし、両手でバンドを持ちます。", "逆に飛ぶ動作を実行して動きを開始し、手を横方向に体の側面に動かします。", "この動作を行うときは肘を伸ばしたままにし、バンドを胸に近づけます。エクササイズ中は必ず肩を後ろに引いてください。", "動作が完了したら一時停止し、制御下で開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Band_Pull_Apart';
UPDATE exercises SET name = 'バンドスカルクラッシャー', instructions = '["バンドをラックまたはベンチの底に固定します。バンドが頭と重なるようにベンチに横たわります。", "バンドを持ち、上腕が床と垂直になるように肘を上げます。肘を曲げた状態で、バンドが頭の上に来るようにします。これが開始位置になります。", "肘を通って腕を伸ばし、上腕を所定の位置に保ちます。動作の先頭で一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Band_Skull_Crusher';
UPDATE exercises SET name = 'バーベルアブロールアウト', instructions = '["このエクササイズでは、腕立て伏せの姿勢をとる必要がありますが、両手を床に持つ代わりに、オリンピック バーベル (片側に 5 ～ 10 ポンドの荷重) をつかみます。これが開始位置になります。", "背中にわずかなアーチを保ちながら、腰を持ち上げ、息を吐きながらバーベルを足の方に転がします。ヒント: この動きを行うときは、臀筋が上がってきて、腹筋を引き締め、常に背中の姿勢を維持する必要があります。また、動きの間中、腕は床に対して垂直に保つ必要があります。そうしないと、腹筋よりも肩と背中を鍛えることになります。", "上部で 2 回目の収縮を行った後、息を吸いながらゆっくりとバーベルを前方の開始位置まで転がし始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Ab_Rollout';
UPDATE exercises SET name = 'バーベルアブロールアウト - 膝上', instructions = '["両側に5〜10ポンドの荷重がかかったオリンピックバーベルを持ち、床にひざまずきます。", "次に、バーベルを体の前の床に置き、両手と膝をすべて立てます（ひざまずいて腕立て伏せの姿勢のように）。これが開始位置になります。", "バーベルをゆっくりと前方に回転させ、体をまっすぐな位置に伸ばします。ヒント: 体が床に触れないようにできるだけ深く降ります。動きのこの部分で息を吸います。", "伸ばした位置でもう一度停止した後、息を吐きながら開始位置に体を戻し始めます。ヒント: ゆっくりと腹筋を常に引き締めてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Ab_Rollout_-_On_Knees';
UPDATE exercises SET name = 'バーベルベンチプレス - ミディアムグリップ', instructions = '["平らなベンチに仰向けになります。中程度の幅のグリップ (前腕と上腕の間の動きの途中で 90 度の角度を作るグリップ) を使用して、バーをラックから持ち上げ、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "開始位置から息を吸い、バーが胸の中央に触れるまでゆっくりと下ろし始めます。", "少し停止した後、息を吐きながらバーを最初の位置に押し戻します。胸の筋肉を使ってバーを押すことに集中してください。腕をロックし、動きの一番上の収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 理想的には、ウェイトを下げるには、上げるよりも約 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Bench_Press_-_Medium_Grip';
UPDATE exercises SET name = 'バーベルカール', instructions = '["バーベルを肩幅の幅で握りながら、上体を直立させて立ちます。手のひらは前を向き、肘は胴体の近くにある必要があります。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方に曲げます。ヒント: 前腕のみを動かす必要があります。", "上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持し、上腕二頭筋を強く締めます。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Curl';
UPDATE exercises SET name = '傾斜に背を向けて寝そべるバーベルカール', instructions = '["インクラインベンチにもたれて横になり、両腕でバーベルを持ち、水平に垂れます。これが開始位置になります。", "上腕を固定したまま、上腕二頭筋を絞りながらウェイトをできるだけ高く丸めます。動きのこの部分を実行するときに息を吐きます。ヒント: 前腕のみを動かします。腕を振らないでください。", "2 回目の収縮の後、息を吸いながらゆっくりと開始位置に戻ります。ヒント: 必ず最後まで行ってください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Curls_Lying_Against_An_Incline';
UPDATE exercises SET name = 'バーベルデッドリフト', instructions = '["負荷がかかったバーベルの前に立ちます。", "背中をできるだけ真っ直ぐに保ちながら、膝を曲げ、前かがみになり、中程度（肩幅）のオーバーハンドグリップを使用してバーを握ります。これがエクササイズの開始位置になります。ヒント: このグリップでバーを握るのが難しい場合は、グリップを変えるか、リスト ストラップを使用してください。", "バーを持ちながら足で押してリフトを開始し、同時に息を吐きながら上体を直立位置に戻します。直立姿勢で胸を突き出し、肩甲骨を後ろに寄せて背中を収縮させます。軍隊の兵士たちが注意を払って立っているときにどのように見えるかを考えてください。", "膝を曲げて開始位置に戻り、同時に背中をまっすぐに保ちながら胴体を腰のところで前に傾けます。バー上のウェイトが床に触れると、開始位置に戻り、次の繰り返しを実行する準備が整います。", "プログラムで規定された回数を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Deadlift';
UPDATE exercises SET name = 'バーベルフルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、肩の高さのすぐ上のラックにバーを置きます。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中くらいのスタンスで脚を置き、つま先をわずかに尖らせます。常に頭を上げて、背中をまっすぐに保ちます。これが開始位置になります。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げて腰を後ろに向けてバーをゆっくりと下げ始めます。ハムストリングスがふくらはぎの上に来るまで下げ続けます。動きのこの部分を実行するときに息を吸います。", "息を吐きながらかかとまたは足の真ん中で床を押してバーを上げ始め、脚を伸ばし腰を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Full_Squat';
UPDATE exercises SET name = 'バーベルグルートブリッジ', instructions = '["地面に座り、足の上にバーベルを乗せて座り始めます。ファットバーを使用するか、バーにパッドを付けると、このエクササイズによって生じる不快感を大幅に軽減できます。腰の真上にバーが来るようにバーを転がし、床に平らに置きます。", "かかとで踏み込み、バーを通して腰を垂直に伸ばすことから動きを始めます。体重は背中上部と足のかかとで支える必要があります。", "できるだけ伸ばしてから、動きを逆にして開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Barbell_Glute_Bridge';
UPDATE exercises SET name = 'バーベルギロチンベンチプレス', instructions = '["中程度の幅のグリップ (前腕と上腕の間の動きの中間で 90 度の角度を作るグリップ) を使用して、バーをラックから持ち上げ、腕をロックした状態で首の上でまっすぐに保持します。これが開始位置になります。", "息を吸いながら、バーを首から約1インチの位置までゆっくりと下げます。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕をロックし、収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下がり始めます。下りには上りよりも少なくとも 2 倍の時間がかかるはずです。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Guillotine_Bench_Press';
UPDATE exercises SET name = 'バーベルハックスクワット', instructions = '["腕の長さでバーベルを後ろに持ち、足を肩幅に広げてまっすぐに立ちます。ヒント: 手のひらを後ろに向けて、肩幅くらいの幅でグリップするのが最適です。このエクササイズではリストラップを使用すると、より良いグリップを得ることができます。これが開始位置になります。", "頭と目を上げて背筋を伸ばしたまま、太ももの上部が床と平行になるまでしゃがみます。息を吸いながらゆっくりと下がっていきます。", "主に足のかかとで押して太ももを締め、息を吐きながら元に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Hack_Squat';
UPDATE exercises SET name = 'バーベルヒップスラスト', instructions = '["地面に座り、ベンチをすぐ後ろに置きます。荷重をかけたバーベルを足の上に置きます。ファットバーを使用するか、バーにパッドを付けると、このエクササイズによって生じる不快感を大幅に軽減できます。", "バーが腰の真上になるように回転させ、肩甲骨がベンチの上部近くに来るようにベンチにもたれかかります。", "足を通って動きを開始し、バーを通して腰を垂直に伸ばします。体重は肩甲骨と足で支える必要があります。できるだけ伸ばしてから、動きを逆にして開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Barbell_Hip_Thrust';
UPDATE exercises SET name = 'バーベル インクライン ベンチ プレス - ミディアム グリップ', instructions = '["インクラインベンチに仰向けになります。中程度の幅のグリップ (前腕と上腕の間の動きの途中で 90 度の角度を作るグリップ) を使用して、バーをラックから持ち上げ、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の上部にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕を縮めた位置に固定し、胸を圧迫し、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Incline_Bench_Press_-_Medium_Grip';
UPDATE exercises SET name = 'バーベルインクラインショルダーレイズ', instructions = '["インクラインベンチに仰向けになります。中程度の幅のグリップ (肩幅よりわずかに広いグリップ) を使用してバーをラックから持ち上げ、腕をまっすぐにして体の上にまっすぐ持ちます。これが開始位置になります。", "腕を真っすぐに伸ばしたまま、肩甲骨を前に出し、息を吐きながら肩をベンチから上げてバーを持ち上げます。", "息を吸いながらバーを開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Incline_Shoulder_Raise';
UPDATE exercises SET name = 'バーベルランジ', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、肩の高さのすぐ下のラックにバーを置きます。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、右脚を前に踏み出し、胴体を直立させてバランスを保ちながら腰からしゃがみます。下がりながら息を吸います。注: 膝関節に過度のストレスがかかるため、降りるときに膝がつま先よりも前に出ないようにしてください。リ＞", "主に足のかかとを使って押し上げ、息を吐きながら開始位置に戻ります。", "この動きを推奨回数繰り返した後、左脚で実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Lunge';
UPDATE exercises SET name = 'バーベル リア デルト ロー', instructions = '["幅広（肩幅より高い）でオーバーハンド（手のひらを体に向ける）グリップを使用してバーベルを持ちながら、真っ直ぐに立ちます。", "膝を軽く曲げ、背中の自然なアーチを保ちながら前かがみになります。バーを握るときは腕を前に垂らします。胴体が床と平行になったら、肘を外側に広げて体から遠ざけます。ヒント: 胴体と腕は文字「T」に似ている必要があります。これで、演習を開始する準備が整いました。", "上腕を胴体に対して垂直に保ちながら、後部の三角筋を締めて息を吐きながら、バーベルを胸の上部に向かって引き上げます。ヒント: 正しく実行すると、このエクササイズは逆のベンチ プレスに似たものになります。また、上腕二頭筋を使って作業を行うことは避けてください。三角筋後部をターゲットにすることに重点を置きます。アームはフックとしてのみ機能する必要があります。", "息を吸いながらゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Rear_Delt_Row';
UPDATE exercises SET name = 'ベンチからのバーベルロールアウト', instructions = '["負荷がかかったバーベルをベンチの端近くの地面に置きます。両足をベンチの上にひざまずき、バーベルを中程度から細めのグリップで握ります。これが開始位置になります。", "まず、腰を伸ばしてバーを前方にゆっくりと回転させます。ロールアウトするときは、肩を曲げてバーを頭の上で回転させます。動作中は腕を伸ばしたままにしてください。", "バーをできるだけ前方に移動したら、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Rollout_from_Bench';
UPDATE exercises SET name = 'バーベルシーテッドカーフレイズ', instructions = '["フラットベンチの前約12インチのところにブロックを置きます。", "ベンチに座り、足の指の付け根をブロックの上に置きます。", "誰かにバーベルを太ももの上、膝から約 3 インチ上に置いてもらい、そこに保持してもらいます。これが開始位置になります。", "ふくらはぎを締めて息を吐きながら、つま先をできるだけ高く上げます。", "2回目の収縮の後、ゆっくりと開始位置に戻ります。ヒント: 最大限の効果を得るには、ふくらはぎをできるだけ伸ばしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Seated_Calf_Raise';
UPDATE exercises SET name = 'バーベルショルダープレス', instructions = '["スクワットラックの背中をサポートしてベンチに座ります。頭のすぐ上の高さにバーベルを置きます。回内グリップ（手のひらを前に向ける）でバーベルを握ります。", "適切なグリップ幅でバーベルを持ち上げたら、腕をロックしてバーベルを頭の上まで持ち上げます。肩の高さくらいで頭の少し前に持ちます。これが開始位置です。", "息を吸いながらバーを肩までゆっくりと下げます。", "息を吐きながらバーを元の位置まで持ち上げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Shoulder_Press';
UPDATE exercises SET name = 'バーベルをすくめて', instructions = '["足を肩幅に広げてまっすぐに立ち、回内グリップ（手のひらを太ももに向ける）を使用して両手でバーベルを前に持ちます。ヒント: 手の幅は肩幅より少し広くする必要があります。このエクササイズではリストラップを使用すると、より良いグリップを得ることができます。これが開始位置になります。", "息を吐きながら肩をできるだけ高く上げ、収縮を1秒間保持します。ヒント: 上腕二頭筋を使ってバーベルを持ち上げようとしないでください。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Shrug';
UPDATE exercises SET name = '背中の後ろでバーベルをすくめる', instructions = '["足を肩幅に広げてまっすぐに立ち、両手を後ろに回内グリップ（手のひらを後ろに向ける）でバーベルを持ちます。ヒント: 手の幅は肩幅より少し広くする必要があります。このエクササイズでは、グリップ力を高めるためにリストラップを使用できます。これが開始位置になります。", "息を吐きながら肩をできるだけ高く上げ、収縮を1秒間保持します。ヒント: 上腕二頭筋を使ってバーベルを持ち上げようとしないでください。腕は常に伸ばしたままにしておく必要があります。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Shrug_Behind_The_Back';
UPDATE exercises SET name = 'バーベルサイドベンド', instructions = '["肩の後ろ（首の少し下）にバーベルを置き、まっすぐに立ちます。足は肩幅に開く必要があります。これが開始位置になります。", "背中をまっすぐにして頭を上げた状態で、腰だけをできるだけ右に曲げます。息を吸いながら横に曲がります。次に、少しの間保持し、息を吐きながら開始位置に戻ります。ヒント: 体の残りの部分は動かさないでください。", "次に、代わりに左に曲げてこの動きを繰り返します。しばらく待って、開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Side_Bend';
UPDATE exercises SET name = 'バーベルサイドスプリットスクワット', instructions = '["肩の後ろ（首の少し下）にバーベルを置き、まっすぐに立ちます。両足を広く開き、リード側の足を横に傾けます。これが開始位置になります。", "反対側の脚を少しだけ曲げたまま、リード脚の膝と股関節を曲げて、斜めの足の側に向かって体を下げます。息を吸いながら体を下げます。", "リード脚の股関節と膝を伸ばして開始位置に戻ります。この動きをしながら息を吐きます。", "推奨回数を繰り返した後、反対側の脚でも同じ動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Side_Split_Squat';
UPDATE exercises SET name = 'バーベルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、ラック上のバ​​ーを肩の高さのすぐ下に設定します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。常に頭を上げて、背中もまっすぐに保ちます。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝と腰を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら足のかかとで床を押してバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Squat';
UPDATE exercises SET name = 'ベンチに向かってバーベルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、フラットベンチまたはボックスを後ろに置きます。フラットベンチは、腰を後ろに置き、深く打つことを教えるために使用されます。", "", "次に、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げて腰を後ろに置き、ゆっくりとバーを下げ始めます。後ろのベンチに少し触れるまで下り続けます。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら足のかかとで床を押してバーを上げ始め、足を伸ばして腰を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Squat_To_A_Bench';
UPDATE exercises SET name = 'バーベルステップアップ', instructions = '["バーベルを肩の後ろ（首の少し下）に置き、まっすぐに立ち、高い台（フラットベンチの後ろでスポットするために使用される台など）の後ろで直立します。これが開始位置です。", "右足を高いプラットフォームに置きます。右脚の股関節と膝を伸ばして台を踏みます。主にかかとを使って体の残りの部分を持ち上げ、左足の足も台の上に置きます。息を吐きながら、上に上がるために必要な力を出します。", "息を吸いながら右脚の股関節と膝を曲げて左脚を踏み込みます。右足を左足の隣に置き、元の立ち位置に戻ります。", "右脚で推奨回数だけ繰り返し、次に左脚で実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Step_Ups';
UPDATE exercises SET name = 'バーベルウォーキングランジ', instructions = '["足を肩幅に開き、バーベルを背中の上に置いて立ち始めます。", "片足で前に踏み出し、膝を曲げて腰を落とします。後ろの膝が地面に着きそうになるまで降ります。姿勢は直立を保ち、前膝が前足の上にあるようにしてください。", "前足のかかとを通って両膝を伸ばし、体を元に戻します。", "後ろ足で前に踏み出し、反対側の足で突進を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Barbell_Walking_Lunge';
UPDATE exercises SET name = 'バトルロープ', instructions = '["この演習では、15 ～ 20 フィート離れた中央に太いロープを固定する必要があります。ロープの前に立って、腕を体の横に伸ばし、両手で端を持ちます。これが開始位置になります。", "できるだけ早く片腕を肩の高さまで素早く上げて動きを開始します。", "腕を開始位置まで下げたら、反対側を上げます。", "左右の腕を交互に動かし、できるだけ速くロープを上下に動かし続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Battling_Ropes';
UPDATE exercises SET name = 'ベア クロール スレッド ドラッグ', instructions = '["ハーネスまたは緩めのウェイト ベルトを着用し、そりから反対側を向くようにチェーンを背中に取り付けます。手が地面につくようにかがみます。背中を平らにし、膝を曲げる必要があります。これが開始位置です。", "左右交互に脚を動かし始めます。手を使ってバランスを保ち、引っ張るのを助けます。一定の距離を移動するときは、背中を平らに保つようにしてください。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Bear_Crawl_Sled_Drags';
UPDATE exercises SET name = '頭の後ろの胸のストレッチ', instructions = '["パートナーを後ろに置いて、床に直立して座ります。", "手を後ろに置き、肘をできるだけ後ろに押します。パートナーは肘を抱えてください。これが開始位置になります。", "10 秒以上、手を頭の後ろに置いたまま、肘をゆっくりと前に引いてみてください。パートナーは肘が動かないようにする必要があります。", "次に、筋肉をリラックスさせ、パートナーに心地よい範囲までゆっくりと肘​​を後ろに引いてもらいます。過度のストレッチや怪我を防ぐために、ストレッチが適切であることを必ずパートナーに知らせてください。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Behind_Head_Chest_Stretch';
UPDATE exercises SET name = 'ベンチディップス', instructions = '["このエクササイズでは、背中の後ろにベンチを置く必要があります。ベンチを体に対して垂直にし、ベンチから目をそらしながら、手を完全に伸ばしてベンチの端を持ち、肩幅に開きます。脚は前方に伸ばし、腰のところで曲げて胴体に対して垂直になります。これが開始位置になります。", "息を吸いながら肘を曲げ、上腕と前腕の間の角度が 90 度よりわずかに小さい位置まで体を下げます。ヒント: 動作中は肘をできるだけ近づけてください。前腕は常に下を向いている必要があります。", "上腕三頭筋を使って上半身を再び起こし、開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Bench_Dips';
UPDATE exercises SET name = 'ベンチジャンプ', instructions = '["あなたの前1〜2フィートのボックスまたはベンチから始めます。足を肩幅に開いて立ちます。これが開始位置になります。", "ジャンプの準備として短いスクワットを実行します。腕を後ろに振ります。", "この位置からリバウンドし、腰、膝、足首を伸ばしてできるだけ高くジャンプします。腕を前と上に振ります。", "ベンチを飛び越え、膝を曲げて着地し、脚で衝撃を吸収します。", "振り返って反対方向を向いてから、ベンチを飛び越えて戻ります。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Bench_Jump';
UPDATE exercises SET name = 'ベンチプレス - パワーリフティング', instructions = '["ベンチに横になり、可能であれば頭をバーよりも高くすることから始めます。足を下に押し込み、背中を反らせます。バーを使って体重を支え、肩をベンチから持ち上げて引き込み、肩甲骨を寄せます。足を使ってトラップをベンチに打ち込みます。動きの間中、このタイトな体の位置を維持してください。", "グリップの幅がどんなに広くても、バーのリングをカバーする必要があります。肩を伸ばさずにバーをラックから引き出します。バーを握って引き離すことに集中してください。", "バーを胸の下部または胃の上部まで下げます。バー、手首、肘は常に一直線上にある必要があります。", "バーベルが胴体に触れたところで一時停止し、できるだけ力を入れてバーを押し上げます。肘はロックアウトされるまで押し込む必要があります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Bench_Press_-_Powerlifting';
UPDATE exercises SET name = 'ベンチプレス - バンド付き', instructions = '["フラットベンチを使用して、頭に最も近いベンチの脚の下にバンドを固定します。", "バンドがしっかりと固定されたら、両方のハンドルを掴んでベンチに横になります。", "腕を伸ばしてバンドのハンドルを肩の幅で前に持ちます。", "肩幅になったら、手首を前方に回転させ、手のひらが外側を向くようにします。これが開始位置になります。", "肘が90度の角度になるまでハンドルをゆっくりと下げます。常に完全に制御してください。", "息を吐きながら、胸筋を使ってハンドルを引き上げます。腕を縮めた位置に固定し、胸を圧迫し、1秒間保持してからゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Bench_Press_-_With_Bands';
UPDATE exercises SET name = 'チェーン付きベンチプレス', instructions = '["リーダーチェーンを調整して、希望の長さに短くします。チェーンをバーのスリーブに置きます。", "ベンチに横たわって、可能であれば頭をバーの上に出します。足を下に押し込み、背中を反らせます。バーを使って体重を支え、肩をベンチから持ち上げて引き込み、肩甲骨を寄せます。足を使ってトラップをベンチに打ち込みます。動きの間中、このタイトな体の位置を維持してください。グリップの幅がどんなに広くても、バーのリングをカバーする必要があります。", "肩を伸ばさずにバーをラックから引き出します。バーを握って引き離すことに集中してください。バーを胸の下部または胃の上部まで下げます。バー、手首、肘は常に一直線上にある必要があります。", "バーベルが胴体に触れたところで一時停止し、できるだけ力を入れてバーを押し上げます。肘はロックアウトされるまで押し込む必要があります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Bench_Press_with_Chains';
UPDATE exercises SET name = 'ベンチスプリント', instructions = '["片足をベンチまたはボックスの上に置き、かかとを端に近づけて地面に立ちます。", "足をベンチの上に置き、腰と膝を通って押し出します。", "反対側の足をボックスの上に着地し、もう一方の足を開始位置に戻します。", "片足からもう一方の足へ交互に続けてセットを完了します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Bench_Sprint';
UPDATE exercises SET name = 'ベントアーム バーベル プルオーバー', instructions = '["フラットベンチに横になり、ショルダーグリップ幅を使用してバーベルを持ちます。", "腕を曲げてバーを胸の上でまっすぐに持ちます。これが開始位置になります。", "腕を曲げた位置に保ちながら、胸が伸びるのを感じるまで息を吸いながら、頭の後ろで弧を描くようにゆっくりと体重を下げます。", "この時点で、ウェイトを下げた弧を使ってバーベルを開始位置に戻し、息を吐きながらこの動作を実行します。", "最初の位置にウェイトを 1 秒間保持し、この動作を規定の回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Bent-Arm_Barbell_Pullover';
UPDATE exercises SET name = 'ベントアーム ダンベル プルオーバー', instructions = '["ダンベルを平らなベンチの上に立って置きます。", "ダンベルがベンチの上部にしっかりと配置されていることを確認し、肩だけを表面に置き、ベンチに対して垂直に寝ます（十字架を作るように胴体を横切るようにします）。腰をベンチの下に置き、足を曲げて足を床にしっかりとつけます。頭もベンチから外れるだろう。", "ダンベルを両手で持ち、腕を曲げて胸の上でまっすぐに持ちます。両手のひらでダンベルの側面の一方の下側を押す必要があります。これが開始位置になります。注意: このエクササイズに使用するダンベルがしっかりと固定されていることを常に確認してください。プレートが緩んだ状態でダンベルを使用すると、ダンベルがバラバラになって顔に落ちる可能性があります。", "腕を曲げた状態で腕を固定したまま、胸が伸びるのを感じるまで息を吸いながら、頭の後ろで弧を描くようにゆっくりと体重を下げます。", "この時点で、ウェイトを下げた円弧を使ってダンベルを開始位置に戻し、息を吐きながらこの動きを行います。", "最初の位置にウェイトを 1 秒間保持し、この動作を規定の回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Bent-Arm_Dumbbell_Pullover';
UPDATE exercises SET name = 'ベントニーヒップレイズ', instructions = '["床に平らに寝て、腕を体の横に置きます。", "次に、膝を約 75 度の角度で曲げ、足を床から約 2 インチ持ち上げます。", "腹筋下部を使用して、脚を 75 度の角度で曲げた状態を維持しながら、膝を手前に引き寄せます。骨盤を後ろに回転させて腰を床から持ち上げるまで、この動きを続けます。動きのこの部分を実行するときに息を吐きます。ヒント: 動きの最後には、膝が胸の上に来るようになります。", "動作の頂点で腹筋を 1 秒間締め、息を吸いながらゆっくりと開始位置に戻ります。 ヒント: 常に制御された動作を維持してください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Bent-Knee_Hip_Raise';
UPDATE exercises SET name = 'ベント・オーバー・バーベル・ロウ', instructions = '["回内グリップでバーベルを持ち（手のひらを下に向けて）、膝をわずかに曲げ、腰を曲げて胴体を前に出し、同時に背中を床とほぼ平行になるまでまっすぐに保ちます。ヒント: 頭を上げたままにしてください。腕が床と胴体に対して垂直になるように、バーベルは体の正面にぶら下がります。これが開始位置です。", "次に、胴体を動かさないようにしながら、息を吐きながらバーベルを手前に持ち上げます。肘を体の近くに保ち、体重を支えるために前腕のみを使用します。一番上の収縮した位置で、背中の筋肉を締めて、少しの間保持します。", "次に、息を吸いながらゆっくりとバーベルを下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Bent_Over_Barbell_Row';
UPDATE exercises SET name = 'ベンチに頭をつけてベントオーバーダンベルリアデルトレイズ', instructions = '["両手にダンベルを持ち、インクラインベンチを前に置き、まっすぐに立ちます。", "背中をまっすぐに保ち、背中の自然なアーチを維持しながら、額が前のベンチに触れるまで前かがみになります。腕を地面に対して垂直になるように前に垂らします。手のひらは向かい合って、胴体は床と平行になるようにします。これが開始位置になります。", "胴体を前方に動かさず、腕をまっすぐにして肘をわずかに曲げ、両腕が床と平行になるまでダンベルを真横に持ち上げます。ウェイトを持ち上げるときに息を吐きます。注意: 胴体を振ったり、腕を横ではなく後ろに戻したりしないでください。", "上部で 1 秒間収縮した後、ダンベルをゆっくりと下げて開始位置に戻します。", "推奨回数を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench';
UPDATE exercises SET name = 'ベントオーバー ロープーリー側 横方向', instructions = '["重りを選択し、右手で低プーリーのハンドルを持ちます。", "胴体が床とほぼ平行になるまで腰を曲げます。足を軽く曲げ、左手を左太ももの下に置きます。右腕は肩から前にぶら下げ、肘を少し曲げます。これが開始位置になります。", "肘をわずかに曲げた状態で右腕を床と平行になり、右耳と一直線になるまで横に上げます。このステップを実行するときに息を吐きます。", "息を吸いながらゆっくりと体重を下げて元の位置に戻します。", "推奨回数だけ繰り返し、もう一方の腕でも同じ動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Bent_Over_Low-Pulley_Side_Lateral';
UPDATE exercises SET name = '片腕を曲げてロングバーロー', instructions = '["オリンピックバーベルの片方の端に体重をかけます。バーベルのもう一方の端を 2 つの壁の隅に置くようにしてください。または、バーベルが後ろに滑らないように重い物を地面に置きます。", "胴体が床とできるだけ平行になるまで前屈し、膝をわずかに曲げたままにします。", "次に、体重がかかる側のプレートのすぐ後ろで片腕でバーをつかみ、もう一方の手を膝の上に置きます。これが開始位置になります。", "プレートが胸の下部に触れるまで、肘を内側に入れてバーを真っすぐに引き上げます（背中への刺激を最大限に高めるため）。ウエイトを持ち上げながら背中の筋肉を締め、動作の頂点で 1 秒間保持します。体重を持ち上げるときに息を吐きます。ヒント: 胴体を振らないようにしてください。腕だけを動かせばいいのです。", "ゆっくりとバーを開始位置まで下げ、広背筋をしっかりと伸ばします。ヒント: プレートが床に触れないようにしてください。最適な可動範囲を確保するには、大きなプレート (35 ～ 45 ポンドのプレートなど) ではなく、小さなプレート (25 ポンドのプレート) を使用することをお勧めします。", "推奨回数繰り返し、腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Bent_Over_One-Arm_Long_Bar_Row';
UPDATE exercises SET name = 'ベントオーバーツーアームロングバーロー', instructions = '["オリンピックバーベルの片方の端に体重をかけます。バーベルのもう一方の端を 2 つの壁の隅に置くようにしてください。または、バーベルが後ろに滑らないように重い物を地面に置きます。", "胴体が床とできるだけ平行になるまで前屈し、膝をわずかに曲げたままにします。", "次に、体重がかかる側のプレートのすぐ後ろで両腕でバーをつかみ、もう一方の手を膝の上に置きます。これが開始位置になります。", "プレートが胸の下部に触れるまで、肘を内側に入れてバーを真っすぐに引き上げます（背中への刺激を最大限に高めるため）。ウエイトを持ち上げながら背中の筋肉を締め、動作の頂点で 1 秒間保持します。体重を持ち上げるときに息を吐きます。ヒント: あぶみまたはダブルハンドルのケーブルアタッチメントをバーの端の下に引っ掛けて使用します。", "ゆっくりとバーを開始位置まで下げ、広背筋をしっかりと伸ばします。ヒント: プレートが床に触れないようにしてください。最適な可動範囲を確保するには、大きなプレート (35 ～ 45 ポンドのプレートなど) ではなく、小さなプレート (25 ポンドのプレート) を使用することをお勧めします。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Bent_Over_Two-Arm_Long_Bar_Row';
UPDATE exercises SET name = 'ベントオーバー 2 ダンベルロー', instructions = '["両手にダンベルを持ち（手のひらを胴体に向けます）、膝をわずかに曲げ、腰を曲げて胴体を前に出します。曲げるときは、床とほぼ平行になるまで背中を真っ直ぐに保つようにしてください。ヒント: 頭を上げたままにしてください。腕が床と胴体に対して垂直になるように、ウェイトは体の正面にぶら下がっている必要があります。これが開始位置です。", "胴体を静止させたまま、肘を体に近づけたまま（息を吐きながら）ダンベルを体の横に持ち上げます（ウェイトを保持する以外に前腕に力を加えないでください）。一番上の収縮した位置で、背中の筋肉を締めて 1 秒間保持します。", "息を吸いながら、ゆっくりとウェイトを再び開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Bent_Over_Two-Dumbbell_Row';
UPDATE exercises SET name = '手のひらを内側にして 2 つのダンベルを並べて腰をかがめる', instructions = '["両手にダンベルを持ち（手のひらを向かい合わせに）、膝をわずかに曲げ、腰を曲げて胴体を前に出します。同時に、背中が床とほぼ平行になるまでまっすぐに保ちます。ヒント: 頭を上げたままにしてください。腕が床と胴体に対して垂直になるように、ウェイトは体の正面にぶら下がっている必要があります。これが開始位置です。", "胴体を動かさないようにしながら、息を吐きながらダンベルを体の横に持ち上げ、肩甲骨を寄せます。一番上の収縮した位置で、背中の筋肉を締めて 1 秒間保持します。", "息を吸いながら、ゆっくりとウェイトを再び開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Bent_Over_Two-Dumbbell_Row_With_Palms_In';
UPDATE exercises SET name = 'ベントプレス', instructions = '["ケトルベルを肩まできれいにします。ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。そうすることで手首が回転するはずです。これが開始位置になります。", "ケトルベルの反対側に体を傾け始め、ケトルベルから目を離したまま、空いている手で地面に触れることができるまで続けます。このとき、腕を地面に対して垂直に保ちながら、肘を通って垂直にウェイトを押します。", "ケトルベルを頭の上に置き、直立姿勢に戻ります。ケトルベルを肩に戻し、必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Bent_Press';
UPDATE exercises SET name = '自転車', instructions = '["まず、バイクに座り、シートを自分の高さに合わせて調整します。"]'::jsonb, category = '有酸素運動', equipment = 'その他' WHERE id = 'Bicycling';
UPDATE exercises SET name = '自転車、ステーショナリー', instructions = '["まず、バイクに座り、シートを自分の高さに合わせて調整します。", "メニューから希望のオプションを選択します。電源を入れるにはペダルを踏み始める必要がある場合があります。手動設定を使用することも、使用するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。負荷のレベルはトレーニング中に変更できます。ハンドルを使用して心拍数を監視し、適切な強度を維持することができます。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Bicycling_Stationary';
UPDATE exercises SET name = 'ボードプレス', instructions = '["ベンチに横になり、可能であれば頭をバーよりも高くすることから始めます。 2x6 で作られた 1 ～ 5 枚のボードをネジで留めて、トレーニング パートナーやバンドで所定の位置に保持したり、シャツの下に押し込んだりすることができます。", "足を下に押し込み、背中を反らせます。バーを使って体重を支え、肩をベンチから持ち上げて引き込み、肩甲骨を寄せます。足を使ってトラップをベンチに打ち込みます。動きの間中、このタイトな体の位置を維持してください。", "標準的なベンチグリップでも、上腕三頭筋に集中するために肩幅でも構いません。肩を伸ばさずにバーをラックから引き出します。バー、手首、肘は常に一直線上にある必要があります。バーを握って引き離すことに集中してください。", "バーをボードまで下げ、できるだけ力を入れてバーを押し上げます。肘はロックアウトされるまで押し込む必要があります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Board_Press';
UPDATE exercises SET name = 'ボディアップ', instructions = '["地面にプランクの姿勢を想定します。つま先と前腕で体重を支え、胴体をまっすぐに保つ必要があります。前腕は肩幅に開く必要があります。これが開始位置になります。", "手のひらを地面にしっかりと押し付け、肘を通って体を地面から持ち上げます。動きを実行するときは、胴体を堅く保ちます。", "肘を曲げながら、前腕をゆっくりと地面に下げます。", "繰り返す。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Body-Up';
UPDATE exercises SET name = 'ボディトライセッププレス', instructions = '["バーを胸の高さのラックに置きます。", "立った状態で、肩幅くらいの幅でバーを握り、1～2ヤード後退し、足を揃えて腕を伸ばしてバーにもたれかかります。これが開始位置になります。", "肘を曲げてバーに向かって体を下げることから始めます。", "一時停止し、肘を伸ばして動きを逆にします。", "肩にチェーンを追加して自重から進めます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Body_Tricep_Press';
UPDATE exercises SET name = '自重フライ', instructions = '["均等に荷重がかかる 2 つの EZ バーを地面に並べて配置します。回転できることを確認してください。", "腕を伸ばして体をまっすぐにして、つま先と手で体重を支え、バーの上で腕立て伏せの姿勢をとります。", "バーに手を置きます。これが開始位置になります。", "ゆっくりと制御された動きを使用して、手を体の正中線から遠ざけ、バーを回転させます。動作のこの部分で息を吸います。", "バーをできるだけ離した後、バーを一緒に引いて開始位置に戻ります。この動きをしながら息を吐きます。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Bodyweight_Flyes';
UPDATE exercises SET name = '体重ミッドロー', instructions = '["まず、手のひらを自分の反対側に向けて懸垂器具を中程度から幅広のグリップで握ります。ぶら下がった姿勢から、膝を胸に押し込み、後ろにもたれて両足を懸垂器具の体側に掛けます。これが開始位置になります。", "腕を真っすぐに伸ばした状態から始めて、肘を曲げて肩甲骨を引いて、足が懸垂器具に接触するまで体を起こします。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Bodyweight_Mid_Row';
UPDATE exercises SET name = '自重スクワット', instructions = '["足を肩幅に開いて立ちます。手を頭の後ろに置いても構いません。これが開始位置になります。", "腰を後ろに向けて座り、膝と腰を曲げることから動きを始めます。", "可能であれば最大限の深さまで下げ続け、開始位置に戻るまですぐに動きを逆にします。しゃがむときは、頭と胸を上げたまま、膝を外側に押し出します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Bodyweight_Squat';
UPDATE exercises SET name = '自重ウォーキングランジ', instructions = '["足を肩幅に開き、手を腰に当てて立ち始めます。", "片足で前に踏み出し、膝を曲げて腰を落とします。後ろの膝が地面に着きそうになるまで降ります。姿勢は直立を保ち、前膝が前足の上にあるようにしてください。", "前足のかかとを通って両膝を伸ばし、体を元に戻します。", "後ろ足で前に踏み出し、反対側の足で突進を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Bodyweight_Walking_Lunge';
UPDATE exercises SET name = 'サイドベンド付きボスボールケーブルクランチ', instructions = '["標準ハンドルをケーブル マシンの各アームに接続し、最も下の位置に配置します。", "ボスボールをつかみ、ケーブルマシンの正面中央に置きます。", "ボスボールの上に横になり、背中のくびれをボールの周りに反らせます。お尻は床に触れずに床に近づける必要があります。", "両手を後ろに伸ばして各ケーブルのハンドルを掴みます。", "足をワイドスタンスに置き、腕を膝の間にまっすぐ前に伸ばします。手は膝の高さにある必要があります。", "腕を真っすぐに保ち、ケーブルの上向きの角度と一直線上に置きます。腕を下げたり曲げたりせずに、クシュクシュとした動きで胴体を上げます。", "腕で正しい位置を維持します。ボスボールの周りで背中をアーチ状にし、腹部を伸ばした状態で、ゆっくりと元の位置に戻ります。", "失敗するまで同じ一連の動作を繰り返します。", "失敗に達したら、腹筋を引き締めて胴体をプランクの位置に上げ、背中がボスボールから離れるようにします。", "腕を体の横に下ろします。まっすぐにしておいてください。交互にサイドベンドを始めます。かかとに手を伸ばしてください！この仕上げの動きは腹斜筋に焦点を当てます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Bosu_Ball_Cable_Crunch_With_Side_Bends';
UPDATE exercises SET name = 'ハングポジションからのボトムアップクリーン', instructions = '["ケトルベルを片手に直立してエクササイズを開始します。", "ケトルベルを勢いよく後ろに振り、次に勢いよく動きを逆にします。ケトルベルのハンドルをできるだけ強く握り、ケトルベルを肩まで持ち上げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Bottoms-Up_Clean_From_The_Hang_Position';
UPDATE exercises SET name = 'ボトムズアップ', instructions = '["地面に仰向けになることから始めます。脚はまっすぐにし、腕は体の横に置きます。これが開始位置になります。", "この動きを行うには、腰と膝を曲げて膝を胸に引き寄せます。次に、足を真上に伸ばし、地面に対して垂直になります。骨盤を回転させて持ち上げ、臀部を床から持ち上げます。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Bottoms_Up';
UPDATE exercises SET name = 'ボックスジャンプ（複数回答）', instructions = '["腕の長さほど離れたボックスまたはプラットフォームに向かってリラックスした姿勢をとります。腕は体の横に下げ、脚をわずかに曲げます。", "腕を使って最初のバーストを補助し、上方と前方にジャンプし、同時に足で箱またはプラットフォームの上に着地します。", "すぐにドロップするかジャンプして元の開始場所に戻ります。その後、このシーケンスを繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Box_Jump_Multiple_Response';
UPDATE exercises SET name = 'ボックススキップ', instructions = '["いくつかの箱を約8フィートの間隔で並べる必要があります。", "片足をもう一方の脚から少し後ろに向けて最初のボックスに向かい始めます。", "後ろ足を蹴り出し、腰でできるだけ高さを上げようとします。", "ボックスに着地したらすぐに、もう一方の脚を前方と上方に動かし、高さと距離を稼ぎ、ボックスから飛び降ります。最初のボックスに着地したのと同じ足で、最初の 2 つのボックスの間に着地します。", "次に、次のボックスに進み、繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Box_Skip';
UPDATE exercises SET name = 'ボックススクワット', instructions = '["ボックススクワットを使用すると、必要な深さまでしゃがみ、スクワットの動きで爆発的な強さを養うことができます。後ろの適切な高さにボックスを備えたパワーラックから始めます。通常、パラレルスクワットに達するボックスの高さを目指しますが、必要に応じてそれより高くまたは低くトレーニングすることもできます。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足の幅を広くして背中、臀筋、内転筋、ハムストリングスに重点を置くか、足を近づけて大腿四頭筋をより発達させます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。ボックスの上に座るまで、腰を落として座ります。理想的には、すねが地面に対して垂直である必要があります。ボックスに到達したら一時停止し、股関節屈筋を緩めます。決して箱から跳ね返らないようにしてください。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きをリードしながらボックスから上向きにドライブします。頭からつま先まで締め付けを維持しながら、上向きに進みます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Box_Squat';
UPDATE exercises SET name = 'バンド付きボックススクワット', instructions = '["後ろの適切な高さにボックスを備えたパワーラックから始めます。適切な張力がかかるように、バンドを袖にセットし、バンドペグ、ラック、またはダンベルのいずれかに固定します。ダンベルを使用する場合は、ダンベルが動かないように固定してください。また、使用しているダンベルが、使用しているバンドに対して十分な重さであることを確認してください。ダンベルを固定するために追加のプレートを使用できます。さらに張力が必要な場合は、床のベースを広げるか、バンドをチョークします。通常、パラレルスクワットに達するボックスの高さを目指しますが、必要に応じてそれより高くまたは低くトレーニングすることもできます。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足の幅を広くして背中、臀筋、内転筋、ハムストリングスに重点を置くか、足を近づけて大腿四頭筋をより発達させます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。ボックスの上に座るまで、腰を落として座ります。理想的には、すねが地面に対して垂直である必要があります。ボックスに到達したら一時停止し、股関節屈筋を緩めます。決して箱から跳ね返らないようにしてください。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きをリードしながらボックスから上向きにドライブします。頭からつま先まで締め付けを維持しながら、上向きに進みます。バーベルをラックに戻す際は注意してください。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Box_Squat_with_Bands';
UPDATE exercises SET name = 'チェーン付きボックススクワット', instructions = '["後ろの適切な高さにボックスを備えたパワーラックから始めます。通常、パラレルスクワットに達するボックスの高さを目指しますが、必要に応じてそれより高くまたは低くトレーニングすることもできます。", "チェーンをセットアップするには、まずリーダー チェーンをバーのスリーブに巻き付けます。重いチェーンはスナップフックを使用して取り付けてください。ムーブメントの上部でいくつかのリンクが床に残るようにリードチェーンの長さを調整します。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足の幅を広くして背中、臀筋、内転筋、ハムストリングスに重点を置くか、足を近づけて大腿四頭筋をより発達させます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。ボックスの上に座るまで、腰を落として座ります。理想的には、すねが地面に対して垂直である必要があります。ボックスに到達したら一時停止し、股関節屈筋を緩めます。決して箱から跳ね返らないようにしてください。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きをリードしながらボックスから上向きにドライブします。頭からつま先まで締め付けを維持しながら、上向きに進みます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Box_Squat_with_Chains';
UPDATE exercises SET name = '上腕筋-SMR', instructions = '["上腕をフォームローラーに当てて横向きに寝ます。上腕は体とほぼ一直線になり、上腕二頭筋の外側がフォームローラーに押し付けられるようにする必要があります。", "腰を床から持ち上げて、腕と足で体重を支えます。 10〜30秒間保持してから、側を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Brachialis-SMR';
UPDATE exercises SET name = 'ブラッドフォード/ロッキープレス', instructions = '["肩の高さにバーを置き、回内グリップ（手のひらを前に向ける）でミリタリー プレス ベンチに座ります。ヒント: グリップは肩幅より広くし、バーベルを下げるときに前腕と上腕の間に 90 度の角度を作る必要があります。これが開始位置です。", "正しいグリップでバーベルを持ち上げたら、腕をロックしてバーベルを頭の上まで持ち上げます。", "次に、息を吸いながらゆっくりとバーを頭の後ろまで下げます。", "息を吐きながらバーを元の位置まで持ち上げます。", "息を吸いながら、ゆっくりとバーを開始位置まで下げます。これが１回の繰り返しです。", "推奨回数の繰り返しが完了するまで、この方法を交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Bradford_Rocky_Presses';
UPDATE exercises SET name = 'バストアップ', instructions = '["腕立て伏せの姿勢を開始しますが、肘を地面に置き、前腕の上に置きます。腕は90度の角度で曲げる必要があります。", "背中を完全に真っすぐに保つのではなく、少し外側に背中を反らせます。", "臀筋を天井に向かって上げ、腹筋をしっかり締めて胸郭と腰の間の距離を縮めます。その結果、高いブリッジの位置に到達することになります。動きのこの部分を実行するときに息を吐きます。", "息を吸いながら、開始位置までゆっくりと腰を下げます。 ヒント: 背中が下に垂れないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Butt-Ups';
UPDATE exercises SET name = 'バットリフト（ブリッジ）', instructions = '["床に仰向けになり、両手を体の横に置き、膝を曲げます。足は肩幅くらいに置く必要があります。これが開始位置になります。", "主にかかとで押し、背中をまっすぐに保ちながら腰を床から持ち上げます。動作のこの部分を実行するときに息を吐き、上部を 1 秒間保持します。", "息を吸いながらゆっくりと元の姿勢に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Butt_Lift_Bridge';
UPDATE exercises SET name = '蝶', instructions = '["背中をパッドの上に平らにしてマシンに座ります。", "ハンドルを握ります。ヒント: 上腕は床と平行に置く必要があります。それに応じて機械を調整してください。これが開始位置になります。", "胸の中央を圧迫しながら、ハンドルをゆっくりと押します。動作のこの部分で息を吐き、収縮を 1 秒間保持します。", "胸の筋肉が完全に伸びるまで、息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Butterfly';
UPDATE exercises SET name = 'ケーブルチェストプレス', instructions = '["適切な重量に調整し、ハンドルを握りながら座ります。上腕は体に対して約 45 度にし、頭と胸を上げます。肘は約90度まで曲げる必要があります。これが開始位置になります。", "まず、肘を通って伸ばし、ハンドルをまっすぐ前に押します。この動きを実行するときは、肩甲骨を引いたままにしてください。", "完全に伸ばした状態で一時停止した後、ケーブルの張力を維持しながら開始位置に戻ります。", "この動きは、背中をパッドから離した状態、傾斜または傾斜した状態、または両手を交互に行って実行することもできます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Chest_Press';
UPDATE exercises SET name = 'ケーブルクロスオーバー', instructions = '["開始位置に入るには、プーリーを高い位置 (頭の上) に置き、使用する負荷を選択し、両手でプーリーを持ちます。", "両腕を前で引き寄せながら、両方の滑車の間の想像上の直線の前に進みます。胴体は腰から少し前に曲がっている必要があります。これが開始位置になります。", "上腕二頭筋の腱へのストレスを防ぐために肘を軽く曲げ、胸が伸びると感じるまで広い弧を描くように腕を横に（両側を真っすぐに）伸ばします。動きのこの部分を実行するときに息を吸います。ヒント: 動きの間中、腕と胴体は静止したままにしておく必要があることに注意してください。動きは肩関節でのみ行われます。", "息を吐きながら腕を開始位置に戻します。ウェイトを下げるときに使用したのと同じ円弧の動きを使用してください。", "開始位置で 1 秒間保持し、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Crossover';
UPDATE exercises SET name = 'ケーブルクランチ', instructions = '["ロープが取り付けられた高い滑車の下にひざまずきます。", "ケーブル ロープのアタッチメントをつかみ、手が顔の横に来るまでロープを下げます。", "腰をわずかに曲げて、体重で腰を過度に伸ばすようにします。これが開始位置になります。", "腰を動かさず、肘が太腿の中央に向かって移動するように腹筋を収縮させながら腰を曲げます。動きのこの部分を実行するときに息を吐き、収縮を 1 秒間保持します。", "息を吸いながらゆっくりと元の位置に戻ります。ヒント: 動作中は腹筋に一定の緊張を保つようにしてください。また、作業の衝撃が腰にかかるほど重い重量を選択しないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Crunch';
UPDATE exercises SET name = 'ケーブルデッドリフト', instructions = '["ケーブルをタワーの底部に移動し、適切な重量を選択します。支柱の間に直接立ちます。", "まず、ハンドルに届くまでしゃがみ、腰と膝を曲げます。", "それらをつかんだら、上昇を開始します。かかとを使って運転すると、手を体の横に下げたまま腰と膝を伸ばすことができます。動作中は頭と胸を上げたままにしてください。", "完全な立位に達したら、開始位置に戻り、これを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Deadlifts';
UPDATE exercises SET name = 'ケーブル ハンマー カール - ロープ アタッチメント', instructions = '["ロープアタッチメントを低いプーリーに取り付け、機械から約 12 インチ離れたところに向かって立ちます。", "ニュートラル（手のひらを内側にする）グリップでロープを握り、背中と胴体の自然なアーチを動かさないようにまっすぐに立ちます。", "肘を体の横に置き、動作中ずっと肘を動かさないようにします。ヒント: 前腕のみを動かす必要があります。上腕ではありません。これが開始位置になります。", "上腕二頭筋を使って、息を吐きながら上腕二頭筋が前腕に触れるまで腕を引き上げます。ヒント: 肘を内側に置き、上腕を動かさないようにしてください。", "上腕二頭筋を締めて 1 秒間収縮した後、ゆっくりと体重を元の位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Hammer_Curls_-_Rope_Attachment';
UPDATE exercises SET name = 'ケーブル股関節内転', instructions = '["低い滑車の前に前を向いて立ち、片方の足を滑車の横に置き、もう片方の足を滑車から遠ざけます。", "足首カフをケーブルに取り付け、プーリーの隣にある脚の足首にも取り付けます。", "次に、広いスタンスでスタックから出て離れ、プーリー システムのバーを握ります。", "足首カフのない方の足（遠い方の足）に立ち、カフのある方の脚を低いプーリーに向かって引っ張ります。これが開始位置になります。", "次に、太ももの内側を使って股関節を外転させ、足首カフを遠い方の脚の前に置いて脚を動かすという動きを実行します。動きのこの部分で息を吐きます。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数繰り返した後、反対側の脚でも同じ動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Hip_Adduction';
UPDATE exercises SET name = 'ケーブル傾斜プッシュダウン', instructions = '["まっすぐなバーが取り付けられたハイプーリーマシンの反対側を向いた傾斜ベンチに横たわります。", "肩の幅で回内（オーバーハンド、手のひらを下にする）グリップでストレートバーアタッチメントを頭上に握り、腕を前に伸ばします。バーは太もも上部から約2インチ離れた位置にある必要があります。これが開始位置になります。", "上腕を動かさないようにしたまま、バーが頭上にまっすぐ届くまで腕を半円を描くように後ろに持ち上げます。動きのこの部分で息を吸います。", "広背筋を使ってゆっくりと開始位置に戻り、開始位置に到達したら収縮を維持します。この動きを実行している間、息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Incline_Pushdown';
UPDATE exercises SET name = 'ケーブルインクライントライセプスエクステンション', instructions = '["まっすぐなバーが取り付けられたハイプーリーマシンの反対側を向いた傾斜ベンチに横たわります。", "回内（オーバーハンド、手のひらを下にする）狭いグリップ（肩幅より狭い）でストレートバーアタッチメントを頭上で握り、肘を体の横に押し込みます。床から測ると上腕は約 25 度の角度になるはずです。", "上腕を固定したまま、上腕三頭筋を曲げながら腕を伸ばします。動きのこの部分で息を吐き、収縮を 1 秒間保持します。", "ゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Incline_Triceps_Extension';
UPDATE exercises SET name = 'ケーブル内部回転', instructions = '["低い滑車の横に横向きに座り（脚を前に伸ばすか交差させて）、ケーブルに最も近い腕で片手でケーブル アタッチメントを握ります。ヒント: 滑車の高さを調整できる場合は、代わりに平らなベンチを使用して座ることもできます。", "肘を90度に曲げ、腕をプーリーの方向に向けて、肘を体の横に置きます。これが開始位置になります。", "前腕が腹筋を横切るまで肩を内側に回転させて、片手ケーブル アタッチメントを体に向かって引っ張ります。想像上の半円を作成します。ヒント: 前腕は常に胴体に対して垂直である必要があります。", "ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返した後、次の腕で同じ動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Internal_Rotation';
UPDATE exercises SET name = 'ケーブルアイアンクロス', instructions = '["まずプーリーを高い位置に移動し、使用する抵抗を選択し、ハンドルを両手に持ちます。", "両方の滑車の間に直接立ち、腕を体の横に伸ばします。頭と胸を上げて腕を「T」字にします。これが開始位置になります。", "肘を伸ばしたまま、腕を体の横にまっすぐ引きます。", "収縮のピークで一時停止した後、腕を開始位置に戻します。", "規定の回数だけ動きを続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Iron_Cross';
UPDATE exercises SET name = 'ケーブル柔道フリップ', instructions = '["ロープアタッチメントをタワーに接続し、ケーブルをプーリーの最下位位置に移動します。ワイドスタンスでケーブルに体を向けて立ち、両手でロープを掴みます。", "柔道のフリップをするように、ロープを肩にかけながら、体を滑車から遠ざけるようにひねります。", "両足の間で体重を移動しながら、前方にひねったりしゃがんだりして、ケーブルを下に引っ張ります。", "開始位置に戻り、失敗するまで繰り返します。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Judo_Flip';
UPDATE exercises SET name = 'ケーブルライディングトライセプスエクステンション', instructions = '["平らなベンチに横になり、細いオーバーハンド グリップで低いプーリーのストレート バー アタッチメントを握ります。ヒント: これを行う最も簡単な方法は、横になっているときに誰かにバーを渡してもらうことです。", "腕を伸ばした状態で、バーを胴体の上に置きます。腕と胴体が 90 度の角度になるようにします。これが開始位置になります。", "上腕を動かさず、肘を内側に置いたまま、肘を曲げてバーを下げます。バーが額に軽く触れるまで下げます。動きのこの部分を実行するときに息を吸います。", "バーを持ち上げて開始位置に戻すときに、上腕三頭筋を曲げます。動きのこの部分を実行するときに息を吐きます。", "収縮した位置で 1 秒間保持し、推奨される回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Lying_Triceps_Extension';
UPDATE exercises SET name = 'ケーブルワンアームトライセップエクステンション', instructions = '["右手で、回外した (手のひらを上に向けた) グリップを使用して、ハイケーブル プーリーに取り付けられた 1 つのハンドルを握ります。ウェイトスタックの真正面に立つ必要があります。", "次に、ハンドルを下に引いて、上腕と肘が体の側面に固定されるようにします。上腕と前腕は鋭角 (90 度未満) を形成する必要があります。もう一方の腕を腰に添え、片方の脚を前に、もう片方の脚を後ろに置くと、バランスが良くなります。これが開始位置になります。", "上腕三頭筋を収縮させながら、腕が真っ直ぐになるまでシングル ハンドル アタッチメントを体の横に下げます。この動きをしながら息を吐きます。ヒント: 前腕のみを動かします。上腕は常に動かさないようにしてください。", "上腕三頭筋を締めて、この収縮した位置で 1 秒間保持します。", "ハンドルをゆっくりと開始位置に戻します。", "推奨回数繰り返した後、もう一方の腕でも同じ動きを行います。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_One_Arm_Tricep_Extension';
UPDATE exercises SET name = 'ケーブルプリーチャーカール', instructions = '["プーリーマシンの前約 2 フィートの位置に説教者用ベンチを置きます。", "ロープーリーにストレートバーを取り付けます。", "肘と上腕をベンチパッドの上にしっかりと乗せてプリーチャーベンチに座り、誰かに低いプーリーからバーを手渡してもらいます。", "バーをつかみ、プリーチャーベンチパッドの上で腕を完全に伸ばします。これが開始位置になります。", "次に、肩に向かって体重を積み上げ始め、動きの一番上で上腕二頭筋を強く締めます。この動作を実行しながら息を吐きます。また、上部で 1 秒間押し続けます。", "次に、ゆっくりとウェイトを開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Preacher_Curl';
UPDATE exercises SET name = 'ケーブルリアデルトフライ', instructions = '["プーリーを適切な高さに調整し、重量を調整します。滑車は頭の上にあるはずです。", "右手で左のプーリーをつかみ、左手で右のプーリーをつかみ、前で交差させます。これが開始位置になります。", "腕を後ろと外側に動かして動きを開始し、動きを実行する間は腕をまっすぐに保ちます。", "ハンドルを開始位置に戻す前に、動作の終わりで一時停止してください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Rear_Delt_Fly';
UPDATE exercises SET name = 'ケーブルリバースクランチ', instructions = '["アンクルストラップアタッチメントを低滑車ケーブルに接続し、その前の床にマットを置きます。", "プーリーに足を向けて座り、ケーブルを足首に取り付けます。", "横になって足を上げ、膝を90度の角度で曲げます。足とケーブルが一直線に並んでいる必要があります。そうでない場合は、適切になるまでプーリーを上下に調整します。", "手を頭の後ろに置き、膝を胴体の内側に引き寄せ、腰を床から持ち上げます。", "少し停止し、ゆっくりと制御された方法で腰を落とし、脚を最初の 90 度の角度に戻します。安静時の姿勢でも腹筋に緊張が残っているはずです。", "失敗するまで同じ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Reverse_Crunch';
UPDATE exercises SET name = 'ケーブル ロープ オーバーヘッド上腕三頭筋エクステンション', instructions = '["滑車機の下側の滑車にロープを取り付けます。", "両手でロープをつかみ、ニュートラルグリップ（手のひらを向かい合う）を使用して、両手を頭の真上に置いて腕を伸ばします。肘は頭の近くに置き、腕は床に対して垂直にし、指の関節を天井に向けます。これが開始位置になります。", "上腕を動かさないようにしながら、頭の後ろでロープをゆっくりと下げます。この動きをしながら息を吸い、上腕三頭筋が完全に伸びたところで一時停止します。", "息を吐きながら上腕三頭筋を曲げて開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Rope_Overhead_Triceps_Extension';
UPDATE exercises SET name = 'ケーブル ロープ後部デルト列', instructions = '["背中に座ってケーブルローを行う場合と同じ位置に、低いプーリーローステーションに座ります。", "滑車にロープを取り付け、オーバーハンドグリップで握ります。腕は床と平行に伸ばし、肘を広げます。", "腰を直立させたまま、膝を軽く曲げるように腰を後ろにスライドさせます。これが開始位置になります。", "肘を上げて横に伸ばしたまま、ケーブルのアタッチメントを胸の上部、首のすぐ下に向かって引っ張ります。息を吐きながら、肘が背中の少し後ろに移動するまでこの動きを続けます。ヒント: 動作中は上腕を水平、胴体に対して垂直、床と平行に保ちます。", "腕を伸ばし、肩を前に伸ばした最初の位置に戻ります。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Rope_Rear-Delt_Rows';
UPDATE exercises SET name = 'ケーブル・ロシアン・ツイスト', instructions = '["標準のハンドルアタッチメントを接続し、ケーブルを中間プーリーの位置に配置します。", "ケーブルに対して垂直なバランスボールの上に寝て、片手でハンドルを握ります。ケーブルに重りの張力がかかる状態で、滑車から腕の長さほど離れた位置にいる必要があります。", "ハンドルを両手で持ち、腕を胸の上に完全に伸ばします。手はプーリーの真上にある必要があります。そうでない場合は、適切になるまでプーリーを上下に調整します。", "腰を高くし、腹筋を引き締めてください。胴体を滑車から離れる方向に回転させて、4 分の 1 回転させます。体は頭から膝まで平らでなければなりません。", "少しの間停止し、ゆっくりと制御された方法で開始位置にリセットします。静止位置でもケーブルに側面張力が残っているはずです。", "失敗するまで同じ動作を繰り返します。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Russian_Twists';
UPDATE exercises SET name = 'ケーブルシーテッドクランチ', instructions = '["背中を高い滑車に向けて平らなベンチに座ります。", "ケーブル ロープのアタッチメントを両手で（手のひらを向かい合わせて）つかみ、両手を両肩にしっかりと置きます。ヒント: 体重によって腰がわずかに過伸展するようにしてください。これが開始位置になります。", "腰を固定した状態で、肘が腰に向かって移動するように腰を曲げます。このステップを実行するときに息を吐きます。", "息を吸いながら、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Seated_Crunch';
UPDATE exercises SET name = 'ケーブル シート ラテラル レイズ', instructions = '["向かい合った 2 つの低い滑車の中央に立ち、自分のすぐ後ろに平らなベンチを置きます (自分に対して垂直になるように、ベンチの狭い端が後ろになるようにします)。各プーリーに使用する重量を選択します。", "次に、後ろのフラットベンチの端に足を膝の前に置いて座ります。", "背中を平らに保ちながら前かがみになり、胴体を太ももの上に置きます。", "プーリーに取り付けられたシングル ハンドルを誰かに渡してもらいます。体重を選択したら、左手で左のプーリーをつかみ、左手で右のプーリーをつかみます。滑車は膝の下を通過し、手のひらを向かい合わせにして肘をわずかに曲げて腕を伸ばします。これが開始位置になります。", "腕を動かさないようにしながら、上腕が床と平行になり、肩の高さになるまで横に上げます。この動きの実行中に息を吐き、収縮を 1 秒間保持します。", "息を吸いながら、ゆっくりと腕を開始位置まで下げます。", "推奨回数だけ繰り返します。ヒント: 運動中は上腕を胴体に対して垂直に保ち、肘の位置を固定 (10 度から 30 度の角度) に保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Seated_Lateral_Raise';
UPDATE exercises SET name = 'ケーブルショルダープレス', instructions = '["ケーブルをタワーの底部に移動し、適切な重量を選択します。", "支柱の間に直接立ちます。ケーブルを掴み、手のひらを前に向けて肩の高さで持ちます。これが開始位置になります。", "頭と胸を上げたまま、肘を通ってハンドルを頭の真上に押します。", "一番上で停止した後、開始位置に戻り、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Shoulder_Press';
UPDATE exercises SET name = 'ケーブルシュラッグ', instructions = '["低いプーリーに取り付けられたケーブル バー アタッチメントを、肩幅またはわずかに広いオーバーハンド (手のひらを下に向けた) グリップで握ります。", "腕を前に伸ばしてバーを持ち、滑車の近くで直立して立ちます。これが開始位置になります。", "息を吐きながら肩をできるだけ高く上げてバーを持ち上げます。上部の収縮を 1 秒間保持します。ヒント: 腕は常に伸ばしたままにしてください。バーを持ち上げるために上腕二頭筋を使用しないでください。肩だけが上下に動くはずです。", "バーを元の位置に下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Shrugs';
UPDATE exercises SET name = 'ケーブルリストカール', instructions = '["まず、ストレートバーが取り付けられた低滑車ケーブルの前にフラットベンチを置きます。", "腕を使って肩の幅までの狭い回外グリップでケーブル バーを掴み (手のひらを上に)、前腕が太ももの上部に当たるように持ち上げます。手首は膝のすぐ上に垂れ下がっている必要があります。", "まずは手首を上に丸めて息を吐きます。収縮を 1 秒間続けます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。", "このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Cable_Wrist_Curl';
UPDATE exercises SET name = 'カーフマシンショルダーシュラッグ', instructions = '["ショルダーパッドが肩の上に来るようにカーフマシンの上に体を置きます。胴体はまっすぐで、腕は体の横で通常通りに伸ばします。これが開始位置になります。", "息を吐きながら肩を耳に向かって上げ、収縮を 1 秒間保持します。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Calf-Machine_Shoulder_Shrug';
UPDATE exercises SET name = 'カーフプレス', instructions = '["開始位置で脚がわずかに曲がるだけになるようにシートを調整します。足の指の付け根がプラットフォームにしっかりと乗っている必要があります。", "適切な重さを選択し、ハンドルを握ります。これが開始位置になります。", "膝を伸ばして脚をまっすぐにし、重りをかろうじて持ち上げます。足首は完全に屈曲し、つま先は上を向いている必要があります。足の指の付け根をできるだけ下に押して動きを実行します。", "少し停止した後、動きを逆にして繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Calf_Press';
UPDATE exercises SET name = 'レッグプレスマシンでカーフプレス', instructions = '["レッグプレスマシンを使用して、マシンに座り、中程度（肩幅）の足のスタンスで両脚を体の正面のプラットフォームに置きます。", "加重プラットフォームを所定の位置に保持している安全バーを下げ、膝を固定せずに足が完全に前に伸びるまでプラットフォームを押し上げます。 (注: 一部のレッグ プレス ユニットでは、安全性を高めるためにセーフティ バーを付けたままにすることができます。レッグ プレス ユニットでこれが許可されている場合は、これがエクササイズを実行する推奨される方法です。) 胴体と脚は完全に 90 度の角度をなす必要があります。次に、かかとを伸ばした状態で、つま先と足の指の付け根をプラットフォームの下部に慎重に置きます。この章の冒頭で説明したように、つま先は前方、外側、または内側を向いている必要があります。これが開始位置になります。", "足首をできるだけ高く伸ばし、ふくらはぎを曲げて息を吐きながらかかとを上げてプラットフォームを押します。膝が常に動かないように注意してください。いかなるときも曲げてはいけません。下がり始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げ、ふくらはぎが伸びるまで足首を曲げてゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Calf_Press_On_The_Leg_Press_Machine';
UPDATE exercises SET name = 'ダンベルでカーフレイズ', instructions = '["バランスをとるために頑丈な物につかまり、ダンベルのハンドル、できれば転がるように丸いプレートが付いているものの上に立ちます。このようにすると、体を安定させるためにもっと頑張らなければなりません。したがって、運動の効果が高まります。", "次に、ふくらはぎをしっかりと伸ばすことができるように、足を少し前に倒します。これが開始位置になります。", "ふくらはぎを持ち上げながらハンドルの上で足を転がし、完全に伸ばすようにします。この動作の実行中に息を吐きます。ふくらはぎの上部を強く収縮させ、1秒間保持します。ヒント: 上がってくるときに、ダンベルを少し後方に回転させます。", "次に、息を吸いながらダンベルを少し前に転がしながら降り、ストレッチを強化します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Calf_Raise_On_A_Dumbbell';
UPDATE exercises SET name = 'カーフレイズ - バンド付き', instructions = '["エクササイズバンドをつかみ、足の指でその上に立ち、足と腕の間のバンドの長さが両側で同じであることを確認します。", "バンドのハンドルを持ちながら、ショルダープレスを行う準備をしているかのように腕を頭の横に上げます。手のひらは前を向き、肘を曲げて横に向けます。この動きによりバンドに緊張が生じます。これが開始位置になります。", "手を肩の横に置き、息を吐きながらつま先で立ち、動きの一番上でふくらはぎを強く収縮させます。", "1秒ほど収縮した後、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Calf_Raises_-_With_Bands';
UPDATE exercises SET name = '壁に肘を当ててふくらはぎを伸ばす', instructions = '["数フィート離れたところから壁に向かって立ちます。", "壁に寄りかかり、前腕に体重を置きます。", "かかとを地面につけたままにしてみてください。 10〜20秒間押し続けます。壁から遠ざかったり、壁に近づいたりすることで、それぞれ難易度が上がります。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Calf_Stretch_Elbows_Against_Wall';
UPDATE exercises SET name = '壁に手をついてふくらはぎを伸ばす', instructions = '["数フィート離れたところから壁に向かって立ちます。スタンスをずらして片足を前に出します。", "前かがみになって両手を壁に置き、かかと、腰、頭を一直線に保ちます。", "かかとを地面につけたままにしてみてください。 10〜20秒間保持してから、側を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Calf_Stretch_Hands_Against_Wall';
UPDATE exercises SET name = 'ふくらはぎ-SMR', instructions = '["床に座り始めます。フォームローラーを下腿の下に置きます。もう一方の足は反対側に交差させるか、床に置いて体重の一部を支えます。これが開始位置になります。", "手を体の横またはすぐ後ろに置き、お尻を床から持ち上げるように押し下げ、体重の多くをふくらはぎの筋肉にかけます。膝の下から足首の上までローリングし、緊張した箇所で 10 ～ 30 秒間停止します。もう一方の脚でも同じ手順を繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Calves-SMR';
UPDATE exercises SET name = '車のデッドリフト', instructions = '["この種目用器具には通常、ニュートラル グリップ ハンドルが付いていますが、通常のデッドリフトのようにアプローチできる真っ直ぐなバーが付いているものもあります。この装置には、車両や、トラクターのタイヤや樽などの他の重量物を積載することができます。", "しゃがむのが得意な方はハンドルの中心に体を置き、デッドリフターが得意な方は数インチ後ずさりしてください。足は腰幅程度に開く必要があります。腰を曲げてハンドルを握ります。足とグリップを固定した状態で、大きく息を吸い、腰を下げて膝を曲げます。", "頭を前に向け、胸を張り、背中を反らせた状態を保ち、かかとから体重を上に移動し始めます。体重が上がったら、肩甲骨を寄せながら腰を前に動かします。", "腰を曲げて体重を床に誘導して体重を下げます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Car_Deadlift';
UPDATE exercises SET name = '車の運転手', instructions = '["直立した状態で、バーベルプレートの3時と9時の位置を両手で持ちます。手のひらは向かい合って、腕は前にまっすぐに伸ばす必要があります。これが開始位置になります。", "プレートをできるだけ片側に回転させて動きを開始します。ハンドルを片側に回すのと同じ種類の動きを使用します。", "動きを逆にして、反対側まで回転させます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Car_Drivers';
UPDATE exercises SET name = 'カリオカ クイックステップ', instructions = '["足を数インチ離し、左腕を上げてリラックスした運動姿勢から始めます。", "右足を素早く後ろに踏み出し、膝を引き上げます。", "右膝を引くときは腕を元に戻し、膝がまっすぐ上下に動くことを確認します。移動中に足を回転させないようにして、横に移動するときも前を見続けてください。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Carioca_Quick_Step';
UPDATE exercises SET name = '猫のストレッチ', instructions = '["床に手と膝をついて立ちます。", "お腹を引っ込めて背骨、腰、肩、首を丸め、頭を下げます。", "15秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Cat_Stretch';
UPDATE exercises SET name = 'キャッチとオーバーヘッドスロー', instructions = '["壁またはパートナーに向かって立ち始めます。", "両手を使ってボールを頭の後ろに置き、できるだけ伸ばして、ボールを前方に勢いよく投げます。", "スロースルーをフォローして、スローからのリバウンドを受け取る準備をしてください。壁に向かって投げる場合は、リバウンドを受け取るのに十分な壁の近くに立って、パートナーと投げる場合よりも少し高い位置を狙うようにしてください。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Catch_and_Overhead_Throw';
UPDATE exercises SET name = 'チェーンハンドルエクステンション', instructions = '["この演習では、2 つのケーブル ハンドル アタッチメントとフラット ベンチ、およびチェーンが必要です。チェーンの中央をハンドルにクリップし、フラットベンチに座ります。肘はまっすぐ上を向いている必要があります。", "手首を回内した状態で、上腕を動かさずに肘から伸ばします。", "ロックアウトで一時停止し、動きを逆にして開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'その他' WHERE id = 'Chain_Handle_Extension';
UPDATE exercises SET name = 'チェーンプレス', instructions = '["まず、チェーンをケーブルハンドルアタッチメントに接続します。ダンベルプレスと同じ姿勢でフラットベンチに座ります。手首を回内し、腕を床に対して垂直にする必要があります。これが開始位置になります。", "肘を曲げてチェーンを下げ、チェーンの一部を床に下ろします。", "肘が 90 度の角度になるまで続けてから、動作を逆に肘を伸ばしてロックアウトします。"]'::jsonb, category = 'パワーリフティング', equipment = 'その他' WHERE id = 'Chain_Press';
UPDATE exercises SET name = '椅子の脚を伸ばすストレッチ', instructions = '["椅子に直立して座り、座面の側面を持ちます。", "片脚を上げ、膝を伸ばし、足首を曲げます。", "ゆっくりとその脚をできるだけ外側に動かし、次に中心に戻して下に下げます。", "もう一方の脚でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Chair_Leg_Extended_Stretch';
UPDATE exercises SET name = '椅子の腰のストレッチ', instructions = '["椅子に直立して座ります。", "腕を頭の上に置いて片側に曲がります。空いた手で椅子につかまることができます。", "10 秒間押し続け、反対側でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Chair_Lower_Back_Stretch';
UPDATE exercises SET name = 'チェアスクワット', instructions = '["まず、自分の身長に最も適した位置にバーを設定します。バーに荷重がかかったら、バーの下に踏み込み、肩の後ろに置きます。", "手を前に向けてバーを持ち、ロックを解除し、足を伸ばしてラックから持ち上げます。", "足をバーの前約18インチ前方に動かします。足の位置は肩幅でスタンスをとり、つま先をわずかに向けます。常に前を向いて、背骨を中立かわずかにアーチ状に保ちます。これが開始位置になります。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げます。上脚と下脚の間の角度が 90 度を超えるまで下がり続けます。", "息を吐きながら足のかかとで床を押してバーを上げ始め、膝を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Chair_Squat';
UPDATE exercises SET name = '椅子の上半身のストレッチ', instructions = '["椅子の端に座り、背もたれを握ります。", "腕を伸ばして背中をまっすぐに保ち、上半身を前に引っ張ってストレッチを感じます。 20〜30秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Chair_Upper_Body_Stretch';
UPDATE exercises SET name = '胸と肩の前部のストレッチ', instructions = '["まずは両足を揃えて立ち、ボディバーかほうきの柄を持ちます。", "ポールを肩幅より少し広めに握り、手のひらを下に向けて体の前に持ちます。", "ポールを頭の後ろで慎重に持ち上げます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Chest_And_Front_Of_Shoulder_Stretch';
UPDATE exercises SET name = '3点スタンスからのチェストプッシュ', instructions = '["背中を平らにしてしゃがみ、片手を地面についた三点スタンスから始めます。メディシンボールを目の前に置きます。", "まず、ボールを胸に引き寄せて最初の一歩を踏み出し、両手を構えて投げる準備をします。", "2 番目のステップを実行するときは、できるだけ強く前方に爆発的にボールを放します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Chest_Push_from_3_point_stance';
UPDATE exercises SET name = 'チェストプッシュ (複数回答)', instructions = '["壁に向かってひざまずく姿勢から始めるか、パートナーを利用してください。ボールを両手で胸にしっかりと当てます。", "ボールをできるだけ強く押しながら、腰を前方外側に爆発させてパスを実行します。", "前に倒れて手で体を捕まえてフォロースルーします。", "すぐに直立姿勢に戻ります。必要な回数だけ繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Chest_Push_multiple_response';
UPDATE exercises SET name = 'チェストプッシュ (単一応答)', instructions = '["両手でメディシン ボールを胸にしっかりと押し込み、ひざまずいた姿勢から始めます。", "ボールをできるだけ遠くに押しながら、腰を前方外側に爆発させてパスを実行します。", "前に倒れて手で体を捕まえてフォロースルーします。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Chest_Push_single_response';
UPDATE exercises SET name = 'チェストプッシュとランリリース', instructions = '["膝を曲げ、腰を後ろに伸ばし、背中を平らにした運動姿勢から始めます。メディシンボールを足の近くに持ちます。これが開始位置になります。", "最初の一歩を踏み出すときに、メディシンボールを胸に引き込みます。", "2 歩目を踏み出すと、爆発的にボールを前方に押し出し、リリース後すぐに 10 ヤードを全力疾走します。本当に速ければ、自分のパスをキャッチすることができます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Chest_Push_with_Run_Release';
UPDATE exercises SET name = 'スタビリティボールで胸部ストレッチ', instructions = '["バランスボールの横に手と膝をつきます。", "肘をボールの上に置き、腕を体の横に伸ばします。これが開始位置になります。", "肘をボールの上に置いたまま、胴体を床に向かって下げます。ストレッチを 20 ～ 30 秒間保持し、もう一方の腕でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'exercise ball' WHERE id = 'Chest_Stretch_on_Stability_Ball';
UPDATE exercises SET name = '子供のポーズ', instructions = '["四つん這いになり、手を前に出して歩きます。", "お尻を下げてかかとの上に座ります。背筋全体を伸ばすために、背もたれに座りながら腕を床に沿って引きずります。", "かかとに落ち着いたら、手を足の横に置いてリラックスします。背中に「息を吹き込む」。額を床に置きます。膝に問題がある場合は、この姿勢を避けてください。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Childs_Pose';
UPDATE exercises SET name = '懸垂', instructions = '["手のひらを胴体に向け、グリップを肩幅よりも狭くして懸垂バーを握ります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を湾曲させて胸を突き出しながら、胴体をできるだけ真っ直ぐに保ちます。これが開始位置です。ヒント: 胴体をできるだけまっすぐに保つことで、上腕二頭筋への刺激が最大化され、背中への負担が最小限に抑えられます。", "息を吐きながら、頭が懸垂バーの高さのあたりになるまで胴体を引き上げます。動きを実行するために上腕二頭筋の筋肉を使うことに集中してください。肘を体に近づけてください。ヒント: 上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で上腕二頭筋を 1 秒間締めた後、ゆっくりと胴体を下げて開始位置に戻します。腕を完全に伸ばしたとき。動きのこの部分を実行するときに息を吸います。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Chin-Up';
UPDATE exercises SET name = 'あごから胸までのストレッチ', instructions = '["床に座った姿勢になります。", "両手を頭の後ろに置き、指を組み、親指を下に向け、肘をまっすぐ前に向けます。ゆっくりと頭を胸に引き寄せます。 20〜30秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Chin_To_Chest_Stretch';
UPDATE exercises SET name = 'サーカスの鐘', instructions = '["サーカスベルは、太いハンドルが付いた特大のダンベルです。ダンベルを足の間に置き、両手でハンドルを握ります。", "腰と膝を通ってダンベルを目的の肩まで伸ばし、余った手を放してダンベルをきれいにします。", "バランスを崩さないように、ダンベルヘッドの 1 つを肩の後ろに置くようにしてください。頭上に上げるには、膝を曲げてダンベルを沈め、ダンベルを頭上に伸ばしながら、ダンベルから少し離れるように傾けながら上向きに動かします。", "ベルを慎重に床に戻し、ベルをできるだけ制御下に保ちます。床への損傷を防ぐために、このイベントは厚いゴムマットの上で行うのが最善です。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Circus_Bell';
UPDATE exercises SET name = 'クリーン', instructions = '["バーベルをすねの近くの床に置き、脚のすぐ外側でオーバーハンド（またはフック）グリップを握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐに保つ必要があります。膝の上まで体重をコントロールしながら動かします。", "次に、クリーンの加速の主な源である 2 番目のプルが始まります。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、腕は伸ばしたまま、体を完全に伸ばし、わずかに後ろに傾く必要があります。", "完全な伸展が達成されたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げることにより、3番目のプルに移行します。伸展がピークに達したら、バーの下で肘を回転させながら、積極的に体を引き下げます。前屈みの姿勢でバーを受け取ります。その深さは、3 回目のプル終了時のバーの高さによって決まります。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。ボトムスクワットの位置まで下がり続けます。これは回復に役立ちます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるまで続けます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean';
UPDATE exercises SET name = 'クリーンデッドリフト', instructions = '["バーベルをすねの近くに持って立ち始めます。足は腰の真下に置き、足を少し外側に向けます。ダブルオーバーハンドグリップまたはフックグリップで、肩幅程度の間隔でバーを握ります。バーに向かってしゃがみます。背骨は完全に伸び、肩がバーの前に位置し、背中ができるだけ垂直になるような背中の角度を保つ必要があります。", "かかとの前部から床を通過することから始めます。バーが上向きに移動するとき、後ろの角度を一定に保ちます。膝を横に広げてバーの軌道に当たらないようにします。", "バーが膝を越えたら、腰と膝が伸びるまで腰をバーに押し込んでリフトを完了します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean_Deadlift';
UPDATE exercises SET name = 'クリーンプル', instructions = '["バーベルをすねの近くの床に置き、脚のすぐ外側でオーバーハンドまたはフックグリップを握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐにして肘を伸ばしたままにしてください。膝の上まで体重をコントロールしながら動かします。", "次に、クリーンの加速の主な源である 2 番目のプルが始まります。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、腕は伸ばしたまま、体を完全に伸ばし、わずかに後ろに傾く必要があります。完全な伸展は暴力的かつ突然である必要があり、必要以上に伸展を延長しないように注意してください。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean_Pull';
UPDATE exercises SET name = 'クリーンシュラッグ', instructions = '["肩幅、ダブルオーバーハンドまたはフックグリップでバーを太ももの真ん中の位置にぶら下げて開始します。背中はまっすぐで、わずかに前傾している必要があります。", "肩を耳に向かってすくめます。このエクササイズでは通常、クリーンよりも重い重量を負荷することができますが、実行が遅くなるほどの過負荷は避けてください。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean_Shrug';
UPDATE exercises SET name = 'クリーン＆ジャーク', instructions = '["バーベルをすねの近くの床に置き、脚のすぐ外側でオーバーハンドまたはフックグリップを握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐに保つ必要があります。膝の上まで体重をコントロールしながら動かします。", "次に、クリーンの加速の主な源である 2 番目のプルが始まります。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、腕は伸ばしたまま、体を完全に伸ばし、わずかに後ろに傾く必要があります。", "完全な伸展が達成されたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げることにより、3番目のプルに移行します。伸展がピークに達したら、バーの下で肘を回転させながら、積極的に体を引き下げます。前屈みの姿勢でバーを受け取ります。その深さは、3 回目のプル終了時のバーの高さによって決まります。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。ボトムスクワットの位置まで下がり続けます。これは回復に役立ちます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるまで続けます。", "第 2 段階はジャークで、重量を頭上に上げます。肩の前部に体重をかけて立ち、ディップから始めます。足を腰の真下に置き、腰を後ろに動かさずに膝を曲げます。ほんの少しだけ下に下がり、できるだけ力強く方向を反転します。", "かかとを使ってドライブすると、できるだけ多くのスピードと力が生まれ、バーが肩から離れるときに頭を邪魔にならないように移動してください。", "足が床から離れたこの瞬間、できるだけ早く足を受け取る位置に置かなければなりません。足が積極的にプラットフォームに向かって動いていない一瞬の間、アスリートはバーを押し上げようとする努力によってバーを押し下げてしまいます。足を分割し、片足を前に、もう片足を後ろに置きます。腕を頭上に伸ばしてバーを受け取ります。立った姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean_and_Jerk';
UPDATE exercises SET name = 'クリーニングしてプレス', instructions = '["膝を腕の内側に置き、肩幅にスタンスをとります。次に、背中を平らに保ちながら、膝と腰を曲げて、腕を完全に伸ばし、肩の幅よりわずかに広い回内グリップでバーをつかむことができるようにします。肘を横に向けます。バーはすねの近くにある必要があります。肩をバーの上、またはバーより少し前に置きます。平らな背中の姿勢を確立します。これが開始位置になります。", "膝を伸ばしてバーを引き始めます。背中の角度を一定に保ちながら、腰を前方に動かし、同じ速度で肩を上げます。バーを体に近づけたまま、まっすぐ上に持ち上げ続けます。", "バーが膝を通過したら、ジャンプする動作と同じように、足首、膝、腰を力強く伸ばします。このとき、手でバーを誘導し続け、肩をすくめ、動きの勢いを利用してバーをできるだけ高く引き上げます。バーは体の近くに移動し、肘は前に出さないようにする必要があります。", "最大の高さでは、足が床から離れ、バーの下に体を引き込み始める必要があります。このメカニズムは、使用される重量に応じて若干変化する可能性があります。バーの下に体を引き込みながら、しゃがんだ姿勢になる必要があります。", "バーが最終の高さに達したら、肘をバーの周りとバーの下で回転させます。バーの重みを吸収するために胴体を直立させ、腰と膝を曲げながらバーを肩の前に掛けます。", "バーをきれいな位置に保ち、完全な高さまで立ちます。", "足を動かさずに、息を吐きながら頭上のバーを押します。コントロールの下でバーを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Clean_and_Press';
UPDATE exercises SET name = 'ブロックから掃除する', instructions = '["希望の高さのボックスまたはスタンドにバーベルを置き、足のすぐ外側でオーバーハンドまたはフックグリップを握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕は肘を向けてまっすぐに保つ必要があります。", "完全に伸展できたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げて、受けの姿勢に移行します。積極的に体を引き下げ、バーの下で肘を回転させます。前屈みの姿勢でバーを受け取ります。その深さは、3 回目のプル終了時のバーの高さによって決まります。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。ボトムスクワットの位置まで下がり続けます。これは回復に役立ちます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるまで続けます。次のレップのために重量をボックスに戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Clean_from_Blocks';
UPDATE exercises SET name = 'クロックプッシュアップ', instructions = '["床の上でうつ伏せの姿勢になり、手とつま先で体重を支えます。", "腕を完全に伸ばし、手を肩幅に広げます。動作中は体をまっすぐに保ちます。これが開始位置になります。", "肘を曲げて胸を地面に向かって下げます。", "一番下では、逆の動きをして、空中に浮くまでできるだけ早く肘を伸ばして体を押し上げます。片側に12〜18インチ「ジャンプ」することを目指してください。", "加速するときは、外側の足を進行方向から遠ざけます。地面から離れて、次の繰り返しのために体を約 30 度移動します。", "開始位置に戻り、開始位置に戻るまでエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Clock_Push-Up';
UPDATE exercises SET name = 'クローズグリップバーベルベンチプレス', instructions = '["平らなベンチに仰向けになります。グリップを閉じて (肩幅程度に) バーをラックから持ち上げ、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の中央にバーを感じるまでゆっくりと下ろします。ヒント: 通常のベンチプレスとは異なり、上腕三頭筋の働きを最大限に高めるために、肘を常に胴体の近くに保つようにしてください。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、上腕三頭筋を使ってバーを押します。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Close-Grip_Barbell_Bench_Press';
UPDATE exercises SET name = 'クローズグリップダンベルプレス', instructions = '["ダンベルを平らなベンチの上に立って置きます。", "ダンベルがベンチの上部にしっかりと配置されていることを確認し、肩だけを表面に置き、ベンチに対して垂直に寝ます。腰はベンチの下にあり、足を曲げて足を床にしっかりとつけます。", "ダンベルを両手で持ち、腕を伸ばして胸の上にまっすぐ持ちます。両方の手のひらでダンベルの側面の下側を押す必要があります。これが開始位置になります。", "ダンベルを胸まで下げて動きを開始します。", "肘を伸ばして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Close-Grip_Dumbbell_Press';
UPDATE exercises SET name = 'クローズグリップ EZバーカール バンド付き', instructions = '["バーの両端にバンドを取り付けます。バーを持ち、バンドの中央に足を置きます。 EZ バーを細く回外したグリップで直立して立ちます。肘は胴体の近くにある必要があります。これが開始位置になります。", "上腕を所定の位置に保ちながら、肘を曲げてカールを実行します。体重を持ち上げながら息を吐きます。", "上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持し、上腕二頭筋を強く締めます。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Close-Grip_EZ-Bar_Curl_with_Band';
UPDATE exercises SET name = 'クローズグリップEZバープレス', instructions = '["適切な重量のEZバーを装着した平らなベンチに横になります。", "細いグリップを使ってバーを持ち上げ、肘を内側に入れて胴体の上でまっすぐに持ちます。腕は床に対して垂直でなければなりません。これが開始位置になります。", "次に、息を吸いながらバーを胸の下部まで下げます。この動作を行うときは肘を閉じたままにしてください。", "上腕三頭筋を使ってバーを押し上げ、息を吐きながら肘を伸ばしてバーを元の位置に押し戻します。", "繰り返す。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Close-Grip_EZ-Bar_Press';
UPDATE exercises SET name = 'クローズグリップEZバーカール', instructions = '["E-Z カール バーの内側ハンドルに近い部分を持ちながら、上体を直立させて立ちます。手のひらは前を向き、バーの形状によりわずかに内側に傾いている必要があります。肘は胴体の近くにある必要があります。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方にカールさせます。ヒント: 前腕のみを動かします。", "上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持し、上腕二頭筋を強く締めます。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Close-Grip_EZ_Bar_Curl';
UPDATE exercises SET name = 'クローズグリップフロントラットプルダウン', instructions = '["上部のプーリーに幅広のバーが取り付けられたプルダウン マシンに座ります。身長に合わせてマシンの膝パッドを調整してください。これらのパッドは、バーにかかる抵抗によって体が持ち上がるのを防ぎます。", "所定のグリップを使用して、手のひらを前に向けてバーを握ります。グリップに関する注意: ワイドグリップの場合、両手の間隔は肩幅より広くする必要があります。中程度のグリップの場合は、両手の間隔を肩幅と同じにする必要があります。クローズグリップの場合は、肩の幅よりも狭い距離に手を置く必要があります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を反らせて胸を突き出しながら、胴体を約 30 度ほど後ろに戻します。これが開始位置です。", "息を吐きながら、肩と上腕を下と後ろに引いて、バーが胸の上部に触れるまで下げます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は動かないようにします (腕だけを動かします)。前腕はバーを握る以外の仕事をしてはなりません。したがって、前腕を使ってバーを引き下げようとしないでください。", "収縮した位置で 1 秒後、肩甲骨を引き寄せながら、腕を完全に伸ばし、広背筋が完全に伸びたら、バーをゆっくりと開始位置に戻します。動きのこの部分で息を吸います。", "6. この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Close-Grip_Front_Lat_Pulldown';
UPDATE exercises SET name = 'ダンベルを使ったクローズグリッププッシュアップ', instructions = '["床に横になり、直立したダンベルに手を置きます。つま先と手で体重を支え、胴体を堅く保ち、腕をまっすぐにして肘を内側に置きます。これが開始位置になります。", "息を吸いながら肘を曲げながら体を下げます。腰が上がったり垂れたりしないように、体をまっすぐに保ちます。", "肘を伸ばして開始位置に戻ります。このステップを実行するときに息を吐きます。", "収縮した位置で一時停止した後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Close-Grip_Push-Up_off_of_a_Dumbbell';
UPDATE exercises SET name = 'クローズグリップスタンディングバーベルカール', instructions = '["バーベルを両手で持ち、手のひらを上にして数インチ間隔をあけます。", "胴体をまっすぐにして頭を上げて立ちます。足は肩幅くらいにし、肘を胴体に近づける必要があります。これが開始位置になります。ヒント: 動作中は上腕と肘を動かさないようにします。", "前腕が上腕二頭筋に触れるまで、バーを半円を描くように巻き上げます。動きのこの部分を実行するときに息を吐き、上部で上腕二頭筋を 1 秒間強く収縮させます。ヒント: ウェイトを持ち上げるときに、背中を曲げたり、スイング動作を使用したりしないでください。前腕だけを動かす必要があります。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Close-Grip_Standing_Barbell_Curl';
UPDATE exercises SET name = '繭', instructions = '["地面に仰向けになることから始めます。足はまっすぐにし、腕は頭の後ろに伸ばします。これが開始位置になります。", "この動きを行うには、膝を胸のほうに押し込み、骨盤を回転させて臀筋を床から持ち上げます。このとき、背骨を曲げて腕を頭の上に戻し、クランチ動作を同時に実行します。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Cocoons';
UPDATE exercises SET name = 'コナンの車輪', instructions = '["重りを載せた状態で、作業具の端をしっかりと握ります。バーを肘の曲がり部分に置き、手首を握ります。前腕に体重がかからないようにしてください。", "地面から重量を持ち上げることから始めます。短く速い歩幅で歩くときは、しっかりと直立した姿勢を保ちます。円を描くように上を向いて目をそらしましょう。イベント中は息を止めないでください。 1 つ以上の完全なターンを完了するまで歩き続けます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Conans_Wheel';
UPDATE exercises SET name = 'コンセントレーションカール', instructions = '["平らなベンチに座り、脚の間にダンベルを 1 つ置きます。膝を曲げて足を床に置き、足を広げます。", "右腕を使ってダンベルを持ち上げます。右上腕の後ろを右太ももの内側の上に置きます。手のひらが太ももから前を向くまで回転させます。ヒント: 腕を伸ばし、ダンベルが床の上にある必要があります。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方に曲げます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。ヒント: 動きの頂点では、腕の小指が親指より高い位置にあることを確認してください。これにより、良好な収縮が保証されます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。 注意: スイング動作は絶対に避けてください。", "推奨回数だけ繰り返します。次に、左腕で同じ動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Concentration_Curls';
UPDATE exercises SET name = 'クロスボディクランチ', instructions = '["仰向けに寝て、膝を約60度曲げます。", "足を床に平らに保ち、両手を頭の後ろに軽く置きます。これが開始位置になります。", "次に、体を丸めて右肘と肩を体の横に置き、同時に左膝を左肩に近づけます。肘を伸ばして膝に触れるようにしてください。この動きをしながら息を吐きます。ヒント: 肩を肘だけではなく膝に近づけるようにしてください。動作を実行するときに重要なのは腹筋を収縮させることであることを覚えておいてください。肘を動かすだけではありません。", "次に、息を吸いながら開始位置に戻り、左肘と右膝で繰り返します。", "規定の繰り返しがすべて完了するまで、この方法で交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Cross-Body_Crunch';
UPDATE exercises SET name = 'クロスボディハンマーカール', instructions = '["両手にダンベルを持ってまっすぐに立ちます。手は体の横に下ろし、手のひらを内側に向けます。", "手のひらを内側に向けたまま、腕をひねらずに、息を吐きながら右腕のダンベルを左肩に向かって丸めます。ダンベルの上部を肩に当て、収縮した状態を 1 秒間保持します。", "息を吸いながら同じ軌道に沿ってダンベルをゆっくりと下げ、左腕でも同じ動きを繰り返します。", "各腕で推奨回数の繰り返しが実行されるまで、この方法を交互に続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Cross_Body_Hammer_Curl';
UPDATE exercises SET name = 'クロスオーバー - バンド付き', instructions = '["エクササイズバンドを固定ポストの周りに固定します。", "ポストから背を向けた状態で、バンドの両端にあるハンドルをつかみ、バンドに張力を加えるのに十分な量だけ前に踏み出します。", "腕を横に上げ、床と平行に、胴体に垂直に（胴体と腕が文字「T」のようになります）、手のひらを前に向けます。肘を軽く曲げて伸ばします。これが開始位置になります。", "腕をまっすぐに保ちながら、息を吐きながら胸筋を曲げながら、半円を描くように胸の前に腕を置きます。収縮を 1 秒間保持します。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨される繰り返し回数を実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Cross_Over_-_With_Bands';
UPDATE exercises SET name = 'クロスオーバー リバース ランジ', instructions = '["足を肩幅に開いて立ちます。これが開始位置になります。", "片足で後ろに下がり、股関節と前膝を曲げてリアランジを実行します。このとき、前脚を横切って胴体を回転させます。", "少し停止した後、開始位置に戻り、反対側も繰り返し、交互に続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Crossover_Reverse_Lunge';
UPDATE exercises SET name = '十字架', instructions = '["十字架では、ウェイトを静的に横に広げて一定時間保持します。この種目はダンベルを使って練習することもできますが、斧やハンマーなどのさまざまな道具を使って練習するのがベストです。感覚が異なります。", "立ち上がって、道具を持った腕を横に上げます。腕は地面と平行でなければなりません。競技では、平行線を突破したことを知らせるためにジャッジまたはセンサーが使用されます。できるだけ長く保持してください。通常、ウェイトは 30 ～ 60 秒で失敗するほど重くする必要があります。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Crucifix';
UPDATE exercises SET name = 'クランチ - 両手をオーバーヘッド', instructions = '["背中を平らにして床に横になり、ハムストリングスとふくらはぎの間で約60度の角度で膝を曲げます。", "足を床に平らに保ち、手のひらを交差させて腕を頭上に伸ばします。これが開始位置になります。", "上体を前に丸め、肩甲骨を床から少し浮かせます。常に腕を頭、首、肩と一直線に保つようにしてください。その位置から前方に動かさないでください。動きのこの部分を実行するときに息を吐き、収縮を 1 秒間保持します。", "息を吸いながら、ゆっくりと開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Crunch_-_Hands_Overhead';
UPDATE exercises SET name = 'クランチ - エクササイズ ボールに足を乗せる', instructions = '["仰向けに寝て、足をバランスボールの上に置き、膝を90度の角度で曲げます。", "足を3〜4インチ離して置き、つま先が触れるように内側に向けます。", "肘を内側に置いたまま、手を頭の両側に軽く置きます。 ヒント: 指を頭の後ろで固定しないでください。", "腹筋をより効果的に分離するために、背中のくびれを床に押し下げます。これが開始位置になります。", "肩を床から転がし始め、腰をできるだけ強く押し続けます。肩は床から約 4 インチだけ浮くようにし、腰は床につけたままにする必要があります。動きのこの部分を実行するときに息を吐きます。収縮の頂点で腹部を強く絞り、1秒間保持します。ヒント: ゆっくりと制御された動きに集中してください。いかなる場合でも勢いを使うことは控えてください。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Crunch_-_Legs_On_Exercise_Ball';
UPDATE exercises SET name = 'クランチ', instructions = '["仰向けになって両足を地面に平らにつけるか、膝を90度に曲げてベンチに座ります。足をベンチに置く場合は、足を3～4インチ離して置き、つま先が触れるように内側に向けます。", "次に、肘を内側に置いたまま、両手を頭の両側に軽く置きます。 ヒント: 指を頭の後ろで固定しないでください。", "腹筋をより効果的に分離するために背中のくびれを床に押し込みながら、肩を床から転がし始めます。", "腹部を収縮させて息を吐きながら、腰をできるだけ強く押し続けます。肩は床から約 4 インチだけ浮くようにし、腰は床につけたままにする必要があります。動きの頂点で、腹部を強く収縮させ、その収縮を 1 秒間維持します。ヒント: ゆっくりと制御された動きに集中してください。勢いを利用して自分自身をだまさないでください。", "1 秒間の収縮の後、息を吸いながら再びゆっくりと開始位置まで下がり始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Crunches';
UPDATE exercises SET name = 'キューバプレス', instructions = '["立った姿勢で回内グリップでダンベルを両手に持ちます。上腕が床と平行になるように上げ、下腕が「かかし」の位置でぶら下がるようにします。これが開始位置になります。", "動きを開始するには、肩を外側に回転させて上腕を 180 度動かします。上腕を所定の位置に保ち、手首が肘の真上にくるまで上腕を回転させ、前腕が床に対して垂直になります。", "次に、肘を伸ばしてダンベルを押し、腕を頭上に伸ばします。", "息を吸いながら、手順を逆にして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Cuban_Press';
UPDATE exercises SET name = 'ダンサーのストレッチ', instructions = '["床に座ってください。", "膝を曲げたまま、右足を左足の上に交差させます。左足はまっすぐにして床に下ろします。", "左腕を右脚の上に置き、右手を床に置きます。", "上体を右に回転し、10〜20秒間保持します。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Dancers_Stretch';
UPDATE exercises SET name = '死んだバグ', instructions = '["仰向けに寝て、両手を天井に向かって伸ばします。", "足、膝、腰を90度まで曲げます。", "息を強く吐き出して胸郭を下げ、背中を床に平らにし、骨盤を回転させて臀部を締めます。動きの間ずっとこの姿勢を保ちます。これが開始位置になります。", "片方の脚を伸ばし、膝と股関節をまっすぐにして脚を地面のすぐ上に持ってくることからエクササイズを開始します。", "背中が反ろうとするため、この動作を行うときは腰椎と骨盤の位置を維持してください。", "しっかりと固定し、作業脚を開始位置に戻します。", "セットが完了するまで、反対側も交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Dead_Bug';
UPDATE exercises SET name = 'バンドを使ったデッドリフト', instructions = '["短いバンドを使ってデッドリフトを行うには、開始前にバンドをバーに巻き付け、バンドに足を踏み入れてセットアップするだけです。長いバンドの場合は、重いダンベルやラックなどの安全なベースに固定する必要があります。", "足とグリップをセットした状態で、大きく息を吸い、腰を下げ、すねがバーに触れるまで膝を曲げます。頭を前方に向け、胸を張って背中を反​​らせ、かかとから体重を上に移動し始めます。バーが膝を通過したら、積極的にバーを後ろに引き、肩甲骨を寄せながら腰を前方にバーに押し込みます。", "腰を曲げてバーを床に誘導してバーを下げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Deadlift_with_Bands';
UPDATE exercises SET name = 'チェーンを使ったデッドリフト', instructions = '["チェーンをバーの袖に取り付けるか、バーの上に中央を垂らすだけで、持ち上げるときに重量が大きく増加します。", "バーが足の中心に来るようにバーに近づきます。足は腰幅程度に開く必要があります。腰を曲げて肩幅でバーを握り、肩甲骨を突き出します。通常、重いセットではオーバーハンド グリップまたはオーバー/アンダー グリップを使用します。足とグリップをセットした状態で、大きく息を吸い、腰を下げ、すねがバーに触れるまで膝を曲げます。", "頭を前方に向け、胸を張って背中を反​​らせ、かかとから体重を上に移動し始めます。バーが膝を通過したら、積極的にバーを後ろに引き、肩甲骨を寄せながら腰を前方にバーに押し込みます。", "腰を曲げてバーを床に誘導してバーを下げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Deadlift_with_Chains';
UPDATE exercises SET name = 'デクラインバーベルベンチプレス', instructions = '["下りベンチの端で足を固定し、ゆっくりとベンチに横になります。", "中程度の幅のグリップ (前腕と上腕の間の動きの途中で 90 度の角度を作るグリップ) を使用して、バーをラックから持ち上げ、腕をロックした状態でバーを体の上にまっすぐ持ちます。腕は床に対して垂直でなければなりません。これが開始位置になります。ヒント: 腱板を保護するために、バーベルをラックから持ち上げるのをスポッターに手伝ってもらうのが最善です。", "息を吸いながら、胸の下部にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕をロックし、収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下がり始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります)。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Decline_Barbell_Bench_Press';
UPDATE exercises SET name = 'クローズグリップベンチをディクラインしてスカルクラッシャーへ', instructions = '["下りベンチの端で足を固定し、ゆっくりとベンチに横になります。", "閉じたグリップ (肩幅よりわずかに狭いグリップ) を使用して、バーをラックから持ち上げ、腕をロックして肘を立ててまっすぐに持ちます。腕は床に対して垂直でなければなりません。これが開始位置になります。ヒント: 腱板を保護するために、バーベルをラックから持ち上げるのをスポッターに手伝ってもらうのが最善です。", "次に、息を吸いながらバーを胸の下部まで下げます。この動作を行うときは肘を閉じたままにしてください。", "上腕三頭筋を使ってバーを押し上げ、息を吐きながら開始位置に押し戻します。", "息を吸いながら上腕を動かさないようにしながら、バーが額に軽く触れるまで前腕を半円を描くように手前に動かし、ゆっくりとバーを下ろします。動きのこの部分を実行するときに息を吸います。", "上腕三頭筋を収縮させて息を吐きながら、バーを持ち上げて開始位置に戻します。", "推奨回数が実行されるまで、手順 3 ～ 6 を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Decline_Close-Grip_Bench_To_Skull_Crusher';
UPDATE exercises SET name = 'デクラインクランチ', instructions = '["下りベンチの端に足を固定し、横になります。", "次に、肘を内側に置いたまま、両手を頭の両側に軽く置きます。 ヒント: 指を頭の後ろで固定しないでください。", "腹筋をより効果的に分離するためにベンチに背中のくびれを押し下げながら、肩をベンチから下ろし始めます。", "腹部を収縮させて息を吐きながら、腰をできるだけ強く押し続けます。肩はベンチから約 4 インチだけ上がり、腰はベンチから離れないようにしてください。動きの頂点で、腹部を強く収縮させ、その収縮を 1 秒間維持します。ヒント: ゆっくりと制御された動きに集中してください。勢いを利用して自分自身をだまさないでください。", "1 秒間の収縮の後、息を吸いながら再びゆっくりと開始位置まで下がり始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Decline_Crunch';
UPDATE exercises SET name = 'デクラインダンベルベンチプレス', instructions = '["デクラインベンチの端で両脚を固定し、両手にダンベルを抱えて横になり、太ももの上に置きます。手のひらは向かい合うようになります。", "横になったら、ダンベルを肩の幅で体の前に動かします。", "肩幅になったら、手首を前方に回転させ、手のひらが外側を向くようにします。これが開始位置になります。", "息を吐きながら、ゆっくりとウェイトを体の横に下ろします。常にダンベルを完全に制御してください。ヒント: 動作全体を通じて、前腕は常に床に対して垂直である必要があります。", "息を吐きながら、胸筋を使ってダンベルを押し上げます。腕を縮めた位置に固定し、胸を圧迫し、1秒間保持してからゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Decline_Dumbbell_Bench_Press';
UPDATE exercises SET name = 'デクライン・ダンベル・フライ', instructions = '["デクラインベンチの端で両脚を固定し、両手にダンベルを抱えて横になり、太ももの上に置きます。手のひらは向かい合うようになります。", "横になったら、ダンベルを肩の幅で体の前に動かします。手のひらは向かい合って、腕は床に対して垂直になり、完全に伸びている必要があります。これが開始位置になります。", "上腕二頭筋の腱へのストレスを防ぐために肘を軽く曲げ、胸が伸びると感じるまで腕を両側から広い弧を描きながら下げます。動きのこの部分を実行するときに息を吸います。ヒント: 動きの間中、腕は静止したままにしておく必要があることに注意してください。動きは肩関節でのみ行われます。", "胸の筋肉を締めて息を吐きながら、腕を開始位置に戻します。ヒント: ウェイトを下げるときに使用したのと同じ円弧の動きを使用してください。", "収縮した位置で 1 秒間保持し、その動きを規定の回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Decline_Dumbbell_Flyes';
UPDATE exercises SET name = 'デクラインダンベルトライセップスエクステンション', instructions = '["デクラインベンチの端で両脚を固定し、両手にダンベルを抱えて横になり、太ももの上に置きます。手のひらは向かい合うようになります。", "横になったら、ダンベルを肩の幅で体の前に動かします。手のひらは向かい合って、腕は床に対して垂直になり、完全に伸びている必要があります。これが開始位置になります。", "息を吸いながら上腕を動かさず（肘を内側に）、親指が耳の横に来るまで前腕を自分に向かって半円を描くように動かし、ダンベルをゆっくりと下ろします。動きのこの部分を実行するときに息を吸います。", "上腕三頭筋を収縮させて息を吐きながら、ダンベルを持ち上げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Decline_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = 'デクライン EZ バー トライセプス エクステンション', instructions = '["下りベンチの端で足を固定し、ゆっくりとベンチに横になります。", "閉じたグリップ (肩幅よりわずかに狭いグリップ) を使用して、ラックから EZ バーを持ち上げ、腕を固定して肘を立ててまっすぐに持ちます。腕は床に対して垂直でなければなりません。これが開始位置になります。ヒント: 腱板を保護するために、バーベルをラックから持ち上げるのをスポッターに手伝ってもらうのが最善です。", "息を吸いながら上腕を動かさないようにしながら、バーが額に軽く触れるまで前腕を半円を描くように手前に動かし、ゆっくりとバーを下ろします。動きのこの部分を実行するときに息を吸います。", "上腕三頭筋を収縮させて息を吐きながら、バーを持ち上げて開始位置に戻します。", "推奨される繰り返し回数が実行されるまで繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Decline_EZ_Bar_Triceps_Extension';
UPDATE exercises SET name = 'デクライン・オブリーク・クランチ', instructions = '["下りベンチの端で足を固定し、ゆっくりとベンチに横になります。", "床から測って胴体が約 35 ～ 45 度になるまで上体をベンチから上げます。", "片方の手を頭の横に置き、もう片方の手を太ももに置きます。これが開始位置になります。", "開始位置から上体を左に回転させながらゆっくりと上体を起こします。右肘が左膝に触れるまで、息を吐きながらクランチを続けます。この収縮した位置を 1 秒間保持します。ヒント: 腹筋を引き締め、動きをゆっくりと制御することに集中してください。", "息を吸いながら、体をゆっくりと元の位置まで下げます。", "右側で 1 セットを推奨回数繰り返し完了したら、左側に切り替えます。ヒント: 上向きの姿勢で胴体を実際にひねり、収縮を感じることに集中してください。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Decline_Oblique_Crunch';
UPDATE exercises SET name = 'デクラインプッシュアップ', instructions = '["床にうつ伏せになり、手を約36インチ離して置き、胴体を腕の長さで持ち上げます。足をボックスやベンチまで上げます。これが開始位置になります。", "次に、息を吸いながら胸が床に着きそうになるまで体を下げます。", "次に、息を吐き、胸を絞りながら上半身を開始位置に戻します。", "一番上の収縮した位置で少し停止した後、再び体を下に下げ始め、必要なだけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Decline_Push-Up';
UPDATE exercises SET name = 'リバースクランチの減少', instructions = '["デクラインベンチに仰向けになり、両手でベンチの上部をつかみます。この位置から体がずり落ちないように注意してください。", "膝と足を合わせたまま、腹筋を使って脚を床と平行に保ちます。ヒント: 脚は完全に伸ばし、膝をわずかに曲げます。これが開始位置になります。", "息を吐きながら、骨盤を後方に回転させながら脚を胴体に向かって動かし、腰をベンチから上げます。この動きの終わりには、膝が胸に触れます。", "収縮を 1 秒間保持し、息を吸いながら脚を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Decline_Reverse_Crunch';
UPDATE exercises SET name = 'デクライン・スミス・プレス', instructions = '["スミスマシンの下にディクラインベンチを置きます。次に、横になって腕をほぼ完全に伸ばしたときに届く高さにバーベルを置きます。肩の幅よりも広い回内グリップを使用して、ラックからバーのロックを解除し、腕を伸ばした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、肘を曲げて胴体に軽く触れながら、コントロールしながらバーを下げます。", "少し停止した後、息を吐きながら肘を伸ばしてバーを開始位置に戻します。", "この動作を規定回数繰り返します。", "セットが完了したら、バーをラックにロックして戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Decline_Smith_Press';
UPDATE exercises SET name = '赤字デッドリフト', instructions = '["まず、通常は高さ 1 ～ 3 インチの、その上に立つことができるプラットフォームまたはウェイト プレートを用意します。バーが足の中心に来るようにバーに近づきます。足は腰幅程度に開く必要があります。腰を曲げて肩幅でバーを握り、肩甲骨を突き出します。通常、重いセットではオーバーハンド グリップまたはオーバー/アンダー グリップを使用します。", "足とグリップをセットした状態で、大きく息を吸い、腰を下げ、すねがバーに触れるまで膝を曲げます。頭を前に向け、胸を張り、背中を反らせた状態を保ち、かかとから体重を上に移動し始めます。バーが膝を通過したら、積極的にバーを後ろに引き、肩甲骨を寄せながら腰を前方にバーに押し込みます。", "腰を曲げてバーを床に誘導してバーを下げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Deficit_Deadlift';
UPDATE exercises SET name = '深度ジャンプ・リープ', instructions = '["このドリルには、高さ 12 ～ 16 インチの箱またはベンチが 2 つ必要で、もう 1 つは高さ 22 ～ 26 インチです。", "2 つのボックスのうちの 1 つの上に腕を両側に置いて立ちます。デプスジャンプの場合と同様に、足は揃えてエッジからわずかに離れる必要があります。もう 1 つのボックスを演奏者の約 2 ～ 3 フィート前に、演奏者の向きに置きます。", "最初のボックスを降ろし、着地し、両足で同時に離陸することから始めます。", "腕を最大限に使って体を最大限に伸ばして、より高いボックスに飛び乗って、できるだけ激しく上方と外側にドライブしてリバウンドします。もう一度、脚で衝撃を吸収させます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Depth_Jump_Leap';
UPDATE exercises SET name = 'ディップマシン', instructions = '["ディップマシンにしっかりと座り、重さを選択し、ハンドルをしっかりと握ります。", "ここで、上腕三頭筋に重点を置くために、肘を体の横に置いておきます。肘は90度の角度で曲げる必要があります。", "上腕三頭筋を収縮させながら、息を吐きながら腕を下に伸ばします。ヒント: 動きの最後では、腕を少し曲げて上腕三頭筋の緊張を保つことに集中してください。", "次に、息を吸いながらゆっくりと腕を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Dip_Machine';
UPDATE exercises SET name = 'ディップス - 胸バージョン', instructions = '["この演習では、平行棒にアクセスする必要があります。開始位置に入るには、腕の長さで体をバーの上に保持します (腕を固定した状態)。", "息を吸いながら、胸がわずかに伸びるのを感じるまで、上体を約 30 度前傾させ、肘をわずかに広げてゆっくりと体を下げます。", "ストレッチを感じたら、息を吐きながら胸を使って体を開始位置に戻します。ヒント: 動作の最初に胸を 1 秒間絞ることを忘れないでください。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Dips_-_Chest_Version';
UPDATE exercises SET name = 'ディップス - 上腕三頭筋バージョン', instructions = '["開始位置に入るには、腕をバーの上でほぼロックした状態で、体を腕の長さに保ちます。", "次に、息を吸いながらゆっくりと体を下に下げます。胴体は直立したままにし、肘を体の近くに置く必要があります。これは、上腕三頭筋の関与に焦点を当てるのに役立ちます。上腕と前腕の間に90度の角度が形成されるまで体を下げます。", "次に、息を吐きながら上腕三頭筋を使って上半身を押し上げ、体を開始位置に戻します。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Dips_-_Triceps_Version';
UPDATE exercises SET name = 'ロバの子牛を育てる', instructions = '["この演習を行うには、ロバの子牛を育てる機械にアクセスする必要があります。まず、腰と腰を付属のパッド付きレバーの下に置きます。尾骨部分がパッドと接触する部分である必要があります。", "両腕をサイドハンドルに置き、かかとを伸ばした状態で足の指の付け根をふくらはぎブロックに置きます。ターゲットしたい領域に応じてつま先を前方、内側、または外側に揃え、膝を固定せずにまっすぐにします。これが開始位置になります。", "息を吐きながらかかとを上げ、足首をできるだけ高く伸ばし、ふくらはぎを曲げます。膝が常に動かないように注意してください。いかなるときも曲げてはいけません。下がり始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げ、ふくらはぎが伸びるまで足首を曲げてゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Donkey_Calf_Raises';
UPDATE exercises SET name = 'ダブルケトルベル交互ハングクリーン', instructions = '["2つのケトルベルを足の間に置きます。開始位置に立つには、お尻を後ろに押し出し、まっすぐ前を見てください。", "一方のケトルベルを肩に当て、もう一方のケトルベルを持ちます。", "滑らかな動きで上のケトルベルを下げながら、下のケトルベルを押し上げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Double_Kettlebell_Alternating_Hang_Clean';
UPDATE exercises SET name = 'ダブルケトルベルジャーク', instructions = '["ケトルベルのハンドルを両手に持ちます。", "ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。これが開始位置になります。", "膝を曲げて体を沈め、胴体を直立状態に保ちます。", "すぐに方向を反転し、かかとを突き抜けてドライブし、本質的にはジャンプして勢いを生み出します。", "その際、腕を伸ばしてケトルベルを頭上に押し上げてロックアウトし、体の勢いを利用してウェイトを動かします。", "片足を前に、もう片足を後ろに、分割して足を地面に戻します。", "ウェイトを頭上に保ち、両足を揃えて立った姿勢に戻ります。次の繰り返しを実行するには、ウェイトを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Double_Kettlebell_Jerk';
UPDATE exercises SET name = 'ダブルケトルベルプッシュプレス', instructions = '["2 つのケトルベルを肩まできれいにします。", "数インチしゃがみ、動きを素早く逆にします。脚の勢いを利用してケトルベルを頭上に飛ばします。", "ケトルベルがロックアウトされたら、ケトルベルを肩まで下げ、これを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Double_Kettlebell_Push_Press';
UPDATE exercises SET name = 'ダブルケトルベルスナッチ', instructions = '["2つのケトルベルを足の後ろに置きます。膝を曲げて座ってケトルベルを持ち上げます。", "ケトルベルを脚の間で力強く振り、方向を逆にします。", "腰を使ってドライブし、途切れることのない動作でケトルベルを頭上に固定します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Double_Kettlebell_Snatch';
UPDATE exercises SET name = 'ダブルケトルベル風車', instructions = '["ケトルベルを前足の前に置き、反対側の腕でケトルベルを頭上で掃除して押します。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。", "ケトルベルを常にロックアウトした状態で、ロックアウトされたケトルベルの方向にお尻を押し出します。ケトルベルをロックアウトした状態で、足を腕から 45 度の角度で外に向けます。", "腰を片側に曲げ、お尻を突き出し、ケトルベルを床から取り出せるまでゆっくりと傾けます。頭の上にかざすケトルベルから常に目を離さないでください。", "ケトルベルを地面から回収した後、少し停止し、動きを逆にして開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Double_Kettlebell_Windmill';
UPDATE exercises SET name = 'ダブルレッグバットキック', instructions = '["膝を軽く曲げて立ち始めます。", "短い距離を素早くしゃがみ、腰と膝を曲げ、すぐに伸ばしてジャンプして垂直高さを最大にします。", "上がるときは、膝を曲げてかかとを押し込み、お尻に触れるようにします。", "膝を部分的に曲げた状態で着地し、脚を使って衝撃を吸収して動作を終了します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Double_Leg_Butt_Kick';
UPDATE exercises SET name = '下向きバランス', instructions = '["バランスボールの上にうつ伏せになります。", "ボールの上でうつ伏せになり、両手を床に沿って前に歩き、肘と膝を伸ばして足を上げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Downward_Facing_Balance';
UPDATE exercises SET name = 'ドラッグカール', instructions = '["回外グリップ（手のひらを前に向ける）でバーベルを掴み、肘を胴体と背中に近づけます。これが開始位置になります。", "息を吐きながら、肘を後ろに保ちながらバーを胴体に接触させて「引きずり」ながらバーを丸めます。ヒント: ご覧のとおり、肘を脇に固定したままにするのではなく、肘を元に戻します。また、肩を上げないでください。", "バーを常に胴体に接触させたまま、ゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Drag_Curl';
UPDATE exercises SET name = 'ドロッププッシュ', instructions = '["低いボックスやその他のプラットフォームを 2 ～ 3 フィート離して配置します。", "ボックスの間に手を置いて体を支えながら、その間の腕立て伏せの姿勢に移動します。", "正しい姿勢で手を上に押し上げて肩幅に動かしてプラットフォームから落下し、腕を通して衝撃を吸収することで着地を和らげます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Drop_Push';
UPDATE exercises SET name = 'ダンベルオルタネートバイセップカール', instructions = '["腕の長さでダンベルを両手に持ち（胴体を直立させ）立ちます。肘は胴体の近くに置き、手のひらは太ももの方を向くようにします。", "上腕を固定したまま、手のひらが前を向くまで回転させながら、適切なウェイトを曲げます。この時点で、上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで、息を吐きながら上腕二頭筋の収縮を続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。ヒント: 前腕のみを動かします。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。 ヒント: 降りるときに、手のひらをねじって開始位置 (太ももに面する) に戻すことを忘れないでください。", "左手でも同じ動きを繰り返します。これは 1 回の繰り返しに相当します。", "この方法を交互に推奨回数繰り返し続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Alternate_Bicep_Curl';
UPDATE exercises SET name = 'ダンベルベンチプレス', instructions = '["平らなベンチに横になり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "次に、太ももを使ってダンベルを持ち上げるのを助け、ダンベルを 1 つずつ持ち上げて、ダンベルを肩幅で前に持ちます。", "肩幅になったら、手首を前方に回転させ、手のひらが外側を向くようにします。ダンベルは胸のすぐ横に置き、上腕と前腕が 90 度の角度を作るようにします。常にダンベルを完全に制御できるようにしてください。これが開始位置になります。", "次に、息を吐きながら、胸を使ってダンベルを押し上げます。リフトの最上部で腕をロックし、胸を張り、1 秒間保持してからゆっくりと降り始めます。ヒント: 理想的には、ウェイトを下げるには、上げるよりも約 2 倍の時間がかかります。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Bench_Press';
UPDATE exercises SET name = 'ニュートラルグリップのダンベルベンチプレス', instructions = '["ダンベルを両手に持ち、平らなベンチに仰向けになります。足は床に平らに置き、肩甲骨を引っ込めます。", "ニュートラルなグリップを維持し、手のひらを向かい合わせにして、腕を真上に伸ばし、床に対して垂直にします。これが開始位置になります。", "肘を曲げて上腕を横に下げることから動きを始めます。ダンベルが胴体に着くまで降ります。", "一時停止し、肘を伸ばして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Bench_Press_with_Neutral_Grip';
UPDATE exercises SET name = 'ダンベルバイセップカール', instructions = '["ダンベルを両手に腕を伸ばした長さでまっすぐに立ちます。肘を胴体の近くに保ち、手のひらが前を向くまで回転させます。これが開始位置になります。", "次に、上腕を動かさないようにして、上腕二頭筋を収縮させながら、息を吐きながらウェイトを丸めます。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまでウェイトを上げ続けます。上腕二頭筋を締めながら、収縮した位置を少しの間保持します。", "次に、息を吸いながらゆっくりとダンベルを下げ始め、開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Bicep_Curl';
UPDATE exercises SET name = 'ダンベルクリーン', instructions = '["両手にダンベルを持ち、足を肩幅に広げて立ち始めます。", "ダンベルが床に着くまで腰を後ろに押しながら、腰と膝を曲げてウェイトを床に下ろします。これが開始位置になります。", "動きを開始するには、腰、膝、足首を伸ばして上向きに激しくジャンプし、ウェイトを上向きに加速させます。ダンベルをニュートラルなグリップで保ち、完全に伸びるまで腕をまっすぐに保ちます。", "完全に伸ばした後、腰と膝を曲げてスクワットの姿勢で体重を受けます。腕を曲げて、ダンベルを肩に導きます。", "スクワットの姿勢でウエイトを受けたら、腰と膝を伸ばして立った姿勢でウエイトを肩に置きます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Clean';
UPDATE exercises SET name = 'ダンベルフロアプレス', instructions = '["手にダンベルを持って床に横たわります。膝は曲げることができます。ウェイトを体の上に完全に伸ばした状態から始めます。", "上腕が床に触れるまでウェイトを下げます。肘を引いて上腕三頭筋のサイズと強さを強調したり、腕を横に傾けて胸に焦点を当てたりできます。", "一番下で停止し、肘を通って上に体重を乗せます。"]'::jsonb, category = 'パワーリフティング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Floor_Press';
UPDATE exercises SET name = 'ダンベルフライ', instructions = '["平らなベンチに横になり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "次に、太ももを使ってダンベルを持ち上げるのを手伝い、ダンベルを 1 つずつ持ち上げて、手のひらを向かい合わせにして肩幅で体の前に持ちます。ダンベルを押すように持ち上げますが、ロックアウトする直前に停止して保持します。これが開始位置になります。", "上腕二頭筋の腱へのストレスを防ぐために肘を軽く曲げ、胸が伸びると感じるまで腕を両側から広い弧を描きながら下げます。動きのこの部分を実行するときに息を吸います。ヒント: 動きの間中、腕は静止したままにしておく必要があることに注意してください。動きは肩関節でのみ行われます。", "胸の筋肉を締めて息を吐きながら、腕を開始位置に戻します。ヒント: ウェイトを下げるときに使用したのと同じ円弧の動きを使用してください。", "収縮した位置で 1 秒間保持し、その動きを規定の回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Flyes';
UPDATE exercises SET name = 'ダンベルインクラインロー', instructions = '["ニュートラルグリップを使用して、インクラインベンチに寄りかかります。", "ニュートラルなグリップでダンベルを両手に持ち、腕をまっすぐに伸ばします。これが開始位置になります。", "肩甲骨を引き込み、肘を曲げてダンベルを体の横に漕ぎます。", "動作の先頭で一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Incline_Row';
UPDATE exercises SET name = 'ダンベルインクラインショルダーレイズ', instructions = '["インクラインベンチに座り、両手にダンベルを持ち、太ももの上に置きます。", "脚を持ち上げて肩に重りを置き、後ろにもたれかかります。腕を伸ばしてダンベルを肩の上に置きます。腕は床に対して垂直になり、手のひらは前を向き、関節は天井を向くようにします。これが開始位置になります。", "腕をまっすぐにしてロックしたまま、息を吐きながら肩をベンチから上げてダンベルを持ち上げます。", "息を吸いながらダンベルを開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Incline_Shoulder_Raise';
UPDATE exercises SET name = 'ダンベルランジ', instructions = '["2 つのダンベルを両手に持ち、胴体を直立させて脇に置きます。これが開始位置になります。", "足を後ろに動かさずに右脚を約2フィート（約2フィート）ほど前方に踏み出し、胴体を直立させてバランスを保ちながら上体を下げます。下がりながら息を吸います。注: 他のエクササイズと同様に、膝関節に過度のストレスがかかるため、降りるときに膝がつま先よりも前に出ないように注意してください。前すねが地面に対して垂直になるようにしてください。", "主に足のかかとを使って押し上げ、息を吐きながら開始位置に戻ります。", "この動きを推奨回数繰り返した後、左脚で実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Lunges';
UPDATE exercises SET name = 'ダンベル ライイング ワンアーム リア ラテラル レイズ', instructions = '["片手にダンベルを持ち、わずかに傾斜した（床から測って約15度）調節可能なベンチに胸を下にして横になります。もう片方の手でベンチの脚を掴むと安定します。", "肘をわずかに曲げて腕を伸ばしたまま、ダンベルを持つ手の手のひらを中立的な姿勢（手のひらを胴体に向ける）に置きます。これが開始位置になります。", "次に、肘が肩の高さになり、息を吐きながら腕が床とほぼ平行になるまで、ダンベルを持った腕を横に上げます。ヒント: 動作中は腕を伸ばしたままにし、胴体に対して腕を垂直に保ちます。また、収縮を上部で 1 秒間続けてください。", "息を吸いながら、ダンベルを開始位置までゆっくりと下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Lying_One-Arm_Rear_Lateral_Raise';
UPDATE exercises SET name = 'ダンベル ライプロネーション', instructions = '["平らなベンチにうつ伏せになり、片方の腕でダンベルを持ち、もう一方の手をベンチの上で組んで頭をその上に置きます。", "ダンベルを持つ腕の肘を曲げ、上腕と前腕の間に90度の角度を作ります。", "次に、前腕が床に対して垂直になり、上腕が胴体に対して垂直になるように上腕を上げます。ヒント: 上腕は床と平行にし、胴体に対して 90 度の角度を作る必要があります。これが開始位置になります。", "息を吐きながら、上腕と前腕の間の 90 度の角度を維持しながら、ダンベルが前方に持ち上げられるように前腕を外側に回転させます。前腕が床と平行になるまでこの外旋を続けます。この時点で、収縮を 1 秒間保持します。", "息を吸いながら、ゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Lying_Pronation';
UPDATE exercises SET name = 'ダンベル ライイング リア ラテラル レイズ', instructions = '["両手にダンベルを持ち、わずかに傾斜した（床から測って約15度）調節可能なベンチに胸を下にして横になります。", "肘をわずかに曲げて腕を伸ばしたまま、手の平を中立的な姿勢（手のひらを胴体に向ける）に置きます。これが開始位置になります。", "次に、息を吐きながら肘が肩の高さになり、腕が床とほぼ平行になるまで腕を横に上げます。ヒント: 動作中は腕を胴体に対して垂直に保ち、腕を伸ばしたままにします。また、収縮を上部で 1 秒間続けてください。", "息を吸いながら、ゆっくりとダンベルを開始位置まで下げます。", "推奨回数だけ繰り返した後、もう一方の腕に切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Lying_Rear_Lateral_Raise';
UPDATE exercises SET name = 'ダンベル・ライイング・スピネーション', instructions = '["平らなベンチに横向きに寝て、片方の腕でダンベルを持ち、もう片方の手で頭をベンチの上に置きます。", "ダンベルを持つ腕の肘を曲げ、上腕と前腕の間に90度の角度を作ります。", "次に、前腕が床と平行になり、胴体に対して垂直になるように上腕を上げます (ヒント: そのため、前腕は体の真正面になります)。上腕は胴体の近くで静止し、床と平行になるようにします（常に胴体と一直線になるようにします）。これが開始位置になります。", "息を吐きながら、前腕を外側に回転させ、上腕と前腕の間の 90 度の角度を維持しながら、ダンベルが半円を描くように持ち上げます。前腕が床に対して垂直になり、胴体が天井を向くまでこの外旋を続けます。この時点で、収縮を 1 秒間保持します。", "息を吸いながら、ゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返した後、もう一方の腕に切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Lying_Supination';
UPDATE exercises SET name = 'ダンベルワンアームショルダープレス', instructions = '["ダンベルをつかみ、ミリタリー プレス ベンチまたは背もたれの付いたユーティリティ ベンチに座り、ダンベルを太ももの上に直立させて置くか、まっすぐに立ちます。", "ダンベルを肩の高さまで持ち上げます。もう一方の手は、腰をつかんだり固定面を掴んだりして、完全に横に伸ばしたままにすることができます。", "手のひらが前を向くように手首を回転させます。これが開始位置です。", "息を吐きながら、腕が完全に伸びるまでダンベルを押し上げます。", "2 回目の停止の後、息を吸いながらゆっくりと開始位置に戻ります。", "推奨回数繰り返した後、腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_One-Arm_Shoulder_Press';
UPDATE exercises SET name = 'ダンベルワンアームトライセップスエクステンション', instructions = '["ダンベルをつかみ、ミリタリー プレス ベンチまたは背もたれの付いたユーティリティ ベンチに座り、ダンベルを太ももの上に直立させて置くか、まっすぐに立ちます。", "ダンベルをきれいにして肩の高さまで上げ、腕全体が床と頭の横に垂直になるように腕を頭の上に伸ばします。ダンベルは体の上にあるはずです。もう一方の手は、腰を使って横に完全に伸ばしたままにして、ダンベルを持つ上腕を支えたり、固定面を掴んだりできます。", "手のひらが前を向き、小指が天井を向くように手首を回転します。これが開始位置になります。", "上腕を動かさないようにしながら、ダンベルを頭の後ろにゆっくりと下げます。この動きをしながら息を吸い、上腕三頭筋が完全に伸びたところで一時停止します。", "息を吐きながら上腕三頭筋を曲げて開始位置に戻ります。ヒント: 前腕のみを動かすことが重要です。上腕は常に頭の横に固定しておく必要があります。", "推奨回数繰り返し、腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_One-Arm_Triceps_Extension';
UPDATE exercises SET name = 'ダンベル ワンアーム アップライトロー', instructions = '["ダンベルを持ち、腕を前に伸ばし、肘を軽く曲げ、背中をまっすぐにして直立します。これが開始位置になります。ヒント: ダンベルは太ももの上に置き、手のひらを太ももに向けます。", "もう一方の手は、腰をつかんだり、固定面をつかんだりして、完全に横に伸ばしたままにすることができます。これが開始位置になります。", "息を吐きながら、横の肩を使ってダンベルを持ち上げます。ダンベルを上げていくときは、ダンベルを体に近づける必要があります。ダンベルが顎とほぼ一直線になるまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。ダンベルを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "ダンベルをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数繰り返し、腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_One-Arm_Upright_Row';
UPDATE exercises SET name = 'ダンベルプローンインクラインカール', instructions = '["両手にダンベルを持ち、インクラインベンチに仰向けになり、肩をインクラインの頂上近くに置きます。膝をシートの上に置くことも、足を横にまたぐこともできます (私の好みの方法です)。", "腕を伸ばして自然に前に垂らし、床と直角になるようにします。", "次に、肘を体の横に置き、手のひらを前に向けます。これが開始位置になります。", "腕が完全に曲がるまで上腕二頭筋を収縮させてダンベルを上げます。動きのこの部分を実行するときに息を吐き、前腕だけが動くことを確認します。上腕は常に静止したままにしておく必要があります。", "腕が完全に伸びるまでダンベルを下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Prone_Incline_Curl';
UPDATE exercises SET name = 'ダンベルレイズ', instructions = '["両腕にダンベルを持ち、両腕を体の横に伸ばし、肘を軽く曲げ、背中をまっすぐにして直立します。これが開始位置になります。ヒント: ダンベルは太ももの横に置き、手のひらを後ろに向けます。", "息を吐きながら、横の肩を使ってダンベルを持ち上げます。ダンベルを持ち上げるときは、ダンベルを体の横に置く必要があります。ダンベルが顎とほぼ一直線になるまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。ダンベルを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "ダンベルをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Raise';
UPDATE exercises SET name = 'ダンベルリアランジ', instructions = '["2 つのダンベルを両手に持ち、胴体を直立させて脇に置きます。これが開始位置になります。", "右足を左足から約2フィートほど後ろに踏み出し、上体を垂直に保ちバランスを保ちながら上体を下げます。下がりながら息を吸います。ヒント: 他のエクササイズと同様に、膝関節に過度のストレスがかかるため、降りるときに膝がつま先よりも前に出ないようにしてください。前すねが地面に対して垂直になるようにしてください。ランジ中は胴体を直立状態に保ちます。柔軟な股関節屈筋が重要です。長いランジは大殿筋を強調します。短いランジは大腿四頭筋を強調します。", "息を吐きながら押し上げて開始位置に戻ります。ヒント: 大腿四頭筋を強調するために、足の指の付け根を使って押します。臀部に集中するには、かかとで押します。", "今度は反対の足でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Rear_Lunge';
UPDATE exercises SET name = 'ダンベルスカプション', instructions = '["この矯正エクササイズは、肩甲骨を安定させる筋肉を強化します。両手に軽い重りを持ち、体の横にぶら下がります。親指は上を向いているはずです。", "中心から約 30 度ずれた位置で、腕を前に突き出す動作を開始します。この動作を行うときは、腕を完全に伸ばす必要があります。", "腕が地面と平行になるまで続けてから、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Scaption';
UPDATE exercises SET name = 'ダンベルシーテッドボックスジャンプ', instructions = '["ベンチの横に数フィートのところにボックスを置きます。ダンベルを両手で胸に当て、ボックスに向かってベンチに座ります。これが開始位置になります。", "両足を地面にしっかりと置き、前傾姿勢になり、腰と膝を伸ばして前方に飛び上がります。", "両足でボックスに着地し、腰と膝を曲げて衝撃を吸収します。", "降りて開始位置に戻ります。"]'::jsonb, category = 'プライオメトリクス', equipment = 'ダンベル' WHERE id = 'Dumbbell_Seated_Box_Jump';
UPDATE exercises SET name = 'ダンベルシーテッド片脚カーフレイズ', instructions = '["平らなベンチから約12インチの床にブロックを置きます。", "平らなベンチに座り、ダンベルを左太ももの膝から約3インチ上に置きます。", "次に、左足の指の付け根をブロックの上に置きます。これが開始位置になります。", "息を吐きながらつま先をできるだけ高く上げ、ふくらはぎの筋肉を収縮させます。収縮を 1 秒間保持します。", "ゆっくりと開始位置に戻り、できるだけ下に伸ばします。", "規定の回数繰り返した後、右脚でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Seated_One-Leg_Calf_Raise';
UPDATE exercises SET name = 'ダンベルショルダープレス', instructions = '["両手にダンベルを持ち、背中をサポートするミリタリー プレス ベンチまたはユーティリティ ベンチに座ります。ダンベルを太ももの上に直立させます。", "次に、太ももを使ってダンベルを 1 つずつ肩の高さまで上げ、所定の位置に押し上げます。", "手のひらが前を向くように手首を回転させるようにしてください。これが開始位置です。", "次に、息を吐きながらダンベルを上部に触れるまで押し上げます。", "次に、一番上の収縮位置で少し停止した後、息を吸いながらゆっくりとウェイトを開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Shoulder_Press';
UPDATE exercises SET name = 'ダンベルをすくめます', instructions = '["ダンベルを両手に持ち（手のひらを胴体に向けて）直立し、腕を横に伸ばします。", "息を吐きながら肩をできるだけ高く上げてダンベルを持ち上げます。上部の収縮を 1 秒間保持します。ヒント: 腕は常に伸ばしたままにしてください。ダンベルを持ち上げるために上腕二頭筋を使用しないでください。肩だけが上下に動くはずです。", "ダンベルを元の位置に下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Shrug';
UPDATE exercises SET name = 'ダンベルサイドベンド', instructions = '["左手でダンベルを持ち（手のひらを胴体に向けて）、右手で腰を持ちながらまっすぐに立ちます。足は肩幅に置く必要があります。これが開始位置になります。", "背中をまっすぐにして頭を上げた状態で、腰だけをできるだけ右に曲げます。息を吸いながら横に曲がります。次に、少しの間保持し、息を吐きながら開始位置に戻ります。ヒント: 体の残りの部分は動かさないでください。", "次に、代わりに左に曲げてこの動きを繰り返します。しばらく待って、開始位置に戻ります。", "推奨回数繰り返した後、手を変えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Side_Bend';
UPDATE exercises SET name = 'ダンベルスクワット', instructions = '["両手にダンベルを持ちながらまっすぐに立ちます（手のひらは足の側面に向けます）。", "足を肩幅の中くらいの幅でスタンスをとり、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。注: この説明では、全体的な開発をターゲットとする上記の中程度のスタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択できます。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げて胴体をゆっくりと下げ始めます。太ももが床と平行になるまで下げ続けます。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながら胴体を上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Squat';
UPDATE exercises SET name = 'ベンチに向かってダンベルスクワット', instructions = '["両手にダンベルを持ち（手のひらを足の側面に向けて）、フラットベンチを後ろにしてまっすぐに立ちます。", "足を肩幅の中くらいの幅でスタンスをとり、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。注: この説明では、全体的な開発をターゲットとする上記の中程度のスタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択できます。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げて胴体をゆっくりと下げ始めます。後ろのベンチに少し触れるまで下り続けます。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながらバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Squat_To_A_Bench';
UPDATE exercises SET name = 'ダンベルステップアップ', instructions = '["両手にダンベルを持ちながらまっすぐに立ちます（手のひらは足の側面に向けます）。", "右足を高いプラットフォームに置きます。右脚の股関節と膝を伸ばして台を踏みます。主にかかとを使って体の残りの部分を持ち上げ、左足の足も台の上に置きます。息を吐きながら、上に上がるために必要な力を出します。", "息を吸いながら右脚の股関節と膝を曲げて左脚を踏み込みます。右足を左足の隣に置き、元の立ち位置に戻ります。", "右脚で推奨回数だけ繰り返し、次に左脚で実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Step_Ups';
UPDATE exercises SET name = 'ダンベル トライセップ エクステンション - プロネーション グリップ', instructions = '["平らなベンチに横になり、肩の真上に 2 つのダンベルを置きます。腕を完全に伸ばし、胴体と床に対して 90 度の角度を形成する必要があります。", "手のひらは前を向き、肘は内側に引き込む必要があります。これが開始位置になります。", "次に、息を吸いながらダンベルを耳の近くまでゆっくりと下げます。上腕を動かさず、肘を内側に引き込むようにしてください。", "次に、息を吐きながら上腕三頭筋を使って体重を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Dumbbell_Tricep_Extension_-Pronated_Grip';
UPDATE exercises SET name = 'ダイナミックバックストレッチ', instructions = '["足を肩幅に開いて立ちます。これが開始位置になります。", "腕を真っすぐに伸ばしたまま、5～10回腕を前にまっすぐ振り上げ、そのたびに腕が頭の上に来るまで可動範囲を広げます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Dynamic_Back_Stretch';
UPDATE exercises SET name = 'ダイナミックチェストストレッチ', instructions = '["両手を合わせて立ち、腕を体の真前に伸ばします。これが開始位置になります。", "腕をまっすぐに伸ばしたまま、大げさに拍手をする動作と同じように、腕をできるだけ後ろに素早く動かし、再び元に戻します。 5〜10回繰り返し、回数を重ねるごとに速度を上げていきます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Dynamic_Chest_Stretch';
UPDATE exercises SET name = 'EZバーカール', instructions = '["幅広のアウターハンドルにEZカールバーを持ち、まっすぐに立ちます。バーの形状により、手のひらは前を向き、わずかに内側に傾ける必要があります。肘を胴体に近づけてください。これが開始位置になります。", "次に、上腕を固定したまま、息を吐きながらウェイトを前方に丸めながら上腕二頭筋を収縮させます。前腕を動かすことだけに集中してください。", "上腕二頭筋が完全に収縮し、バーが肩の高さになるまでウェイトを上げ続けます。上部の収縮した位置をしばらく保持し、上腕二頭筋を締めます。", "次に、息を吸いながらゆっくりとバーを下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'EZ-Bar_Curl';
UPDATE exercises SET name = 'EZバー スカルクラッシャー', instructions = '["しっかりと握って EZ バーを持ち上げ、ベンチに横たわった状態で肘を内側に入れて保持します。腕は床に対して垂直になるようにしてください。これが開始位置になります。", "上腕を固定したまま、肘を曲げてバーを下げます。動きのこの部分を実行するときに息を吸います。バーが額の真上に来たら一時停止します。", "肘を伸ばして息を吐きながら、バーを持ち上げて開始位置に戻します。", "繰り返す。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'EZ-Bar_Skullcrusher';
UPDATE exercises SET name = 'エルボーサークル', instructions = '["足を少し開いて座ったり立ったりします。", "手を肩に置き、肘を肩の高さにして外側を指します。", "肘でゆっくりと円を描きます。サークルを開始するときに息を吐き、サークルを完了するときに息を吸います。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Elbow_Circles';
UPDATE exercises SET name = '肘から膝まで', instructions = '["床に横になり、右足を曲げた左膝の上に交差させます。肩甲骨を地面につけて、頭の後ろで手を組みます。これが開始位置になります。", "背骨を曲げ、胴体を回転させて左肘を右膝に近づける動作を実行します。", "開始位置に戻り、必要な回数だけ動きを繰り返してから、サイドを切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Elbow_to_Knee';
UPDATE exercises SET name = 'エルボーバック', instructions = '["まっすぐに立ちなさい。", "両手を腰に置き、指を下に向け、肘を外側に置きます。", "次に、両肘が触れ合うようにゆっくりと肘​​を後ろに引きます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Elbows_Back';
UPDATE exercises SET name = 'エレベーテッド・バック・ランジ', instructions = '["適切な重量を負荷した肩の高さでバーをラックに置きます。短く盛り上がった台を後ろに置きます。", "バーを背中上部に掛けて、背中をアーチ型に保ち、引き締まった状態に保ちます。両足で高くなったプラットフォームに乗ります。これが開始位置になります。", "片足を後ろに踏み出すことから始めます。膝が床につくまで腰と膝を曲げて降ります。", "一時停止し、腰と膝を伸ばして起き上がり、開始位置まで戻ってから交互に行います。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Elevated_Back_Lunge';
UPDATE exercises SET name = '高架ケーブル列', instructions = '["高さ約 4 ～ 6 インチの何らかのプラットフォーム (エアロビクス プラットフォームやカーフレイズ プラットフォームなど) を用意します。", "ケーブルローイングマシンのシートに置きます。", "マシンに座り、膝が軽く曲がって固定されていないことを確認しながら、前部のプラットフォームまたはクロスバーに足を置きます。", "背中の自然な位置を保ちながら前かがみになり、V バーのハンドルを握ります。", "腕を伸ばした状態で、胴体が脚から 90 度の角度になるまで後ろに引きます。背中はわずかにアーチ状になり、胸が突き出るようになります。バーを前に持つと、広背筋が気持ちよく伸びているのが感じられるはずです。これがエクササイズの開始位置です。", "胴体を動かさないようにして、腹部に触れるまで腕を胴体に近づけたまま、ハンドルを胴体の方に引きます。その動きをしながら息を吐きます。この時点で、背中の筋肉を強く締める必要があります。収縮を 1 秒間保持し、息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Elevated_Cable_Rows';
UPDATE exercises SET name = 'エリプティカルトレーナー', instructions = '["まず、楕円形に乗り、メニューから目的のオプションを選択します。ほとんどのエリプティカルには手動設定があり、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。高度を調整してワークアウトの強度を変更できます。", "ハンドルを使用して心拍数を監視し、適切な強度を維持することができます。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Elliptical_Trainer';
UPDATE exercises SET name = 'エクササイズボールクランチ', instructions = '["バランスボールの上に横になり、腰の湾曲をボールの球面に押し付けます。足は膝を曲げて床にしっかりと押し付けます。上半身はボールの上部からぶら下がっている必要があります。腕は体の横に置くか、胸の上で交差させる必要があります。これらの位置は首の負担を避けるためです（手を頭の後ろに置く位置ではなく）。", "胴体を下げてストレッチ位置にし、首を常に動かさないようにします。これが開始位置になります。", "腰を動かさず、腹部を収縮させて腰を曲げ、腹部が心地よい収縮を感じるまで肩と体幹を上向きに丸めます。腕を横にしている場合は腕を脚の横にスライドさせ、腕を交差している場合は胸の上に置くだけです。腰は常にボールに触れている必要があります。この動きを行うときに息を吐き、収縮を 1 秒間保持します。", "息を吸いながら、開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Exercise_Ball_Crunch';
UPDATE exercises SET name = 'エクササイズボールプルイン', instructions = '["バランスボールを近くに置き、その前の床に横たわり、腕立て伏せの姿勢で両手を肩幅に開きます。", "次に、すねの下をバランスボールの上に置きます。ヒント: この時点で、すねをボールの上に置いて脚を完全に伸ばし、上半身は前に伸ばした 2 本の腕で支えながら腕立て伏せのような姿勢をとる必要があります。これが開始位置になります。", "背中を完全に真っ直ぐにして上半身を動かさないようにしながら、息を吐きながら膝を胸に引き寄せ、ボールが足首の下で前方に転がるようにします。腹筋を締めてその位置を 1 秒間保持します。", "次に、ゆっくりと足を伸ばし、息を吸いながらボールを​​開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Exercise_Ball_Pull-In';
UPDATE exercises SET name = '拡張レンジ ワンアーム ケトルベル フロア プレス', instructions = '["床に横になり、片腕でケトルベルを押しられる位置に置きます。ケトルベルはハンドルを持って持つ必要があります。押しているのと同じ側の脚を曲げ、膝が体の正中線を超えるようにします。", "肘を伸ばして腕を内転させてケトルベルを体の上に押し付けます。開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Extended_Range_One-Arm_Kettlebell_Floor_Press';
UPDATE exercises SET name = '外部回転', instructions = '["平らなベンチに横向きに寝て、片方の腕でダンベルを持ち、もう一方の手をベンチの上で組んで頭をその上に置きます。", "ダンベルを持つ腕の肘を曲げ、上腕と前腕の間に90度の角度を作ります。ヒント: 腕を胴体と平行に保ちます。", "次に、上腕を固定したまま肘を曲げます。このようにして、前腕は床と平行になり、胴体に対して垂直になります (ヒント: したがって、前腕は体の真正面になります)。上腕は胴体の近くで静止し、床と平行になるようにします（常に胴体と一直線になるようにします）。これが開始位置になります。", "息を吐きながら、前腕を外側に回転させ、上腕と前腕の間の 90 度の角度を維持しながら、ダンベルが半円を描くように持ち上げます。前腕が床に対して垂直になり、胴体が天井を向くまでこの外旋を続けます。この時点で、収縮を 1 秒間保持します。", "息を吸いながら、ゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返した後、もう一方の腕に切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'External_Rotation';
UPDATE exercises SET name = 'バンドによる外回転', instructions = '["バンドをポストに巻き付けてチョークします。バンドは肘と同じ高さにある必要があります。バンドから数フィート離れたところに左側を向けて立ちます。", "右手でバンドの端をつかみ、肘を体の横にしっかりと押し付けたままにします。パッドまたはフォームロールを肘で所定の位置に保持し、所定の位置にしっかりと保持することをお勧めします。", "上腕を所定の位置に置き、肘を 90 度に曲げ、手を胴体の前面に伸ばします。これが開始位置になります。", "肘を所定の位置に保ちながら、バックハンドの動きで腕を回転させることでこの動きを実行します。", "できる限り続けて、一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'External_Rotation_with_Band';
UPDATE exercises SET name = 'ケーブルによる外旋', instructions = '["ケーブルを肘と同じ高さに調整します。バンドから数フィート離れたところに左側を向けて立ちます。", "右手でハンドルを握り、肘を体の横にしっかりと押し付けたままにします。パッドまたはフォームロールを肘で所定の位置に保持し、所定の位置にしっかりと保持することをお勧めします。", "上腕を所定の位置に置き、肘を 90 度に曲げ、手を胴体の前面に伸ばします。これが開始位置になります。", "肘を所定の位置に保ちながら、バックハンドの動きで腕を回転させることでこの動きを実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'External_Rotation_with_Cable';
UPDATE exercises SET name = 'フェイスプル', instructions = '["ロープまたは二重ハンドルが取り付けられた高い滑車に面し、両手を離しながら重りを直接顔に向けて引っ張ります。上腕を地面と平行に保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Face_Pull';
UPDATE exercises SET name = 'ファーマーズ ウォーク', instructions = '["農家歩きに使用できるさまざまな道具があります。これらの器具が利用できない場合は、重いダンベルや短いバーを使って行うこともできます。まずは器具の間に立つことから始めます。", "ハンドルを握った後、背筋をまっすぐにして頭を上げたまま、かかとを通ってハンドルを持ち上げます。", "短く素早い歩数で歩き、呼吸を忘れないようにしましょう。指定された距離 (通常は 50 ～ 100 フィート) をできるだけ早く移動します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Farmers_Walk';
UPDATE exercises SET name = '高速スキップ', instructions = '["片足を少し前に出してリラックスした姿勢から始めます。これが開始位置になります。", "右→右ステップ、左→左ステップなどのステップホップパターンを前後に交互に実行することでスキップします。", "地面との密着を維持して高速スキップを実行し、滞空時間を短縮し、できるだけ早く移動します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Fast_Skipping';
UPDATE exercises SET name = 'フィンガーカール', instructions = '["両手でバーベルを持ち、手のひらを上に向けます。両手は肩幅くらいに開きます。", "両足を床に平らに置き、肩幅よりわずかに広めの距離に置きます。これが開始位置になります。", "指を伸ばしてバーをできるだけ下げます。バーを手の上に転がしながら、指の最後の関節でバーをキャッチします。", "次に、息を吐きながら手を閉じて、バーをできるだけ高く上げます。上部の収縮を保持します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Finger_Curls';
UPDATE exercises SET name = 'フラットベンチケーブルフライ', instructions = '["2 つの低い滑車の間にフラットベンチを置き、その上に横たわったときに胸とケーブル滑車が一直線になるようにします。", "ベンチに平らに寝て、足を地面に置きます。", "誰かに両手のハンドルを渡してもらいます。手のひらを上にしてグリップを握って、ハンドル アタッチメントをそれぞれ握ります。", "肘を軽く曲げて腕を体の横に伸ばします。ヒント: この曲げは動作全体を通じて一定に保ちます。腕は床と平行になるようにしてください。これが開始位置です。", "次に、動きの頂点で両手が合うまでケーブルを一緒に引っ張り、体の真前で半円を描くように腕を持ち上げ始めます。この動作を実行するときに胸を絞り、この動作中に息を吐きます。また、上部で収縮を 1 秒間保持します。ヒント: この動作を正しく実行すると、この動作のトップの位置で腕が胴体に対して垂直になり、床が胸の上に触れるはずです。", "ゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Flat_Bench_Cable_Flyes';
UPDATE exercises SET name = 'フラットベンチレッグプルイン', instructions = '["エクササイズマットまたは平らなベンチの上に足を端から離して横になります。", "手を臀筋の下に置き、手のひらを下にするか、ベンチをつかんで脇に置きます（または手のひらを下にしてエクササイズマットの横に置きます）。足も真っすぐに伸ばします。これが開始位置になります。", "膝を曲げ、息を吐きながら太ももの上部を中央部に引き寄せます。膝が胸の近くに来るまでこの動きを続けます。収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Flat_Bench_Leg_Pull-In';
UPDATE exercises SET name = 'フラットベンチ ライイングレッグレイズ', instructions = '["ベンチに背中を平らにして横になり、脚を端から前に伸ばします。", "手を臀部の下に置き、手のひらを下にするか、ベンチを握りながら脇に置きます。これが開始位置になります。", "脚を伸ばしたまま、膝を少し曲げて固定し、床に対して 90 度の角度になるまで脚を上げます。動きのこの部分を実行するときに息を吐き、上部の収縮を 1 秒間保持します。", "次に、息を吸いながら、ゆっくりと脚を下げて開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Flat_Bench_Lying_Leg_Raise';
UPDATE exercises SET name = '屈筋インクライン ダンベル カール', instructions = '["ダンベルを自分から遠い側に向けて持ち、自分に近い側により多くの重量がかかるようにします。 （これは、すべての上腕二頭筋ダンベルエクササイズに良い効果をもたらすために行うことができます）。次に、通常のインクライン ダンベル カールを行いますが、手首にかかるストレスを中和するために手首をできるだけ後ろに保ちます。", "両手にダンベルを持ち、45度の角度のインクラインベンチに座ります。", "肘を内側にして腕を体の横に下げ、親指を体から離れる方向に向けて手のひらを前に向けます。ヒント: 手を上げていくときに手をひねってはいけないので、動作中はこの手の位置を維持します。これが開始位置になります。", "上腕二頭筋が完全に収縮して息を吐き出すまで、2 つのダンベルを同時に丸めます。ヒント: 腕を振ったり、勢いをつけたりしないでください。常に制御された動きを維持してください。上部で収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Flexor_Incline_Dumbbell_Curls';
UPDATE exercises SET name = 'フロアグルートハムレイズ', instructions = '["このエクササイズにはパートナーと一緒に行ったり、安定したものの下で足を支えたりすることができます。", "膝をつき、脚と胴体を直立させて始めます。パートナーを使用すると、足をしっかりとホールドして正しい位置を保ちます。これが開始位置になります。", "前に進むときに股関節を曲げないように注意しながら、膝を伸ばして体を下げます。", "床に着いたら手を前に置きます。この動きは非常に難しく、自力ではできないかもしれません。腕を使って床を軽く押し、開始位置に戻りやすくします。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Floor_Glute-Ham_Raise';
UPDATE exercises SET name = 'フロアプレス', instructions = '["バーをラックに掛けるのに適切な高さになるように J フックを調整します。床に横になり、頭をパワーラックの端近くに置きます。肩甲骨を寄せたままにします。バーをフックから外します。", "バーを胸の底またはお腹の上の方に下げ、バーを握りながらバーを引き離そうとします。動作中は必ず肘を引いてください。上腕が地面に接触するまでバーを下げて停止し、重量がぶつかったり跳ねたりしないようにします。", "バー、手首、肘を一直線に保ちながら、できるだけ早くバーを押し上げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Floor_Press';
UPDATE exercises SET name = 'チェーン付きフロアプレス', instructions = '["バーをラックに掛けるのに適切な高さになるように J フックを調整します。この演習では、チェーンをバーの端に直接掛け、端がプレートから遠ざかるようにします。", "床に横になり、頭をパワーラックの端近くに置きます。肩甲骨を寄せたまま、バーをフックから外します。", "バーを胸の底またはお腹の上の方に下げ、バーを握りながらバーを引き離そうとします。動作中は必ず肘を引いてください。上腕が地面に接触するまでバーを下げて停止し、重量がぶつかったり跳ねたりしないようにします。", "バー、手首、肘を一直線に保ちながら、できるだけ早くバーを押し上げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Floor_Press_with_Chains';
UPDATE exercises SET name = 'フラッターキック', instructions = '["平らなベンチの上にうつ伏せになり、腰をベンチの端に置き、足をまっすぐに伸ばし、つま先を床から高く上げ、腕をベンチの上に置き、前端をつかみます。", "臀筋とハムストリングスを締め、脚が腰と同じ高さになるまでまっすぐにします。これが開始位置になります。", "左脚を右脚よりも高く持ち上げて動きを開始します。", "次に、右脚を上げながら左脚を下げます。", "各脚で推奨回数を繰り返すまで、この方法を交互に繰り返します (水中でバタ足キックをしているかのように)。常に制御された動きを保つようにしてください。ヒント: この動作を行うときは、通常通りに呼吸します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Flutter_Kicks';
UPDATE exercises SET name = 'フットSMR', instructions = '["このエクササイズは足の筋肉の筋膜を伸ばします。靴を脱いで座った状態から始めます。フット ローラーや、PVC パイプの小さな部分などの同様の物体を使用して、土踏まず全体に足をローラーに当てます。これが開始位置になります。", "足の土踏まずを横切ってしっかりと押し込みます。 10〜30秒間保持してから、足を入れ替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Foot-SMR';
UPDATE exercises SET name = '押しながら前方にドラッグ', instructions = '["デュアルハンドルチェーンまたはロープアタッチメントをスレッドに取り付けます。そりから背を向けて、両手にハンドルを持ちます。", "一歩前進することから動きを始めます。前かがみになり、脚と腰を伸ばして動き、一歩ごとに立ち止まって肘を伸ばし、手を前に押します。押す準備ができている開始位置に戻るまで前に進みます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Forward_Drag_with_Press';
UPDATE exercises SET name = 'フランケンシュタイン スクワット', instructions = '["このドリルは、クリーンスクワットとフロントスクワット中にバーと体の両方の正しい位置を教えます。", "バーベルを肩の前に置き、グリップを放し、腕を前に伸ばします。肩を前に押し出して棚を作り、バーが喉に触れるようにします。肩甲骨を前方に動かすだけにしてください。胸椎を丸めないでください。", "両脚の間に座り、膝と股関節を曲げてスクワットします。胴体を直立させ、腕を上げ、肩を前に出すと、バーは所定の位置に留まります。ハムストリングスがふくらはぎに接触するまで、スクワットの最下部まで進みます。", "かかとの前を通って膝と腰を伸ばして直立姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Frankenstein_Squat';
UPDATE exercises SET name = 'フリーハンドジャンプスクワット', instructions = '["胸の上で腕を交差させます。", "頭を上げて背筋を伸ばし、足を肩幅に置きます。", "背中をまっすぐにして胸を張ったまま、太ももの上部が床と平行になるか、より低くなるまで、息を吸いながらしゃがみます。", "主に足の指の付け根を使って押し、太ももをバネのように使って、できるだけ高く空中に真っすぐにジャンプします。動きのこの部分で息を吐きます。", "再び床に触れたら、すぐにしゃがみ、再びジャンプします。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Freehand_Jump_Squat';
UPDATE exercises SET name = 'カエルホップ', instructions = '["手を頭の後ろで組んで立ち、胴体を直立させ、頭を上げた状態でしゃがみます。これが開始位置になります。", "不必要に高くジャンプしないように、数フィート前にジャンプします。足が地面に着くと、足で衝撃を吸収し、再びジャンプします。この動作を5〜10回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Frog_Hops';
UPDATE exercises SET name = 'カエルの腹筋運動', instructions = '["床（またはエクササイズマット）に背中を平らにして横になり、足を前に伸ばします。", "次に、膝を曲げて、足の裏を互いに接触させながら、太ももの外側を床（またはマット）の横に置きます。", "次に、太ももの外側を床につけたまま（または少なくとも床にほとんど触れたまま）、両方の足の裏を押してできるだけ近くに引き上げてみましょう。ヒント: この位置では、脚がひし形の形を作るはずです。", "次に、反対側の肩に触れて腕を前に交差させます。これが開始位置になります。", "息を吐きながら腰を床に平らにし、胴体を上に丸めます。ヒント: これは、腹筋運動の最初の 1/4 の動作を実行するようなものです。上の位置で 1 秒間保持します。", "息を吸いながら、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Frog_Sit-Ups';
UPDATE exercises SET name = 'フロントバーベルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、肘を高く保ち、上腕を床と平行にわずかに上に保ちながら、腕をバーの下に上げます。バーを三角筋の上に置き、バーを握りながら腕を交差させて完全にコントロールします。", "最初に脚で押し、同時に胴体をまっすぐにしてバーをラックから持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足の位置のセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら主に足の中央で床を押してバーを上げ始め、再び足を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Front_Barbell_Squat';
UPDATE exercises SET name = 'ベンチに向かってフロントバーベルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、フラットベンチを後ろに置き、自分の身長に最も適したラックにバーを置きます。適切な高さを選択し、バーに負荷をかけたら、肘を高く保ち、上腕を床と平行にわずかに上に保ちながら、腕をバーの下に上げます。バーを三角筋の上に置き、バーを握りながら腕を交差させて完全にコントロールします。", "最初に脚で押し、同時に胴体をまっすぐにしてバーをラックから持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足の位置のセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。お尻がベンチに触れるまで下り続けます。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら主に足のかかとで床を押してバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Front_Barbell_Squat_To_A_Bench';
UPDATE exercises SET name = 'フロントボックスジャンプ', instructions = '["まず、目の前 1 ～ 2 フィートに適切な高さの箱を置きます。足を幅に広げて立ちます。これが開始位置になります。", "ジャンプの準備として短いスクワットを行い、腕を後ろに振ります。", "この位置からリバウンドし、腰、膝、足首を伸ばしてできるだけ高くジャンプします。腕を前と上に振ります。", "膝を曲げてボックスに着地し、足で衝撃を吸収します。ボックスからジャンプして地面に戻ることもできますが、できれば片足ずつ降りることもできます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Front_Box_Jump';
UPDATE exercises SET name = 'フロントケーブルレイズ', instructions = '["ロープーリーマシンのウェイトを選択し、左手でロープーリーに取り付けられている片手ケーブルアタッチメントを握ります。", "プーリーから背を向けて腕をまっすぐ下ろし、ハンド ケーブル アタッチメントを太ももの前に腕の長さで置き、手のひらを太ももに向けます。これが開始位置になります。", "胴体を静止したまま（スイングしないように）、肘を軽く曲げて左腕を前に持ち上げ、手のひらは常に下を向きます。腕が床と平行になるまで上げ続けます。動きのこの部分を実行するときに息を吐き、頂点で 1 秒間停止します。", "次に、息を吸いながら腕をゆっくりと元の位置まで下げます。", "この腕で推奨回数をすべて実行したら、腕を切り替えて正しい腕でエクササイズを実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Front_Cable_Raise';
UPDATE exercises SET name = 'フロントコーンホップ（またはハードルホップ）', instructions = '["コーンまたはその他の小さなバリアを数フィート離して一列に設置します。", "足を肩幅に開き、最初のコーンの前に立ちます。これが開始位置になります。", "最初のコーンの上で両足でジャンプし、ジャンプしながら両腕を振ります。", "膝を曲げて着地の衝撃を吸収し、最初の跳躍から次のコーンを飛び越えてリバウンドします。", "すべてのコーンを飛び越えるまで続けます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Front_Cone_Hops_or_hurdle_hops';
UPDATE exercises SET name = 'フロントダンベルレイズ', instructions = '["ダンベルを 2 つ選び、胴体をまっすぐにして立ち、ダンベルを腕の長さで太ももの前に置き、手のひらを太ももに向けます。これが開始位置になります。", "胴体を静止したまま（スイングしないように）、肘を軽く曲げ、手のひらを常に下に向けて左のダンベルを前に持ち上げます。腕が床と平行になるまで上げ続けます。動きのこの部分を実行するときに息を吐き、頂点で 1 秒間停止します。 2回目の一時停止の後に息を吸います。", "次に、ダンベルをゆっくりと開始位置まで下げ、同時に右のダンベルを持ち上げます。", "各腕で推奨される繰り返し回数がすべて完了するまで、この方法で交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Front_Dumbbell_Raise';
UPDATE exercises SET name = 'フロントインクラインダンベルレイズ', instructions = '["両手にダンベルを持ち、傾斜を30度から60度に設定したインクラインベンチに座ります。ヒント: 筋肉に当てる角度を毎回少しずつ変えることができます。", "腕を前にまっすぐ伸ばし、手のひらを下に向け、ダンベルを太ももの約1インチ上に上げます。これが開始位置になります。", "肘を固定したまま、ダンベルを肩の少し上までゆっくりと真っすぐに上げます。上部を 1 秒間締めて、動きのこの部分で息を吐き出すようにしてください。ヒント: 常に頭をベンチに置き、足を床に置いてください。", "息を吸いながら腕を最初の位置に下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Front_Incline_Dumbbell_Raise';
UPDATE exercises SET name = '前足上げ', instructions = '["椅子またはその他のサポートの隣に立ち、片手でつかみます。", "脚をまっすぐに保ちながら、脚を前に振ります。ダウンスイングを続けて、柔軟性が許す限り脚を後ろに下げます。 5～10回繰り返したら、足を入れ替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Front_Leg_Raises';
UPDATE exercises SET name = 'フロントプレートレイズ', instructions = '["まっすぐに立った状態で、バーベルプレートの3時と9時の位置を両手で持ちます。手のひらは向かい合って、腕を伸ばして肘を軽く曲げて固定し、プレートを腰の近くで前方にできる限り下げます。ヒント: エクササイズ中は腕はこの位置に留まります。これが開始位置になります。", "息を吐きながら、プレートが肩の高さの少し上になるまでゆっくりとプレートを上げます。収縮を 1 秒間保持します。ヒント: ウェイトを振り回したり、肘を曲げたりしないように注意してください。動きの間中、胴体も静止したままにする必要があります。", "息を吸いながら、ゆっくりとプレートを元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Front_Plate_Raise';
UPDATE exercises SET name = 'フロントレイズとプルオーバー', instructions = '["平らなベンチに横になり、手のひらを下にしてグリップを約15インチ離してバーベルを持ちます。", "バーを太ももの上に置き、肘を軽く曲げたまま腕を伸ばしてロックします。これが開始位置になります。", "次に、半円を描くように体重を上げ、息を吸いながら腕をまっすぐに保ちます。バーが反対側の頭の上に来るまで、同じ動きを続けます。 (ヒント: バーは約 180 度移動します)。この時点で、腕は床と平行になり、手のひらは天井に向けられます。", "次に、息を吐きながら動作を逆にして、バーベルを開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Front_Raise_And_Pullover';
UPDATE exercises SET name = 'フロントスクワット（クリーングリップ）', instructions = '["まず、バーを肩の高さより少し下のラックにセットします。バーを三角筋の上に置き、鎖骨を押し込み、喉に軽く触れます。手はきれいに握り、バーを所定の位置に保つために指だけでバーに触れてください。", "最初に脚で押し、同時に胴体をまっすぐにしてバーをラックから持ち上げます。ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。常に頭と肘を上げておいてください。これが開始位置になります。", "膝を曲げて脚の間に座ります。ハムストリングスがふくらはぎの上に来るまで下げ続けます。しゃがむときに外転筋を意識的に使って膝を外側に押し出し、膝を足と一直線に保つようにします。", "息を吐きながら主にかかとまたは足の中央で床を押してバーを上げ始め、脚を再び伸ばして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Front_Squat_Clean_Grip';
UPDATE exercises SET name = '2つのケトルベルを使ったフロントスクワット', instructions = '["2 つのケトルベルを肩まできれいにします。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。", "常にまっすぐ前を見て、できるだけ低くしゃがみ、一番下で停止します。しゃがむときは、膝を外側に押し出します。両脚の間でしゃがみ、頭と胸を上げて胴体を直立させます。", "かかとを通って立ち上がり、これを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Front_Squats_With_Two_Kettlebells';
UPDATE exercises SET name = 'フロントツーダンベルレイズ', instructions = '["ダンベルを 2 つ選び、胴体をまっすぐにして立ち、ダンベルを腕の長さで太ももの前に置き、手のひらを太ももに向けます。これが開始位置になります。", "胴体を静止したまま（スイングしないように）、肘を軽く曲げ、手のひらを常に下に向けてダンベルを前に持ち上げます。腕が床と平行になるまで上げ続けます。動きのこの部分を実行するときに息を吐き、頂点で 1 秒間停止します。", "息を吸いながら、ダンベルをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Front_Two-Dumbbell_Raise';
UPDATE exercises SET name = '全可動域ラットプルダウン', instructions = '["立っているか高いベンチに座って、高滑車に取り付けられている 2 本のあぶみケーブルをつかみます。反対側の手で腕を十字に組み、手のひらが前を向くように掴みます。", "胸を張って腰を軽くアーチ状に保ち、通常のプルダウンをしているかのようにハンドルを引き下げます。可動範囲はより円弧状になります。動きの間、手を回転させて、下の位置で手のひらが前ではなく互いに向き合うようにします。ゆっくりと開始位置に戻り、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Full_Range-Of-Motion_Lat_Pulldown';
UPDATE exercises SET name = 'ジロンダ胸骨あご', instructions = '["懸垂バーを肩幅くらいの幅でアンダーハンドグリップで握ります。", "次に、腕を完全に伸ばしてぶら下がり、胸を突き出して後ろにもたれかかります。ヒント: 動き全体を通して、体は後ろに傾いた状態になります。これが開始位置になります。", "動きの間ずっと背骨をアーチ状にし、頭をバーからできるだけ遠ざけるように後ろに傾けた状態で、自分自身をバーに向かって引き寄せ始めます。動きのこの部分を実行するときに息を吐きます。ヒント: 動きの上限では、腰と脚が床に対して約 45 度の角度になります。", "鎖骨がバーを通過し、胸下部または胸骨部分がバーに触れるまで引っ張り続けます。その収縮を少しの間止めてください。ヒント: 動きのこの部分が完了するまでに、頭が床と平行になります。", "息を吸いながらゆっくりと開始位置に戻り始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Gironda_Sternum_Chins';
UPDATE exercises SET name = 'グルートハムレイズ', instructions = '["まずは自分の身体に合わせて機器を調整することから始めましょう。うつ伏せになり、ローラーの間のフットプレートに足を置きます。膝はパッドのすぐ後ろにある必要があります。", "動きの一番下から始めます。膝を曲げて動きを開始するときは、背中をアーチ状に保ちます。このとき、つま先をフットプレートに押し込みます。上半身をまっすぐに保ち、体が直立するまで続けます。", "降下をコントロールしながら開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'マシン' WHERE id = 'Glute_Ham_Raise';
UPDATE exercises SET name = '臀部のキックバック', instructions = '["床またはエクササイズマットの上にひざまずいて、両腕を前に（胴体に対して垂直に）伸ばして腰を曲げ、ひざまずいて腕立て伏せの姿勢になりますが、腕は肩幅に開きます。頭は前を向き、膝を曲げてハムストリングスとふくらはぎの間に 90 度の角度を作る必要があります。これが開始位置になります。", "息を吐きながら、90度の角度を保ったまま、ハムストリングスが背中と一直線になるまで右脚を持ち上げます。この動作全体を通して臀部を収縮させ、上部で収縮を 1 秒間保持します。ヒント: 動きの終わりには、大腿部は床と平行になり、ふくらはぎは床に対して垂直になる必要があります。", "息を吸いながら最初の位置に戻り、今度は左脚で繰り返します。", "推奨されている繰り返しがすべて完了するまで、足を交互に動かし続けます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Glute_Kickback';
UPDATE exercises SET name = 'ゴブレットスクワット', instructions = '["軽いケトルベルの角を胸の近くに持って立ちます。これが開始位置になります。", "ハムストリングスがふくらはぎの上に来るまで、脚の間にしゃがみます。胸と頭を上げ、背中をまっすぐに保ちます。", "一番下の位置で停止し、肘を使って膝を外側に押し出します。開始位置に戻り、10〜20回繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Goblet_Squat';
UPDATE exercises SET name = 'おはよう', instructions = '["肩の高さのラックにバーを置きます。パワースクワットと同じように、肩の上ではなく、肩の後ろにバーを掛けます。背中を引き締め、肩甲骨を寄せ、膝を軽く曲げます。ラックから後退します。", "まず腰を曲げ、平行に近い位置まで曲げながら腰を後ろに動かします。背中をアーチ状にし、頸椎を適切な位置に保ちます。", "臀筋とハムストリングスを使って腰を伸ばして、この動きを逆にします。開始位置に戻るまで続けます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Good_Morning';
UPDATE exercises SET name = 'おはようピンをオフ', instructions = '["胃とほぼ同じ高さのラック上のバ​​ーから始めます。バーの下にかがみ込み、パワースクワットと同じようにバーを肩の上ではなく、肩の後ろに掛けます。適切な高さでは、かがんだときに床とほぼ平行になるはずです。背中を引き締め、肩甲骨を寄せ、膝を軽く曲げます。背中をアーチ状にし、頸椎を適切な位置に保ちます。", "臀部とハムストリングスを使って腰を伸ばすことから動作を開始すると、体重をかけて立っていることになります。ゆっくりとウェイトを下げてピンに戻し、開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Good_Morning_off_Pins';
UPDATE exercises SET name = 'ゴリラチン/クランチ', instructions = '["肩幅よりわずかに広いアンダーハンドグリップ（手のひらを自分に向ける）を使用して懸垂バーにぶら下がります。", "次に、ふくらはぎが床と平行になるように膝を 90 度の角度で曲げ、太ももが床に対して垂直になるようにします。これが開始位置になります。", "息を吐きながら、膝が胸の高さになるまで膝を押し上げながら体を引き上げます。ノーズがバーと同じ高さになるとすぐに上がるのが止まります。ヒント: この時点に到達したら、同時にクランチも終了する必要があります。", "ゆっくりと息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Gorilla_Chin_Crunch';
UPDATE exercises SET name = '鼠径部と背中のストレッチ', instructions = '["膝を曲げて足を揃えて床に座ります。", "頭の後ろで指を組みます。これが開始位置になります。", "肘を太ももの内側に近づけながら、下向きにカールします。少し停止した後、頭を上げて背中をまっすぐにして開始位置に戻ります。 10〜20回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Groin_and_Back_Stretch';
UPDATE exercises SET name = 'グロイナー', instructions = '["床の上で腕立て伏せの姿勢から始めます。これが開始位置になります。", "両足を使って前方にジャンプし、足を手の横に置いて着地します。このとき、頭を上げたままにしてください。", "開始位置に戻り、すぐにこの動きを繰り返し、10 ～ 20 回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Groiners';
UPDATE exercises SET name = 'ハックスクワット', instructions = '["胴体の後部をマシンの背面パッドに当て、肩を付属の肩パッドの下に引っ掛けます。", "肩幅の中程度のスタンスでつま先をわずかに尖らせて、脚をプラットフォームに置きます。ヒント: 常に頭を上げて、背中も常にパッドの上に置いてください。", "腕をマシンのサイドハンドルに置き、安全バーを外します (ほとんどのデザインでは、サイドハンドルを正面を向いた位置から斜めの位置に移動することで行われます)。", "次に、膝を固定せずに脚をまっすぐにします。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足の位置のセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上にして（常にパッドの上に背を向けて）まっすぐな姿勢を維持しながら、膝を曲げてユニットをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながらユニットを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Hack_Squat';
UPDATE exercises SET name = 'ハンマーカール', instructions = '["胴体を直立させて立ち、両手にダンベルを腕の長さで持ちます。肘は胴体の近くにある必要があります。", "手のひらは胴体の方を向くようにします。これが開始位置になります。", "次に、上腕を固定したまま、息を吐きながら体重を前方に丸めながら上腕二頭筋を収縮させます。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで重量を上げ続けます。上腕二頭筋を締めながら、収縮した位置を少しの間保持します。ヒント: 肘を動かさないようにし、前腕だけを動かすことに集中してください。", "短い一時停止の後、息を吸いながらゆっくりとダンベルを下げ始め、開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Hammer_Curls';
UPDATE exercises SET name = 'ハンマーグリップインクラインDBベンチプレス', instructions = '["インクラインベンチに仰向けになり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "太ももを使ってダンベルを持ち上げるのを助け、ダンベルを肩の幅で持てるように片腕ずつきれいにします。", "肩幅になったら、手のひらをニュートラルグリップ（手のひらを向かい合う）に保ちます。肘を広げて上腕を肩と一直線にし（胴体に対して垂直）、肘を曲げて上腕と前腕の間に 90 度の角度を作ります。これが開始位置になります。", "次に、息を吸いながらゆっくりとウェイトを体の横に下ろします。常にダンベルを完全に制御できるようにしてください。", "息を吐きながら、胸筋を使ってダンベルを押し上げます。腕を縮めた位置にロックし、1秒間保持してからゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、ダンベルを太ももに戻し、床に置きます。これがダンベルを処分する最も安全な方法です。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Hammer_Grip_Incline_DB_Bench_Press';
UPDATE exercises SET name = 'ハムストリング-SMR', instructions = '["座った姿勢で、フォームロールの上に脚を伸ばし、フォームロールが脚の上部の後ろに来るようにします。体重を支えるために手を体の横または後ろに置きます。これが開始位置になります。", "手を使って腰を床から持ち上げ、フォームロールにかかる体重を片足に移します。伸ばしている脚のハムストリングをリラックスさせます。", "ヒップの下から膝の後ろの上までフォームの上をローリングし、緊張した箇所で 10 ～ 30 秒間停止します。もう一方の脚でも同じ手順を繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Hamstring-SMR';
UPDATE exercises SET name = 'ハムストリングのストレッチ', instructions = '["仰向けになり、片足を上に伸ばし、股関節を90度にします。もう一方の脚は床に平らに置きます。", "ベルト、バンド、またはロープを足の指の付け根に巻きます。これが開始位置になります。", "ベルトを引っ張って、ふくらはぎとハムストリングスに緊張を与えます。このストレッチを 10 ～ 30 秒間保持し、もう一方の脚でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Hamstring_Stretch';
UPDATE exercises SET name = '逆立ち腕立て伏せ', instructions = '["壁を背にして腰を曲げ、両手を肩幅の幅で床に置きます。", "腕をまっすぐにして壁に向かって蹴り上げます。体は逆さまになり、腕と脚を完全に伸ばします。体全体をできるだけまっすぐに保ちます。ヒント: 初めてこれを行う場合は、スポッターに手伝ってもらいます。また、下を向くのではなく、常に壁に頭を向けるようにしてください。", "息を吸いながら、頭が床に着きそうになるまで、ゆっくりと地面に体を下ろします。ヒント: 頭部の損傷を避けるために、ゆっくりと降りることが最も重要です。", "肘がほぼロックされるまで、息を吐きながらゆっくりと体を押し上げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Handstand_Push-Ups';
UPDATE exercises SET name = 'ハングクリーン', instructions = '["肩幅、ダブルオーバーハンドまたはフックグリップでバーを太ももの真ん中の位置にぶら下げて開始します。背中はまっすぐで、わずかに前傾している必要があります。", "まずは腰、膝、足首を積極的に伸ばして体重を上に上げます。このとき、肩を耳に向かってすくめます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるまで続けます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Hang_Clean';
UPDATE exercises SET name = 'ハングクリーン - 膝下', instructions = '["肩幅、ダブルオーバーハンドまたはフックグリップでバーを膝のすぐ下に垂らして始めます。背中はまっすぐで、わずかに前傾している必要があります。", "まずは腰、膝、足首を積極的に伸ばし、体重を上向きに上げます。このとき、肩を耳に向かってすくめます。完全な伸展が達成されたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げることにより、3番目のプルに移行します。", "伸展がピークに達したら、バーの下で肘を回転させながら、積極的に体を引き下げます。前屈みの姿勢でバーを受け取ります。その深さは、3 回目のプル終了時のバーの高さによって決まります。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。ボトムスクワットの位置まで下がり続けます。これは回復に役立ちます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるまで続けます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Hang_Clean_-_Below_the_Knees';
UPDATE exercises SET name = 'ハング・スナッチ', instructions = '["オーバーハンドまたはフックグリップでバーを幅広に握ることから始めます。足は外側を向いた状態で腰の真下に来るようにします。膝をわずかに曲げ、胴体を前傾させます。背骨は完全に伸び、頭は前を向いている必要があります。バーは腰の位置にある必要があります。これが開始位置になります。", "脚と腰を積極的に伸ばします。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足をレシーブポジションに移動するときに、バーを頭上に持ち上げながら、バーの下に力を入れて自分自身を引きます。体をできるだけ低くし、腕を頭上に完全に伸ばしてバーを受け取ります。", "体重を頭上に乗せた状態で立った姿勢に戻ります。続いて、コントロールしながら体重を地面に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Hang_Snatch';
UPDATE exercises SET name = 'ハング スナッチ - 膝下', instructions = '["オーバーハンドまたはフックグリップでバーを幅広に握ることから始めます。足は外側を向いた状態で腰の真下に来るようにします。膝をわずかに曲げ、胴体を前傾させます。背骨は完全に伸び、頭は前を向いている必要があります。バーは膝のすぐ下にある必要があります。これが開始位置になります。", "脚と腰を積極的に伸ばします。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足をレシーブポジションに移動するときに、バーを頭上に持ち上げながら、バーの下に力を入れて自分自身を引きます。体をできるだけ低くし、腕を頭上に完全に伸ばしてバーを受け取ります。", "体重を頭上に乗せた状態で立位に戻り、制御しながら体重を床に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Hang_Snatch_-_Below_Knees';
UPDATE exercises SET name = 'ハンギングバーグッドモーニング', instructions = '["胃とほぼ同じ高さのラック上のバ​​ーから始めます。チェーンまたは吊り下げストラップを使用してバーを吊り下げます。", "トラップの上ではなく、パワースクワットと同じように、バーの下にかがみ、肩の後ろにバーを掛けます。適切な高さでは、かがんだときに床とほぼ平行になるはずです。背中を引き締め、肩甲骨を寄せ、膝を軽く曲げます。背中をアーチ状にし、頸椎を適切な位置に保ちます。", "臀部とハムストリングスを使って腰を伸ばすことから動作を開始すると、体重をかけて立っていることになります。", "ウェイトをゆっくりと下げて開始位置に戻し、チェーンで支えます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Hanging_Bar_Good_Morning';
UPDATE exercises SET name = 'ハンギングレッグレイズ', instructions = '["ワイドグリップまたはミディアムグリップを使用して、両腕を腕の長さで伸ばし、懸垂バーにぶら下がります。脚は真っすぐに下げ、骨盤をわずかに後ろに回転させます。これが開始位置になります。", "胴体が脚に対して 90 度の角度になるまで脚を上げます。この動きを行うときに息を吐き、収縮を 1 秒ほど保持します。", "息を吸いながらゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Hanging_Leg_Raise';
UPDATE exercises SET name = 'ハンギングパイク', instructions = '["肩の幅よりわずかに広いオーバーハンドグリップ（手のひらを自分の反対側に向ける）を使用して両脚を揃えて懸垂バーにぶら下がります。ヒント: バーを握りやすくするために、リストラップを使用することもできます。", "次に、膝を 90 度の角度で曲げ、ふくらはぎが床に対して垂直になるように上脚を前に出し、大腿部は床と平行に保ちます。これが開始位置になります。", "息を吐きながら、上のバーがすねに触れそうになるまで脚を引き上げます。ヒント: 頂上にいるときは、できるだけ足を伸ばすようにしてください。", "開始位置に到達するまで、できるだけゆっくりと脚を下ろします。ヒント: 常にスイングしたり、勢いをつけたりすることは避けてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Hanging_Pike';
UPDATE exercises SET name = 'ヒービングスナッチバランス', instructions = '["このドリルはスナッチを学ぶのに役立ちます。まず、肩の後ろに軽い重量を持ちます。足を外側に向けた状態で、足を腰幅よりわずかに広く開き、スクワットを行うのと同じ位置にします。", "まず膝を少し浸し、元に戻ってバーの負荷を軽く下ろします。バーの下に体を突っ込み、フルスクワットの状態でバーを頭上に持ち上げます。", "立った姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Heaving_Snatch_Balance';
UPDATE exercises SET name = 'ヘビーバッグスラスト', instructions = '["この演習では重いバッグを使用してください。バッグの横で直立姿勢をとり、両足をかなり広めに千鳥状に開きます。バッグの胸の高さくらいに手を置きます。これが開始位置になります。", "まず腰をひねり、バッグをできるだけ強く前に押します。この動きを素早く実行し、バッグを体から遠ざけます。", "これらの手順を逆にして、バッグが後ろに揺れるときにバッグを受け取ります。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Heavy_Bag_Thrust';
UPDATE exercises SET name = '高いケーブルカール', instructions = '["いくつかの高い滑車の間に立ち、それぞれの腕でハンドルを握ります。手のひらを自分に向け、上腕が床と平行になるように置きます。これが開始位置になります。", "ハンドルが耳の横になるまで手前にカールします。このとき、上腕二頭筋を曲げて息を吐き出すようにしてください。上腕は動かさず、前腕だけを動かします。上腕二頭筋を締めながら、収縮した位置で 1 秒間保持します。", "ゆっくりと腕を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'High_Cable_Curls';
UPDATE exercises SET name = 'ヒップサークル (うつ伏せ)', instructions = '["地面に手と膝をついて立ちます。正しい姿勢を保ち、曲がった片方の膝を地面から浮かせます。これが開始位置になります。", "膝を曲げた位置に保ち、大腿骨を円弧を描くように回転させ、膝で大きな円を描くようにします。", "これをゆっくりと何回か繰り返し、反対側も同様に行います。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Hip_Circles_prone';
UPDATE exercises SET name = 'バンドを使ったヒップエクステンション', instructions = '["バンドの一端を支柱の下部に固定し、もう一端を片方の足首に取り付けます。", "バンドの取り付けポイントに向かって、支柱をつかんで体を安定させます。", "頭と胸を上げたまま、膝をまっすぐに保ちながら、抵抗した脚をできるだけ後ろに動かします。", "脚を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Hip_Extension_with_Bands';
UPDATE exercises SET name = 'バンドを使った股関節屈曲', instructions = '["バンドの一端を支柱の下部に固定し、もう一端を片方の足首に取り付けます。", "バンドの取り付け部分から反対側を向いてください。", "頭と胸を上げたまま、膝を90度まで上げて停止します。", "脚を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Hip_Flexion_with_Band';
UPDATE exercises SET name = 'バンドを使ったヒップリフト', instructions = '["適切なバンドを選択したら、バンドを両側に固定してからラックの中央に置きます。ラックにペグがない場合は、重いダンベルなどを使用してバンドを固定できますが、動かないことを確認してください。", "バンドが腰の真上にくるように位置を調整します。膝を曲げて足を床に平らに置きます。手は床にあっても、バンドを所定の位置に持っていても構いません。", "肩を地面につけたまま、かかとを通って腰を上げ、バンドをできるだけ高く押し込みます。", "動作の先頭で一時停止し、開始位置に戻ります。"]'::jsonb, category = 'パワーリフティング', equipment = 'チューブ・バンド' WHERE id = 'Hip_Lift_with_Band';
UPDATE exercises SET name = 'ボールを抱きしめる', instructions = '["床に座ってください。", "バランスボールを両脚の間に挟み、腰を床に向かって下げます。", "腕をボールの周りに抱き締めて体を支えます。足が床に平らになり、膝が足首の上に並ぶように脚を調整します。ボールが転がって尻に戻らないように、ボールをしっかりと握りましょう。"]'::jsonb, category = 'ストレッチ', equipment = 'exercise ball' WHERE id = 'Hug_A_Ball';
UPDATE exercises SET name = '膝を胸に抱き寄せる', instructions = '["仰向けに寝て、両膝を胸の近くまで引き上げます。", "腕を膝の上ではなく、膝の下に置きます（膝関節に大きな圧力がかかります）。", "ゆっくりと膝を肩に向かって引き寄せます。これでお尻の筋肉もストレッチされます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Hug_Knees_To_Chest';
UPDATE exercises SET name = 'ハードルホップ', instructions = '["ハードルまたはその他の小さな障壁を数フィート離して一列に設置します。", "最初のハードルの前に足を肩幅に広げて立ちます。これが開始位置になります。", "最初のハードルを両足で飛び越え、両腕を振りながらジャンプします。", "膝を曲げて着地時の衝撃を吸収し、最初の跳躍から跳ね返り、次のハードルを飛び越えます。すべてのハードルを飛び越えるまで続けてください。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Hurdle_Hops';
UPDATE exercises SET name = 'ハイパーエクステンション（バックエクステンション）', instructions = '["過伸展ベンチにうつ伏せになり、足首をフットパッドの下にしっかりと押し込みます。", "可能であれば上部パッドを調整して、太もも上部が幅広のパッド上で平らになるようにし、制限なく腰を曲げることができる十分なスペースを残します。", "体をまっすぐにして、腕を前（私の好み）または頭の後ろで交差させます。これが開始位置になります。ヒント: ウェイトプレートを前に置いて、腕を組んで負荷を高めることもできます。", "背中を平らに保ちながら、腰からできるだけ遠くまでゆっくりと前屈を始めます。この動きをしながら息を吸います。ハムストリングスが気持ちよく伸び、背中が丸まらなければ前進できなくなるまで前進を続けます。ヒント: このエクササイズを行うときは、決して背中を丸めないでください。また、他の人よりも遠くまで行ける人もいます。重要なのは、背中を丸めずに、体が許す限り遠くまで進むことです。", "息を吸いながら、ゆっくりと上体を起こして元の位置に戻します。ヒント: 直線を超えて背中を反​​らせようとする誘惑を避けてください。また、背中を怪我から守るために、胴体を振り回さないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Hyperextensions_Back_Extensions';
UPDATE exercises SET name = '過伸展ベンチを使用しない過伸展', instructions = '["誰かに足を押さえてもらって、腰がベンチの端からぶら下がるまでフラットベンチの端まで滑り降ります。ヒント: 上半身全体が床に向かって垂れ下がっている必要があります。また、過伸展ベンチと同じ姿勢になりますが、フラットベンチと過伸展ベンチの高さが異なるため、可動範囲は短くなります。", "体をまっすぐにして、腕を前（私の好み）または頭の後ろで交差させます。これが開始位置になります。ヒント: ウェイトプレートを前に置いて、腕を組んで負荷を高めることもできます。", "背中を平らに保ちながら、腰からできるだけ遠くまでゆっくりと前屈を始めます。この動きをしながら息を吸います。床に着きそうになるか、ハムストリングスが伸びていると感じるまで（どちらか早い方）、前に進み続けます。ヒント: このエクササイズを行うときは、決して背中を丸めないでください。", "息を吐きながら、上体をゆっくりと元の位置に戻します。ヒント: 直線を超えて背中を反​​らせようとする誘惑を避けてください。また、背中を怪我から守るために、胴体を振り回さないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Hyperextensions_With_No_Hyperextension_Bench';
UPDATE exercises SET name = 'ITバンドと臀部のストレッチ', instructions = '["ベルト、ロープ、またはバンドを片方の足に巻き付け、その脚を体の反対側に振り、地面に横たわったまま脚を伸ばしたままにします。これが開始位置になります。", "足を床から離したまま、ベルトを引っ張り、張力を利用してつま先を引き上げます。 10〜20秒間保持し、反対側でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'IT_Band_and_Glute_Stretch';
UPDATE exercises SET name = '腸脛管-SMR', instructions = '["横向きに寝て、下の脚を腰と膝の間のフォームローラーの上に置きます。もう片方の足は前で交差させても構いません。", "耐えられるだけの体重を下肢に置きます。下肢を地面に接触させておく必要はありません。伸ばしている脚の筋肉を必ずリラックスさせてください。", "脚をフォームの上で腰から膝まで転がし、緊張した部分で 10 ～ 30 秒間停止します。反対側の脚でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Iliotibial_Tract-SMR';
UPDATE exercises SET name = 'シャクトリムシ', instructions = '["足を閉じて立ちます。足をまっすぐに伸ばしたまま、体を伸ばして、両手を体の前の床に置きます。これが開始位置になります。", "まず、手を左右交互にゆっくりと前に歩きます。このとき、足をまっすぐに保ちながら、股関節だけを曲げます。", "腕立て伏せの姿勢で体が地面と平行になるまで続けます。", "次に、手を所定の位置に保ち、足をゆっくりと短いステップで、一度に数インチだけ動かします。", "足が短針の位置に来るまで歩き続けます。その間、足はまっすぐに保ちます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Inchworm';
UPDATE exercises SET name = 'インクラインバーベルトライセプスエクステンション', instructions = '["バーベルをオーバーハンドグリップ（手のひらを下）にして、肩幅より少し狭めに持ちます。", "45 ～ 75 度の間の任意の角度に設定されたインクライン ベンチに仰向けになります。", "腕を伸ばして肘を内側に置き、バーを頭上に持ってきます。腕は頭の上で胴体と一直線になるようにします。これが開始位置になります。", "次に、前腕が上腕二頭筋に触れるまで、頭の後ろで半円を描くようにバーを下げます。この動きをしながら息を吸います。ヒント: 上腕は動かさず、常に頭に近づけてください。前腕だけを動かす必要があります。", "息を吐きながら開始位置に戻り、上腕三頭筋を収縮させます。収縮を 1 秒間保持します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Incline_Barbell_Triceps_Extension';
UPDATE exercises SET name = 'インクラインベンチプル', instructions = '["両手にダンベルを持ち、約30度の傾斜に設定されたインクラインベンチにうつ伏せになります。", "腕を床に向けて完全に伸ばして体の横に垂らします。", "手が回内（手のひらを下に向けた状態）で握るまで手首を回します。", "今度は肘を外側に広げます。これが開始位置になります。", "息を吐きながら、リバースベンチプレスをしているかのようにダンベルを引き上げ始めます。これを行うには、肘を曲げ、前腕を垂らしながら上腕を上げます。上腕が背中と同じ高さになるまでこの動きを続けます。ヒント: 肘を横に出し、上腕と胴体が動きの頂点で「T」の字を描くようにします。上部の収縮を 1 秒間保持します。", "息を吸いながらゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Incline_Bench_Pull';
UPDATE exercises SET name = 'インクラインケーブルチェストプレス', instructions = '["適切な重量に調整し、ハンドルを握りながら座ります。上腕は体に対して約 45 度にし、頭と胸を上げます。肘は約90度まで曲げる必要があります。これが開始位置になります。", "まず、肘を通って伸ばし、ハンドルをまっすぐ前に押します。この動きを実行するときは、肩甲骨を引いたままにしてください。", "完全に伸ばした状態で一時停止した後、ケーブルに張力を掛けたまま開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Incline_Cable_Chest_Press';
UPDATE exercises SET name = 'インクライン ケーブル フライ', instructions = '["開始位置に立つには、プーリーを床の高さ (胴体より下のマシンの可能な限り低いレベル) に設定します。", "インクライン ベンチ (45 度に設定) を滑車の間に置き、それぞれの重りを選択し、両手で滑車をつかみます。", "両手にハンドルを持ち、インクラインベンチに横になり、顔の前で両手を腕の長さで合わせます。これが開始位置になります。", "肘を軽く曲げて（上腕二頭筋の腱へのストレスを防ぐため）、胸が伸びると感じるまで腕を両側から広い弧を描きながら下げます。動きのこの部分を実行するときに息を吸います。ヒント: 動作中は腕を動かさないように注意してください。この動きは肩関節でのみ行われます。", "胸の筋肉を締めて息を吐きながら、腕を開始位置に戻します。収縮した位置を 1 秒間保持します。ヒント: ウェイトを下げるときに使用したのと同じ円弧の動きを使用してください。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Incline_Cable_Flye';
UPDATE exercises SET name = '手のひらを内側に向けたインクライン ダンベル ベンチ', instructions = '["インクラインベンチに仰向けになり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "太ももを使ってダンベルを持ち上げるのを助け、ダンベルを肩の幅で持てるように片腕ずつきれいにします。", "肩幅になったら、手のひらをニュートラルグリップ（手のひらを向かい合う）に保ちます。肘を広げて上腕を肩と一直線にし（胴体に対して垂直）、肘を曲げて上腕と前腕の間に 90 度の角度を作ります。これが開始位置になります。", "次に、息を吸いながらゆっくりとウェイトを体の横に下ろします。常にダンベルを完全に制御できるようにしてください。", "息を吐きながら、胸筋を使ってダンベルを押し上げます。腕を縮めた位置にロックし、1秒間保持してからゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、ダンベルを太ももに戻し、床に置きます。これがダンベルを処分する最も安全な方法です。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Dumbbell_Bench_With_Palms_Facing_In';
UPDATE exercises SET name = 'インクラインダンベルカール', instructions = '["両手にダンベルを持ち、腕を伸ばしてインクラインベンチに座ります。肘を胴体の近くに保ち、手のひらが前を向くまで回転させます。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方に曲げます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Dumbbell_Curl';
UPDATE exercises SET name = 'インクライン ダンベル フライ', instructions = '["両手にダンベルを持ち、傾斜角度が 30 度以下に設定されたインクラインベンチに横になります。", "肘を軽く曲げて腕を上に伸ばします。", "次に、手のひらが自分に向くように手首を回転させます。ヒント: 小指は隣同士にある必要があります。これが開始位置になります。", "息を吸いながら、腕を伸ばしたまま、手のひらが向かい合うまで手首を回転させながら、ゆっくりと腕を横に下げ始めます。ヒント: 動きの終わりには、腕は体の横にあり、手のひらは天井に向けられています。", "息を吐きながら、動作を逆にして、小指が再び隣り合うように手を回転させて、ダンベルを開始位置に戻し始めます。ヒント: この動きは肩関節と手首でのみ発生することに注意してください。肘関節で起こる動きはありません。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Dumbbell_Flyes';
UPDATE exercises SET name = 'インクライン ダンベル フライ - ひねりを加えて', instructions = '["両手にダンベルを持ち、傾斜角度が 30 度以下に設定されたインクラインベンチに横になります。", "肘を軽く曲げて腕を上に伸ばします。", "次に、手のひらが自分に向くように手首を回転させます。ヒント: 小指は隣同士にある必要があります。これが開始位置になります。", "息を吸いながら、腕を伸ばしたまま、手のひらが向かい合うまで手首を回転させながら、ゆっくりと腕を横に下げ始めます。ヒント: 動きの終わりには、腕は体の横にあり、手のひらは天井に向けられています。", "息を吐きながら、動作を逆にして、小指が再び隣り合うように手を回転させて、ダンベルを開始位置に戻し始めます。ヒント: この動きは肩関節と手首でのみ発生することに注意してください。肘関節で起こる動きはありません。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Dumbbell_Flyes_-_With_A_Twist';
UPDATE exercises SET name = 'インクラインダンベルプレス', instructions = '["インクラインベンチに仰向けになり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "次に、太ももを使ってダンベルを押し上げ、肩幅で持てるようにダンベルを 1 つずつ持ち上げます。", "ダンベルを肩幅まで上げたら、手首を前方に回転させ、手のひらが外側を向くようにします。これが開始位置になります。", "常にダンベルを完全に制御できるようにしてください。次に息を吐きながら胸でダンベルを押し上げます。", "腕を一番上でロックし、1秒間保持してから、ゆっくりと体重を下げ始めます。ヒント 理想的には、ウェイトを下げるには上げる時間の約 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "終わったら、ダンベルを太ももの上に戻してから床に置きます。これがダンベルを解放する最も安全な方法です。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Dumbbell_Press';
UPDATE exercises SET name = 'インクラインハンマーカール', instructions = '["インクラインベンチに座り、両手にダンベルを持ちます。足を揃えて彼の背中をしっかりと押す必要があります。ダンベルを体の横にまっすぐ下げ、ニュートラルなグリップで持ちます。これが開始位置になります。", "肘を曲げて動きを開始し、上腕を動かないようにしてください。", "動きの頂点まで続けて一時停止し、ゆっくりと開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Hammer_Curls';
UPDATE exercises SET name = 'インクラインインナー上腕二頭筋カール', instructions = '["両手にダンベルを持ち、インクラインベンチに仰向けになります。", "ダンベルは腕の長さで体の横にぶら下げ、手のひらを外側に向けます。これが開始位置になります。", "次に、息を吐きながら、前腕を三角筋の側面と一直線に保ちながら、体重を外側に上にカールさせます。ダンベルが肩の高さで三角筋の側面に来るまでカールを続けます。ヒント: 動きの終わりは、上腕二頭筋のポーズと同じように見えるはずです。", "動きの上部で 2 回目の収縮を行った後、息を吸い始め、ウェイトを持ち上げるときに使用したのと同じ経路を使用して、ウェイトを開始位置にゆっくりと下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Incline_Inner_Biceps_Curl';
UPDATE exercises SET name = 'インクラインプッシュアップ', instructions = '["ベンチまたは頑丈な高台に面して立ちます。両手をベンチまたはプラットフォームの端に、肩幅よりわずかに広く置きます。", "腕と体をまっすぐにして前足をベンチまたはプラットフォームから後ろに置きます。腕は体に対して垂直になるようにします。体をまっすぐに保ち、腕を曲げて胸をボックスまたはプラットフォームの端に下げます。", "腕が伸びるまで体を押し上げます。繰り返す。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Incline_Push-Up';
UPDATE exercises SET name = 'インクラインプッシュアップクローズグリップ', instructions = '["適切な高さのスミス マシン バーまたは頑丈な高台に面して立ちます。", "手をバーの上に並べて置きます。", "足をバーから後ろに置き、腕と体をまっすぐにします。これが開始位置になります。", "体を真っ直ぐに保ち、腕を曲げて胸をバーまで下げます。", "肘を伸ばして元の位置に戻り、体を押し上げます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Incline_Push-Up_Close-Grip';
UPDATE exercises SET name = 'インクラインプッシュアップ デプスジャンプ', instructions = '["このドリルには、高さ約12インチの箱と、厚いマットまたはエアロビクスステップが2枚必要です。", "ステップを肩のすぐ外側に置き、インクラインプッシュアップの姿勢になるように足をボックスの上に置き、手をステップのすぐ内側に置きます。これが開始位置になります。", "まず肘を曲げて体を下げ、すぐに姿勢を反転して体を地面から押し出します。地面から離れるときは、手をステップの上に移動し、肘を曲げて衝撃を吸収します。", "この動作を繰り返して開始位置に戻ります。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Incline_Push-Up_Depth_Jump';
UPDATE exercises SET name = 'インクラインプッシュアップ ミディアム', instructions = '["適切な高さのスミス マシン バーまたは頑丈な高台に面して立ちます。", "両手を肩幅くらいに開き、バーの上に手を置きます。", "足をバーから後ろに置き、腕と体をまっすぐにします。これが開始位置になります。", "体を真っ直ぐに保ち、腕を曲げて胸をバーまで下げます。", "肘を伸ばして元の位置に戻り、体を押し上げます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Incline_Push-Up_Medium';
UPDATE exercises SET name = 'インクライン・プッシュアップ・リバース・グリップ', instructions = '["適切な高さのスミス マシン バーまたは頑丈な高台に面して立ちます。", "手のひらを上にしてバーの上に手を置き、両手を肩幅くらいに開きます。", "足をバーから後ろに置き、腕と体をまっすぐにします。これが開始位置になります。", "体を真っ直ぐに保ち、腕を曲げて胸をバーまで下げます。", "肘を伸ばして元の位置に戻り、体を押し上げます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Incline_Push-Up_Reverse_Grip';
UPDATE exercises SET name = 'インクラインプッシュアップワイド', instructions = '["適切な高さのスミス マシン バーまたは頑丈な高台に面して立ちます。", "手を肩幅より広くしてバーの上に手を置きます。", "足をバーから後ろに置き、腕と体をまっすぐにします。腕は体に対して垂直になるようにします。これが開始位置になります。", "体を真っ直ぐに保ち、腕を曲げて胸をバーまで下げます。", "肘を伸ばして元の位置に戻り、体を押し上げます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Incline_Push-Up_Wide';
UPDATE exercises SET name = '中間の鼠径部ストレッチ', instructions = '["足を伸ばして仰向けに寝ます。ベルト、ロープ、またはバンドを片方の足に巻き付け、その足をできるだけ横に振ります。これが開始位置になります。", "ベルトを軽く引っ張って、鼠径部とハムストリングの筋肉に緊張を与えます。 10〜20秒間保持し、反対側でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Intermediate_Groin_Stretch';
UPDATE exercises SET name = '中間股関節屈筋と大腿四頭筋ストレッチ', instructions = '["床にうつ伏せになり、片足にロープ、ベルト、またはバンドを巻き付けます。", "膝を曲げ、伸ばす脚の股関節を伸ばし、両手でベルトを引っ張ります。膝と股関節が床から離れ、股関節屈筋と大腿四頭筋に緊張が生じます。ストレッチを 10 ～ 20 秒間保持し、反対側の脚でも同様に行います。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Intermediate_Hip_Flexor_and_Quad_Stretch';
UPDATE exercises SET name = 'バンド付き内旋', instructions = '["バンドをポストに巻き付けてチョークします。バンドは肘と同じ高さにある必要があります。バンドから数フィート離れたところに右側を向けて立ちます。", "右手でバンドの端をつかみ、肘を体の横にしっかりと押し付けたままにします。パッドまたはフォームロールを肘で所定の位置に保持し、所定の位置にしっかりと保持することをお勧めします。", "上腕を所定の位置に置き、肘を 90 度に曲げ、手を胴体から遠ざけます。これが開始位置になります。", "肘を所定の位置に保ちながら、フォアハンドの動きで腕を回転させて動きを実行します。", "できる限り続けて、一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Internal_Rotation_with_Band';
UPDATE exercises SET name = '反転された行', instructions = '["バーをラックに腰程度の高さまで置きます。スミスマシンを使用することもできます。", "肩幅よりも広い幅でバーを握り、バーの下にぶら下がった状態になります。体は真っ直ぐになり、かかとを地面に付け、腕を完全に伸ばします。これが開始位置になります。", "肘を曲げて胸をバーに向かって引き寄せることから始めます。この動きを行うときは、肩甲骨を引っ込めます。", "動作の先頭で一時停止し、開始位置に戻ります。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Inverted_Row';
UPDATE exercises SET name = 'ストラップ付き逆列', instructions = '["ロープや吊り下げストラップをラックやその他の安定した物体に吊り下げます。両端を持ち、ロープにぶら下がって仰向けの姿勢になります。体は真っ直ぐになり、かかとを地面に付け、腕を完全に伸ばします。これが開始位置になります。", "肘を曲げて胸を手に引き寄せることから始めます。この動きを行うときは、肩甲骨を引っ込めます。", "動作の先頭で一時停止し、開始位置に戻ります。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Inverted_Row_with_Straps';
UPDATE exercises SET name = '鉄十字', instructions = '[]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Iron_Cross';
UPDATE exercises SET name = '鉄十字(ストレッチ)', instructions = '["床にうつ伏せになり、腕を体の横に伸ばし、手のひらを床に押し付けます。これが開始位置になります。", "まず、片方の膝を曲げてその脚を体の後ろに置き、反対側の手の近くで地面に触れるようにしてください。", "すぐに脚を開始位置に戻し、もう一方の脚でも素早く繰り返します。交互に10〜20回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Iron_Crosses_stretch';
UPDATE exercises SET name = '等尺性胸部絞り', instructions = '["座っているときまたは立っているときに、腕を90度の角度で曲げ、胸の前で両手の平を合わせます。ヒント: 手は開いて、手のひらを合わせ、指を前方 (胴体に対して垂直) に向けます。", "胸を収縮させながら両手を押し合います。ゆっくりとした張力から始めて、ゆっくりと上げてください。この収縮を実行する間、通常の呼吸を続けてください。", "推奨される秒数の間押し続けます。", "今度はゆっくりと緊張を緩めてください。", "推奨されている時間休憩し、これを繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Isometric_Chest_Squeezes';
UPDATE exercises SET name = '等尺性首エクササイズ - 前面と背面', instructions = '["頭と首をニュートラルポジション（頭を直立させて前を向いた通常の姿勢）にして、両手を頭の前側に置きます。", "次に、首の筋肉を収縮させながら、頭の動きに抵抗しながら、ゆっくりと前に押します。ゆっくりとした張力から始めて、ゆっくりと上げてください。この収縮を実行する間、通常の呼吸を続けてください。", "推奨される秒数の間押し続けます。", "今度はゆっくりと緊張を緩めてください。", "推奨されている時間休憩し、手を後頭部に当てて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Isometric_Neck_Exercise_-_Front_And_Back';
UPDATE exercises SET name = 'アイソメトリック首エクササイズ - 側面', instructions = '["頭と首をニュートラルポジション（頭を直立させて前を向いた通常の姿勢）にして、左手を頭の左側に置きます。", "次に、左首の筋肉を収縮させながら、頭の動きに抵抗しながら、ゆっくりと左に押します。ゆっくりとした張力から始めて、ゆっくりと上げてください。この収縮を実行する間、通常の呼吸を続けてください。", "推奨される秒数の間押し続けます。", "今度はゆっくりと緊張を緩めてください。", "推奨されている時間休憩し、右手を頭の右側に置いて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Isometric_Neck_Exercise_-_Sides';
UPDATE exercises SET name = 'アイソメトリックワイパー', instructions = '["腕立て伏せの姿勢をとり、体をまっすぐに保ちながら手とつま先で体重を支えます。手は肩幅のすぐ外側にある必要があります。これが開始位置になります。", "まず体重をできるだけ片側に移動し、体を下げるときにその側の肘が曲がるようにします。", "曲げた腕を伸ばして動きを逆に動かし、体を押し上げてから反対側に倒します。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Isometric_Wipers';
UPDATE exercises SET name = 'JMプレス', instructions = '["クローズグリップベンチプレスと同じ方法でエクササイズを開始します。平らなベンチに横になり、肘を内側に伸ばして腕の長さ (完全に伸ばした状態) でバーベルを持ちます。ただし、腕を胴体に対して垂直にするのではなく、バーが胸の上部の真上にセットされていることを確認してください。これが開始位置になります。", "次に、完全に伸ばした位置から始めて、横たわった上腕三頭筋の伸展を行うかのようにバーを下げます。この動きをしながら息を吸います。中間点に到達したら、上腕が胴体に対して垂直になるまで脚に向かって動かし、バーを約 1 インチ戻します。ヒント: 上腕を前に出すときは、肘の曲がりを一定に保ちます。", "息を吐きながら、上腕三頭筋を使ってバーを押し上げ、クローズグリップベンチプレスを実行します。", "ここで開始位置に戻り、最初からやり直してください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'JM_Press';
UPDATE exercises SET name = 'ジャックナイフ シットアップ', instructions = '["床（またはエクササイズマット）に仰向けになり、腕を頭の後ろにまっすぐ伸ばし、脚も伸ばします。これが開始位置になります。", "息を吐きながら腰を曲げ、同時に脚と腕を上げてジャックナイフの姿勢になります。ヒント: 脚は床から約 35 ～ 45 度の角度で伸ばして持ち上げ、腕は脚と平行に伸ばします。上半身は床から離れている必要があります。", "息を吸いながら、腕と脚を下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Jackknife_Sit-Up';
UPDATE exercises SET name = 'ジャンダ・シットアップ', instructions = '["基本的な腹筋姿勢で体を床に置きます。膝を90度の角度に曲げ、足を床に平らに置き、腕を胸の上または横に交差させます。これが開始位置になります。", "臀部とハムストリングスを強く締めながら、肺を空気で満たし、ゆっくりと (3 ～ 6 秒数えて) 上昇し、ゆっくりと息を吐きます。ヒント: 臀部とハムストリングスを締めることが重要です。これにより、相互抑制と呼ばれるプロセスで股関節屈筋が不活性化されます。これは基本的に、収縮した筋肉の反対側の筋肉が弛緩することを意味します。", "息を吸いながら、ゆっくりと制御された方法で開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Janda_Sit-Up';
UPDATE exercises SET name = 'ジェファーソンスクワット', instructions = '["バーベルを床に置きます。", "バーの長さの中央に立ちます。", "膝を曲げて背中をまっすぐに保ち、右手でバーの前部を握ります。手のひらは左側を向いて (ニュートラルグリップ) にしてください。", "左手でバーの後部をつかみます。手のひらはニュートラルグリップの位置にある必要があります（手のひらが右側を向く）。ヒント: グリップがバーの上で均等になっていることを確認してください。胴体はバーの中央に位置し、胴体と右手 (前方にあるはず) との距離は、胴体と左手 (背中にあるはず) との距離と同じである必要があります。", "次に、体重をかけてまっすぐに立ちます。ヒント: 足は肩幅に開き、つま先をわずかに尖らせる必要があります。", "膝を曲げてしゃがみ、太ももの上部が床と平行になるまで背中をまっすぐに保ちます。ヒント: 床と頭を上げた状態で、背中をできるだけ垂直に保ちます。また、膝がつま先より前に出ないように注意してください。動きのこの部分で息を吸います。", "次に、足で押して開始位置に戻ります。ヒント: バーを腕の長さでぶら下げ、肘を軽く曲げて固定します。アームはフックとしてのみ機能します。彼らと一緒に持ち上げたりすることは避けてください。太ももを使って持ち上げてください。あなたの腕ではありません。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Jefferson_Squats';
UPDATE exercises SET name = 'ジャークバランス', instructions = '["このドリルは、ジャーク中に自分自身を十分に低くする方法を学び、動作中に後ろに下がってしまう人を修正するのに役立ちます。バーをジャークポジションでラックに置き、肩を前方に、胴体を直立させ、足をわずかに開きます。", "通常のジャークと同じように動きを開始し、胴体を垂直に保ちながら膝を沈め、腕ではなく勢いを使って体重を上げながら力強く元に戻ります。", "後ろ足を所定の位置に保ち、体重をジャークするときにそれを使って体を完全に前方に動かします。頭上に体重をかけて立ち上がることで回復します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Jerk_Balance';
UPDATE exercises SET name = 'ジャークディップスクワット', instructions = '["この動きによりジャークのディップ部分が強化されます。バーをジャークポジションでラックに置き、肩を前に上げて棚を作り、バーを喉に軽く接触させます。足は腰の真下にあり、楽な姿勢で足を外側に向けます。", "胴体を垂直に保ち、膝を曲げて腰を下げ、腰を後ろに動かさずに膝を前方に移動させます。ディップが過度であってはなりません。足を強く動かして体重を開始位置に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Jerk_Dip_Squat';
UPDATE exercises SET name = 'ジョギング、トレッドミル', instructions = '["まず、トレッドミルに乗り、メニューから希望のオプションを選択します。ほとんどのトレッドミルには手動設定があり、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。高度を調整してワークアウトの強度を変更できます。", "トレッドミルは便利で心臓血管にも効果があり、通常は屋外でジョギングするよりも影響が少ないです。体重 150 ポンドの人が 30 分間ジョギングするとほぼ 250 カロリーを消費しますが、ランニングでは 450 カロリー以上消費します。ジョギング中は正しい姿勢を維持し、降車時や心拍数の確認時など、必要な場合にのみハンドルを握ります。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Jogging_Treadmill';
UPDATE exercises SET name = 'ケグロード', instructions = '["樽を積み込むには、積み込みプラットフォームから通常 30 ～ 50 フィートの距離に希望の番号を置きます。", "まず最初の樽のクローズハンドルを掴み、ハンドルを横に傾けて樽の底の反対側の端を掴みます。樽を胸まで持ち上げます。", "樽をより高い位置に置けるほど、より速くプラットフォームに移動できるはずです。肩掛けは通常禁止されています。樽をしっかりと握ってください。できるだけ早くプラットフォームに移動し、腰、膝、足首を通してできるだけ高い位置まで荷重を加えます。", "開始位置に戻って次の樽を取り出し、イベントが完了するまで繰り返します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Keg_Load';
UPDATE exercises SET name = 'ケトルベル アーノルド プレス', instructions = '["ケトルベルを肩まできれいにします。ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。手のひらは内側を向いている必要があります。", "まっすぐ前を見て、ケトルベルを頭上に押し出し、動きの一番上で手のひらが前を向くように手首を回転させます。", "手のひらを内側に向けてケトルベルを開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Arnold_Press';
UPDATE exercises SET name = 'ケトルベル デッドクリーン', instructions = '["ケトルベルを足の間に置きます。開始位置に立つには、お尻を後ろに押し出し、まっすぐ前を見てください。", "ケトルベルを肩まできれいにします。ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。そうすることで手首が回転するはずです。", "背中をまっすぐにし、お尻を突き出してハムストリングスに負荷をかけたまま、ケトルベルを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Dead_Clean';
UPDATE exercises SET name = 'ケトルベル フィギュア 8', instructions = '["ケトルベルを脚の間に置き、肩幅よりも広いスタンスで立ちます。お尻を突き出し、背中を平らにして前かがみになります。", "ケトルベルを手に取り、脚の間のもう一方の手に渡します。受け手は脚の後ろから伸ばすようにします。何度か行ったり来たりを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Figure_8';
UPDATE exercises SET name = 'ケトルベルハングクリーン', instructions = '["ケトルベルを足の間に置きます。開始位置に立つには、お尻を後ろに押し出し、まっすぐ前を見てください。", "ケトルベルを肩まできれいにします。ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。そうすることで手首が回転するはずです。", "ハムストリングスに負荷をかけたまま、ケトルベルを脚の間にぶら下がった位置まで下げます。常に頭を上げてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Hang_Clean';
UPDATE exercises SET name = 'ケトルベル片足デッドリフト', instructions = '["ケトルベルのハンドルを片手で持ちます。ケトルベルを持つ側と同じ側に片足で立ちます。", "膝をわずかに曲げたまま、股関節を曲げてバランスをとるために自由脚を後ろに伸ばし、スティッフレッグデッドリフトを実行します。", "地面と平行になるまでケトルベルを下げ続け、その後直立位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_One-Legged_Deadlift';
UPDATE exercises SET name = 'ケトルベルは脚の間をパスします', instructions = '["ケトルベルを 1 つ脚の間に置き、楽な姿勢をとります。お尻を突き出し、背中を平らにして前かがみになります。", "ケトルベルを手に取り、脚の間で「W」の字を描くようにもう一方の手に渡します。何度か行ったり来たりを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Pass_Between_The_Legs';
UPDATE exercises SET name = 'ケトルベル海賊船', instructions = '["ワイドスタンスでケトルベルを両手で持ちます。腕を伸ばして腰の高さで吊り下げます。これが開始位置になります。", "片側を向き、頭の高さまでケトルベルを振り、動きを開始します。モーションの先頭で少し停止します。", "反対側に回転しながらベルを下げ、再びケトルベルを頭の高さまで上げます。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Pirate_Ships';
UPDATE exercises SET name = 'ケトルベルピストルスクワット', instructions = '["ケトルベルを両手で持ち上げ、角の部分を持ちます。片足を床から離し、もう一方の足でしゃがみます。", "膝を曲げてしゃがみ、腰を後ろに向けて座り、ケトルベルを前に持ちます。", "一番下の位置を 1 秒間保持してから、動きを逆に動かし、かかとを通って頭と胸を上げたままにします。", "もう一度体を下げて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Pistol_Squat';
UPDATE exercises SET name = 'ケトルベル シーテッド プレス', instructions = '["床に座り、足を楽に広げます。", "ケトルベルを 1 つ肩まできれいにします。", "ケトルベルが頭上でロックアウトされるまで、ケトルベルを押し上げて外します。開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Seated_Press';
UPDATE exercises SET name = 'ケトルベル シーソー プレス', instructions = '["2つのケトルベルを肩の上で拭きます。", "ケトルベルを 1 つ押します。", "ケトルベルを下げ、すぐにもう一方のケトルベルを押します。両側で同じ回数の繰り返しを行うようにしてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Seesaw_Press';
UPDATE exercises SET name = 'ケトルベル相撲ハイプル', instructions = '["ケトルベルを足の間の地面に置きます。足をワイドスタンスに置き、両手でケトルベルを握ります。膝を曲げた状態で、腰をできるだけ後ろに置きます。胸と頭を上げてください。これが開始位置になります。", "まず腰と膝を伸ばし、同時にケトルベルを肩に引き寄せ、肘を上げます。動きを逆にして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Sumo_High_Pull';
UPDATE exercises SET name = 'ケトルベルスラスター', instructions = '["2 つのケトルベルを肩まできれいにします。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。これが開始位置になります。", "腰と膝を曲げてしゃがみ始め、腰を脚の間に下げます。できるだけ低く降りながら、直立したまっすぐな背中を維持してください。", "一番下では、方向を逆にして、かかとから膝と腰を伸ばしてしゃがみます。このとき、腕をまっすぐ上に伸ばして両方のケトルベルを頭上に押し、スクワットの勢いを利用してウェイトを上に押し上げます。", "次の繰り返しを開始するときに、ウェイトを肩に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Thruster';
UPDATE exercises SET name = 'ケトルベル ターキッシュ ゲットアップ (ランジ スタイル)', instructions = '["床に仰向けになり、肘を伸ばしてケトルベルを一番上の位置まで押します。ケトルベルと同じ側で膝を曲げます。", "ケトルベルを常にロックアウトした状態で、反対側に旋回して、動かしていない腕を使ってランジ ポジションまで前進するのを助けます。空いている手で座った位置まで体を動かし、片膝を立てます。", "ケトルベルを見上げながら、ゆっくりと立ち上がります。動きを逆にして開始位置に戻し、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Turkish_Get-Up_Lunge_style';
UPDATE exercises SET name = 'ケトルベル ターキッシュ ゲットアップ (スクワット スタイル)', instructions = '["床に仰向けになり、肘を伸ばしてケトルベルを一番上の位置まで押します。ケトルベルと同じ側で膝を曲げます。", "ケトルベルを常にロックアウトした状態で、反対側に旋回して、動かしていない腕を使ってランジ ポジションまで前進するのを助けます。", "空いている手で座った位置まで体を押してから、立ち上がってください。ケトルベルを見上げながら、ゆっくりと立ち上がります。動きを逆にして開始位置に戻し、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Turkish_Get-Up_Squat_style';
UPDATE exercises SET name = 'ケトルベル風車', instructions = '["ケトルベルをリードフットの前に置き、反対側の腕で頭上に押し上げます。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。肘を伸ばして頭上に押し込みます。", "ケトルベルを常にロックアウトした状態で、ロックアウトされたケトルベルの方向にお尻を押し出します。ケトルベルをロックアウトした状態で、足を腕から 45 度の角度で外に向けます。腰を片側に曲げ、お尻を突き出し、空いているほうの手で床に触れるまでゆっくりと傾けます。頭の上にかざしたケトルベルから常に目を離さないでください。", "地面に着いたら少し停止し、動きを逆にして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Kettlebell_Windmill';
UPDATE exercises SET name = 'キッピングマッスルアップ', instructions = '["手のひらの付け根をリングの上に置き、フォールスグリップでリングを握ります。", "足を少し後ろに振る動きから始めます。", "この動きに対抗するには、脚を前上に振り上げ、顎と胸を後ろに引き、両腕で体を引き上げます。懸垂のトップの位置に達したら、肩を前に回転させながらリングを脇の下に引き、肘がまっすぐ後ろに動くようにします。これにより、動きのディップ部分に進むための適切な位置に移動できます。", "コントロールと安定性を維持しながら、肘を伸ばして動作を完了します。", "地面に体を下げるときは注意してください。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Kipping_Muscle_Up';
UPDATE exercises SET name = '膝を体全体に向ける', instructions = '["右脚をまっすぐにして床に横になります。左脚を曲げて体全体に下ろし、右手で膝を床に向けて押し下げます。 (タイトな場合は膝が床につく必要はありません。)", "左腕を体の横に楽に置き、頭を左に向けます。尾てい骨に重りを付けていると想像してください。胸を反対方向に伸ばして腰を伸ばしながら、尾骨を床に向かって後ろに倒します。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Knee_Across_The_Body';
UPDATE exercises SET name = '膝のサークル', instructions = '["足を揃えて立ち、手を腰に当てます。", "次に、通常の呼吸をしながら、膝を円を描くように動かします。", "推奨回数だけ繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Knee_Circles';
UPDATE exercises SET name = '平行棒でのニー/ヒップレイズ', instructions = '["前腕が胴体の隣のパッドの上に置かれ、ハンドルを握るように垂直レッグレイズベンチに体を置きます。腕は90度に曲がります。", "胴体はまっすぐにして、腰をマシンのパッドに押し付け、脚を床に向けて伸ばします。これが開始位置になります。", "息を吐きながら、脚を伸ばしたまま持ち上げます。脚が床とほぼ平行になるまでこの動きを続け、収縮を 1 秒間保持します。ヒント: このエクササイズを実行するときは、勢いを付けたり、スイングしたりしないでください。", "息を吸いながらゆっくりと元の姿勢に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Knee_Hip_Raise_On_Parallel_Bars';
UPDATE exercises SET name = 'ニータックジャンプ', instructions = '["膝をわずかに曲げた快適な立位から始めます。手を前に持ち、手のひらを下にして指先を胸の高さで合わせます。これが開始位置になります。", "急速に 4 分の 1 のスクワット状態になり、すぐに上向きに爆発します。膝を胸に向かって動かし、手のひらに触れるようにします。", "できるだけ高くジャンプして膝を上げ、適切な着地を確保して脚を再び伸ばし、膝を元に戻すことで衝撃を吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Knee_Tuck_Jump';
UPDATE exercises SET name = 'ニーリングアームドリル', instructions = '["このドリルは、ランニング中の腕の効率を高めるのに役立ちます。左足を前に、右膝を下ろしてひざまずきます。前かかとに圧力を加えて、臀部とハムストリングを活性化させます。", "長い振り子のようなスイングで腕をブロックすることから始めます。腕の角度を閉じ、ジョギングするときと同じように腕でブロックし、ランニングに進み、最後にスプリントに進みます。", "手が腰を通過したらすぐに、全力疾走の動作中に手を前方に加速させ、できるだけ速く動かします。", "膝を入れ替えて繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Kneeling_Arm_Drill';
UPDATE exercises SET name = '交互斜めツイストを伴うニーリング ケーブル クランチ', instructions = '["ロープアタッチメントをハイプーリーケーブルに接続し、その前の床にマットを置きます。", "両手でロープをつかみ、タワーから約 2 フィート後方にひざまずきます。", "ロープを頭の後ろに置き、手を耳の横に置きます。", "両手を同じ場所に保ち、腹筋を収縮させ、ひじが膝に届くまでクランチ運動でロープを下に引っ張ります。", "一番下で少し停止し、開始位置に到達するまでゆっくりと制御された方法で立ち上がります。", "半分まで下るまで同じ下向きの動きを繰り返します。半分まで下がった時点で、片方の肘を反対側の膝に向けて回転させ始めます。", "もう一度、一番下で少し停止し、開始位置に到達するまでゆっくりと制御された方法で立ち上がります。", "前と同じ動きを繰り返しますが、もう一方の肘を反対側の膝に交互に置きます。", "この一連の動作を失敗するまで続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists';
UPDATE exercises SET name = 'ニーリングケーブル上腕三頭筋エクステンション', instructions = '["ハイプーリーマシンの前にベンチを横向きに置きます。", "両手を約6インチ離し、手のひらを下に向けて、まっすぐなバーアタッチメントを頭の上に持ちます。", "機械から背を向けてひざまずきます。", "頭と上腕の後ろをベンチに置きます。肘を曲げて前腕をハイプーリーの方向に向けます。これが開始位置になります。", "肘を内側にして上腕を常に頭の近くに保ちながら、肘がロックされ腕が床と平行になるまで半円を描くようにバーを押し出します。上腕三頭筋を強く収縮させ、この位置を 1 秒間保持します。この動きをしながら息を吐きます。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Kneeling_Cable_Triceps_Extension';
UPDATE exercises SET name = 'ひざまずいて前腕のストレッチ', instructions = '["まず、マットの上にひざまずき、手のひらを平らにし、指を膝のほうに向けます。", "手首と前腕が伸びると感じるまで、手のひらを床に平らに保ちながら、ゆっくりと後ろにもたれかかります。 20〜30秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Kneeling_Forearm_Stretch';
UPDATE exercises SET name = 'ひざまずく滑車列', instructions = '["頭の上にある滑車を使用して適切な重量を選択してください。ケーブルにロープを取り付け、数フィート離れたところにひざまずき、両腕を伸ばしてロープを前に持ちます。これが開始位置になります。", "肘を曲げて肩を完全に引っ込めて動きを開始し、肘を外側に向けてロープを胸の上部に向かって引っ張ります。", "少し停止した後、ゆっくりと開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Kneeling_High_Pulley_Row';
UPDATE exercises SET name = 'ひざまずく股関節屈筋', instructions = '["マットの上にひざまずき、右膝を上げて足の裏が床につくようにし、左足を後ろに伸ばして足の甲が床につくようにします。", "腰が伸びていると感じるまで体重を前方に移動します。 15 秒間押し続けて、反対側も繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Kneeling_Hip_Flexor';
UPDATE exercises SET name = 'ニーリングジャンプスクワット', instructions = '["床にひざまずき、バーベルを肩の後ろに掛けて始めます。または、自分の体重を使ってこのエクササイズを行うこともできます。これはパワーラック内で行うことができ、ラックの取り外しが簡単になります。", "お尻が足に触れるまで腰を落として座り、頭と胸を上げたままにします。", "腰を爆発させて、足を床に平らに着地させるのに十分な力を生み出します。", "かかとを通って膝を伸ばして立ち位置までスクワットを続けます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Kneeling_Jump_Squat';
UPDATE exercises SET name = 'ひざまずくシングルアームハイプーリーロー', instructions = '["シングルハンドルをハイプーリーに取り付け、重量を選択します。", "ケーブル タワーの前にひざまずき、腕を伸ばして片手でケーブルを持ちます。これが開始位置になります。", "手のひらを前に向けた状態から始めて、肘を曲げて体重を胴体まで引き下げ、肩甲骨を引っ込めます。このとき、手首を回転させて、動きが完了した時点で手のひらが自分の方を向くようにします。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Kneeling_Single-Arm_High_Pulley_Row';
UPDATE exercises SET name = 'ニーリングスクワット', instructions = '["バーをパワーラックに適切な高さにセットします。バーの後ろにひざまずきます。膝を置くためにマットを敷くと効果的です。バーの下に滑り込ませ、肩の後ろに掛けます。肩甲骨を引っ込め、バーを背中全体にしっかりと締める必要があります。重りを外します。", "頭を前に向けて、ふくらはぎに触れるまでお尻をついて座ります。", "動きを逆にして、胴体を直立位置に戻します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Kneeling_Squat';
UPDATE exercises SET name = '地雷180年代', instructions = '["バーを地雷に差し込むか、コーナーにしっかりと固定します。バーに適切な重量を加えます。", "腕を前に伸ばし、両手でバーを肩の高さまで床から持ち上げます。ワイドスタンスを採用します。これが開始位置になります。", "体重を片側に完全に振り下ろしながら、体幹と腰を回転させてこの動きを実行します。エクササイズ中は腕を伸ばしたままにしてください。", "動作を逆にして、ウェイトを反対側まで振ります。", "セットが完了するまで交互に動きを続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Landmine_180s';
UPDATE exercises SET name = '地雷リニアジャマー', instructions = '["バーを地雷に差し込むか、バーがない場合はコーナーにしっかりと固定します。バーに適切な重量を加え、ハンドルアタッチメントをバーに配置します。", "ハンドルを肩に当ててバーを床から持ち上げます。これが開始位置になります。", "アスレティックな姿勢で、腕を曲げたまま、腰を曲げて腰を後ろにセットしてスクワットします。", "逆に、腰、膝、足首を力強く伸ばし、肘も伸ばして腕を伸ばします。この動きは、しゃがんだ状態からできるだけ力強く完全に伸ばして、爆発的に行う必要があります。", "開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Landmine_Linear_Jammer';
UPDATE exercises SET name = 'ラテラルバウンド', instructions = '["進行方向から 90 度を向いて半しゃがんだ姿勢を想定します。これが開始位置になります。", "外側の脚に体重を移動するときに、リード脚が内側に反動するようにします。", "すぐに押し出して伸ばし、できるだけ横にバウンドしようとします。", "着地したら、すぐに反対方向に押し出し、元の開始位置に戻ります。", "往復を数回繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Lateral_Bound';
UPDATE exercises SET name = 'ラテラルボックスジャンプ', instructions = '["短いボックスを隣に置き、快適な立位姿勢をとります。これが開始位置になります。", "素早くクォータースクワットをして伸張反射を開始し、すぐに方向を逆にして上と横にジャンプします。", "足がボックスの上に十分な隙間を確保できるように、膝を十分に高くします。", "ボックスの中央に着地し、脚を使って衝撃を吸収します。", "慎重にボックスの反対側に飛び降り、往復を数回繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Lateral_Box_Jump';
UPDATE exercises SET name = 'ラテラルコーンホップ', instructions = '["いくつかのコーンを数フィート離して一列に配置します。", "進行方向に対して 90 度を向いて、コーンの端の隣に立ちます。これが開始位置になります。", "膝を浸して伸張反射を開始することでジャンプを開始し、すぐに方向を逆にして地面を押し出し、コーンの上を横向きに上向きにジャンプします。", "脚を使って着地時の衝撃を吸収し、次のジャンプでリバウンドしてコーンの列を下っていきます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Lateral_Cone_Hops';
UPDATE exercises SET name = 'ラテラルレイズ - バンド付き', instructions = '["まず、エクササイズバンドの上に立ち、腕の長さで緊張が始まるようにします。肩の幅よりわずかに狭い回内（手のひらを太ももに向ける）グリップを使用してハンドルを握ります。ハンドルは太ももの側面に置く必要があります。腕は肘を少し曲げて伸ばし、背中はまっすぐにします。これが開始位置になります。", "息を吐きながら、横の肩を使ってハンドルを横に持ち上げます。ハンドルが平行より少し上になるまで持ち上げ続けます。ヒント: ハンドルを持ち上げるときは、水を注ぐように手をわずかに傾け、腕を伸ばしたままにしてください。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "ハンドルをゆっくりと開始位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Lateral_Raise_-_With_Bands';
UPDATE exercises SET name = '広背筋-SMR', instructions = '["床に横たわった状態で、フォームロールを背中の下の脇、脇の下のすぐ後ろに置きます。これが開始位置になります。", "体重を広背筋に移しながら、伸ばしている側の腕を後ろと横に伸ばし、上半身が地面から離れた状態に保ちます。 10〜30秒間保持し、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Latissimus_Dorsi-SMR';
UPDATE exercises SET name = 'レッグオーバーフロアプレス', instructions = '["床に横になり、ケトルベルを 1 つ胸の位置に置き、ハンドルを持ちます。作業側の脚を非作業側の脚の上に伸ばします。フリーアームを体側に伸ばしてサポートできます。", "ケトルブルをロックアウト位置に押し込みます。", "ケトルベルを肘の上に保ちながら、肘が地面に触れるまでウェイトを下げます。必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Leg-Over_Floor_Press';
UPDATE exercises SET name = 'レッグアップ・ハムストリングのストレッチ', instructions = '["仰向けに寝て片膝を曲げ、その足を床に平らに置いて背骨を安定させます。", "もう一方の脚を空中に伸ばします。固い場合はまっすぐにすることができません。大丈夫です。持ち上げた足の裏が天井に向くように（またはできるだけ天井に近づくように）膝を伸ばします。", "ゆっくりと脚をできるだけ真っ直ぐにしてから、脚を鼻のほうに引き寄せます。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Leg-Up_Hamstring_Stretch';
UPDATE exercises SET name = 'レッグエクステンション', instructions = '["このエクササイズでは、レッグエクステンションマシンを使用する必要があります。まず体重を選択し、足をパッドの下に置き（足を前に向けて）、手でサイドバーを持ち、マシンに座ります。これが開始位置になります。ヒント: パッドが下腿の上 (足のすぐ上) に来るようにパッドを調整する必要があります。また、下肢と上肢の間で脚が 90 度の角度を形成していることを確認してください。角度が 90 度未満の場合は、膝がつま先の上にあることを意味し、膝関節に過度のストレスが生じます。マシンがそのように設計されている場合は、別のマシンを探すか、エクササイズの実行を開始するときに 90 度の角度に到達したら下降が停止することを確認してください。", "大腿四頭筋を使用して、息を吐きながら脚を最大限に伸ばします。体の残りの部分がシート上で静止したままであることを確認してください。収縮した位置で 1 秒間停止します。", "90 度の角度制限を超えないように、息を吸いながらゆっくりとウェイトを元の位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leg_Extensions';
UPDATE exercises SET name = 'レッグリフト', instructions = '["両足を肩幅くらいに並べてまっすぐに立ち、スクワットラックの側面や椅子の上部などの丈夫な面をつかんで、体を引き締めてバランスを保ちます。", "アンクルウェイトの有無にかかわらず、レッグカールを行うかのように片方の脚を後ろに持ち上げますが、もう一方の脚はまっすぐに保ちながら立ちます。この動きをしながら息を吐きます。", "息を吸いながら、上げた脚をゆっくりと床に戻します。", "推奨回数だけ繰り返します。", "反対側の足でもこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Leg_Lift';
UPDATE exercises SET name = 'レッグプレス', instructions = '["レッグプレスマシンを使用して、マシンに座り、中程度（肩幅）の足のスタンスで両脚を体の正面のプラットフォームに置きます。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足の位置のセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "加重プラットフォームを所定の位置に保持している安全バーを下げ、足が前に完全に伸びるまでプラットフォームを押し上げます。ヒント: 膝を固定しないように注意してください。胴体と脚が完全に 90 度の角度をなしている必要があります。これが開始位置になります。", "息を吸いながら、上脚と下脚が 90 度の角度になるまでプラットフォームをゆっくりと下げます。", "主に足のかかとで押し、大腿四頭筋を使用すると、息を吐きながら開始位置に戻ります。", "推奨回数繰り返し、完了したら安全ピンを適切にロックしてください。完全に荷物を積んだ状態でそのプラットフォームが落ちてしまうのは望ましくありません。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leg_Press';
UPDATE exercises SET name = 'レッグプルイン', instructions = '["エクササイズマットの上に横になり、脚を伸ばし、手のひらを体の横に下に向けるか、臀部の下に置きます。ヒント: 私の好みは、手を隣に置くことです。これが開始位置になります。", "膝を曲げ、息を吐きながら太ももの上部を中央部に引き寄せます。膝が胸の高さになるまでこの動きを続けます。この動きを実行するときに腹筋を収縮させ、頂点で 1 秒間保持します。ヒント: この動作を実行するとき、下肢 (ふくらはぎ) は常に床と平行に保つ必要があります。", "息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Leg_Pull-In';
UPDATE exercises SET name = 'チェストプレスを活用する', instructions = '["ピンに適切な重りを乗せ、身長に合わせてシートを調整します。動作の開始時には、ハンドルは胸筋の下部または中央付近にある必要があります。", "胸と頭を上げ、肩甲骨を引っ込める必要があります。これが開始位置になります。", "肘を通してハンドルを前方に押します。", "トップで少し停止した後、開始位置のすぐ上にウェイトを戻します。セットが完了するまでウェイトを停止位置に戻さず、筋肉の緊張を保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Chest_Press';
UPDATE exercises SET name = 'デッドリフトを活用する', instructions = '["ピンに適切な重量を加えます。ハンドルの間に直接立ちます。下部のハンドルを快適なグリップで握り、息を吸いながら腰を下げます。頭を前に向けて胸を張ってください。これが開始位置になります。", "ウェイトを開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Deadlift';
UPDATE exercises SET name = 'デクラインチェストプレスを活用する', instructions = '["ピンに適切な重りを乗せ、身長に合わせてシートを調整します。動作の開始時にはハンドルが胸筋の底近くにある必要があります。胸と頭を上げ、肩甲骨を引っ込める必要があります。これが開始位置になります。", "肘を通してハンドルを前方に押します。", "トップで少し停止した後、開始位置のすぐ上にウェイトを戻します。セットが完了するまでウェイトをストップ位置に戻さず、筋肉の緊張を保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Decline_Chest_Press';
UPDATE exercises SET name = 'ハイローを活用する', instructions = '["ピンに適切な重りを載せて、ちょうど上のハンドルに手が届くようにシートの高さを調整します。膝パッドを調整して、姿勢を低く保ちます。回内グリップでハンドルを握ります。これが開始位置になります。", "ハンドルを胴体に向かって引き、肘を曲げながら肩甲骨を引っ込めます。", "動作の最下部で一時停止し、ゆっくりとハンドルを開始位置に戻します。", "複数回繰り返す場合は、鍛えられている筋肉の緊張を維持するために、体重をストップまで完全に戻すことは避けてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_High_Row';
UPDATE exercises SET name = 'インクラインチェストプレスを活用する', instructions = '["ピンに適切な重りを乗せ、身長に合わせてシートを調整します。動作の開始時にはハンドルが胸筋の上部近くにある必要があります。胸と頭を上げ、肩甲骨を引っ込める必要があります。これが開始位置になります。", "肘を通してハンドルを前方に押します。", "トップで少し停止した後、開始位置のすぐ上にウェイトを戻します。セットが完了するまでウェイトをストップ位置に戻さず、筋肉の緊張を保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Incline_Chest_Press';
UPDATE exercises SET name = 'Iso Rowを活用する', instructions = '["ピンに適切な重りを乗せ、ハンドルが胸の高さになるようにシートの高さを調整します。ニュートラルグリップまたは回内グリップでハンドルを握ります。これが開始位置になります。", "ハンドルを胴体に向かって引き、肘を曲げながら肩甲骨を引っ込めます。", "動作の最下部で一時停止し、ゆっくりとハンドルを開始位置に戻します。複数回繰り返す場合は、鍛えられている筋肉の緊張を維持するために、体重をストップまで完全に戻すことは避けてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Iso_Row';
UPDATE exercises SET name = 'ショルダープレスを活用する', instructions = '["ピンに適切な重りを乗せ、身長に合わせてシートを調整します。動作の開始時にはハンドルが肩の上部近くにある必要があります。胸と頭を上げ、ハンドルを回内グリップで持ちます。これが開始位置になります。", "肘を通してハンドルを上に押し上げます。", "トップで少し停止した後、開始位置のすぐ上にウェイトを戻します。セットが完了するまでウェイトを停止位置に戻さず、筋肉の緊張を保ちます。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Shoulder_Press';
UPDATE exercises SET name = '肩をすくめて活用する', instructions = '["ピンに適切な重量を加えます。ハンドルの間に直接立ちます。", "上部のハンドルを快適なグリップで握り、息を吸いながら腰を下げます。頭を前に向けて胸を張ってください。", "かかとで床を踏み切り、腰と膝を伸ばして立った位置に上がります。動作中は腕をまっすぐに保ち、最後に肩を後ろに戻します。これが開始位置になります。", "肩を耳に向かってすくめ、まっすぐ上下に動かして体重を上げます。", "動作の最高点で一時停止し、体重を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Leverage_Shrug';
UPDATE exercises SET name = 'リニア 3 パート スタート テクニック', instructions = '["このドリルは、行き止まりから全力疾走に向けてできるだけ早く加速するのに役立ちます。開始点に線を使用すると便利です。両足をライン上に置いた状態から始めます。左足のつま先を右足首の横に置きます。右足を左足の4～6インチ後ろに置きます。", "右手をラインの上に置き、鼻を左膝に近づけます。", "前傾姿勢でしゃがみ、頭を腰より低くし、体重を左脚に置きます。これが開始位置になります。", "左手を地面と平行になるように上げ、体の後ろを指し、準備ができたら爆発させます。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Linear_3-Part_Start_Technique';
UPDATE exercises SET name = '直線加速ウォールドリル', instructions = '["壁に対して約45度の角度で寄りかかります。両足を揃え、臀部を収縮させます。", "まずは右膝を素早く上げて停止し、まっすぐ地面に押し込みます。", "足を入れ替えて反対側の膝を上げ、地面をまっすぐに攻撃します。", "もう一度右足で繰り返し、右足が地面に着いたらすぐに素早く左右に交互にできるだけ速く叩き出します。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Linear_Acceleration_Wall_Drill';
UPDATE exercises SET name = 'リニアデプスジャンプ', instructions = '["互いに数フィート離れた 2 つのボックスまたはベンチが必要です。まず、一方のボックスの上にもう一方のプラットフォームに面して立ちます。", "動きを開始するには、プラットフォームの間の地面にゆっくりと降り、膝と股関節を曲げます。", "動きを逆にするには、爆発して腰、膝、足首を伸ばして他のプラットフォームにジャンプします。", "足に伝わる衝撃を和らげながら、ソフトに着地します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Linear_Depth_Jump';
UPDATE exercises SET name = '丸太リフト', instructions = '["丸太を目の前にして立ち始めます。ハンドルを握り、丸太の掃除を始めます。掃除を始めるために前かがみになったときに、丸太をできるだけ高く持ち上げて、胸の中に引き込みます。ヒップと膝を伸ばして引き上げると、きれいになります。", "頭を後ろに押し上げて上を向き、胸に丸太を置く棚を作ります。プレスを浸すことから始め、膝をわずかに曲げ、動きを逆にします。この押し込みプレスにより丸太が垂直に動き始める勢いが生まれます。続けて肘を伸ばして頭の上の丸太を押します。フォームに厳密なルールはありませんので、最も効率的なテクニックを使用してください。丸太を押すときは、繰り返しのたびに前を向いて頭を押し進めるようにしてください。", "できるだけ何度も繰り返します。丸太を地面に戻すときに、その下降を制御しようとします。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Log_Lift';
UPDATE exercises SET name = 'ロンドン橋', instructions = '["クライミングロープをハイビームまたはクロスメンバーに取り付けます。その下で、スミス マシンのバーが安全装置で所定の位置にロックされ、動かないことを確認します。あるいは、安全なボックスを利用することもできます。", "バーの上に立ち、ロープを使ってバランスをとります。これが開始位置になります。", "体をまっすぐに保ち、後ろに寄りかかり、ロープをゆっくりと両手で動かしながら体を下げます。地面に対して垂直になるまで続けます。", "体を真っすぐに保ったまま、逆の動きで両手を重ねて開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'London_Bridges';
UPDATE exercises SET name = '天井を見る', instructions = '["床にひざまずき、両手でかかとを持ちます。", "お尻を前方に持ち上げながら、頭を後ろに戻して天井を見上げ、背中にアーチを作ります。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Looking_At_Ceiling';
UPDATE exercises SET name = '低いケーブルクロスオーバー', instructions = '["開始位置に移動するには、滑車を低い位置に置き、使用する負荷を選択し、両手でハンドルを握ります。", "前に進み、滑車に張力を加えます。手のひらは前を向き、手を腰より下に置き、腕はまっすぐに伸ばします。これが開始位置になります。", "腕を軽く曲げて、手を上に、体の正中線に向かって引き寄せます。両手は胸の前で組み、手のひらを上に向けます。", "少し停止した後、腕を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Low_Cable_Crossover';
UPDATE exercises SET name = 'ローケーブル上腕三頭筋エクステンション', instructions = '["希望の重量を選択し、ロープが取り付けられたシーテッドローマシンのベンチに仰向けに寝ます。頭はアタッチメントの方向を向いているはずです。", "手のひらを向かい合わせてロープの端の外側を握ります（ニュートラルグリップ）。", "肘が 90 度の角度で曲がり、上腕が胴体に対して垂直 (90 度の角度) になるように位置を決めます。ヒント: 肘を内側に保ち、上腕が天井を向くようにし、前腕が頭上の滑車を向くようにします。これが開始位置になります。", "息を吐きながら、前腕がまっすぐ垂直になるまで伸ばします。上腕と肘は動作中静止したままになります。前腕だけを動かす必要があります。上腕三頭筋を 1 秒間強く収縮させます。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Low_Cable_Triceps_Extension';
UPDATE exercises SET name = '首までの低プーリー列', instructions = '["ロープが取り付けられた低滑車ローイングマシンに座ります。", "手のひらを下にしてロープの端を持ち、背筋を伸ばして膝を軽く曲げて座ります。ヒント: 背中をほぼ完全に垂直にし、腕を前に完全に伸ばします。これが開始位置になります。", "胴体を動かさないようにしながら、肘を上げて曲げ始め、息を吐きながらロープを首に向かって引っ張ります。動きの間中、上腕は床と平行に保つ必要があります。ヒント: 手がほぼ耳の近くに来て (前腕は少し上向きに傾いているため、動きの終わりには床と平行になりません)、肘が体側から離れるまでこの動きを続けます。", "収縮した位置で 2 秒ほど保持した後、息を吸いながらゆっくりと開始位置に戻ります。ヒント: 繰り返しになりますが、動作のどの部分でも胴体を動かしてはなりません。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Low_Pulley_Row_To_Neck';
UPDATE exercises SET name = '腰部-SMR', instructions = '["座った姿勢で、フォームロールを腰の下に置きます。腕を前で交差させ、肩を突き出します。これが開始位置になります。", "腰を床から上げて後ろにもたれかかり、体重を腰に掛けたままにします。次に、体重をわずかに片側に移動し、体重が背骨とその側の筋肉にかからないようにします。腰をローリングし、緊張点を10〜30秒間保持します。反対側でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Lower_Back-SMR';
UPDATE exercises SET name = 'ローワーバックカール', instructions = '["腕を体の横に広げてうつ伏せになります。これが開始位置になります。", "腰の筋肉を使って背骨を伸ばし、胸を地面から持ち上げます。腕を使って体を押し上げないでください。動作中は頭を上げたままにしてください。 10〜20回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Lower_Back_Curl';
UPDATE exercises SET name = 'ランジパススルー', instructions = '["右手にケトルベルを持ち、上体を直立させて立ちます。これが開始位置になります。", "左足を前に踏み出し、腰と膝を曲げて上体を下げ、胴体を直立状態に保ちます。後ろの膝を地面につく寸前まで下げます。", "ランジしながら、前足の下にあるケトルベルを反対側の手に渡します。", "足のかかとを押しながら、開始位置に戻ります。", "脚を交互に動かし、推奨回数だけこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Lunge_Pass_Through';
UPDATE exercises SET name = 'ランジスプリント', instructions = '["スミスマシンのバーを適切な高さに調整します。バーの下に体を置き、肩の後ろでバーを持ち上げます。バーを外し、両足を分割して、片足を前に、もう片足を後ろに動かします。これが開始位置になります。", "後ろの膝を地面近くまで下げ、膝を曲げながら腰を下げます。", "下り坂の一番下ですぐに方向を反転します。後ろ足で軽い圧力をかけながら、前足のかかとを爆発的に押し込みます。飛び上がって足の位置を逆にします。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Lunge_Sprint';
UPDATE exercises SET name = '横たわって脚の付け根を曲げた状態', instructions = '["膝を曲げて足の裏を合わせて仰向けに寝ます。パートナーに膝を抱えてもらいます。これが開始位置になります。", "パートナーが動きを妨げている間、膝をしっかりと締めるようにしてください。", "10 ～ 20 秒後、パートナーがゆっくりと膝を床に向かって押しながら、筋肉をリラックスさせます。怪我や過度のストレッチを防ぐために、ストレッチが適切であることを必ずヘルパーに伝えてください。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Lying_Bent_Leg_Groin';
UPDATE exercises SET name = 'ライイングケーブルカール', instructions = '["ロープーリーに取り付けられたストレートバーまたは E-Z バーアタッチメントを両手で、アンダーハンド (手のひらを上に向けて) 肩幅くらいの幅で握ります。", "ウエイトスタックの前のエクササイズマットの上に仰向けになり、プーリーマシンのフレームに対して足を平らにし、脚をまっすぐにします。", "腕を伸ばし、肘を体の近くに置き、腕をわずかに曲げます。これが開始位置になります。", "上腕を動かさず、肘を体に近づけたまま、息を吐きながらバーを胸に向かってゆっくりとカールさせ、上腕二頭筋を締めます。", "動きの一番上でもう一度絞った後、ゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Lying_Cable_Curl';
UPDATE exercises SET name = 'ライイングキャンバーバーベルロウ', instructions = '["エクササイズベンチの下に反りのあるバーを置きます。", "エクササイズベンチにうつ伏せになり、手のひらを下にして肩幅より広い幅でバーを握ります（回内グリップ）。これが開始位置になります。", "息を吐きながらバーを上げ、肘を体に近づけて胸のどちらかに近づけます（背中の上部中央をターゲットにする場合）。広背筋をターゲットにする場合は腹部に近づけます。", "もう一度トップを維持した後、息を吸いながらゆっくりと開始位置まで腰を下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Lying_Cambered_Barbell_Row';
UPDATE exercises SET name = 'ハイプーリーに横たわってクローズグリップバーカール', instructions = '["ハイプーリーまたはラットプルダウンマシンの前にフラットベンチを置きます。", "肩幅程度のアンダーハンドグリップ (手のひらを上) を使用して、ストレートバーアタッチメントを持ちます。", "頭をベンチの端の上に置いて仰向けに寝ます。", "次に、腕を肩の上にまっすぐ伸ばします。胴体と腕が 90 度の角度をなし、肘が内側にある必要があります。これが開始位置になります。", "息を吐きながら、あごに触れるまでバーを半円を描くように曲げます。上腕の収縮した位置で上腕二頭筋を 1 秒間締めます。ヒント: このモーションを実行するときは、前腕のみが動きます。上腕は決して動かしてはいけません。動作中は垂直を保つ必要があります。", "ゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Lying_Close-Grip_Bar_Curl_On_High_Pulley';
UPDATE exercises SET name = '横たわってクローズグリップバーベル上腕三頭筋を頭の後ろで伸ばす', instructions = '["バーベルまたは EZ カール バーを回内グリップ (手のひらを前に向ける) で持ち、フラット ベンチに仰向けになり、頭をベンチの端に近づけます。ヒント: バーベルを持っている場合は肩幅のグリップを使用して握り、E-Z バーを使用している場合は内側のハンドルをつかみます。", "腕を前に伸ばし、（腕を伸ばしたまま）半円を描くようにゆっくりとバーを頭上の位置まで戻します。このステップの終わりには、腕が頭上にあり、床と平行になっているはずです。これが開始位置になります。ヒント: 肘は常に内側に置いておきます。", "息を吸いながら、上腕を動かさないようにしながら、肘を曲げてバーを下げます。前腕が床に対して垂直になるまでバーを下げ続けます。", "息を吐きながら、下腕も床と平行になるまで半円を描くようにバーを押し上げて、バーを開始位置に戻します。動きの頂点で上腕三頭筋を 1 秒間強く収縮させます。ヒント: 繰り返しますが、前腕のみを動かす必要があります。上腕は常に静止したままにしておく必要があります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head';
UPDATE exercises SET name = '横たわってクローズグリップバーベルトライセプスプレストゥアゴ', instructions = '["回内グリップ（手のひらを前に向ける）でバーベルまたはEZカールバーを持ち、頭をベンチの端から離してフラットベンチに仰向けになります。ヒント: バーベルを持っている場合は肩幅のグリップを使用して握り、E-Z バーを使用している場合は内側のハンドルをつかみます。", "バーベルを胸の上に持ちながら腕を前に伸ばします。腕は胴体に対して垂直（90度の角度）である必要があります。これが開始位置になります。", "息を吸いながら、上腕を動かさずに肘を内側に保ちながら、肘を曲げて半円を描くようにバーを下げます。顎に軽く触れるまでバーを下げ続けます。", "息を吐きながら、半円を描くようにバーを押し上げて、バーを開始位置に戻します。動きの頂点で上腕三頭筋を 1 秒間強く収縮させます。ヒント: 繰り返しますが、前腕のみを動かす必要があります。上腕は常に静止したままにしておく必要があります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Lying_Close-Grip_Barbell_Triceps_Press_To_Chin';
UPDATE exercises SET name = 'ライイングクロスオーバー', instructions = '["足を伸ばして仰向けに寝ます。", "片足を体の上で交差させ、膝を曲げ、膝が地面に着くようにします。パートナーはあなたの横にひざまずいて、片手で肩を押さえ、もう一方の手で組んだ足をコントロールする必要があります。これが開始位置になります。", "パートナーが実際の動きを妨げるので、曲がった膝を地面から持ち上げようとします。", "10 ～ 20 秒後、パートナーが膝を床に向かって軽く押しながら、脚をリラックスさせます。反対側でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Lying_Crossover';
UPDATE exercises SET name = 'ライイングダンベルトライセップエクステンション', instructions = '["2つのダンベルを目の前に持ちながら、平らなベンチに横になります。腕は胴体と床から 90 度の角度で完全に伸ばす必要があります。手のひらは内側に向け、肘は内側に押し込む必要があります。これが開始位置です。", "息を吸いながら、肘をついて上腕を動かさないようにしながら、ダンベルが耳の近くに来るまでゆっくりと体重を下げます。", "この時点で、肘を内側に置き、上腕を動かさないようにしながら、息を吐きながら上腕三頭筋を使って体重を開始位置まで戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Lying_Dumbbell_Tricep_Extension';
UPDATE exercises SET name = 'うつ伏せプレートの首の抵抗', instructions = '["頭の後ろにウェイトプレートを持ち、平らなベンチに体全体をまっすぐにしてうつ伏せになります。ヒント: 胸の上部、首、顔がベンチから離れるように、肩がフラットベンチの端よりわずかに上になるように位置を取る必要があります。これが開始位置になります。", "プレートを後頭部に固定したまま、息を吸いながらゆっくりと頭を下げます（「はい」と言うように）。", "息を吐きながら、半円を描くように頭を元の位置まで上げます。収縮を 1 秒間保持します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Lying_Face_Down_Plate_Neck_Resistance';
UPDATE exercises SET name = '仰向け寝プレートの首の抵抗', instructions = '["額の上にウェイトプレートを置き、平らなベンチに体全体をまっすぐにして仰向けに寝ます。ヒント: トラップ、首、頭がベンチから離れるように、肩がフラットベンチの端よりわずかに上になるように位置を取る必要があります。これが開始位置になります。", "プレートを額に固定したまま、息を吸いながら半円を描くようにゆっくりと頭を後ろに下げます。", "息を吐きながら、半円を描くように頭を元の位置まで上げます。収縮を 1 秒間保持します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Lying_Face_Up_Plate_Neck_Resistance';
UPDATE exercises SET name = '横たわる臀部', instructions = '["仰向けになり、パートナーが横にひざまずきます。", "片方の脚の股関節を曲げて床から持ち上げます。足が反対側の腰の上に来るように脚を回転させ、下腿が体に対して垂直になるようにします。パートナーは膝と足首を所定の位置に保持する必要があります。これが開始位置になります。", "パートナーに向かって足を押してみますが、パートナーは実際に足を動かすのを妨げているはずです。", "10 ～ 20 秒後、パートナーが足首と膝を胸に向かって優しく押しながら、完全にリラックスします。怪我や過度のストレッチを防ぐために、ストレッチが適切であることを必ずヘルパーに伝えてください。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Lying_Glute';
UPDATE exercises SET name = '横たわっているハムストリング', instructions = '["足を伸ばして仰向けに寝ます。あなたのパートナーはあなたの隣にひざまずいているはずです。片足を天井に向かって上げ、パートナーに足首を持ってもらいます。必要に応じて、パートナーは肩を使ってあなたの足を支えることができます。これが開始位置になります。", "パートナーに脚を固定してもらい、膝を曲げてハムストリングを 10 ～ 20 秒間収縮させます。", "次に、足をリラックスさせて、パートナーが足をあなたの頭の方へそっと押してもらいます。怪我や過度のストレッチを防ぐために、ストレッチが適切であることを必ずヘルパーに伝えてください。完了したらサイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Lying_Hamstring';
UPDATE exercises SET name = 'ライイングハイベンチバーベルカール', instructions = '["背の高い平らなベンチに前向きに寝て、バーベルを回外グリップで持ちます（手のひらを上に向けます）。ヒント: バーベルを持っている場合は肩幅のグリップを使用して握り、E-Z バーを使用している場合は内側のハンドルをつかみます。上半身は、胸の上部がベンチの端の上にあり、腕を伸ばして床に垂直にしてバーベルを前にぶら下げるように配置する必要があります。これが開始位置になります。", "肘を内側に入れ、上腕を動かさないようにしながら、上腕二頭筋を収縮させて息を吐きながら、ウェイトを半円を描くように丸めます。ムーブメントの上部を 1 秒間押し続けます。", "息を吸いながら、ゆっくりと元の位置に戻ります。ヒント: 常に体重を完全にコントロールし、揺れを避けてください。動作中は前腕のみを動かす必要があることに注意してください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Lying_High_Bench_Barbell_Curl';
UPDATE exercises SET name = 'ライイングレッグカール', instructions = '["マシンのレバーを身長に合わせて調整し、レバーのパッドが脚の後ろ（ふくらはぎの数インチ下）にくるようにレッグカールマシンにうつ伏せになります。ヒント: レッグ カール マシンは、フラットではなく角度を付けて使用することをお勧めします。これは、角度を付けた位置の方がハムストリングを鍛えるのに適しているためです。", "胴体をベンチ上で平らに保ち、脚が完全に伸びていることを確認して、マシンのサイドハンドルを握ります。つま先をまっすぐに置きます (または、足の位置のセクションで説明されている他の 2 つのスタンスのいずれかを使用することもできます)。これが開始位置になります。", "息を吐きながら、上脚をパッドから持ち上げずに、脚をできるだけ上に丸めます。完全に収縮した位置に到達したら、その状態を 1 秒間保持します。", "息を吸いながら足を元の位置に戻します。推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Lying_Leg_Curls';
UPDATE exercises SET name = 'ライイングマシンスクワット', instructions = '["膝を曲げ、太ももが平行より少し下にある状態でレッグマシンが中に入るような高さにレッグマシンを調整します。", "重量を選択したら、膝を曲げ、太ももをプラットフォームと平行に少し下にして、マシン内で体を上向きに配置します。膝がつま先より前に出ないように注意してください。ハムストリングスとふくらはぎの間の角度は 90 度よりわずかに小さい角度にする必要があります (開始位置では平行より少し下で開始する必要があるため)。肩がショルダーパッドの下に押し付けられている間、背中と頭がマシンの上に置かれている必要があります。", "ハンドルの横に手を置き、足を肩幅の位置でわずかに外側に向けます。これが開始位置になります。", "息を吐きながら足の指の付け根で押しながら、大腿四頭筋を締めながら体全体を直立させます。収縮した位置を 1 秒間保持します。ヒント: 平行線より下でスタートするので、最初の繰り返しのときだけ太ももに力を入れて、手を使って体を持ち上げることを選択できます。", "息を吸いながらゆっくりとしゃがみますが、開始位置まで完全に下がるのではなく、太ももがプラットフォームと平行になった時点で停止します。ハムストリングスとふくらはぎの間の角度は90度である必要があります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Lying_Machine_Squat';
UPDATE exercises SET name = '横たわって片腕を横に上げる', instructions = '["ダンベルを片手に持ち、平らなベンチに胸を向けて横になります。もう片方の手でベンチの脚を掴むと安定します。", "肘を軽く曲げて腕を伸ばしたまま、ダンベルを持つ手の手のひらを中立的な姿勢（手のひらを胴体に向ける）に置きます。これが開始位置になります。", "次に、肘が肩の高さになり、息を吐きながら腕が床とほぼ平行になるまで、ダンベルを持った腕を横に上げます。ヒント: 動作中は腕を伸ばしたままにし、胴体に対して腕を垂直に保ちます。また、収縮を上部で 1 秒間続けてください。", "息を吸いながら、ダンベルを開始位置までゆっくりと下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Lying_One-Arm_Lateral_Raise';
UPDATE exercises SET name = 'うつ伏せの大腿四頭筋', instructions = '["床にうつ伏せになり、パートナーがあなたの隣にひざまずきます。片方の膝を曲げてその脚を地面から上げ、足でお尻に触れるようにしてください。パートナーは膝と足首を支える必要があります。これが開始位置になります。", "パートナーが実際の動きを妨げている間に、膝を伸ばしてみてください。", "10 ～ 20 秒後、パートナーが足を臀部に向かって優しく押し、大腿四頭筋と股関節屈筋をさらに伸ばしながら筋肉をリラックスさせます。", "10〜20秒後、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Lying_Prone_Quadriceps';
UPDATE exercises SET name = 'ライイング・リア・デルト・レイズ', instructions = '["ダンベルを両手に持ち、胸を下にして平らなベンチに横になります。", "肘をわずかに曲げて腕を伸ばしたまま、手の平を中立的な姿勢（手のひらを胴体に向ける）に置きます。これが開始位置になります。", "次に、息を吐きながら肘が肩の高さになり、腕が床とほぼ平行になるまで腕を横に上げます。ヒント: 動作中は腕を胴体に対して垂直に保ち、腕を伸ばしたままにします。また、収縮を上部で 1 秒間続けてください。", "息を吸いながら、ゆっくりとダンベルを開始位置まで下げます。", "推奨回数だけ繰り返した後、もう一方の腕に切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Lying_Rear_Delt_Raise';
UPDATE exercises SET name = 'ライイング・スパイン・ダンベルカール', instructions = '["フラットベンチに仰向けになり、両腕でダンベルを太ももの上に持ちます。", "腕を伸ばし、手のひらを太ももに向けてダンベルを横に持ちます（ニュートラルグリップ）。", "腕を胴体に近づけて肘を内側に置きながら、腕をゆっくりと（肘を軽く曲げて伸ばしたままにしながら）床に向かってできるだけ下げます。これ以上下がれなくなったら、上腕をその位置でロックし、それが開始位置になります。", "息を吐きながら、ゆっくりとウェイトを巻き上げ始め、同時に手首を回転させて手のひらを上に向けます。上腕二頭筋が完全に収縮するまでウェイトをカールし続け、トップの位置で 1 秒間強く絞ります。ヒント: 前腕のみを動かす必要があります。動きの間中、上腕は動かさず、肘は閉じたままにしておく必要があります。", "非常にゆっくりと開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Lying_Supine_Dumbbell_Curl';
UPDATE exercises SET name = 'ライイング T バー ロウ', instructions = '["T バーローマシンに希望の重量を負荷し、胸の上部がパッドの上部に来るように脚の高さを調整します。ヒント: 一部のマシンでは、胸の上部がパッドの上部にくる高さになる適切なステップに立つことしかできません。", "パッドの上にうつ伏せになり、ハンドルを握ります。強調したい背中の部分に応じて、手のひらを下にするか、手のひらを上にするか、手のひらを置く位置を使用できます。", "バーをラックから持ち上げ、腕を前に伸ばします。これが開始位置になります。", "ゆっくりと息を吐きながら体重を引き上げ、動きの一番上で背中を締めます。ヒント: 背中の筋肉をより効果的に働かせるために、動作中は上腕をできるだけ胴体に近づけてください。また、決してパッドから体を持ち上げたり、重量を持ち上げるために上腕二頭筋を使用したりしないでください。", "動きの上部で 2 回目の収縮を行った後、息を吸いながらゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Lying_T-Bar_Row';
UPDATE exercises SET name = 'ライイング・トライセプス・プレス', instructions = '["e-zバー（私の好み）またはストレートバーを頭の後ろの床に置き、足を床に置いた平らなベンチに横になります。", "中程度のオーバーハンド (回内) グリップを使用してバーを後ろに持ち、腕の長さでバーを前に上げます。ヒント: 腕は胴体と床に対して垂直である必要があります。肘は内側に引き込む必要があります。これが開始位置です。", "息を吸いながら、上腕と肘を動かさないようにしながら、バーが額に軽く触れるまでゆっくりとウェイトを下げます。", "この時点で、息を吐きながら上腕三頭筋を使って体重を開始位置まで戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Lying_Triceps_Press';
UPDATE exercises SET name = 'マシンベンチプレス', instructions = '["チェストプレスマシンに座り、重量を選択します。", "マシンに付属のレバーを踏むと、ハンドルが前方に移動し、ハンドルをつかんで腕を完全に伸ばすことができます。", "手のひらを下にしてハンドルを握り、上腕が胴体の側面の床と平行になるように肘を上げます。ヒント: ハンドルを握るので、前腕は前を向きます。ハンドルを前方に持ってきて腕を伸ばすと、開始位置になります。", "次に、息を吸いながらハンドルを手前に戻します。", "胸筋を曲げて息を吐きながら、ハンドルを体から遠ざけます。開始位置に戻る前に、収縮を 1 秒間保持します。", "推奨される回数だけ繰り返します。", "終了したら、もう一度レバーを踏み、ゆっくりとハンドルを元の位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Machine_Bench_Press';
UPDATE exercises SET name = 'マシンバイセップカール', instructions = '["シートを適切な高さに調整し、体重を選択してください。上腕をパッドの上に置き、ハンドルを握ります。これが開始位置になります。", "この動きを行うには、肘を曲げ、下腕を上腕に向かって引っ張ります。", "動きの頂点で一時停止し、ゆっくりと体重を開始位置に戻します。", "鍛えられている筋肉の緊張を保つために、セットが完了するまでウェイトをストップまで戻さないようにしてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Machine_Bicep_Curl';
UPDATE exercises SET name = 'マシンプリーチャーカール', instructions = '["プリーチャーカールマシンに座り、重さを選択します。", "上腕の後ろ（上腕三頭筋）を付属のプリーチャーパッドの上に置き、アンダーハンドグリップ（手のひらを上に向けて）を使用してハンドルを握ります。ヒント: 腕をパッドの上に置くときは、肘を内側に置いておくようにしてください。これが開始位置になります。", "次に、息を吐きながらハンドルを持ち上げ、上腕二頭筋を収縮させます。ポジションのトップでは、収縮を1秒間保持していることを確認してください。ヒント: 前腕のみを動かします。上腕は常にパッドの上に固定したままにしておく必要があります。", "息を吸いながらハンドルをゆっくりと下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Machine_Preacher_Curls';
UPDATE exercises SET name = 'マシンショルダー（ミリタリー）プレス', instructions = '["ショルダープレスマシンに座り、重量を選択します。", "肘を曲げて胴体と一直線に保ちながら、ハンドルを体の側面に持ちます。これが開始位置になります。", "次に、息を吐きながらハンドルを持ち上げ、腕を完全に伸ばします。ポジションのトップでは、収縮を1秒間保持していることを確認してください。", "息を吸いながらハンドルをゆっくりと下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Machine_Shoulder_Military_Press';
UPDATE exercises SET name = 'マシン上腕三頭筋エクステンション', instructions = '["シートを適切な高さに調整し、体重を選択してください。上腕をパッドの上に置き、ハンドルを握ります。これが開始位置になります。", "この動きを行うには、肘を伸ばし、下腕を上腕から引き離します。", "動作が完了したら一時停止し、ゆっくりと体重を開始位置に戻します。", "鍛えられている筋肉の緊張を保つために、セットが完了するまでウェイトをストップまで戻さないようにしてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Machine_Triceps_Extension';
UPDATE exercises SET name = 'メディシン ボール チェスト パス', instructions = '["この演習にはパートナーが必要です。 1 つが欠けていると、この動作は壁に対して実行できます。", "両手で胴体にメディシン ボールを持ったパートナーと向き合い始めます。", "ボールを胸に引き寄せ、逆の動きで肘を伸ばします。スポーツ用途では、投げながらステップを踏むことができます。", "あなたのパートナーはボールをキャッチし、あなたに投げ返す必要があります。", "胸の高さで両手で投げを受けます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Medicine_Ball_Chest_Pass';
UPDATE exercises SET name = 'メディシン ボール フル ツイスト', instructions = '["この演習では、メディシン ボールとパートナーが必要です。パートナーと背中合わせに立ち、2～3フィートの間隔をあけてください。これが開始位置になります。", "体幹の前でボールを持ちます。パートナーと同時に腰を開き、肩を回します。", "完全に回転させるには、あなたとパートナーは同じ方向、つまり反時計回りにひねる必要があります。", "ボールをパートナーにパスすると、二人とも反対方向にひねって同じ手順を繰り返すことができます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Medicine_Ball_Full_Twist';
UPDATE exercises SET name = 'メディシンボールすくい投げ', instructions = '["メディシンボールを手に持って半しゃがみの姿勢をとります。ボールが足の近くに来るように腕を下げます。", "まず腰を前に突き出し、脚を伸ばして飛び上がります。", "このとき、腕を頭上に振り上げ、伸ばしたままにし、動きのピークでボールを放します。目標は、ボールを後ろに最も遠くまで投げることです。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Medicine_Ball_Scoop_Throw';
UPDATE exercises SET name = 'ミドルバックシュラッグ', instructions = '["インクラインベンチにうつ伏せになり、両手にダンベルを持ちます。腕は完全に伸ばして垂れ下がり、床の方向を向いている必要があります。手のひらは向かい合うようにしてください。これが開始位置になります。", "息を吐きながら、肩甲骨を寄せて、収縮を 1 秒間保持します。ヒント: この動きは、ハグの逆の動作、または腕がないかのように後側方運動を実行しようとしているのと同じです。", "息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Middle_Back_Shrug';
UPDATE exercises SET name = '背中中央部のストレッチ', instructions = '["足を肩幅に開き、手を腰に置くように立ちます。", "伸びを感じるまでウエストをひねります。 10〜15秒間保持してから、反対側にひねります。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Middle_Back_Stretch';
UPDATE exercises SET name = 'ミックスグリップあご', instructions = '["肩幅よりわずか約 1 インチ広い間隔で、片手の手のひらを前に向け、もう一方の手のひらを自分に向けて懸垂バーをつかみます。これが開始位置になります。", "次に、息を吐きながら体を引き上げ始めます。ヒント: 手のひらを上に向けた腕で、動作を実行するために背中の筋肉を使うことに集中してください。その腕の肘は胴体に近い位置に保つ必要があります。手のひらを前に向けたもう一方の腕では、肘は離れていますが、胴体と一直線になります。広背筋を使って体を引き上げることに集中します。", "上部で 2 回目の収縮を行った後、息を吸いながらゆっくりと下がり始めます。", "推奨回数だけ繰り返します。", "次のセットでは、グリップを切り替えます。したがって、右手で手のひらを自分に向け、左手で手のひらを前に向けた場合、次のセットでは、右手では手のひらを前に向け、左手では手のひらを自分に向けることになります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Mixed_Grip_Chin';
UPDATE exercises SET name = 'モンスターウォーク', instructions = '["バンドを両足首に巻き、もう1つを両膝に巻きます。足を肩幅に開いたときにきつくなるくらいの張力が必要です。", "まず、左足と右足を交互に前に短く一歩踏み出します。", "数歩歩いたら、逆の手順で元の位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Monster_Walk';
UPDATE exercises SET name = '登山者', instructions = '["手とつま先で体重を支え、腕立て伏せの姿勢から始めます。膝と股関節を曲げ、片方の脚を膝が股関節のほぼ下に来るまで持ってきます。これが開始位置になります。", "脚の位置を急激に逆転させ、曲げた脚を真っ直ぐになってつま先で支えられるまで伸ばし、股関節と膝を曲げた状態でもう一方の足を持ち上げます。 20〜30秒間交互に繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Mountain_Climbers';
UPDATE exercises SET name = 'ムービングクローシリーズ', instructions = '["この動作は、スプリントで優れたパフォーマンスを発揮できるようにランニング フォームを整えるのに役立ちます。走るときは、股関節を伸ばすときに臀部を蹴るように、膝を曲げるようにしてください。", "脚を前方に戻しながらクワッドをリロードし、次のステップで地面を攻撃します。", "走りながら腕でブロックし、素早い 1 ～ 2 モーションでパンチスルーするようにしてください。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Moving_Claw_Series';
UPDATE exercises SET name = 'マッスルスナッチ', instructions = '["荷重をかけたバーベルを太ももの真ん中の位置でワイドグリップで保持して開始します。足は腰の真下にあり、必要に応じて足を外側に向けます。胸を張り、頭を前に向けて腰を下げます。肩はバーの直前にある必要があります。これが開始位置になります。", "かかとの前を通ってバーを上げてプルを開始します。腰から膝、足首まで伸ばして 2 回目のプルに移行し、できるだけ早くバーを押し上げます。バーは体の近くにある必要があります。", "膝を曲げ直さずに、バーを頭上の位置まで上げ続けます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Muscle_Snatch';
UPDATE exercises SET name = 'マッスルアップ', instructions = '["手のひらの付け根をリングの上に置き、フォールスグリップでリングを握ります。肘を体の横に引き下げて肘を曲げ、懸垂を開始します。", "懸垂のトップの位置に達したら、肩を前に回転させながらリングを脇の下に引き、肘がまっすぐ後ろに動くようにします。これにより、動きのディップ部分に進むための適切な位置に移動できます。", "コントロールと安定性を維持しながら、肘を伸ばして動作を完了します。", "地面に体を下げるときは注意してください。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Muscle_Up';
UPDATE exercises SET name = 'ナロースタンスハックスクワット', instructions = '["胴体の後部をマシンの背面パッドに当て、肩を付属の肩パッドの下に引っ掛けます。", "肩幅よりも狭いナロースタンスでつま先をわずかに尖らせて、脚をプラットフォームに置きます。足の間隔は約 3 インチ以下にする必要があります。ヒント: 常に頭を上げて、背中も常にパッドの上に置いてください。", "腕をマシンのサイドハンドルに置き、安全バーを外します (ほとんどのデザインでは、サイドハンドルを正面を向いた位置から斜めの位置に移動することで行われます)。", "次に、膝を固定せずに脚をまっすぐにします。これが開始位置になります。", "頭を上にして（常にパッドの上に背を向けて）まっすぐな姿勢を維持しながら、膝を曲げてユニットをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。", "息を吐きながら、主に足のかかとで床を押してユニットを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Narrow_Stance_Hack_Squats';
UPDATE exercises SET name = 'ナロースタンスレッグプレス', instructions = '["レッグプレスマシンを使用して、マシンに座り、つま先をわずかに尖らせた肩幅より狭いナロースタンスで両足を体の前の台に置きます。足の間隔は約 3 インチ以下にする必要があります。ヒント: 常に頭を上げて、背中も常にパッドの上に置いてください。", "加重プラットフォームを所定の位置に保持している安全バーを下げ、足が前に完全に伸びるまでプラットフォームを押し上げます。ヒント: 膝を固定しないように注意してください。胴体と脚が完全に 90 度の角度をなしている必要があります。これが開始位置になります。", "息を吸いながら、上脚と下脚が 90 度の角度になるまでプラットフォームをゆっくりと下げます。", "主に足のかかとで押し、大腿四頭筋を使用すると、息を吐きながら開始位置に戻ります。", "推奨回数繰り返し、完了したら安全ピンを適切にロックしてください。完全に荷物を積んだ状態でそのプラットフォームが落ちてしまうのは望ましくありません。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Narrow_Stance_Leg_Press';
UPDATE exercises SET name = 'ナロースタンススクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、足を肩幅より狭いナロースタンスにしてつま先をわずかに尖らせます。足の間隔は約 3 ～ 6 インチにする必要があります。常に頭を上げて（下を向くとバランスが崩れます）、背中をまっすぐに保ちます。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながらバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Narrow_Stance_Squats';
UPDATE exercises SET name = 'ナチュラル グルート ハム レイズ', instructions = '["ラットプルダウンマシンまたはプリーチャーベンチのレッグパッドを使用して、足首がパッドの下にあり、膝がシートの上にあり、マシンとは反対側を向くように位置を決めます。直立して正しい姿勢を保つ必要があります。", "これが開始位置になります。膝がほぼ完全に真っ直ぐになるまで、コントロールしながら体を下げます。", "コントロールを保ったまま、体を起こして開始位置に戻ります。", "繰り返しを完了できない場合は、バンドやパートナーを利用したり、ボックスを押したりして繰り返しを完了できるようにしてください。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Natural_Glute_Ham_Raise';
UPDATE exercises SET name = 'ネック-SMR', instructions = '["マッスルローラーまたは麺棒を使用して、ローラーを頭の後ろの首に当てます。ローラーを背骨に直接当てるのではなく、ローラーが背骨の両側の筋肉に押し付けられるように少し回転させてください。これが開始位置になります。", "首のてっぺんから始めて、首の筋肉をゆっくりと下に押し下げ、緊張した部分で 10 ～ 30 秒間停止します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Neck-SMR';
UPDATE exercises SET name = 'ネックプレス', instructions = '["平らなベンチに仰向けになります。中程度の幅のグリップ (前腕と上腕の間の動きの中間で 90 度の角度を作るグリップ) を使用して、バーをラックから持ち上げ、腕をロックした状態で首の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、首にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕をロックし、収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下がり始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります)。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Neck_Press';
UPDATE exercises SET name = 'オブリーククランチ', instructions = '["床に平らになり、腰を地面に押しつけます。このエクササイズでは、片手を頭の横に置き、もう一方の手を床の横に置く必要があります。", "足が高く、平らな面に置かれていることを確認してください。", "次に、手が頭に触れている肩を上げます。", "肩と体を膝につくまで持ち上げるだけです。たとえば、右手を頭の横に置いている場合は、右肘が左膝に触れるまで体を上に上げます。同じバリエーションを逆に適用して、左肘を使って右膝に触れることもできます。", "膝が肘に触れたら、開始位置に達するまで体を下げます。", "エクササイズのエキセントリック（下降）部分では息を吸い、エクササイズのコンセントリック（上向き）部分では息を吐くことを忘れないでください。", "両側で推奨される繰り返しがすべて完了するまで、この方法で交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Oblique_Crunches';
UPDATE exercises SET name = 'オブリーククランチ - 床の上で', instructions = '["まず、右側を下にして両足を重ねて横になります。膝が少し曲がっていることを確認してください。", "左手を頭の後ろに置きます。", "このセットポジションに着いたら、通常のクランチを実行するときと同じように左肘を上げ始めます。ただし、今回は腹斜筋に重点を置きます。", "できるだけ高くクランチし、収縮を1秒間保持してから、ゆっくりと元の位置に戻ります。", "エクササイズのエキセントリック（下降）部分では息を吸い、エクササイズのコンセントリック（上昇）部分では息を吐くことを忘れないでください。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Oblique_Crunches_-_On_The_Floor';
UPDATE exercises SET name = 'オリンピックスクワット', instructions = '["トラップの上にバーベルを支えた状態から始めます。胸が上がり、頭が前を向くようにします。必要に応じて足を外側に向け、腰幅のスタンスを採用します。", "腰をできるだけ後ろに動かさず、膝を曲げて降ります。これには膝を前方に移動する必要があります。足と一直線に並んでいることを確認してください。目標は、胴体をできるだけ直立に保つことです。かかとの前部に体重をかけたまま、最後まで続けます。", "上の脚が下の脚に接触した瞬間に、動きを逆転させて体重を上に動かします。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Olympic_Squat';
UPDATE exercises SET name = '仰向け大腿四頭筋ストレッチ', instructions = '["平らなベンチまたはステップに横になり、片脚と腕を横にぶら下げます。", "膝を曲げて足の甲を持ちます。このとき、腰が反らないように注意してください。", "おへそを背骨に向かって引いて、ニュートラルな状態を保ちます。足を押し下げて手に押し込みます。ヒップのストレッチを追加するには、持ち上げている脚のヒップを天井に向かって持ち上げます。", "サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'On-Your-Back_Quad_Stretch';
UPDATE exercises SET name = 'オンユアサイドクアッドストレッチ', instructions = '["まず、右側を下にして横になり、右膝を 90 度に曲げて体の前の床に置きます (これにより胴体が安定します)。", "左膝を後ろに曲げ、左手で左足を持ちます。股関節屈筋を伸ばすには、左足を手に押し戻しながら、左股関節を前に押します。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'On_Your_Side_Quad_Stretch';
UPDATE exercises SET name = 'ワンアームダンベルロー', instructions = '["フラットベンチを選択し、その両側にダンベルを置きます。", "右脚をベンチの端の上に置き、上半身が床と平行になるまで胴体を腰から前に曲げ、右手をベンチのもう一方の端に置いて支えます。", "左手で床に置かれたダンベルを持ち上げ、腰をまっすぐに保ちながら重量を保持します。手のひらは胴体の方を向くようにしてください。これが開始位置になります。", "抵抗を胸の横までまっすぐ引き上げ、上腕を体の横に近づけ、胴体を動かさないようにします。このステップを実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。また、腕ではなく背中の筋肉を使って力を入れるようにしてください。最後に、上半身は静止したままにし、腕だけを動かします。前腕はダンベルを保持すること以外に他の仕事をしてはいけません。したがって、前腕を使ってダンベルを引き上げようとしないでください。", "抵抗を開始位置までまっすぐ下げます。このステップを実行するときに息を吸います。", "指定した回数だけ動作を繰り返します。", "側を変えて、もう一方の腕でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One-Arm_Dumbbell_Row';
UPDATE exercises SET name = 'ワンアーム フラット ベンチ ダンベル フライ', instructions = '["平らなベンチに横になり、片手にダンベルを太ももの上に置きます。ダンベルを持った手のひらはニュートラルグリップにある必要があります。", "太ももを使ってダンベルを持ち上げるのを助け、ダンベルをきれいにして、持ち上げる腕を完全に伸ばした状態でダンベルを前に持てるようにします。このエクササイズではニュートラルなグリップを維持することを忘れないでください。より適切にサポートできるよう、持ち上げていない側の手はフラットベンチを持つ側に置く必要があります。これが開始位置になります。", "上腕二頭筋の腱へのストレスを防ぐために、体重がかかった腕は肘をわずかに曲げる必要があります。まず、胸にストレッチを感じるまで、体重をかけて腕を広い弧を描くように下げます。動きのこの部分を実行するときに息を吸います。ヒント: 動作中は、持ち上げるアームは静止したままにしておく必要があることに注意してください。動きは肩関節でのみ行われます。", "胸の筋肉を締めて息を吐きながら、持ち上げた腕を開始位置に戻します。ヒント: ウェイトを下げるときに使用したのと同じ円弧の動きを使用してください。", "収縮した位置で 1 秒間保持し、その動きを規定の回数繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One-Arm_Flat_Bench_Dumbbell_Flye';
UPDATE exercises SET name = 'ワンアーム ハイプーリー ケーブル サイド ベンド', instructions = '["標準ハンドルをタワーに接続します。ケーブルをプーリーの最も高い位置に移動します。", "側面をケーブルに向けてスタンドします。片手で手を伸ばし、アンダーハンドグリップでハンドルをつかみます。", "肘が体の脇に触れ、ハンドルが肩の近くに来るまでケーブルを引き下げます。", "足を腰幅に離して配置します。空いている手を腰に置き、ピボット ポイントを測りやすくします。", "腕を静止位置に保ちます。サイドクランチでは、斜めに収縮して重量を下げます。", "最大収縮に達したら、ゆっくりと重量を解放して開始位置に戻します。ウェイトスタックは静止位置で決して降ろさないでください。目標は、セット中に常に緊張感を保つことです。", "失敗まで繰り返す。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'One-Arm_High-Pulley_Cable_Side_Bends';
UPDATE exercises SET name = 'ワンアーム インクライン ラテラル レイズ', instructions = '["手にダンベルを持ち、インクラインベンチプレスで横向きに寝ます。肩がインクラインベンチに押し付けられ、腕がおへその周りにくるようにして体全体に横たわっていることを確認してください。", "ダンベルを上腕に持ち、床と平行に前に伸ばしたままにします。これが開始位置です。", "ダンベルを常に床と平行に保ちながら、横方向に上げます。腕は天井を向くまでまっすぐ上に伸ばします。ヒント: この動作を実行するときに息を吐きます。ダンベルをその位置に保持し、肩が収縮するのを少し感じてください。", "息を吸いながら、体全体の体重を下げて開始位置に戻します。", "この動作を規定回数繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One-Arm_Incline_Lateral_Raise';
UPDATE exercises SET name = 'ワンアームケトルベルクリーン', instructions = '["ケトルベルを足の間に置きます。ケトルベルをつかむためにかがむときは、お尻を後ろに押し、目は前に向け続けます。", "ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。そうすることで手首が回転するはずです。", "ウェイトを開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Clean';
UPDATE exercises SET name = 'ワンアームケトルベルクリーンアンドジャーク', instructions = '["ケトルベルのハンドルを持ちます。", "ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。", "膝を曲げて体を沈め、胴体を直立状態に保ちます。", "すぐに方向を反転し、かかとを突き抜けてドライブし、本質的にはジャンプして勢いを生み出します。このとき、体の勢いを利用して体重を動かし、腕を伸ばしてケトルベルを頭上に押し上げてロックアウトします。", "ウェイトの下でしゃがんだ姿勢に戻り、ウェイトを頭上で受け取ります。", "体重を頭上に乗せたまま、立った姿勢に戻ります。次の繰り返しを行うには、ウェイトを床まで下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Clean_and_Jerk';
UPDATE exercises SET name = 'ワンアームケトルベルフロアプレス', instructions = '["床に横になり、片手でケトルベルを持ち、上腕を床で支えます。手のひらは内側を向いている必要があります。", "手首を回転させながら、ケトルベルを天井に向かってまっすぐ押し上げます。", "ケトルベルを下げて開始位置に戻し、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Floor_Press';
UPDATE exercises SET name = 'ワンアームケトルベルジャーク', instructions = '["ケトルベルのハンドルを持ちます。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。これが開始位置になります。", "膝を曲げて体を沈め、胴体を直立状態に保ちます。", "すぐに方向を反転し、かかとを突き抜けてドライブし、本質的にはジャンプして勢いを生み出します。このとき、体の勢いを利用して体重を動かし、腕を伸ばしてケトルベルを頭上に押し上げてロックアウトします。ウェイトの下でしゃがんだ姿勢に戻り、ウェイトを頭上で受け取ります。体重を頭上に乗せたまま、立った姿勢に戻ります。", "次の繰り返しを実行するには、ウェイトを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Jerk';
UPDATE exercises SET name = 'ワンアームケトルベル ミリタリープレス サイド', instructions = '["ケトルベルを肩まできれいにします。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが内側を向くように手首を回転させます。これが開始位置になります。", "ケトルベルを見て、頭上でロックアウトされるまで押し上げます。", "コントロールしながらケトルベルを肩まで下げ、繰り返します。安定性と強度を高めるために、広背筋、お尻、お腹を力強く収縮させてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Military_Press_To_The_Side';
UPDATE exercises SET name = 'ワンアームケトルベルパラプレス', instructions = '["ケトルベルを肩まできれいにします。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。これが開始位置になります。", "肘を横に広げてケトルベルを持ち、頭上で固定されるまで押し上げます。", "コントロールしながらケトルベルを肩まで下げ、繰り返します。安定性と強度を高めるために、広背筋、お尻、お腹を力強く収縮させてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Para_Press';
UPDATE exercises SET name = 'ワンアームケトルベルプッシュプレス', instructions = '["ケトルベルのハンドルを持ちます。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。これが開始位置になります。", "膝を曲げて体を沈め、胴体を直立状態に保ちます。", "すぐに方向を反転し、かかとを突き抜けてドライブし、本質的にはジャンプして勢いを生み出します。このとき、体の勢いを利用して体重を動かし、腕を伸ばしてケトルベルを頭上に押し上げてロックアウトします。次の繰り返しを実行するには、ウェイトを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Push_Press';
UPDATE exercises SET name = 'ワンアームケトルベルロウ', instructions = '["ケトルベルを足の前に置きます。膝を軽く曲げ、前かがみになるときにできるだけお尻を突き出して開始姿勢をとります。ケトルベルをつかんでお腹に引き寄せ、肩甲骨を引いて肘を曲げます。背中をまっすぐにしてください。下げて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Row';
UPDATE exercises SET name = 'ワンアームケトルベルスナッチ', instructions = '["ケトルベルを足の間に置きます。膝を曲げ、お尻を後ろに押して、適切な開始位置に入ります。", "まっすぐ前を見て、脚の間でケトルベルを後ろに振ります。", "すぐに方向を逆転し、腰と膝を使ってケトルベルを上向きに加速させます。ケトルベルが肩まで上がったら、手を回転させてまっすぐ上にパンチし、勢いを利用して頭上にロックアウトされた重量を受け止めます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Snatch';
UPDATE exercises SET name = 'ワンアームケトルベルスプリットジャーク', instructions = '["ケトルベルのハンドルを持ちます。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。これが開始位置になります。", "膝を曲げて体を沈め、胴体を直立状態に保ちます。", "すぐに方向を反転し、かかとを突き抜けてドライブし、本質的にはジャンプして勢いを生み出します。このとき、体の勢いを利用して体重を動かし、腕を伸ばしてケトルベルを頭上に押し上げてロックアウトします。", "ウェイトの下でしゃがんだ姿勢に戻り、片方の脚を前に、もう一方の脚を後ろに置き、ウェイトを頭上で受け取ります。", "体重を頭上に乗せたまま、立った姿勢に戻り、両足を揃えます。次の繰り返しを実行するには、ウェイトを下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Split_Jerk';
UPDATE exercises SET name = 'ワンアームケトルベル スプリット スナッチ', instructions = '["ケトルベルのハンドルを片手で持ちます。", "床に向かってしゃがみ、動作を逆にして、腰、膝、最後に足首を伸ばしてケトルベルを頭上に上げます。", "体を完全に伸ばした後、ランジの姿勢に下がり、片足を前に、片足を後ろに下げて頭上でウェイトを受け取ります。腰を使ってドライブスルーし、中断のない 1 回の動作でケトルベルを頭上でロックするようにしてください。", "立った姿勢に戻り、体重を頭上で支え、両足を揃えます。ウェイトを下げて開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Split_Snatch';
UPDATE exercises SET name = 'ワンアームケトルベルスイング', instructions = '[]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Kettlebell_Swings';
UPDATE exercises SET name = 'ワンアームロングバーロー', instructions = '["バーを地雷や隅に置いて動かないようにします。適切な重りを末端に負荷します。", "バーの隣に立ち、片手でカラーの近くでグリップを握ります。腰と脚を使って立ち上がる。", "腰を後ろに向けて胸を張り、膝を曲げた姿勢をとります。腕を伸ばす必要があります。これが開始位置になります。", "肩を引っ込めて肘を曲げて体重を横に引き寄せます。動作中にウェイトを急激に動かしたり、ごまかしたりしないでください。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'One-Arm_Long_Bar_Row';
UPDATE exercises SET name = 'ワンアーム・メディシン・ボール・スラム', instructions = '["千鳥足の運動姿勢で立った姿勢から始めます。片手でメディシン ボールを後ろ足と同じ側に持ちます。これが開始位置になります。", "まず腕を回し、メディシンボールを頭の上に上げます。このとき、腰、膝、足首を伸ばしてスラムに備えて負荷を加えます。", "伸展のピークに達したら、肩、背骨、腰を曲げて、ボールを目の前の地面にしっかりと投げ込みます。", "バウンド時にボールをキャッチし、必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'メディシンボール' WHERE id = 'One-Arm_Medicine_Ball_Slam';
UPDATE exercises SET name = 'ワンアーム オープン パーム ケトルベル クリーン', instructions = '["ケトルベルを 1 つ足の間に置きます。", "片手でハンドルを掴み、ケトルベルを素早く持ち上げ、ケトルベルのボールが手のひらに着地するように反転させます。", "ケトルベルを前に投げ、片手でハンドルを握ります。", "ケトルベルを床に持って行き、繰り返します。必ず両腕を鍛えてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Open_Palm_Kettlebell_Clean';
UPDATE exercises SET name = '片腕オーバーヘッドケトルベルスクワット', instructions = '["片腕でケトルベルを掃除して押します。ケトルベルを肩に向かって引っ張りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。肘を通してウェイトを頭上に押し込みます。これが開始位置になります。", "まっすぐ前を見て、ケトルベルを頭上に固定したまま、膝と腰を曲げ、脚の間に胴体を下げ、頭と胸を上げたままにします。", "一番下の位置で少し停止してから、足のかかとを通って一番上の位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'One-Arm_Overhead_Kettlebell_Squats';
UPDATE exercises SET name = 'ワンアームサイドデッドリフト', instructions = '["バーベルの中心の隣に立ちます。膝を曲げてバーベルに届くまで体を下げます。", "ブリーフケースをつかむようにバーを握ります (バーは横向きなので、手のひらは自分に向けます)。かなりの重量を使用する場合は、リストラップが必要になる場合があります。これが開始位置です。", "息を吐きながら足を使ってバーベルを持ち上げます。立った姿勢になるまでバーベルを持ち上げながら、腕を完全に伸ばします。", "息を吸いながらゆっくりとバーベルを下ろします。ヒント: 怪我の発生を防ぐため、体重を下げるときは必ず膝を曲げてください。", "推奨回数だけ繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'One-Arm_Side_Deadlift';
UPDATE exercises SET name = 'ワンアームサイドラテラル', instructions = '["ダンベルを選択し、片方の手の上に置きます。インクラインベンチプレスなどの安定したものをつかむには、持ち上げていない手で行う必要があります。リフティングアームの方に体を傾け、インクラインベンチを握っている手から離れると、バランスが保てます。", "胴体をまっすぐにして立ち、ダンベルを腕の長さで脇に置き、手のひらを自分に向けます。これが開始位置になります。", "胴体を静止させたまま（スイングしないように）、肘を軽く曲げ、グラスに水を注ぐように手を少し前に傾けてダンベルを体の横に持ち上げます。腕が床と平行になるまで上げ続けます。この動きを実行しながら息を吐き、頂点で 1 秒間停止します。", "息を吸いながらダンベルをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One-Arm_Side_Laterals';
UPDATE exercises SET name = '片足ケーブルのキックバック', instructions = '["革製の足首カフを低いケーブルプーリーに引っ掛け、カフを足首に取り付けます。", "約 2 フィートの距離からウェイト スタックに向かい、支えとなる鉄骨フレームをつかみます。", "膝と腰をわずかに曲げ、腹筋を引き締めたまま、臀部を収縮させて、息を吐きながら快適に移動できる程度の高さで、半円弧を描くように作業脚をゆっくりと後ろに「蹴り」ます。ヒント: 最大の収縮を達成するために、完全に伸展した状態で臀部を 1 秒間締めます。", "次に、開始位置に到達するまで、ケーブルの引っ張りに抵抗しながら、ゆっくりと作業脚を前に出します。", "推奨回数だけ繰り返します。", "脚を入れ替えて、反対側でも同じ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'One-Legged_Cable_Kickback';
UPDATE exercises SET name = '片腕を壁に当てる', instructions = '["立った姿勢から、曲げた腕を壁または出入り口に置きます。", "広背筋が伸びていると感じるまで、ゆっくりと腕に体を傾けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'One_Arm_Against_Wall';
UPDATE exercises SET name = '片腕懸垂', instructions = '["このエクササイズでは、まず懸垂バーの周りにタオルを置きます。", "手のひらを自分に向けて懸垂バーを握ります。片方の手で懸垂バーをつかみ、もう片方の手でタオルをつかみます。", "腰を反らせて胸を突き出しながら、上体を約30度ほど戻します。これが開始位置です。v", "肩と上腕を下と後ろに引き、バーが胸の上部に触れるまで胴体を引き上げます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で 2 秒後、息を吸い始め、腕を完全に伸ばし広背筋が完全に伸びたら、胴体をゆっくりと開始位置に戻します。", "この動作を規定回数繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'One_Arm_Chin-Up';
UPDATE exercises SET name = 'ワンアームダンベルベンチプレス', instructions = '["フラットベンチに横になり、片手にダンベルを太ももの上に置きます。", "太ももを使ってダンベルを持ち上げるのを助け、ダンベルを肩の幅で前に持てるようにきれいにします。持ち上げていない手を使って、ダンベルを体の上に適切に配置します。", "肩幅になったら、手首を前方に回転させて、手のひらが反対側を向くようにします。これが開始位置になります。", "息を吸いながら、ゆっくりとウェイトを体の横に下ろします。常にダンベルを完全にコントロールできるようにしてください。ヒント: 最初は少し苦労するかもしれませんが、持ち上げていない方の手でダンベルのバランスを保ちやすくしてください。持ち上げていない方の手は、必要な場合にのみ使用してください。それ以外の場合は、横に置いたままにしてください。", "息を吐きながら、胸筋を使ってダンベルを押し上げます。腕を縮めた位置に固定し、胸を圧迫し、1秒間保持してからゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One_Arm_Dumbbell_Bench_Press';
UPDATE exercises SET name = 'ワンアームダンベルプリーチャーカール', instructions = '["右腕でダンベルをつかみ、上腕をプリーチャーベンチまたはインクラインベンチの上に置きます。ダンベルは肩の長さで持つ必要があります。これが開始位置になります。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、ゆっくりとダンベルを下げます。", "息を吐きながら、上腕二頭筋を使ってウェイトを丸め、上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで持ち上げます。繰り返しますが、完全に収縮させるには、小指を親指よりも高くする必要があることを覚えておいてください。", "収縮した位置で上腕二頭筋を 1 秒間強く絞り、推奨回数繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One_Arm_Dumbbell_Preacher_Curl';
UPDATE exercises SET name = 'ワンアームフロアプレス', instructions = '["平らな場所に横になり、背中を床またはエクササイズマットに押し付けます。膝が曲がっていることを確認してください。", "パートナーに片手でバーを渡してもらいます。開始するときは、バーベルベンチプレスの開始位置と同様に、腕をほぼ完全に伸ばす必要があります。ただし、今回はグリップをニュートラルにします (手のひらが胴体を向くようにします)。", "重量を持ち上げるのに使用していない手は体の横に置いてください。", "肘が地面に触れるまでバーベルを下げることからエクササイズを始めます。ここはエキセントリック（エクササイズの中で下降する部分）なので、必ず息を吸いましょう。", "次に、バーベルを元の開始位置まで持ち上げ始めます。コンセントリック（運動の持ち上げ部分）中に息を吐き出すことを忘れないでください。", "推奨される繰り返しを実行するまで繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'One_Arm_Floor_Press';
UPDATE exercises SET name = 'ワンアームラットプルダウン', instructions = '["適切な重量を選択し、膝パッドを調整して負担を軽減します。回内グリップでハンドルを握ります。これが開始位置になります。", "ハンドルを下に引き、肘を曲げながら肘を体の横に絞ります。", "動作の最下部で一時停止し、ゆっくりとハンドルを開始位置に戻します。", "複数回繰り返す場合は、鍛えられている筋肉の緊張を保つために、体重を完全に戻すことは避けてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'One_Arm_Lat_Pulldown';
UPDATE exercises SET name = '片腕回内ダンベル上腕三頭筋エクステンション', instructions = '["腕を伸ばしてダンベルを持ちながら、ベンチに平らに寝ます。腕は体に対して垂直になるようにしてください。このエクササイズを行うには回内グリップが必要なので、手のひらは足の方を向く必要があります。", "持ち上げていない方の手を上腕二頭筋の上に置き、サポートします。", "息を吸いながらゆっくりとダンベルを下ろし始めます。", "次に、上腕三頭筋を収縮させながらダンベルを上に持ち上げ始めます。コンセントリック（運動の持ち上げ部分）中に息を吐き出すことを忘れないでください。", "設定した繰り返しを実行するまで繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One_Arm_Pronated_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = '片腕回外ダンベル上腕三頭筋エクステンション', instructions = '["腕を伸ばしてダンベルを持ちながら、ベンチに平らに寝ます。腕は体に対して垂直になるようにしてください。このエクササイズを行うには回外グリップが必要なので、手のひらは顔の方を向く必要があります。", "持ち上げていない方の手を上腕二頭筋の上に置き、サポートします。", "息を吸いながらゆっくりとダンベルを下ろし始めます。", "次に、上腕三頭筋を収縮させながらダンベルを上に持ち上げ始めます。コンセントリック（運動の持ち上げ部分）中に息を吐き出すことを忘れないでください。", "設定した繰り返しを実行するまで繰り返します。", "腕を切り替えて動きを繰り返します。", "もう一度腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'One_Arm_Supinated_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = 'イナゴの半分', instructions = '["床にうつ伏せに寝ます。", "左手を左の腰骨の下に置き、腰と恥骨をパッドします。", "右膝を曲げて、右手で足を持てるようにします。", "足を空中に持ち上げ、同時に肩を床から持ち上げます。これにより、右股関節屈筋と胸と肩もストレッチされます。サイドを切り替えます。腰が気にならない場合は、両腕と両足を同時に試してみてください。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'One_Half_Locust';
UPDATE exercises SET name = '片手でハングアップ', instructions = '["回内グリップを使用して片手で懸垂バーをつかみます。足は床または段差の上に置いてください。足を地面につけたまま、体重の大部分をその手からぶら下げます。 10〜20秒間押し続けて、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'One_Handed_Hang';
UPDATE exercises SET name = '片膝から胸まで', instructions = '["床に横たわることから始めます。", "片方の脚をまっすぐに伸ばし、もう片方の膝を胸に引き寄せます。膝関節の下を持ち、膝蓋骨を保護します。", "その膝を鼻の方へそっと引き寄せます。", "サイドを切り替えます。これにより、曲げた脚のお尻と腰、まっすぐな脚の股関節屈筋がストレッチされます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'One_Knee_To_Chest';
UPDATE exercises SET name = '片足バーベルスクワット', instructions = '["まず、フラットベンチの前約 2 ～ 3 フィートの位置に立ち、背中をベンチに向けます。バーベルを床の上の前に置きます。ヒント: 足は肩幅程度に開く必要があります。", "膝を曲げ、両手を肩幅より広く開き、回内グリップを使用して、胸の上に置けるまでバーベルを持ち上げます。", "次にバーベルを頭の上に持ち上げ、首の付け根に置きます。片足を後ろに動かして、つま先をフラットベンチに置きます。もう一方の足は前で静止している必要があります。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。ヒント: このエクササイズを行うときは、背中が真っ直ぐで胸が張っていることを確認してください。", "息を吸いながら、太ももが床と平行になるまでゆっくりと脚を下げます。この時点で、膝はつま先の上に来るはずです。胸は太ももの真ん中の真上にある必要があります。", "胸と腰を先頭にして大腿四頭筋を収縮させ、息を吐きながら脚を開始位置に戻します。", "推奨回数だけ繰り返します。", "脚を入れ替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'One_Leg_Barbell_Squat';
UPDATE exercises SET name = 'オープンパームケトルベルクリーン', instructions = '["ケトルベルを 1 つ足の間に置きます。ケトルベルを肩に向かって持ち上げながら、脚と腰を伸ばしてケトルベルを掃除します。", "ケトルベルが上がってきたら手を放し、ケトルベルのボールが手のひらに着地するように反転させます。", "ケトルベルを前に放し、両手でハンドルを握ります。ケトルベルを開始位置まで下げ、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Open_Palm_Kettlebell_Clean';
UPDATE exercises SET name = 'オーティスアップ', instructions = '["足を固定し、床に仰向けになります。膝は曲がっているはずです。両手で重りを胸に当てます。これが開始位置になります。", "腰と背骨を曲げて胴体を地面から持ち上げることから動きを開始します。", "上に移動するときは、動きの最上部でウェイトが頭の上に来るようにウェイトを押し上げます。", "腹筋運動を逆に行うときに体重を胸に戻し、床まで下がらないように注意します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Otis-Up';
UPDATE exercises SET name = '架空ケーブルのカール', instructions = '["まず、滑車マシンの両側に快適な重量を設定します。注: 選択した重量が両側で同じであることを確認してください。", "次に、両側の滑車の高さを調整し、肩の高さよりも高い位置にあることを確認します。", "両側の中央に立って、アンダーハンドグリップ（手のひらを天井に向ける）を使用して各ハンドルを握ります。腕を完全に伸ばして床と平行にし、足を肩幅に離して配置します。体とハンドルが均等に揃うようにしてください。これが開始位置です。", "息を吐きながら、前腕と上腕二頭筋が触れるまで両側の上腕二頭筋をゆっくりと絞ります。", "息を吸いながら、前腕を開始位置に戻します。注: このエクササイズ中は、前腕を除いて体全体が静止しています。", "プログラムで規定されている推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Overhead_Cable_Curl';
UPDATE exercises SET name = 'オーバーヘッドラット', instructions = '["パートナーを後ろに置いて、床に直立して座ります。片方の腕をまっすぐ上に上げ、肘を曲げて背中に手を触れるようにします。パートナーはあなたの上腕三頭筋と手首を保持する必要があります。これが開始位置になります。", "パートナーが実際にそうするのを妨げるので、上腕を自分の側に引き寄せようとします。", "10 ～ 20 秒後、腕をリラックスさせ、パートナーが上腕三頭筋に軽く圧力を加えて広背筋をさらに伸ばすことができるようにします。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Overhead_Lat';
UPDATE exercises SET name = 'オーバーヘッドスラム', instructions = '["メディーネボールを両手で持ち、足を肩幅に広げて立ちます。これが開始位置になります。", "ボールを頭上に上げ、体を完全に伸ばすことでカウンターの動きを開始します。", "動きを逆にして、ボールを目の前の地面に全力で叩きつけます。", "バウンドしたボールを両手で受け取り、同じ動作を繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Overhead_Slam';
UPDATE exercises SET name = 'オーバーヘッドスクワット', instructions = '["まずは床にバーベルを前に置きます。足の間隔は肩幅より広くなければなりません。", "膝を曲げ、回内グリップ（手のひらを自分に向ける）を使用してバーベルを掴みます。持ち上げる前に、両手を肩幅より広く離す必要があります。位置が決まったら、バーベルを胸の上に置けるまで持ち上げます。", "バーベルを頭の上の少し後ろに移動し、腕が完全に伸びていることを確認します。常に頭を上げて、背中もまっすぐに保ちます。肩甲骨を引っ込めます。これが開始位置です。", "息を吸いながら、太ももが地面と平行になるまで膝を曲げ、ゆっくりと体重を下げます。ヒント: 怪我を避けるため、このエクササイズを行う間は背中をまっすぐに保ち、腕は常に頭の上に伸ばしたままにしてください。", "次に、息を吐きながら足と脚を使って体重を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Overhead_Squat';
UPDATE exercises SET name = 'オーバーヘッドストレッチ', instructions = '["まっすぐに立ち、指を組み、手のひらを天井に向けて開きます。肩を下げたまま腕を上に伸ばします。", "胴体を完全に伸ばすには、尾骨を引き下げて胴体を安定させます。胴体の前面と背面の両方の筋肉をストレッチします。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Overhead_Stretch';
UPDATE exercises SET name = 'オーバーヘッド上腕三頭筋', instructions = '["パートナーを後ろに置いて、床に直立して座ります。片方の腕をまっすぐ上に上げ、肘を曲げて背中に手を触れるようにします。パートナーはあなたの肘と手首を持ってください。これが開始位置になります。", "パートナーが実際にそうするのを妨げるので、腕を真っすぐに空中に伸ばそうとします。", "10 ～ 20 秒後、腕をリラックスさせ、パートナーが手首に軽く圧力を加えて上腕三頭筋をさらに伸ばすことができます。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Overhead_Triceps';
UPDATE exercises SET name = 'パロフプレス', instructions = '["標準ハンドルをタワーに接続し、可能であればケーブルを肩の高さに配置します。そうでない場合は、低いプーリーで十分です。", "ケーブルに体を向けて両手でハンドルを掴み、タワーから離れます。ケーブルに重りの張力がかかる状態で、滑車から腕の長さほど離れた位置にいる必要があります。", "足を腰幅に開き、膝をわずかに曲げて、ケーブルを胸の中央に当てます。これが開始位置になります。", "ケーブルを胸から押し離し、両腕を完全に伸ばします。体幹はしっかりと締められている必要があります。", "この繰り返しを数秒間保持してから、開始位置に戻ります。", "セットの終わりに、反対方向を向いて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Pallof_Press';
UPDATE exercises SET name = '回転式パロフプレス', instructions = '["標準ハンドルをタワーに接続し、ケーブルを肩の高さに配置します。", "ケーブルに体を向けて片手でハンドルを掴み、タワーから離れます。ケーブルに重りの張力がかかる状態で、滑車から腕の長さほど離れた位置にいる必要があります。伸ばしたアームをケーブルに合わせます。", "足を腰幅に広げて、ケーブルを胸の中に引き込み、もう一方の手でハンドルを握ります。このとき両手はハンドルの上にあるはずです。", "前を向いて、ケーブルを胸から遠ざけるように押します。体幹はしっかりと締められている必要があります。", "腰をまっすぐに保ち、完全に 4 分の 1 回転するまで胴体をプーリーから遠ざけるようにひねります。", "堅い姿勢とまっすぐな腕を維持してください。ゆっくりと制御された方法でニュートラル位置に戻ります。腕は前に伸ばす必要があります。", "サイドの張力がまだ体幹に作用している状態で、両手を胸に持ってきて、すぐに外側に向かって完全に伸ばした位置まで押します。これで 1 回のレップが構成されます。", "失敗まで繰り返す。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Pallof_Press_With_Rotation';
UPDATE exercises SET name = 'ベンチの上で手のひらを下にしてダンベルリストカール', instructions = '["まず、フラットベンチの片側に2つのダンベルを置きます。", "体がフラットベンチに向くように両膝をつきます。", "腕を使って回内グリップ（手のひらを下に向ける）で両方のダンベルをつかみ、前腕がフラットベンチに当たるように持ち上げます。手首は端から垂れ下がっているはずです。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。", "このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench';
UPDATE exercises SET name = 'ベンチの上で手のひらを下にしてリストカール', instructions = '["まず、フラットベンチの片側にバーベルを置きます。", "体がフラットベンチに向くように両膝をつきます。", "腕を使って回内グリップ（手のひらを下）でバーベルをつかみ、前腕がフラットベンチに当たるように持ち上げます。手首は端から垂れ下がっているはずです。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。", "このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Palms-Down_Wrist_Curl_Over_A_Bench';
UPDATE exercises SET name = 'ベンチの上で手のひらを上げてバーベル リスト カール', instructions = '["まず、フラットベンチの片側にバーベルを置きます。", "体がフラットベンチに向くように両膝をつきます。", "腕を回外グリップで（手のひらを上に向けて）バーベルを掴み、前腕がフラットベンチに当たるように持ち上げます。手首は端から垂れ下がっているはずです。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。", "このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Palms-Up_Barbell_Wrist_Curl_Over_A_Bench';
UPDATE exercises SET name = 'ベンチの上で手のひらを上げてダンベル リスト カール', instructions = '["まず、フラットベンチの片側に2つのダンベルを置きます。", "体がフラットベンチに向くように両膝をつきます。", "腕を使って両方のダンベルを回外グリップで掴み（手のひらを上に）、前腕がフラットベンチにもたれるように持ち上げます。手首は端から垂れ下がっているはずです。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。エクササイズのこの部分では必ず吸入してください。", "このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench';
UPDATE exercises SET name = '平行棒ディップ', instructions = '["一組の平行棒の間に立ちます。各バーに手を置き、小さくジャンプして、腕をロックした状態で開始位置に着きやすくします。", "肘を曲げることから始めて、腕が90度に折れるまで体を下げます。揺れを避け、下降中は正しい姿勢を維持してください。", "肘を伸ばして動きを逆に動かし、体を押し上げて開始位置に戻します。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Parallel_Bar_Dip';
UPDATE exercises SET name = '骨盤をブリッジに傾ける', instructions = '["足を床に置き、かかとが膝の真下に来るように横になります。", "尾てい骨だけを天井に向かって持ち上げて、腰を伸ばします。 （まだ背骨全体を持ち上げないでください。）お腹を引っ込めます。", "ブリッジに入るには、首を除く背骨全体を持ち上げます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Pelvic_Tilt_Into_Bridge';
UPDATE exercises SET name = '腓骨筋-SMR', instructions = '["横向きに寝て、前腕と下腿の外側に置いたフォームローラーで体重を支えます。上の脚は下の脚の上に置くことも、前で交差させることもできます。これが開始位置になります。", "腰を地面から上げ、膝の下から脚の側の足首の上まで回転し始め、緊張したところで 10 ～ 30 秒間停止します。もう一方の脚でも同じことを繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Peroneals-SMR';
UPDATE exercises SET name = '腓骨筋ストレッチ', instructions = '["座った姿勢で、ベルト、ロープ、またはバンドを片足に巻き付けます。これが開始位置になります。", "脚を伸ばし、かかとを地面から離した状態で、ベルトを引っ張って足を裏返し、足の内側を手前に引っ張ります。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Peroneals_Stretch';
UPDATE exercises SET name = 'フィジオボールヒップブリッジ', instructions = '["腰をサポートせず、背中上部がボールの上に来るようにボールの上に横になります。両足は床に平らに置き、腰幅以上に広げます。これが開始位置になります。", "まず臀筋とハムストリングスを使って股関節を伸ばし、ブリッジをしながら腰を上に上げます。", "動作の先頭で一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Physioball_Hip_Bridge';
UPDATE exercises SET name = 'ピンプレス', instructions = '["ピンプレスはベンチプレスの偏心位相を取り除き、開始時の強度を高めます。また、必要な可動域をトレーニングすることもできます。", "ベンチはパワーラック内に設置してください。ロックアウトだけでも、胸から 1 インチ離れたところでも、可動範囲内の希望のポイントにピンを設定します。バーをピンに移動し、持ち上げる準備をする必要があります。", "Begin by lying on the bench, with the bar directly above the contact point during your regular bench.足を下に押し込み、背中を反らせます。バーを使って体重を支え、肩をベンチから持ち上げて引き込み、肩甲骨を寄せます。足を使ってトラップをベンチに打ち込みます。動きの間中、このタイトな体の位置を維持してください。", "標準的なベンチグリップでも、上腕三頭筋に集中するために肩幅でも構いません。バー、手首、肘は常に一直線上にある必要があります。バーを握って引き離すことに集中してください。", "できるだけ強い力でバーを押し上げます。肘はロックアウトされるまで押し込む必要があります。", "バーをピンに戻し、次の繰り返しを開始する前に一時停止します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Pin_Presses';
UPDATE exercises SET name = '梨状筋-SMR', instructions = '["フォームロールの上にお尻を乗せて座ります。膝を曲げて片足を交差させ、足首が膝の上にくるようにします。これが開始位置になります。", "体重を交差した脚の側に移動し、臀部の上部に緊張を感じるまでお尻の上を転がします。片手で曲げた膝を胸に向かって引っ張ると、ストレッチを助けることができます。この位置を 10 ～ 30 秒間保持してから、側を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Piriformis-SMR';
UPDATE exercises SET name = '板', instructions = '["床にうつ伏せの姿勢になり、つま先と前腕で体重を支えます。腕を曲げて肩の真下に置きます。", "体を常に真っ直ぐに保ち、できるだけ長くこの姿勢を維持してください。難易度を高めるために、腕または脚を上げることができます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Plank';
UPDATE exercises SET name = 'プレートピンチ', instructions = '["縁の広いプレートを 2 枚用意し、滑らかな面を外側にして重ね合わせます。", "指でプレートの外側部分をつかみ、親指で反対側をつかみ、両方のプレートを一緒に保持します。これが開始位置です。", "プレートを指と親指で押します。できるだけ長くこの位置を維持してください。", "プログラムで規定されている推奨セット数だけ繰り返します。", "腕を切り替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Plate_Pinch';
UPDATE exercises SET name = 'プレートツイスト', instructions = '["床またはエクササイズマットの上に横になり、足を完全に伸ばし、上半身を直立させます。腕を軽く曲げて、腹部の前に両手を出してプレートの側面をつかみます。", "足首の近くで足をゆっくりと交差させ、地面から持ち上げます。膝も少し曲げておく必要があります。注: このエクササイズを回転する際のバランスを保つために、上半身を少し後ろに動かします。これが開始位置です。", "プレートを左側に移動し、床に触れます。その動きをしながら息を吐きます。", "息を吸いながら開始位置に戻り、今度は体の右側でこの動きを繰り返します。ヒント: 常にゆっくりと制御された動きを使用してください。けいれん的な動きは腰を傷つける可能性があります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Plate_Twist';
UPDATE exercises SET name = 'プラットフォームハムストリングスライド', instructions = '["この移動には木製の床などが必要です。足を伸ばして仰向けになります。かかとの下にジムタオルまたは軽い重りを置きます。これが開始位置になります。", "もう一方の脚をまっすぐに保ち、膝を曲げることから動きを始めます。", "かかとを床の上で滑らせながら、自分に近づけ続けます。", "膝を完全に曲げたら、動きを逆にして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Platform_Hamstring_Slides';
UPDATE exercises SET name = 'プリエダンベルスクワット', instructions = '["ダンベルの根元を両手で持ち、まっすぐに立ちます。両脚を肩幅より広く開き、膝を軽く曲げます。", "つま先は外側を向いているはずです。注意: エクササイズ中は腕を動かさないでください。これが開始位置です。", "ゆっくりと膝を曲げ、太ももが床と平行になるまで脚を下げます。これはエクササイズのエキセントリックな部分なので、必ず息を吸いましょう。", "主に足のかかとで押して、息を吐きながら体を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Plie_Dumbbell_Squat';
UPDATE exercises SET name = 'プライオケトルベルプッシュアップ', instructions = '["ケトルベルを床に置きます。腕立て伏せの姿勢になり、つま先を立てて片手を地面に置き、片手でケトルベルを持ち、肘を伸ばします。これが開始位置になります。", "背中をまっすぐに保ち、できるだけ低く体を下げることから始めます。", "素早く、力強く方向を変え、ケトルベルの反対側まで体を押し上げ、その際に手を入れ替えます。下降と前後の動きを繰り返して動きを続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Plyo_Kettlebell_Pushups';
UPDATE exercises SET name = 'プライオプッシュアップ', instructions = '["床の上でうつ伏せの姿勢になり、手とつま先で体重を支えます。", "腕を完全に伸ばし、手を肩幅に広げます。動作中は体をまっすぐに保ちます。これが開始位置になります。", "肘を曲げて胸を地面に向かって下げます。", "一番下では、動作を逆にして、できるだけ早く肘を伸ばして体を押し上げます。手が地面から離れるまで上半身を押し上げてみてください。", "開始位置に戻り、エクササイズを繰り返します。", "難易度をさらに高めるには、空中にいる間の動きに拍手を追加します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Plyo_Push-up';
UPDATE exercises SET name = '後脛骨筋ストレッチ', instructions = '["座った姿勢で、ベルト、ロープ、またはバンドを片足に巻き付けます。これが開始位置になります。", "脚を伸ばし、かかとを地面から離した状態で、ベルトを引っ張って足を裏返すようにし、足の外側を手前に引っ張ります。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Posterior_Tibialis_Stretch';
UPDATE exercises SET name = 'パワークリーン', instructions = '["足を肩幅より少し広めに開き、つま先をわずかに向けて立ちます。", "しゃがみ、閉じた回内グリップでバーを握ります。肘を完全に伸ばし、膝の外側で手は肩幅よりわずかに広く開きます。", "バーをすねの前約 1 インチのところ、足の指の付け根の上に置きます。", "背中は平らかわずかにアーチ状にし、胸を張り、肩甲骨を引っ込めます。", "頭を中立の位置（脊柱と一直線上にあり、傾けたり回転させたりしない）に保ち、目の焦点をまっすぐ前に向けます。この段階で息を吸います。", "息を吐きながら腰と膝を力強く伸ばしてバーを床から持ち上げます。ヒント: 上半身は同じ角度を維持する必要があります。まだ腰を曲げず、腰が肩よりも前に上がらないようにしてください（これにより、臀筋が空中に押し上げられ、ハムストリングスが伸びる効果があります）。", "肘を完全に伸ばし、頭をニュートラルな位置に置き、肩をバーの上に置きます。", "バーが上がるときは、できるだけすねに近づけてください。", "バーが膝を通過したら、腰を前に突き出し、膝がロックしないように軽く曲げます。ヒント: この時点で太ももがバーに当たっているはずです。", "背中を平らにするかわずかにアーチ状にし、肘を完全に伸ばし、頭は中立に保ちます。ヒント: 次のフェーズまで息を止めます。", "息を吸いながら、力強く素早く腰と膝を伸ばし、つま先で立ちます。", "バーをできるだけ体の近くに置いてください。ヒント: 背中を平らにし、肘を横に向け、頭を中立の位置にします。また、肩をバーの上に置き、腕をできるだけ長くまっすぐに保ちます。", "下半身の関節が完全に伸びたら、肘をまだ曲げずに、肩を素早く上にすくめます。動きのこの部分で息を吐きます。", "肩が最高の高さに達したら、肘を曲げて体をバーの下に引き込み始めます。", "腕をできるだけ高く、長く引き続けます。ヒント: このフェーズの爆発的な性質により、胴体は直立するか背中を反らせ、頭はわずかに後ろに傾き、足は床と接触しなくなる可能性があります。", "下半身が完全に伸びてバーが最大近くの高さに達したら、体をバーの下に引き、腕をバーの周りと下で回転させます。", "同時に、腰と膝を曲げて 4 分の 1 スクワットの姿勢にします。", "腕がバーの下に来たら、息を吸いながら肘を持ち上げ、上腕が床と平行になるようにします。鎖骨の前部と肩の前部の筋肉にバーを掛けます。", "直立して引き締まった胴体、中立的な頭の位置、平らな足でバーを捉えます。この動作中に息を吐きます。", "腰と膝を完全に直立した位置まで伸ばして立ちます。", "腕の筋肉の緊張を徐々に減らしてバーを下げ、太ももまでバーを制御しながら下降できるようにします。この動作中に息を吸います。", "腰と膝を同時に曲げて、太ももにかかるバーの衝撃を和らげます。", "バーが床に触れるまで肘を完全に伸ばしてしゃがみます。", "フェーズ 1 からやり直し、推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Power_Clean';
UPDATE exercises SET name = 'ブロックからのパワークリーン', instructions = '["希望の高さのボックスにバーベルを置き、脚のすぐ外側を握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐに保つ必要があります。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。", "ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、腕を伸ばしたまま、体を完全に伸ばし、わずかに後ろに傾く必要があります。", "完全な伸展が達成されたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げることにより、3番目のプルに移行します。伸展のピークに達したら、肩にかかる程度までバーの下に体を引き込み、その際にバーの下で肘を回転させます。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立った姿勢になるまで続け、体重をボックスに戻して繰り返しを完了します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Power_Clean_from_Blocks';
UPDATE exercises SET name = 'パワージャーク', instructions = '["肩の前部に体重をかけて立ち、ディップから始めます。足を腰の真下に置き、腰を後ろに動かさずに膝を曲げます。ほんの少しだけ下に下がり、できるだけ力強く方向を反転します。", "かかとを使ってドライブすると、できるだけ多くのスピードと力が生まれ、バーが肩から離れるときに頭を邪魔にならないように移動してください。", "足が床から離れたこの瞬間、できるだけ早く足を受け取る位置に置かなければなりません。足が積極的にプラットフォームに向かって動いていない一瞬の間、アスリートはバーを押し上げようとする努力によってバーを押し下げてしまいます。足は少し広めのスタンスに移動し、膝を部分的に曲げます。", "腕を頭上に伸ばしてバーを受け取ります。", "立った姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Power_Jerk';
UPDATE exercises SET name = 'パワーパーシャル', instructions = '["胴体を直立させて立ち、両手にダンベルを腕の長さで持ちます。肘は胴体の近くにある必要があります。", "手のひらは胴体の方を向くようにします。足は肩幅程度に開く必要があります。これが開始位置になります。", "腕を真っ直ぐに伸ばし、胴体を動かさないようにして、息を吐きながらウェイトを肩の高さくらいの高さになるまで体の横に持ち上げます。", "収縮を一瞬感じて、息を吸いながらウェイトを開始位置まで下げ始めます。ヒント: ウェイトを上げ下げするときは、主に肩に負担が集中するため、手のひらを下に向け、小指を少し高い位置に保ちます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Power_Partials';
UPDATE exercises SET name = 'パワースナッチ', instructions = '["荷重をかけたバーベルを床に置いた状態から始めます。バーはすねに近いか、すねに触れている必要があり、バーを幅広に握る必要があります。足は腰の真下にあり、必要に応じて足を外側に向けます。胸を張り、頭を前に向けて腰を下げます。肩はバーの直前にある必要があります。これが開始位置になります。", "最初のプルは、かかとの前を通ってバーを地面から持ち上げることから始めます。バーが膝を通過するまで、背中の角度は同じに保つ必要があります。", "腰から膝、足首まで伸ばして 2 回目のプルに移行し、できるだけ早くバーを押し上げます。バーは体の近くにある必要があります。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足を少し広めのレシーブポジションに移動し、バーを頭上に上げながらバーの下に体を引き込みます。バーは部分的にしゃがんだ状態で受け取る必要があります。バーを頭上の位置まで上げ続け、頭上にロックアウトされたバーを受け取ります。", "頭上に体重を乗せた状態で立った姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Power_Snatch';
UPDATE exercises SET name = 'ブロックからのパワースナッチ', instructions = '["希望の高さのボックスまたはスタンドにバーベルを載せて開始します。バーは幅広に握る必要があります。足は腰の真下にあり、必要に応じて足を外側に向けます。胸を張り、頭を前に向けて腰を下げます。肩はバーのすぐ前にあり、肘は向いている必要があります。これが開始位置になります。", "最初のプルは、かかとの前を通ってバーをボックスから持ち上げることから始めます。", "腰から膝、足首まで伸ばして 2 回目のプルに移行し、できるだけ早くバーを押し上げます。バーは体の近くにある必要があります。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足をレシーブポジションに移動するときに、バーを頭上に持ち上げながら、バーの下に力を入れて自分自身を引きます。必要に応じて、足は腰のすぐ外側に移動する必要があります。完全にしゃがんだ状態で、腕を完全に頭上に伸ばした状態でバーを受け取ります。", "バーをかかとの前に合わせたまま、頭と胸を上げ、足のかかとを通って立った位置に移動します。慎重に重りを箱に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Power_Snatch_from_Blocks';
UPDATE exercises SET name = 'パワーステア', instructions = '["電動階段では、器具が階段を上っていきます。トレーニング目的の場合は、タイヤまたはボックスを使用して実行できます。", "まず両手で器具を持ちます。足を広く開き、頭と胸を上げます。かかとで地面を走り、膝と腰を伸ばして地面から体重を上げます。", "後ろにもたれながら、通常約 16 ～ 18 インチの高さの階段の上にウェイトを振り上げてみます。足を使ってウェイトを階段に押し込むことができます。", "これを 3 ～ 5 回繰り返し、できるだけ速く動かしながら、より重い重量で続けます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Power_Stairs';
UPDATE exercises SET name = 'プリーチャーカール', instructions = '["この動きを実行するには、プリーチャーベンチと E-Z バーが必要です。 E-Z カール バーの近くの内側ハンドルをつかみます (誰かにバーを手渡してもらうか、ほとんどのプリーチャー ベンチに備えられている前部のバー レストからバーをつかみます)。手のひらは前を向き、バーの形状によりわずかに内側に傾いている必要があります。", "上腕をプリーチャーベンチパッドに当て、胸をそれに当てて、E-Z カールバーを肩の長さで持ちます。これが開始位置になります。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、ゆっくりとバーを下げます。", "息を吐きながら、上腕二頭筋を使ってウェイトを丸め、上腕二頭筋が完全に収縮し、バーが肩の高さになるまで持ち上げます。上腕二頭筋を強く絞り、この位置を 1 秒間保持します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Preacher_Curl';
UPDATE exercises SET name = 'プリーチャーハンマー ダンベルカール', instructions = '["両手にダンベルを持ち、手のひらを向かい合わせにして両腕の上部をプリーチャーベンチの上に置きます（ニュートラルグリップ）。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、ゆっくりとダンベルを下げます。", "息を吐きながら、上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで、上腕二頭筋を使ってウェイトを丸めます。", "収縮した位置で上腕二頭筋を 1 秒間強く絞り、推奨回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Preacher_Hammer_Dumbbell_Curl';
UPDATE exercises SET name = 'プレスシットアップ', instructions = '["まず、ベンチに横になり、バーベルを胸の上に置きます。腹部ベンチの延長上に脚が固定されるように位置を決めます。これが開始位置です。", "息を吸いながら、腹部と臀部を引き締めます。腹筋運動をするときと同じように胴体を丸め、息を吐きながらバーベルを頭上の位置まで押します。ヒント: このエクササイズを実行するときは、腹部の筋肉に集中しながら、腕を使ってバーベルを押し出します。", "バーベルを胴体に戻しながら、上半身を開始位置まで下げます。体を下げるときに息を吸うことを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Press_Sit-Up';
UPDATE exercises SET name = '腹臥位手動ハムストリング', instructions = '["この演習にはパートナーが必要です。足をまっすぐにしてうつ伏せになります。アシスタントがあなたのかかとに手を置きます。", "まず、膝を曲げて脚を丸めます。パートナーは抵抗を与え、最初は軽く、動きが完了するにつれて圧力を強める必要があります。パートナーとコミュニケーションをとり、適切な抵抗レベルを監視してください。", "パートナーが反対方向に向かう抵抗を与えながら、トップで停止し、脚を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Prone_Manual_Hamstring';
UPDATE exercises SET name = 'プラウラー スプリント', instructions = '["スレッドを適切な表面に置き、適切な重量を加えます。そりは力を必要とするのに十分な抵抗を提供する必要がありますが、速度が大幅に低下するほど重すぎてはなりません。", "この練習では、直立ハンドルまたは低いハンドルを使用できます。腕を伸ばしてハンドルに手を置き、器具に寄りかかります。", "正しい姿勢で、交互に短いステップで地面を走ります。短い距離ではできるだけ速く移動します。"]'::jsonb, category = '有酸素運動', equipment = 'その他' WHERE id = 'Prowler_Sprint';
UPDATE exercises SET name = 'プルスルー', instructions = '["ロープまたはハンドルが取り付けられた低い滑車の前の数フィートに立ち始めます。マシンから背を向け、ケーブルをまたいで足を大きく開きます。", "脚をできるだけ遠くまで伸ばし、腰を曲げることから動きを始めます。膝を軽く曲げたままにしてください。腕をまっすぐに保ち、腰を通ってまっすぐに立ちます。肩から上に引っ張らないようにしてください。すべての動きは腰から始まる必要があります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Pull_Through';
UPDATE exercises SET name = '懸垂', instructions = '["所定のグリップを使用して、手のひらを前に向けて懸垂バーを握ります。グリップに関する注意: ワイドグリップの場合、両手の間隔は肩幅より広くする必要があります。中程度のグリップの場合は、両手の間隔を肩幅と同じにする必要があります。クローズグリップの場合は、肩の幅よりも狭い距離に手を置く必要があります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を反らせて胸を突き出しながら、胴体を約 30 度後ろに戻します。これが開始位置です。", "肩と上腕を下と後ろに引き、バーが胸の上部に触れるまで胴体を引き上げます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で 2 秒後、息を吸い始め、腕を完全に伸ばし広背筋が完全に伸びたら、胴体をゆっくりと開始位置に戻します。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Pullups';
UPDATE exercises SET name = 'プッシュアップワイド', instructions = '["両手を広く開き、つま先と手で体を支え、プランクの姿勢になります。肘を伸ばして体を真っ直ぐにする必要があります。腰が垂れないようにしてください。これが開始位置になります。", "まず、肘を曲げて、息を吸いながら胸を床に下げます。", "胸筋を使用して、肘を伸ばして上半身を開始位置に戻します。このステップを実行するときに息を吐きます。", "縮めた位置で一時停止した後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Push-Up_Wide';
UPDATE exercises SET name = '腕立て伏せ - 上腕三頭筋の位置を閉じる', instructions = '["床にうつ伏せになり、両手を肩幅よりも近づけて手の位置を近づけます。胴体を腕の長さで持ち上げていることを確認してください。", "息を吸いながら、胸が床に着きそうになるまで体を下げます。", "上腕三頭筋と胸筋の一部を使って上半身を開始位置に戻し、胸を張ります。このステップを実行するときに息を吐きます。", "収縮した位置で 2 回目の停止を行った後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Push-Ups_-_Close_Triceps_Position';
UPDATE exercises SET name = '足を上げた腕立て伏せ', instructions = '["床にうつ伏せになり、両手を約36インチ離して置き、腕の長さで胴体を持ち上げます。", "平らなベンチの上につま先を置きます。こうすることで体が高くなるようになります。注: フラットベンチの高度が高くなるほど、エクササイズの負荷も高くなります。", "息を吸いながら、胸が床に着きそうになるまで体を下げます。", "胸筋を使って上半身を開始位置に戻し、胸を張ります。このステップを実行するときに息を吐きます。", "収縮した位置で 2 回目の停止を行った後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Push-Ups_With_Feet_Elevated';
UPDATE exercises SET name = 'バランスボールに足を乗せて腕立て伏せ', instructions = '["床にうつ伏せになり、両手を約36インチ離して置き、腕の長さで胴体を持ち上げます。", "つま先をバランスボールの上に置きます。こうすることで体が高くなるようになります。", "息を吸いながら、胸が床に着きそうになるまで体を下げます。", "胸筋を使って上半身を開始位置に戻し、胸を張ります。このステップを実行するときに息を吐きます。", "収縮した位置で 2 回目の停止を行った後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Push-Ups_With_Feet_On_An_Exercise_Ball';
UPDATE exercises SET name = 'プッシュプレス', instructions = '[]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Push_Press';
UPDATE exercises SET name = 'プッシュプレス - 首の後ろ', instructions = '["肩の後ろに体重をかけて立ち、ディップから始めます。足を腰の真下に置き、腰を後ろに動かさずに膝を曲げます。ほんの少しだけ下に下がり、できるだけ力強く方向を反転します。かかとを使ってドライブすると、可能な限りのスピードと力が生まれ、バーが垂直方向に動きます。", "生成された勢いを利用して、腕を通してウェイトを頭上に押し込みます。", "脚を使って衝撃を吸収し、開始位置に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Push_Press_-_Behind_the_Neck';
UPDATE exercises SET name = 'サイドプランクまでプッシュアップ', instructions = '["両手を肩幅のすぐ外側に置いて、つま先を立てて腕立て伏せの姿勢になります。", "肘を曲げて腕立て伏せを行います。降りるときは体をまっすぐにしてください。", "腕立て伏せを 1 回行い、立ち上がるときに体の左側に体重を移動し、サイド プランクで右腕を天井に向かって上げながら横にひねります。", "もう一度腕立て伏せをするために腕を床に下げてから、反対側にひねります。", "このシリーズを左右交互に 10 回以上繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Push_Up_to_Side_Plank';
UPDATE exercises SET name = '腕立て伏せ', instructions = '["床にうつ伏せになり、手を約36インチ離して置き、胴体を腕の長さで持ち上げます。", "次に、息を吸いながら胸が床に着きそうになるまで体を下げます。", "次に、息を吐き、胸を絞りながら上半身を開始位置に戻します。", "一番上の収縮した位置で少し停止した後、再び体を下に下げ始め、必要なだけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Pushups';
UPDATE exercises SET name = '腕立て伏せ (クローズおよびワイドハンドポジション)', instructions = '["床にうつ伏せになり、体を真っすぐにしてつま先を床に置き、手の位置が広い場合は手を肩の幅より広くし、手の位置が近い場合は肩の幅よりも近づけます。胴体を腕の長さで持ち上げていることを確認してください。", "息を吸いながら、胸が床に着きそうになるまで体を下げます。", "胸筋を使って上半身を開始位置に戻し、胸を張ります。このステップを実行するときに息を吐きます。", "収縮した位置で 2 回目の停止を行った後、規定の回数だけ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Pushups_Close_and_Wide_Hand_Positions';
UPDATE exercises SET name = 'ピラミッド', instructions = '["まず、胴体をボールの上で前に転がして、腰がボールの上に乗り、体の最高点になるようにします。", "手と足を床に置きます。ボールの大きさ、柔軟性、手足の長さに応じて、腕と脚はわずかに曲がったりまっすぐになったりすることがあります。これは、胴体と肩の安定した強さを養うのにも役立ちます。"]'::jsonb, category = 'ストレッチ', equipment = 'exercise ball' WHERE id = 'Pyramid';
UPDATE exercises SET name = 'クワッドストレッチ', instructions = '["横向きに寝てください。ベルト、ロープ、またはバンドを足の甲に巻き付けます。膝を曲げて股関節を伸ばし、足でお尻に触れるようにして、手でベルトを持ちます。これが開始位置になります。", "ベルトを肩または頭上に掛けて、軽く引っ張って大腿四頭筋のストレッチを高めます。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Quad_Stretch';
UPDATE exercises SET name = '大腿四頭筋-SMR', instructions = '["床にうつ伏せになり、手または前腕で体重を支えます。片足の大腿四頭筋の下にフォームロールを置き、足が地面から離れた状態に保ちます。脚をできるだけリラックスさせるようにしてください。これが開始位置になります。", "許容できる範囲でストレッチする脚に体重を移動し、膝の上から腰の下までフォームの上を転がり、緊張点を 10 ～ 30 秒間保持します。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Quadriceps-SMR';
UPDATE exercises SET name = 'クイックリープ', instructions = '["このエクササイズにはボックスが必要です。", "箱の端から 1 ～ 2 フィートの位置に立って、箱に向かい始めます。", "腰を使ってボックスに飛び乗り、両足で着地します。足を曲げて足を平らにした状態で着地するようにしてください。", "着地したらすぐに体全体を完全に伸ばし、腕を頭上に振り上げてボックスから爆発させます。着地時の衝撃を足で吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Quick_Leap';
UPDATE exercises SET name = 'ラック納品', instructions = '["このドリルは、バーベルを肩のラックの位置に運ぶことを教えます。かかしの姿勢でバーを持ち始め、上腕を床と平行にし、前腕を垂らします。指を親指に巻き付けてフックグリップを使用します。", "まずバーを中心に肘を回転させ、バーを肩に届けます。肘を前に出したら、握った力を緩めます。肩を突き出してバーのための棚を作り、バーが喉に軽く触れるようにします。", "バーが常に体の近くにあることが重要です。重い荷物の場合、距離が離れると望ましくない衝突が発生するためです。動きがスムーズになると、速度と負荷を上げてからさらに進むことができます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Rack_Delivery';
UPDATE exercises SET name = 'バンド付きラックプル', instructions = '["バーをピンに掛けてパワーラックに設置します。ピンは希望のポイントに設定する必要があります。膝のすぐ下、すぐ上、または太ももの真ん中の位置。ラックの底にバンドを取り付けるか、ダンベルで固定します。もう一方の端をバーに取り付けます。張力を与えるためにバンドを絞める必要がある場合があります。", "デッドリフトの適切な姿勢でバーに対して体を置きます。足は腰の下に置き、グリップは肩幅に置き、背中をアーチ状にし、腰を後ろに引いてハムストリングスに力を入れます。通常、重量は重いため、混合グリップやフック グリップを使用したり、重量を保持しやすくするためにストラップを使用したりできます。", "頭を前に向けて、腰と膝を通って伸ばし、ロックアウトするまでウェイトを上下に引っ張ります。動きを完了するときは、必ず肩を後ろに引いてください。ウェイトをピンに戻して繰り返します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Rack_Pull_with_Bands';
UPDATE exercises SET name = 'ラックプル', instructions = '["バーをピンに掛けてパワーラックに設置します。ピンは希望のポイントに設定する必要があります。膝のすぐ下、すぐ上、または太ももの真ん中の位置。デッドリフトの適切な姿勢でバーに対して体を置きます。足は腰の下に置き、グリップは肩幅に置き、背中をアーチ状にし、腰を後ろに引いてハムストリングスに力を入れます。通常、重量は重いため、混合グリップやフック グリップを使用したり、重量を保持しやすくするためにストラップを使用したりできます。", "頭を前に向けて、腰と膝を通って伸ばし、ロックアウトするまでウェイトを上下に引っ張ります。動きを完了するときは、必ず肩を後ろに引いてください。", "ウェイトをピンに戻して繰り返します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Rack_Pulls';
UPDATE exercises SET name = 'リアレッグレイズ', instructions = '["エクササイズマットの上に両手両膝をつきます。頭は前を向き、膝を曲げてハムストリングスとふくらはぎの間に 90 度の角度を作る必要があります。これが開始位置になります。", "片足を上に後ろに伸ばします。膝と股関節は両方とも伸ばさなければなりません。これを 5 ～ 10 回繰り返してから、側面を切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Rear_Leg_Raises';
UPDATE exercises SET name = 'リカンベントバイク', instructions = '["まず、バイクに座り、シートを自分の高さに合わせて調整します。", "メニューから希望のオプションを選択します。電源を入れるにはペダルを踏み始める必要がある場合があります。手動設定を使用することも、使用するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。負荷のレベルはトレーニング中に変更できます。ハンドルを使用して心拍数を監視し、適切な強度を維持することができます。", "リカンベントバイクは利便性が高く、心血管系にも効果があり、他のアクティビティに比べて影響が少ないです。体重 150 ポンドの人は、30 分間中程度の速度でサイクリングすると約 230 カロリーを消費しますが、ランニングでは 450 カロリー以上消費します。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Recumbent_Bike';
UPDATE exercises SET name = 'スタンスからのリターンプッシュ', instructions = '["この訓練にはパートナーが必要です。", "アスレティックな 2 点または 3 点スタンスから始めます。", "合図があったら、パートナーからパスを受ける位置に移動します。", "メディシンボールを両手で掴み、すぐにパートナーに投げ返します。", "別のルートを実行することで、このドリルを変更できます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Return_Push_from_Stance';
UPDATE exercises SET name = 'リバースバンドベンチプレス', instructions = '["バーを正しい高さに設定して、パワーラック内にベンチを配置します。まず、バンドをバンドペグまたはラックの上部に固定します。バンドの下に適切な位置にいることを確認してください。もう一方の端をバーベルに取り付けます。", "ベンチに横になり、足を下に押し込み、背中を反らせます。バーを使って体重を支え、肩をベンチから持ち上げて引き込み、肩甲骨を寄せます。足を使ってトラップをベンチに打ち込みます。動きの間中、このタイトな体の位置を維持してください。グリップの幅がどんなに広くても、バーのリングをカバーする必要があります。", "肩を伸ばさずにバーをラックから引き出します。バーを握って引き離すことに集中してください。バーを胸の下部または胃の上部まで下げます。バー、手首、肘は常に一直線上にある必要があります。", "バーベルが胴体に触れたところで一時停止し、できるだけ力を入れてバーを押し上げます。肘はロックアウトされるまで押し込む必要があります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Reverse_Band_Bench_Press';
UPDATE exercises SET name = 'リバースバンドボックススクワット', instructions = '["後ろの適切な高さにボックスを備えたパワーラックから始めます。バンドをバンドペグに取り付けるか、ラックの上部に取り付けて、スクワット中にバンドがバーの真上に来るようにします。もう一方の端をバーに取り付けます。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足の幅を広くして背中、臀筋、内転筋、ハムストリングスに重点を置くか、足を近づけて大腿四頭筋をより発達させます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。ボックスの上に座るまで、腰を落として座ります。理想的には、すねが地面に対して垂直である必要があります。ボックスに到達したら一時停止し、股関節屈筋を緩めます。決して箱から跳ね返らないようにしてください。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きをリードしながらボックスから上向きにドライブします。頭からつま先まで締め付けを維持しながら、上向きに進みます。バーベルをラックに戻す際は注意してください。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Reverse_Band_Box_Squat';
UPDATE exercises SET name = 'リバースバンドデッドリフト', instructions = '["バーをパワーラックに設置します。バンドペグまたはフレーム自体を使用して、ラックの上部にバンドを取り付けます。バンドのもう一方の端をバーに取り付けます。", "バーが足の中心に来るようにバーに近づきます。足は腰幅程度に開く必要があります。腰を曲げて肩幅でバーを握り、肩甲骨を突き出します。通常、重いセットではオーバーハンド グリップまたはオーバー/アンダー グリップを使用します。", "足とグリップをセットした状態で、大きく息を吸い、腰を下げ、すねがバーに触れるまで膝を曲げます。頭を前方に向け、胸を張って背中を反​​らせ、かかとから体重を上に移動し始めます。", "バーが膝を通過したら、積極的にバーを後ろに引き、肩甲骨を寄せながら腰を前方にバーに押し込みます。", "腰を曲げてバーを床に誘導してバーを下げます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Reverse_Band_Deadlift';
UPDATE exercises SET name = 'リバースバンドパワースクワット', instructions = '["ピンとバーを適切な高さにセットしたパワーラックで始めます。バーを積み込んだ後、ペグまたはフレーム自体を使用してバンドをラックの上部に取り付けます。バンドのもう一方の端をバーに取り付けます。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足を広く開き、背中、臀筋、内転筋、ハムストリングスに重点を置きます。", "頭を前に向けたままにしてください。背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。できるだけ腰を後ろに向けて座ってください。理想的には、すねが地面に対して垂直である必要があります。バーの位置が低いと、バーをかかとの上に保つために、より大きな胴体の傾きが必要になります。平行を破るまで続けます。平行とは、股関節のしわが膝の上と一直線になることと定義されます。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きを主導しながら上向きに進みます。頭からつま先まで締め付けを維持しながら、開始位置に戻るまで上向きに進みます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Reverse_Band_Power_Squat';
UPDATE exercises SET name = 'リバースバンド相撲デッドリフト', instructions = '["パワーラック内の床にバーを置きます。ペグまたはフレーム自体を使用して、ラックの上部にバンドを取り付けます。もう一方の端をバーベルに取り付けます。", "バーが足の中央と交差するようにバーに近づきます。足は襟の近くで非常に幅広に設定する必要があります。腰を曲げてバーを握ります。腕は肩の真下、脚の内側に置く必要があり、プロネーション グリップ、ミックス グリップ、またはフック グリップを使用できます。肩をリラックスさせると腕が長くなります。", "息を吸い、腰を下げ、胸を張って頭を前に向けます。足の後ろ半分に体重をかけて、両足を広げて床を走ります。腰と膝まで伸ばします。", "バーが膝を通過したら、後ろに傾き、腰をバーに押し込み、肩甲骨を引き寄せます。", "腰を曲げて体重をコントロールしながら、体重を地面に戻します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Reverse_Band_Sumo_Deadlift';
UPDATE exercises SET name = 'リバースバーベルカール', instructions = '["バーベルを肩幅に持ち、肘を胴体に近づけて胴体を直立させて立ちます。手のひらは下を向く必要があります（回内グリップ）。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトをカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。筋肉を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Reverse_Barbell_Curl';
UPDATE exercises SET name = 'リバースバーベルプリーチャーカール', instructions = '["肩幅で EZ バーを握り、手のひらを下に向けて (回内) グリップします。", "次に、両腕の上部をプリーチャーベンチの上に置き、腕を伸ばします。これが開始位置になります。", "息を吐きながら、上腕二頭筋を使ってウェイトを丸め、上腕二頭筋が完全に収縮し、バーベルが肩の高さになるまで持ち上げます。収縮した位置で上腕二頭筋を 1 秒間強く絞ります。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、ゆっくりとバーベルを下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Reverse_Barbell_Preacher_Curls';
UPDATE exercises SET name = '逆ケーブルカール', instructions = '["肩の幅で回内（手のひらを下）にしてグリップを使用し、低いプーリーに取り付けられたバーアタッチメントを持ちながら、胴体を直立させて立ちます。また、肘を胴体に近づけるようにしてください。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトをカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。筋肉を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Reverse_Cable_Curl';
UPDATE exercises SET name = 'リバースクランチ', instructions = '["脚を完全に伸ばし、腕を胴体の横に置き、手のひらを床に置き、床に横になります。エクササイズ中は腕を動かさないでください。", "太ももが床に対して垂直になり、足が揃って床と平行になるように脚を上げます。これが開始位置です。", "息を吸いながら、骨盤を後方に回転させながら脚を胴体に向かって動かし、腰を床から持ち上げます。この動きの終わりには、膝が胸に触れます。", "収縮を 1 秒間保持し、息を吐きながら脚を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Reverse_Crunch';
UPDATE exercises SET name = 'リバースフライ', instructions = '["まず、インクラインベンチに横になり、胸とお腹をインクラインに押し付けます。ダンベルを両手に持ち、手のひらを向かい合わせます（ニュートラルグリップ）。", "ベンチの角度に対して垂直になるように腕を前に伸ばします。足の指の付け根で圧力を加えている間、脚は静止している必要があります。これが開始位置です。", "肘を軽く曲げた状態を維持したまま、息を吐きながら、円弧を描くようにウェイトを互いに遠ざけます（横に）。ヒント: このエクササイズで最良の結果を得るには、肩甲骨を寄せるようにしてください。", "腕は床と平行になるまで上げます。", "収縮を感じ、息を吸いながらウェイトをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Reverse_Flyes';
UPDATE exercises SET name = '外部回転によるリバースフライ', instructions = '["まず、30 度の角度に設定されたインクライン ベンチに横になり、胸とお腹をインクラインに押し付けます。", "ダンベルを両手に持ち、手のひらを床に向けます。腕はベンチの角度に対して垂直になるように前に置きます。ヒント: 肘はわずかに曲がっている必要があります。足の指の付け根で圧力を加えている間、脚は静止している必要があります（かかとが床に触れないようにしてください）。これが開始位置です。", "肘を軽く曲げたまま、息を吐きながら、円弧を描くようにウェイトを互いに遠ざけます。", "ウェイトを持ち上げるとき、手のひらを下に向けた (回内) グリップから手のひらを向かい合わせた (ニュートラル) グリップに切り替えるために、手首を 90 度外側に回転する必要があります。ヒント: このエクササイズで最良の結果を得るには、肩甲骨を寄せるようにしてください。", "腕は頭と同じ高さになるまで上げます。", "収縮を感じ、息を吸いながらウェイトをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Reverse_Flyes_With_External_Rotation';
UPDATE exercises SET name = 'リバースグリップベントオーバーロウ', instructions = '["バーベルを回外グリップで持ちながら直立して立ちます（手のひらを上に向けます）。", "膝をわずかに曲げ、腰を曲げて胴体を前に出し、同時に背中が床とほぼ平行になるまでまっすぐに保ちます。ヒント: 頭を上げたままにしてください。腕が床と胴体に対して垂直になるように、バーベルは体の正面にぶら下がります。これが開始位置です。", "胴体を静止させたまま、息を吐きながらバーベルを持ち上げます。肘を体の近くに保ち、ウェイトを保持する以外に前腕に力を入れないでください。一番上の収縮した位置で、背中の筋肉を締めて 1 秒間保持します。", "息を吸いながら、ゆっくりとウェイトを再び開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Reverse_Grip_Bent-Over_Rows';
UPDATE exercises SET name = 'リバースグリップトライセプスプッシュダウン', instructions = '["まず、バーアタッチメント (ストレートまたは e-z) をハイプーリーマシンにセットします。", "バーアタッチメントに面し、手のひらを上に向けて肩幅で握ります（回外グリップ）。腕が体の側面で完全に伸びるまで、広背筋を使ってバーを下げます。ヒント: 肘は体の脇に置き、足は肩幅に開く必要があります。これが開始位置です。", "息を吸いながらバーアタッチメントをゆっくりと上げ、胸と一直線になるようにします。前腕のみを動かし、肘/上腕は常に側で静止させてください。", "次に、息を吐きながら上腕三頭筋を強く収縮させながら、ケーブル バーを元の凝視位置まで下げ始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Reverse_Grip_Triceps_Pushdown';
UPDATE exercises SET name = '逆過伸展', instructions = '["適切な体重をかけた後、足をパッドの間に置きます。トップパッドの上に横たわり、腰を背中から浮かせるようにし、ハンドルを握って姿勢を保ちます。", "動きを始めるには、腰を曲げて脚を前に引きます。", "腰を伸ばして脚を後ろに蹴り出すことで、動きを逆にします。この動作では、股関節を伸ばしすぎないように注意することが非常に重要です。可動範囲の手前で止まってしまいます。", "もう一度腰を曲げて、キャリッジをできるだけ前方に引っ張って元に戻します。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Reverse_Hyperextension';
UPDATE exercises SET name = 'リバースマシンフライズ', instructions = '["ハンドルが一番後ろになるように調整してください。適切な重量を選択し、ハンドルが肩の高さになるようにシートの高さを調整します。手を内側に向けてハンドルを握ります。これが開始位置になります。", "半円を描くように手を横と後ろに引き、三角筋後部を収縮させます。", "動作中は腕をわずかに曲げたままにし、すべての動作は肩関節で行われます。", "動きの最後部で停止し、ゆっくりと体重を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Reverse_Machine_Flyes';
UPDATE exercises SET name = 'リバースプレートカール', instructions = '["まず、重りのあるプレートを両手で持ち、腕を完全に伸ばしてまっすぐに立ちます。回内グリップ (手のひらを下に向ける) を使用し、指でプレートのザラザラした面を掴み、親指で滑らかな面を掴むようにしてください。注: 最良の結果を得るには、11 時と 1 時の位置にあるウェイト プレートをつかみます。", "両足は肩幅に開き、加重プレートが鼠径部の近くにある必要があります。これが開始位置です。", "息を吐きながら上腕二頭筋と前腕が触れるまで、肘を内側に入れ上腕を動かさないようにしながら、プレートをゆっくりと持ち上げます。この時点でプレートは胴体と均等に位置合わせされている必要があります。", "収縮を一瞬感じて、息を吸いながら体重を開始位置まで下げ始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Reverse_Plate_Curls';
UPDATE exercises SET name = 'リバース・トライセプス・ベンチプレス', instructions = '["平らなベンチに仰向けになります。回外したグリップを閉じて (肩幅程度の幅で) 使用して、バーをラックから持ち上げ、腕を前に伸ばして床に垂直に固定した状態で、バーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の中央にバーを感じるまでゆっくりと下ろします。ヒント: 上腕三頭筋の働きを最大限に高めるために、通常のベンチプレスとは異なり、肘を常に胴体の近くに保つようにしてください。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、上腕三頭筋を使ってバーを押します。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Reverse_Triceps_Bench_Press';
UPDATE exercises SET name = '菱形-SMR', instructions = '["床に背中をつけて横になります。フォームロールを背中上部の下に置き、腕を前で交差させて肩を突き出します。これが開始位置になります。", "腰を地面から持ち上げて、体重をフォームロールの上に置きます。体重を一度に片側に移動し、背中の中央と上部をローリングします。緊張した箇所で 10 ～ 30 秒間一時停止します。"]'::jsonb, category = 'ストレッチ', equipment = 'フォームローラー' WHERE id = 'Rhomboids-SMR';
UPDATE exercises SET name = '人力車キャリー', instructions = '["フレームを開始点に配置し、適切な重量を負荷します。フレームの中央に立って、ハンドルを握り、かかとを通ってフレームを持ち上げることから始めます。胸と頭が高く、背中がまっすぐであることを確認してください。", "すぐに、制御された足取りで活発に歩き始めます。胸を張って前を向き、呼吸を続けるようにしてください。終了点に到達したら、フレームを地面に下ろします。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Rickshaw_Carry';
UPDATE exercises SET name = '人力車デッドリフト', instructions = '["フレームに希望の重量を載せます。ハンドルの間の中心に身を置きます。足は腰幅程度に開く必要があります。腰を曲げてハンドルを握り、肩甲骨を突き出します。", "足とグリップを固定した状態で、大きく息を吸い、腰を下げて膝を曲げます。頭を前に向け、胸を張り、背中を反らせた状態を保ち、かかとから体重を上に移動し始めます。体重が上がったら、肩甲骨を寄せながら腰を前に動かします。", "腰を曲げて体重を地面に誘導して体重を下げます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Rickshaw_Deadlift';
UPDATE exercises SET name = 'リングディップス', instructions = '["両手にリングを持ち、小さくジャンプして腕をロックした状態で開始位置に着きます。", "肘を曲げることから始めて、腕が90度に折れるまで体を下げます。揺れを避け、下降中は正しい姿勢を維持してください。", "肘を伸ばして動きを逆に動かし、体を押し上げて開始位置に戻します。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Ring_Dips';
UPDATE exercises SET name = 'ロケットジャンプ', instructions = '["足を肩幅に開き、腕を体に近づけてリラックスした姿勢から始めます。", "動きを開始するには、半分しゃがみ、できるだけ高く爆発して元に戻ります。", "体全体を完全に伸ばし、できるだけ頭上まで伸ばします。着地時の衝撃を足で吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Rocket_Jump';
UPDATE exercises SET name = 'ロッキングスタンディングカーフレイズ', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れるので、常に頭を上げてください。また、背中をまっすぐに保ち、膝をわずかに曲げたままにしてください。決してロックされていません。これが開始位置になります。", "息を吐きながらかかとを上げ、足首をできるだけ高く伸ばし、ふくらはぎを曲げます。膝が常に動かないように注意してください。いかなるときも曲がりがあってはなりません (位置決め中に作成した最初のわずかな曲がりを除いて)。下がり始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げ、ふくらはぎが伸びるまで足首を曲げてゆっくりと元の位置に戻ります。", "次に、息を吐きながらふくらはぎの前の脛骨の筋肉を収縮させてつま先を持ち上げます。", "1秒間押し続けて、息を吸いながら元に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Rocking_Standing_Calf_Raise';
UPDATE exercises SET name = 'ロッキープルアップ/プルダウン', instructions = '["幅広のグリップを使用して、手のひらを前に向けて懸垂バーを握ります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を反らせて胸を突き出しながら、胴体を約 30 度後ろに戻します。これが開始位置です。", "肩と上腕を下と後ろに引き、バーが胸の上部に触れるまで胴体を引き上げます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で 2 秒後、息を吸い始め、腕を完全に伸ばし広背筋が完全に伸びたら、胴体をゆっくりと開始位置に戻します。", "次に、上で説明したのと同じ動きを繰り返します。ただし、今度は上に上がるときに胴体はまっすぐのままで、バーが胸の上部ではなく首の後ろに触れます。ヒント: 頭をわずかに前傾させると、エクササイズのこの部分を適切に実行しやすくなります。", "開始位置まで腰を下げたら、プログラムで規定の回数だけエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Rocky_Pull-Ups_Pulldowns';
UPDATE exercises SET name = 'ルーマニアンデッドリフト', instructions = '["バーベルを前に置いて地面に置き、肩幅より少し広めの回内（手のひらを下に向けた状態）グリップで握ります。ヒント: 使用する重量に応じて、エクササイズを実行するためにリストラップが必要になる場合があります。また、可動域を広げるために高めのプラットフォームが必要になる場合があります。", "膝をわずかに曲げ、すねを垂直に保ち、腰と背中をまっすぐに保ちます。これが開始位置になります。", "背中と腕を常に完全に真っ直ぐに保ち、息を吐きながら腰を使ってバーを持ち上げます。ヒント: 動きは速くなく、安定して制御されている必要があります。", "完全に真っすぐに立ったら、しゃがむときとは異なり、膝を少しだけ曲げて、腰を後ろに押してバーを下げます。ヒント: 動作の開始時に深呼吸し、胸を張ったままにします。息を止めて下げ、息を吐きながら動作を完了します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Romanian_Deadlift';
UPDATE exercises SET name = '赤字からのルーマニアンデッドリフト', instructions = '["腕を伸ばした位置でバーを前に持ちながら立ち始めます。可動範囲を広げるために、高くなったプラットフォームの上に立つことができます。", "まず膝をわずかに曲げ、次に股関節を曲げ、お尻をできるだけ後ろに動かし、柔軟性が許す限り胴体を下げます。背中は常に完全に伸ばした状態に保たれ、バーは脚と接触したままでなければなりません。適切に行うと、ハムストリングスに強い緊張が感じられるはずです。", "動きを逆にして開始位置に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Romanian_Deadlift_from_Deficit';
UPDATE exercises SET name = 'ロープクライミング', instructions = '["頭の上で両手でロープをつかみます。小さなジャンプをしながらロープを引き下げます。", "片方の脚にロープを巻き付け、足でロープをつまみます。ロープをしっかりと握りながら、腕をできるだけ高く上げます。", "足からロープを放し、両腕で体を引き上げ、膝を胸に近づけます。", "両足をロープに再度固定し、立ち上がってもう一度ロープを高く握ります。ロープの頂上に到達するまで続けます。", "体を下げるには、手を重ねて滑り降りながら、ロープに足をつかんでいる力を緩めます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Rope_Climb';
UPDATE exercises SET name = 'ロープクランチ', instructions = '["ロープが取り付けられたケーブル システムの前に 1 ～ 2 フィートの位置にひざまずきます。", "適切な重さを選択したら、頭上に届く両手でロープを握ります。開始位置では胴体が直立している必要があります。", "まず、背骨を曲げて、ケーブルを引き下げながら胸郭を脚に近づけるようにします。", "動きの一番下で一時停止し、ゆっくりと開始位置に戻ります。", "これらはひねったり、横に動かしたりして斜めに打つことができます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Rope_Crunch';
UPDATE exercises SET name = '縄跳び', instructions = '["ロープの端をそれぞれの手で持ちます。ロープを後ろの地面に置きます。腕を上げて頭の上でロープを回し、目の前に下ろします。地面に着いたらジャンプして飛び越えます。維持できる適切な回転ペースを見つけてください。さまざまな速度とテクニックを使用してバリエーションを導入できます。", "縄跳びはエキサイティングで、調整力が問われ、多くのエネルギーを必要とします。体重 150 ポンドの人が 30 分間縄跳びをすると約 350 カロリーを消費しますが、ランニングでは 450 カロリー以上消費します。"]'::jsonb, category = '有酸素運動', equipment = 'その他' WHERE id = 'Rope_Jumping';
UPDATE exercises SET name = 'ロープストレートアームプルダウン', instructions = '["高滑車にロープを取り付け、重量を選択します。滑車から数フィート後ろに足をずらして立ち、両手でロープを持ちます。腰から前傾し、背中をまっすぐに保ち、腕を前に伸ばします。これが開始位置になります。", "腕をまっすぐに保ち、肩を伸ばしてロープを太ももまで引き下げます。", "動作の一番下のところで一時停止し、広背筋を引き締めます。", "重りをスタックに完全に乗せずに開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Rope_Straight-Arm_Pulldown';
UPDATE exercises SET name = '世界一周肩のストレッチ', instructions = '["ボディバーまたはほうきの柄を持ち、足を揃えてまっすぐに立ちます。", "肩幅よりも広いグリップでポールを腰の後ろで持ちます。手のひらは下に向け、親指は外側に向けます。", "ゆっくりと腕を頭の後ろに上げます。それ以上持ち上げるのが難しい場合は、無理に持ち上げないでください。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Round_The_World_Shoulder_Stretch';
UPDATE exercises SET name = 'ローイング、ステーショナリー', instructions = '["まず、漕ぎ手の上に座ります。かかとがフットペダルのベースに快適に置かれ、ストラップがしっかりと固定されていることを確認してください。必要に応じて、使用するプログラムを選択します。まっすぐに座り、腰を前に曲げます。", "ローワーを使用する場合、動作には 3 つのフェーズがあります。最初のフェーズは、漕ぎ手で前に出るときです。膝を曲げて胸に押し付けます。上半身は少し前傾し、良い姿勢を保ちます。次に、フットペダルを押して両脚を伸ばし、両手を上腹部に近づけ、肩を後ろに引きます。背中の負担を避けるために、主に脚と腰の筋肉を使います。", "回復段階では、腕を伸ばし、膝を曲げ、最初の段階に戻るときに体を再び前に出すだけです。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Rowing_Stationary';
UPDATE exercises SET name = 'ランナーのストレッチ', instructions = '["立ち上がって片足を後ろに置き、ゆっくりと胴体を床まで下げると、このストレッチに入るのが最も簡単です。", "前のかかとを床につけたままにします（浮いてしまう場合は、もう一方の足を後ろに伸ばします）。", "前脚の両側に手を置きます。このストレッチをさらに効果的にするには、お尻を天井に向かって押し上げ、徐々に床に向かって下げていきます。後ろ脚の股関節屈筋と、前脚のハムストリングとお尻をストレッチします。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Runners_Stretch';
UPDATE exercises SET name = 'ランニング、トレッドミル', instructions = '["まず、トレッドミルに乗り、メニューから希望のオプションを選択します。ほとんどのトレッドミルには手動設定があり、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。高度を調整してワークアウトの強度を変更できます。", "トレッドミルは利便性が高く、心臓血管にも効果があり、通常は外で走るよりも影響が少ないです。体重 150 ポンドの人が時速 8 マイルで 30 分間走ると、450 カロリー以上を消費します。ランニング中は正しい姿勢を維持し、降車時や心拍数を確認するときなど、必要な場合にのみハンドルを握ります。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Running_Treadmill';
UPDATE exercises SET name = 'ロシアンツイスト', instructions = '["床に横になり、足を動かないものの下に置くか、パートナーに足を支えてもらいます。足は膝のところで曲げる必要があります。", "太ももで仮想の V 字を描くように上体を起こします。腕は胴体に対して垂直に前に完全に伸ばし、手を握ります。これが開始位置です。", "息を吐きながら、腕が床と平行になるまで胴体を右側にひねります。", "収縮を 1 秒間保持し、息を吐きながら開始位置に戻ります。次に、右側に適用したのと同じテクニックを実行して反対側に移動します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Russian_Twist';
UPDATE exercises SET name = '土嚢の積載', instructions = '["土嚢やその他の物体を積み込むには、まず、作業器具を積み込みプラットフォームから一定の距離 (通常は 50 フィート) に置きます。", "まずは土嚢を持ち上げることから始めます。土嚢は非常に扱いにくく、使用する土嚢によって持ち上げ方も異なります。できるだけ周囲に手を伸ばし、腰と膝を通って高く引き上げます。肩掛けは通常禁止されています。", "できるだけ早くプラットフォームに移動し、腰、膝、足首を通してできるだけ高い位置まで荷重を加えます。落ちないようにプラットフォームの上に置きます。", "開始位置に戻って次の土嚢を回収し、イベントが完了するまで繰り返します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Sandbag_Load';
UPDATE exercises SET name = '肩甲骨懸垂', instructions = '["懸垂バーを回内グリップで握ります。", "ぶら下がった姿勢から、腕を使わずに数インチ体を上げます。これを行うには、肩をすくめる逆の動きで肩甲帯を押します。", "動作が完了したら一時停止し、ゆっくりと開始位置に戻ってから、さらに繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = NULL WHERE id = 'Scapular_Pull-Up';
UPDATE exercises SET name = 'シザーキック', instructions = '["まず、背中を床またはエクササイズマット（オプション）の上に押し付けて横になります。腕は完全に横に伸ばし、手のひらを下に向けます。注: アームは常に静止している必要があります。", "膝を軽く曲げて、かかとが地面から約6インチの高さになるように脚を持ち上げます。これが開始位置です。", "次に、左脚を約 45 度の角度まで持ち上げ、右脚をかかとが地面から約 2 ～ 3 インチになるまで下げます。", "右足を上げ、左足を下げることで動作を切り替えます。このエクササイズを行うときは、呼吸を忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Scissor_Kick';
UPDATE exercises SET name = 'シザーズジャンプ', instructions = '["膝を曲げて片足を前に出し、後ろの膝が地面にほぼ触れるランジスタンスの姿勢を想定します。", "前膝が足の正中線の上にあることを確認します。両脚を伸ばしてできるだけ高くジャンプし、腕を振って揚力を稼ぎます。", "できるだけ高くジャンプしながら、足の位置を変えて、前足を後ろに、後ろ足を前に動かします。", "着地したら、ランジの姿勢をとって脚を通して衝撃を吸収し、これを繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Scissors_Jump';
UPDATE exercises SET name = 'シーテッドバンドハムストリングカール', instructions = '["地面の近くにバンドを固定し、そこから数フィート離れたところにベンチを置きます。", "ベンチに座り、脚をまっすぐにして足首の後ろでバンドを固定します。これが開始位置になります。", "膝を曲げて足をベンチに近づけます。足が床に当たらないように、少し後ろに傾く必要があるかもしれません。", "動作が完了したら一時停止し、ゆっくりと開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Seated_Band_Hamstring_Curl';
UPDATE exercises SET name = 'シーテッドバーベル ミリタリープレス', instructions = '["頭の後ろにバーを置いてミリタリー プレス ベンチに座り、スポッターにバーを渡してもらうか (この方法で腱板を使用する方が効果的です)、回内グリップ (手のひらを前に向ける) で慎重に自分でバーを拾います。ヒント: グリップは肩幅より広くし、バーベルを下げるときに前腕と上腕の間に 90 度の角度を作る必要があります。", "適切なグリップ長でバーベルを持ち上げたら、腕をロックしてバーベルを頭の上まで持ち上げます。肩の高さくらいで頭の少し前に持ちます。これが開始位置です。", "息を吸いながらゆっくりとバーを鎖骨まで下げます。", "息を吐きながらバーを元の位置まで持ち上げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Seated_Barbell_Military_Press';
UPDATE exercises SET name = 'シーテッドバーベルツイスト', instructions = '["まず、フラットベンチの端に座り、太ももの上にバーベルを置きます。足は肩幅くらいに開いてください。", "手のひらを下に向けてバーを握り、両手が肩幅より広くなるようにします。腕が完全に伸びるまでバーベルを頭上に持ち上げ始めます。", "次に、バーベルが首の付け根に沿って止まるまで、頭の後ろにバーベルを下げます。これが開始位置です。", "足と頭を動かさないようにしながら、腹斜筋が収縮するのを感じるように腰を左右に動かします。腰が許す範囲でのみ左右に動かします。伸ばしたり動かしすぎたりすると、怪我をする可能性があります。ヒント: ゆっくりと制御された動きを使用してください。", "開始位置に戻るときは、息を吐きながら体を横にひねり、内側にひねることを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Seated_Barbell_Twist';
UPDATE exercises SET name = '着席ベントオーバーワンアームダンベル上腕三頭筋エクステンション', instructions = '["片腕にダンベルを持ち、ニュートラルグリップ（手のひらを自分に向ける）でフラットベンチの端に座ります。", "膝をわずかに曲げ、腰を曲げて胴体を前に出し、同時に背中が床とほぼ平行になるまでまっすぐに保ちます。必ず頭を上げてください。", "ダンベルを持つ上腕は胴体の近くにあり、胴体と一直線に並んでいる必要があります（手でウェイトを保持するときに前腕が床の方向を向くようにしながら、床と平行になるまで持ち上げます）。ヒント: 前腕と上腕の間の角度は 90 度である必要があります。これが開始位置です。", "上腕を固定したまま、前腕が床と平行になり腕全体が伸びるまで、息を吐きながら上腕三頭筋を使って体重を持ち上げます。他の多くの腕のエクササイズと同様、前腕のみが動きます。", "上部で 2 回目の収縮を行った後、息を吸いながらゆっくりとダンベルを開始位置に下げます。", "この動作を規定回数繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = '座位ベントオーバー・リアデルトレイズ', instructions = '["フラットベンチの前にダンベルを数個前方を向いて置きます。", "両足を揃えてベンチの端に座り、ダンベルをふくらはぎの後ろに置きます。", "ダンベルを持ち上げるために、背中をまっすぐに保ちながら腰を曲げます。摘むときは、手のひらが向かい合うようにします。これが開始位置になります。", "胴体を前方に動かさず、腕を肘のところでわずかに曲げ、両腕が床と平行になるまでダンベルを真横に持ち上げます。ウェイトを持ち上げるときに息を吐きます。 (注: 胴体を振ったり、腕を横ではなく後ろに戻したりしないでください。)", "上部で 1 秒間収縮した後、ダンベルをゆっくりと下げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Bent-Over_Rear_Delt_Raise';
UPDATE exercises SET name = '座位ベントオーバー ツーアーム ダンベル トライセプス エクステンション', instructions = '["ニュートラルグリップ（手のひらを自分に向ける）で両腕にダンベルを持ち、フラットベンチの端に座ります。", "膝をわずかに曲げ、腰を曲げて胴体を前に出し、同時に背中が床とほぼ平行になるまでまっすぐに保ちます。必ず頭を上げてください。", "ダンベルを持つ上腕は胴体の近くにあり、胴体と一直線に並んでいる必要があります（手でウェイトを保持するときに前腕が床の方向を向く一方で、床と平行になるまで持ち上げます）。ヒント: 前腕と上腕の間の角度は 90 度である必要があります。これが開始位置です。", "上腕を固定したまま、前腕が床と平行になり腕全体が伸びるまで、息を吐きながら上腕三頭筋を使って体重を持ち上げます。他の多くの腕のエクササイズと同様、前腕のみが動きます。", "上部で 2 回目の収縮を行った後、息を吸いながらダンベルをゆっくりと元の位置に下げます。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = '座った上腕二頭筋', instructions = '["膝を曲げて床に座り、パートナーが後ろに立ってください。手のひらを向かい合わせにして腕を後ろにまっすぐ伸ばします。あなたのパートナーがあなたの手首を握ってくれます。これが開始位置になります。", "パートナーが実際の動きを妨げている間、肘を曲げるようにしてください。", "10 ～ 20 秒後、パートナーが手首をそっと引き上げて上腕二頭筋を伸ばしながら、腕をリラックスさせます。怪我や過度のストレッチを防ぐために、いつストレッチを行うのが適切かを必ずパートナーに伝えてください。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Seated_Biceps';
UPDATE exercises SET name = '固定ケーブル列', instructions = '["この演習では、V バーを備えた低プーリーローマシンにアクセスする必要があります。注: V バーを使用すると、手のひらが向かい合うニュートラルなグリップが可能になります。スタートポジションに入るには、まずマシンに座り、両足を前部のプラットフォームまたはクロスバーの上に置きます。ただし、膝が軽く曲がっており、ロックされていないことを確認してください。", "背中の自然な位置を保ちながら前かがみになり、V バーのハンドルを握ります。", "腕を伸ばした状態で、胴体が脚から 90 度の角度になるまで後ろに引きます。背中はわずかにアーチ状になり、胸が突き出るようになります。バーを前に持つと、広背筋が気持ちよく伸びているのが感じられるはずです。これがエクササイズの開始位置です。", "胴体を動かさないようにして、腹部に触れるまで腕を胴体に近づけたまま、ハンドルを胴体の方に引きます。その動きをしながら息を吐きます。この時点で、背中の筋肉を強く締める必要があります。収縮を 1 秒間保持し、息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Seated_Cable_Rows';
UPDATE exercises SET name = 'シーテッドケーブルショルダープレス', instructions = '["適切な重量に調整し、ハンドルを握りながら座ります。上腕は体に対して約90度になり、頭と胸を上げます。肘も約90度に曲げる必要があります。これが開始位置になります。", "まず肘を通って伸ばし、頭の上でハンドルを一緒に押します。", "一番上で停止したら、ハンドルを開始位置に戻します。ケーブルの張力を維持してください。", "背中をパッドから離し、両手を交互に変えてこの動きを実行することもできます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Seated_Cable_Shoulder_Press';
UPDATE exercises SET name = 'シーテッドカーフレイズ', instructions = '["マシンに座り、かかとが伸びたプラットフォームの下部につま先を置きます。この章の冒頭にあるように、お好みのつま先の位置 (前方、内側、または外側) を選択してください。", "太ももの下部分をレバー パッドの下に置きます。レバー パッドは太ももの高さに応じて調整する必要があります。次に、レバーパッドが前方に滑るのを防ぐために、レバーパッドの上に手を置きます。", "かかとを押し上げてレバーを少し持ち上げ、安全バーを放します。これが開始位置になります。", "ふくらはぎが完全に伸びるまで、足首を曲げてゆっくりとかかとを下げます。この動きをしながら息を吸います。", "ふくらはぎを収縮させて息を吐きながら、足首をできるだけ高く伸ばしてかかとを上げます。上部の収縮を 1 秒間保持します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Seated_Calf_Raise';
UPDATE exercises SET name = '座ったままのふくらはぎのストレッチ', instructions = '["エクササイズマットの上にまっすぐに座ります。", "片方の膝を曲げ、その足を床に置き、胴体を安定させます。", "もう一方の脚を伸ばし、足首を曲げます。", "バンド、タオル、または手が届く場合は手を使用して、つま先を自分の方に引っ張ります。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Seated_Calf_Stretch';
UPDATE exercises SET name = 'シーテッド・クローズグリップ・コンセントレーション・バーベル・カール', instructions = '["バーベルまたは E-Z バーを足の間に置き、フラットベンチに座ります。膝を曲げて足を床に置き、脚を広げます。", "腕を使ってバーベルを持ち上げ、上腕の後ろを太ももの内側の上に置きます（膝の前から約3.5インチ離れた位置）。このエクササイズを実行するには、肩の幅よりも近い回外グリップが必要です。ヒント: 腕は腕の長さで伸ばし、バーベルは床の上にある必要があります。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方にカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとバーベルを開始位置に戻し始めます。 ヒント: スイング動作はいかなる場合も避けてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Seated_Close-Grip_Concentration_Barbell_Curl';
UPDATE exercises SET name = 'シーテッドダンベルカール', instructions = '["平らなベンチに座り、両手にダンベルを腕の長さで持ちます。肘は胴体の近くにある必要があります。", "手のひらが胴体に向くように回転させます。これが開始位置になります。", "上腕を固定したままウェイトを丸め、ダンベルが太ももを通過したら手首をひねり始め、動作の最後に手のひらが前を向くようにします。息を吐きながら上腕二頭筋を収縮させ、前腕だけを動かすようにしてください。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、手首を回転させてニュートラルグリップに戻しながら、ゆっくりとダンベルを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Dumbbell_Curl';
UPDATE exercises SET name = 'シーテッドダンベルインナー上腕二頭筋カール', instructions = '["平らなベンチの端に座り、両手にダンベルを腕の長さで持ちます。肘は胴体の近くにある必要があります。", "手のひらが中立の位置で内側を向くように回転させます。これが開始位置になります。", "上腕を固定したまま、ダンベルを外側に丸め、持ち上げるときに手のひらを外側に向け、前腕を三角筋外側と一直線に保ちます。ヒント:", "前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。ダンベルを下げるときに腕を回転させて、ニュートラルなグリップに戻せるようにすることを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Dumbbell_Inner_Biceps_Curl';
UPDATE exercises SET name = 'シーテッドダンベル手のひらを下にしてリストカール', instructions = '["まず、フラットベンチの前の床に 2 つのダンベルを置きます。", "フラットベンチの端に足を肩幅くらいに広げて座ります。必ず足を床につけてください。", "腕を使って両方のダンベルをつかみ、手のひらを下に向けて前腕が太ももに当たるように持ち上げます。手首は太ももの端の上にぶら下がっている必要があります。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。エクササイズのこの部分では必ず吸入してください。ヒント: このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。", "終わったら、ダンベルを床に下げるだけです。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Dumbbell_Palms-Down_Wrist_Curl';
UPDATE exercises SET name = 'シーテッドダンベルパームアップリストカール', instructions = '["まず、フラットベンチの前の床に 2 つのダンベルを置きます。", "フラットベンチの端に足を肩幅くらいに広げて座ります。必ず足を床につけてください。", "腕を使って両方のダンベルをつかみ、手のひらを上に向けて前腕が太ももに当たるように持ち上げます。手首は太ももの端の上にぶら下がっている必要があります。", "まずは手首を上に丸めて息を吐きます。", "息を吸いながら、手首をゆっくりと元の位置まで下げます。エクササイズのこの部分では必ず吸入してください。ヒント: このエクササイズを実行するために必要な動きは手首だけであるため、前腕は動かさないようにしてください。", "推奨回数だけ繰り返します。", "終わったら、ダンベルを床に下げるだけです。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Dumbbell_Palms-Up_Wrist_Curl';
UPDATE exercises SET name = 'シーテッドダンベルプレス', instructions = '["ダンベルを 2 個用意し、ミリタリー プレス ベンチまたはバック サポートが付いているユーティリティ ベンチに座り、ダンベルを太ももの上に直立させます。", "太ももを使ってダンベルの両側を肩の高さまで持ち上げ、ダンベルを一度に 1 つずつきれいにします。", "手のひらが前を向くように手首を回転させます。これが開始位置です。", "息を吐きながら、ダンベルの上部が触れるまで押し上げます。", "2 回目の停止の後、息を吸いながらゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Dumbbell_Press';
UPDATE exercises SET name = '着座フラットベンチレッグプルイン', instructions = '["ベンチに座り、両足を平行より少し下に前に伸ばし、両腕でベンチの側面をつかみます。胴体はベンチから約 45 度の角度で後ろに傾いている必要があります。これが開始位置になります。", "膝を手前に引き寄せ、同時に胴体を膝に近づけます。この動きをしながら息を吐きます。", "2 回目の停止の後、息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Seated_Flat_Bench_Leg_Pull-In';
UPDATE exercises SET name = '座位でのハムストリングのストレッチ', instructions = '["マットの上に右脚を前に伸ばし、左脚を曲げて足を右の内腿に当てます。", "ハムストリングが伸びていると感じるまで、腰から前傾し、足首に手を伸ばします。 15 秒間押し続けて、反対側も繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Seated_Floor_Hamstring_Stretch';
UPDATE exercises SET name = '座位三角筋前部', instructions = '["足を曲げて床に直立して座り、パートナーが後ろに立ってください。手のひらを地面に向けて、腕を体の横にまっすぐ突き出します。アシスタントが手首を持っているので、できるだけ後ろに動かすようにしてください。これが開始位置になります。", "肘を真っすぐに伸ばしたまま、実際に動かないようにパートナーが 10 ～ 20 秒間優しく拘束しながら、腕を前に動かしてみます。", "次に、筋肉をリラックスさせ、パートナーに肩と胸のストレッチをゆっくりと強めてもらいます。 10 ～ 20 秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Seated_Front_Deltoid';
UPDATE exercises SET name = '座った臀部', instructions = '["膝を曲げて座った姿勢で、片方の足首を反対側の膝の上に置きます。あなたのパートナーがあなたの後ろに立ってくれるでしょう。次に、パートナーがあなたの肩を手で支えている間、前かがみになります。これが開始位置になります。", "パートナーが胴体の実際の動きを妨げるので、10 ～ 20 秒間胴体を押し戻すようにしてください。", "次に、パートナーが胴体を 10 ～ 20 秒間ゆっくりと前に押してストレッチを強めながら、筋肉をリラックスさせます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Seated_Glute';
UPDATE exercises SET name = '座っておはようございます', instructions = '["パワーラックにボックスを設置します。ピンは適切な高さに設定する必要があります。まずバーの下に足を踏み入れ、トラップの上ではなく肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。", "バーをラックから外し、腰にしっかりとしたアーチを作ります。頭を前に向けたままにしてください。背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。ボックスの上に座るまで、腰を落として座ります。これが開始位置になります。", "バーをしっかりと握りながら、腰をできるだけ前に曲げます。ピンを平行になるように設定すると、失敗した場合の安全性が確保されるだけでなく、いつ停止するかを知ることができます。", "ピンの真上で停止し、胴体が直立するまで動きを逆にします。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Seated_Good_Mornings';
UPDATE exercises SET name = '座ったハムストリング', instructions = '["足を伸ばして座った姿勢で、パートナーに後ろに立ってもらいます。次に、パートナーがあなたの肩を手で支えている間、前かがみになります。これが開始位置になります。", "パートナーが胴体の実際の動きを妨げるので、10 ～ 20 秒間胴体を押し戻すようにしてください。", "次に、パートナーが胴体を 10 ～ 20 秒間ゆっくりと前に押してストレッチを強めながら、筋肉をリラックスさせます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Seated_Hamstring';
UPDATE exercises SET name = '座ったままのハムストリングとふくらはぎのストレッチ', instructions = '["ベルト、ロープ、またはバンドを片足に巻き付けます。両足を伸ばして座ります。これが開始位置になります。", "わずかに前かがみになり、ベルトを引いて足のつま先を後ろに引きます。この位置を 10 ～ 20 秒間保持し、もう一方の脚でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Seated_Hamstring_and_Calf_Stretch';
UPDATE exercises SET name = '着座ヘッドハーネスの首の抵抗', instructions = '["ネックストラップをフラットベンチの端の床に置きます。ウェイトを選択したら、足を肩幅より広く開いてフラットベンチの端に座ります。つま先を指摘する必要があります。", "胴体が床とほぼ平行になるまでゆっくりと前に動かします。両手を使って、ネックストラップを頭の周りにしっかりと固定します。ヒント: 首に負担がかからないように、ウェイトが床に置かれたままであることを確認してください。次に、両手で体重をつかみながら、床に対してほぼ垂直になるまで胴体を後ろに上げます。注: このエクササイズを実行するには、頭と胴体をわずかに前に傾ける必要があります。", "次に、両手を膝の上に置きます。これが開始位置です。", "息を吸いながら、顎が胸の上部に触れるまでゆっくりと首を下げます。", "息を吐きながら、首を元の位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Seated_Head_Harness_Neck_Resistance';
UPDATE exercises SET name = 'シーテッドレッグカール', instructions = '["身長に合わせてマシンのレバーを調整し、バックサポートパッドに背中を当ててマシンに座ります。", "下腿の裏側をパッド付きレバーの上（ふくらはぎの数インチ下）に置き、膝のすぐ上の太腿にラップパッドを固定します。次に、マシンのサイドハンドルを握り、つま先をまっすぐに向け（または、他の 2 つのスタンスのいずれかを使用することもできます）、脚が目の前で完全に真っ直ぐであることを確認します。これが開始位置になります。", "息を吐きながら、膝を曲げてマシンのレバーを太ももの後ろまでできるだけ引きます。胴体は常に静止した状態に保ちます。収縮した位置を 1 秒間保持します。", "息を吸いながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Seated_Leg_Curl';
UPDATE exercises SET name = '座ったままのレッグタック', instructions = '["ベンチに座り、両足を平行より少し下に前に伸ばし、両腕でベンチの側面をつかみます。胴体はベンチから約 45 度の角度で後ろに傾いている必要があります。これが開始位置になります。", "膝を手前に引き寄せ、同時に胴体を膝に近づけます。この動きをしながら息を吐きます。", "2 回目の停止の後、息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Seated_Leg_Tucks';
UPDATE exercises SET name = '座ったワンアームダンベルの手のひらを下に向けたリストカール', instructions = '["右手にダンベルを持ち、フラットベンチに座ります。", "両足を床に平らに置き、肩幅よりわずかに広めの距離に置きます。", "前かがみになり、手のひらを下にして右前腕を右上腿の上部に置きます。ヒント: 手首の後ろが膝の上に来るようにしてください。これが開始位置になります。", "ダンベルをしっかりと握りながら、ダンベルをできるだけ下げます。この動きをしながら息を吸います。", "次に、前腕を収縮させ、息を吐きながら、ダンベルをできるだけ高くカールさせます。収縮を 1 秒間維持してから、再び下げます。ヒント: 動作は手首のみで行う必要があります。", "推奨回数繰り返し、腕を切り替えて同じ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl';
UPDATE exercises SET name = 'シーテッド・ワンアーム・ダンベル・パームズアップ・リストカール', instructions = '["右手にダンベルを持ち、フラットベンチに座ります。", "両足を床に平らに置き、肩幅よりわずかに広めの距離に置きます。", "前かがみになり、手のひらを上にして右前腕を右上腿の上部に置きます。ヒント: 手首の前が膝の上に来るようにしてください。これが開始位置になります。", "ダンベルをしっかりと握りながら、ダンベルをできるだけ下げます。この動きをしながら息を吸います。", "次に、前腕を収縮させ、息を吐きながら、ダンベルをできるだけ高くカールさせます。収縮を 1 秒間維持してから、再び下げます。ヒント: 動作は手首のみで行う必要があります。", "推奨回数繰り返し、腕を切り替えて同じ動作を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl';
UPDATE exercises SET name = '着座ワンアームケーブルプーリー列', instructions = '["スタートポジションに入るには、まずマシンに座り、両足を前部のプラットフォームまたはクロスバーの上に置きます。ただし、膝が軽く曲がっており、ロックされていないことを確認してください。", "背中の自然な位置を保ちながら前かがみになり、手のひらを下にして左腕でシングル ハンドル アタッチメントをつかみます。", "腕を伸ばした状態で、胴体が脚から 90 度の角度になるまで後ろに引きます。背中はわずかにアーチ状になり、胸が突き出るようになります。バーを前に持つと、広背筋が気持ちよく伸びているのが感じられるはずです。右腕は腰でホールドできます。これがエクササイズの開始位置です。", "胴体を静止させたまま、手首を回転させるときに腕を胴体に近づけたまま、ハンドルを胴体の方に引きます。手が腹部の近くに来る頃には、手が中立位置（手のひらが胴体に面する）になります。その動きをしながら息を吐きます。この時点で、背中の筋肉を強く締める必要があります。", "この収縮を 1 秒間保持し、息を吸いながらゆっくりと元の位置に戻ります。 ヒント: 開始位置に戻るときに手首を回転させ、手のひらが再び下を向くようにすることを忘れないでください。", "推奨回数繰り返した後、右手でも同じ動きを行います。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Seated_One-arm_Cable_Pulley_Rows';
UPDATE exercises SET name = '座ったままのオーバーヘッドストレッチ', instructions = '["エクササイズマットの上にまっすぐに座ります。", "足の裏を腰の前6～8インチのところに合わせて触れます。", "片手を体の横の床に置き、もう一方の手を頭の後ろに置きます。", "上体を反対側に傾けながら、肘を天井に持ち上げます。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Seated_Overhead_Stretch';
UPDATE exercises SET name = 'シーテッドパームアップバーベルリストカール', instructions = '["両手でバーベルを持ち、手のひらを上に向けます。両手は肩幅くらいに開きます。", "両足を床に平らに置き、肩幅よりわずかに広めの距離に置きます。", "前かがみになり、手のひらを上にして前腕を太ももの上に置きます。ヒント: 手首の前が膝の上に来るようにしてください。これが開始位置になります。", "息を吸いながらしっかりと握りながら、バーをできるだけ下げます。", "次に、前腕を曲げて息を吐きながら、バーをできるだけ高く上げます。上部の収縮を 1 秒間保持し、ヒント: 手首のみを動かします。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Seated_Palm-Up_Barbell_Wrist_Curl';
UPDATE exercises SET name = 'シーテッド・パームダウン・バーベル・リストカール', instructions = '["両手でバーベルを持ち、手のひらを下に向けます。両手は肩幅くらいに開きます。", "両足を床に平らに置き、肩幅よりわずかに広めの距離に置きます。", "Lean forward and place your forearms on top of your upper thighs with your palms down.ヒント: 手首の後ろが膝の上に来るようにしてください。これが開始位置になります。", "息を吸いながらしっかりと握りながら、バーをできるだけ下げます。", "次に、前腕を曲げて息を吐きながら、バーをできるだけ高く上げます。上部の収縮を 1 秒間保持し、ヒント: 手首のみを動かします。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Seated_Palms-Down_Barbell_Wrist_Curl';
UPDATE exercises SET name = '座位側方挙上', instructions = '["ダンベルをいくつか選び、床に両足をしっかりとつけてフラットベンチの端に座ります。手のひらを内側に向けてダンベルを持ち、腕を腕の長さで体の横にまっすぐ下げます。これが開始位置になります。", "胴体を静止させたまま（スイングしないように）、肘を軽く曲げ、グラスに水を注ぐように手を少し前に傾けてダンベルを体の横に持ち上げます。腕が床と平行になるまで上げ続けます。この動きを実行しながら息を吐き、頂点で 1 秒間停止します。", "息を吸いながらダンベルをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Side_Lateral_Raise';
UPDATE exercises SET name = 'シーテッド・トライセプス・プレス', instructions = '["背中を支えてベンチに座り、ダンベルを両手でつかみ、腕を伸ばして頭上に持ちます。ヒント: より良い方法は、特に非常に重い場合は、誰かに渡してもらうことです。抵抗は手のひらの上に置き、親指で抵抗を囲みます。手のひらは内側に向ける必要があります。これが開始位置になります。", "上腕を頭の近く（肘を内側）に保ち、床に対して垂直に保ち、前腕が上腕二頭筋に触れるまで頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさないようにし、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってダンベルを上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Seated_Triceps_Press';
UPDATE exercises SET name = '座位での両腕パームアップ・ロープーリー・リストカール', instructions = '["バーベルまたはEZカールアタッチメントが取り付けられた低プーリーマシンの前にベンチを置きます。", "ハンドルを太ももの上部に持ってくると、ウェイトスタックが上に動かされてケーブルに張力が生じるように、ベンチを十分に遠くに移動します。", "次に、手のひらを上にして両手でハンドルを持ち、肩幅のグリップを使用します。", "一歩下がってベンチに座り、足を肩幅くらいに開き、床にしっかりとつけます。", "前かがみになり、前腕を太ももの上に置き、手首の後ろを膝の上に置きます。これが開始位置になります。", "息を吸いながらしっかりと握りながら、バーをできるだけ下げます。", "次に、前腕を収縮させながら、バーをできるだけ高く丸めます。ヒント: 手首だけを動かしてください。前腕ではありません。", "上部で 2 回目の収縮を行った後、息を吸いながら開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl';
UPDATE exercises SET name = 'シーソープレス（交互サイドプレス）', instructions = '["両手にダンベルを持ち、直立して立ちます。", "ダンベルを胸/肩の高さまできれいにして(持ち上げて)、アーノルドプレスを実行する準備をしているかのように手のひらが自分の方を向くように手首を回転させます。これが開始位置になります。", "次に、手首を回転させながら左腕を頭上に伸ばし始め、上がるときに手のひらが前を向くようにします。ウェイトを持ち上げるときにも肘が前に出るはずです。同時に、腰から反対側に向かって曲がります。ヒント: このエクササイズを正しく実行すると、体の右側で左腕を使って頭上の何かに手を伸ばそうとしているように見えるはずです。この動きをしながら息を吐きます。", "トップの位置に到達したら、息を吸います。次に、ウェイトを頭上に完全に伸ばし、右側にかがみ、左側への動きを開始します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'See-Saw_Press_Alternating_Side_Press';
UPDATE exercises SET name = 'ショットガン・ロウ', instructions = '["低いケーブルにシングルハンドルを取り付けます。", "正しいウェイトを選択したら、ワイドスプリットスタンスで数フィート後ろに立ってください。腕を伸ばして肩を前に出す必要があります。これが開始位置になります。", "肩を引いて肘を曲げて動きを行います。引くときに手首を回外し、手のひらを上に向けます。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Shotgun_Row';
UPDATE exercises SET name = 'ショルダーサークル', instructions = '["肩をリラックスさせ、腕を体の横にゆったりと置き（座っている場合は膝の上に）、肩を前、上、後ろ、下にゆっくりと回転させます。", "方向を逆にします。このエクササイズは、肩を交互に行うことも、両方を同時に行うこともできます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Shoulder_Circles';
UPDATE exercises SET name = 'ショルダープレス - バンド付き', instructions = '["まず、エクササイズバンドの上に立ち、腕の長さで緊張が始まるようにします。ハンドルをつかみ、手が両側の肩の高さになるように持ち上げます。", "手のひらが前を向くように手首を回転させます。肘を曲げて、上腕と前腕を胴体と一直線にします。これが開始位置です。", "息を吐きながら、腕が頭上に完全に伸びるまでハンドルを持ち上げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Shoulder_Press_-_With_Bands';
UPDATE exercises SET name = 'ショルダーレイズ', instructions = '["腕を横にリラックスさせ、肩を耳に向かって上げてから下げます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Shoulder_Raise';
UPDATE exercises SET name = '肩のストレッチ', instructions = '["左腕を体全体に伸ばしてまっすぐに保ちます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Shoulder_Stretch';
UPDATE exercises SET name = '横向き床ストレッチ', instructions = '["まず左側を下にして横になり、左膝を体の前で曲げて胴体を安定させます（体を直立させるために腹筋も使います）。", "右足をまっすぐに伸ばし、右足を左足の後ろの床に置きます。右腕を頭の上でまっすぐに伸ばし、右手首を軽く引いて体の右側全体を伸ばします。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Side-Lying_Floor_Stretch';
UPDATE exercises SET name = 'サイドブリッジ', instructions = '[]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Side_Bridge';
UPDATE exercises SET name = 'サイドホップスプリント', instructions = '["コーンまたはハードルの側に立ちます。", "このドリルは、障害物を横に飛び越え、着地から跳ね返って元の位置に戻ることから始めます。", "規定の回数または繰り返しできるだけ早くホップし、最後のホップを着地したときに短い距離をダッシュ​​してこの訓練を終了します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Side_Hop-Sprint';
UPDATE exercises SET name = 'サイドジャックナイフ', instructions = '[]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Side_Jackknife';
UPDATE exercises SET name = 'サイドラテラルレイズ', instructions = '["ダンベルをいくつか選び、胴体をまっすぐにして立ち、ダンベルを腕の長さで体の横に置き、手のひらを自分に向けます。これが開始位置になります。", "胴体を静止した位置に保ち（スイングしない）、肘を軽く曲げ、グラスに水を注ぐように手を少し前に傾けてダンベルを体の横に持ち上げます。腕が床と平行になるまで上げ続けます。この動きを実行しながら息を吐き、頂点で 1 秒間停止します。", "息を吸いながらダンベルをゆっくりと元の位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Side_Lateral_Raise';
UPDATE exercises SET name = 'サイドラテラルからフロントレイズまで', instructions = '["立った姿勢で、ダンベルを体の横に持ちます。これが開始位置になります。", "肘を軽く曲げたまま、スイングや不正行為を避けながら、目の前のウェイトを肩の高さまで上げます。", "エクササイズの最後では、腕を伸ばしたままウェイトを前に動かします。", "制御された動きでウェイトを下げます。", "次の繰り返しでは、前のウェイトを肩の高さまで上げてから、ウェイトを横方向に移動します。", "ウェイトを開始位置まで下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Side_Laterals_to_Front_Raise';
UPDATE exercises SET name = 'サイドレッグレイズ', instructions = '["椅子の隣に立ち、支えとしてつかまってもよいでしょう。片足で立ちます。これが開始位置になります。", "脚をまっすぐに保ち、できるだけ横に上げ、反対側の脚を交差できるように振り下ろします。", "このスイング動作を 5 ～ 10 回繰り返し、回数を重ねるごとに可動範囲を広げます。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Side_Leg_Raises';
UPDATE exercises SET name = '横向きで鼠径部のストレッチ', instructions = '["まず、右側を下にして横になり、右膝を前に曲げて胴体を安定させます。", "頭を右手または肩の上に置きます。左脚を上に持ち上げ、膝の後ろ（簡単）または足（強く）を持ちます。", "左膝を左肩に向かって引き、同時に足または膝を床に押し付けます。このストレッチを強化するには、左脚をまっすぐに伸ばします。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Side_Lying_Groin_Stretch';
UPDATE exercises SET name = 'サイドネックストレッチ', instructions = '["肩をリラックスさせた状態から始めて、頭を肩に向かってゆっくりと傾けます。", "頭の側面を軽く引っ張ってストレッチを助けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Side_Neck_Stretch';
UPDATE exercises SET name = '横立ち走り幅跳び', instructions = '["アスレチックスタンスで足を腰幅に広げて立ち始めます。頭と胸を上げ、膝と腰をわずかに曲げます。これが開始位置になります。", "右に体を傾け、腰、膝、足首を伸ばして空中に飛び込みます。腕でブロックして動きをリードし、できるだけ右にジャンプします。", "足を腰幅に開き、同じ方向を向いて着地し、下半身で衝撃を吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = NULL WHERE id = 'Side_Standing_Long_Jump';
UPDATE exercises SET name = 'あごを横に並べる', instructions = '["幅広のグリップを使用して、手のひらを前に向けて懸垂バーを握ります。", "両腕を前に伸ばしてバーを広く握り、腰を反らせて胸を張りながら上体を約30度後ろに戻します。これが開始位置です。", "肩と上腕を下と後ろに引いて、バーが胸の上部にほとんど触れるまで、左側に傾きながら上体を引き上げます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにして (スイングしないで)、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "1秒間の収縮の後、息を吸いながら開始位置に戻ります。", "次に、肩と上腕を下と後ろに引いて、バーが胸の上部にほとんど触れるまで、右側に傾きながら上体を引き上げます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "1秒間の収縮の後、息を吸いながら開始位置に戻ります。", "それぞれの側で規定の回数を繰り返すまで、手順 3 ～ 6 を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Side_To_Side_Chins';
UPDATE exercises SET name = 'サイドリストプル', instructions = '["このストレッチは立ったまま行うのが最も効果的です。左腕を体の正中線の上で交差させ、右手の左手首を腰の高さで押し下げます。左腕を曲げた状態からストレッチを始めます。", "図のように、ゆっくりとまっすぐにして引っ張り、肩の高さまで持ち上げます。このストレッチは肩ではなく背中から始まると感じて、肩の関節をあまり強く引っ張らないようにしてください。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Side_Wrist_Pull';
UPDATE exercises SET name = 'サイドツーサイドボックスシャッフル', instructions = '["ボックスの片側に立って、左足をボックスの中央に置きます。", "まず、ボックスの反対側に飛び上がって、右足をボックスの上に置き、左足を床に着地します。動きを助けるために腕を振ってください。", "ボックス内を前後にシャッフルし続けます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Side_to_Side_Box_Shuffle';
UPDATE exercises SET name = 'シングルアームケーブルクロスオーバー', instructions = '["まずプーリーを高い位置に移動し、使用する抵抗を選択し、ハンドルを両手に持ちます。", "腕を前に伸ばし、両手を合わせて両方の滑車の前に進みます。前かがみになるときに頭と胸を上げ、足を千鳥にする必要があります。これが開始位置になります。", "左腕を所定の位置に保ち、右腕を横に伸ばし、肘をわずかに曲げたままにします。右腕はほぼ肩の高さで体に対して垂直になるようにします。", "手を体の正中線に引き戻して、腕を開始位置に戻します。", "開始位置で 1 秒間保持し、反対側でも同じ動きを繰り返します。規定の回数、交互に繰り返し続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Single-Arm_Cable_Crossover';
UPDATE exercises SET name = 'シングルアームリニアジャマー', instructions = '["バーを地雷に差し込むか、コーナーにしっかりと固定します。バーに適切な重量を加えます。", "バーを床から持ち上げ、片手または両手で肩に持っていきます。ワイドスタンスを採用します。これが開始位置になります。", "肘を伸ばしてウェイトを押し上げて動きを実行します。爆発的に動き、腰と膝を完全に伸ばして最大限の力を生み出します。", "開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Single-Arm_Linear_Jammer';
UPDATE exercises SET name = 'シングルアームプッシュアップ', instructions = '["地面にうつ伏せになり始めます。つま先と片腕で体重を支える位置に移動します。作業する腕は肩の真下に置き、完全に伸ばしてください。脚を伸ばす必要があります。この動作では、通常の腕立て伏せよりも足を離して、より広いベースが必要になる場合があります。", "正しい姿勢を保ち、空いている方の手を背中の後ろに置きます。これが開始位置になります。", "地面に触れるまで肘を曲げて体を下げます。", "ゆっくりと下降し、逆方向に腕を伸ばして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Single-Arm_Push-Up';
UPDATE exercises SET name = 'シングルコーンスプリントドリル', instructions = '["このドリルは素早い足の動きを教えます。コーンが 1 つ必要です。片方の腕を後ろに、もう一方の腕を前に向けてコーンの隣に立ち始めます。", "できるだけ早く足を切り、腕でブロックします。膝を上げたまま、激しい足の動きでコーンを一周します。", "円錐形の周囲を 3 周した後は休憩します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Single-Cone_Sprint_Drill';
UPDATE exercises SET name = 'シングルレッグハイボックススクワット', instructions = '["ボックスをラックに配置します。バンドまたはロープをボックスの上の所定の位置に固定します。", "ボックスの前に立ち、もう一方の足を支えずにそのままにして、完全な直立姿勢までボックスに乗ります。バランスをとるためにバンドをつかんでください", "。同じ足で上下に踏み続けてから、反対側に切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Single-Leg_High_Box_Squat';
UPDATE exercises SET name = 'シングルレッグホップの進行', instructions = '["目の前にコーンを一列に並べます。片足でバランスをとり、リラックスした立位姿勢をとります。反対側の足の膝を上げます。これが開始位置になります。", "前方に飛び跳ね、同じ足でコーンの上にジャンプして着地します。", "カウンターモーションジャンプを使ってコーンからコーンへと飛び移ります。", "最後は向きを変えて反対側の足で戻ります。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Single-Leg_Hop_Progression';
UPDATE exercises SET name = 'シングルレッグラテラルホップ', instructions = '["コーンまたはハードルの側に立ちます。開始位置に入るには、片足で立ち、膝をわずかに曲げます。", "まず、カウンタージャンプを実行してコーンの上を横に飛び越えます。", "ジャンプした脚で着地し、すぐにジャンプして開始位置に戻ります。", "前後に飛び跳ね続けます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Single-Leg_Lateral_Hop';
UPDATE exercises SET name = '片足レッグエクステンション', instructions = '["マシンに座り、適切な位置になるように調整します。パッドはすねの下部にあるべきですが、足首には接触しないようにしてください。ピボットポイントが膝と一直線になるようにシートを調整します。自分の能力に適した重量を選択してください。", "正しい姿勢を維持し、片脚を完全に伸ばし、動作の最高点で停止します。", "筋肉の緊張を保ちながら、体重を止めずに開始位置に戻ります。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Single-Leg_Leg_Extension';
UPDATE exercises SET name = '片足ストライドジャンプ', instructions = '["ボックスの側面に立ち、内側の足をボックスの端近くに置きます。", "まずは腕を上に振りながら上の脚を押し上げ、できるだけ高く上にジャンプします。反対側の膝を上に上げてみます。", "開始時と同じ位置に着地し、内足を使って衝撃を減速します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Single-Leg_Stride_Jump';
UPDATE exercises SET name = 'シングルダンベルレイズ', instructions = '["ワイドスタンスで両手でダンベルを持ち、ハンドルの代わりにダンベルのヘッドを握ります。腕を伸ばして腰にぶら下げます。これが開始位置になります。", "腕を伸ばしたまま、肩の高さまで体重を上げます。動作中は胴体と腰を動かさないようにしてください。", "開始位置に戻り、推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Single_Dumbbell_Raise';
UPDATE exercises SET name = '片足バットキック', instructions = '["まず片足で立ち、曲がった膝を上げます。これが開始位置になります。", "反動ジャンプを使用して、接地した脚の股関節、膝、足首を伸ばして上向きに踏み切ります。", "すぐに膝を曲げて、飛び跳ねた足のかかとでお尻に触れてみてください。", "脚を腰の下で部分的に曲げた位置に戻して着地します。反対側の足は、ドリル中は比較的同じ位置に留まっている必要があります。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Single_Leg_Butt_Kick';
UPDATE exercises SET name = 'シングルレッググルートブリッジ', instructions = '["足を平らにし、膝を曲げて床に横になります。", "片足を地面から上げ、膝を胸に引き寄せます。これが開始位置になります。", "かかとを通って腰を上に伸ばし、臀部を地面から持ち上げることでこの動きを実行します。", "できるだけ伸ばして一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Single_Leg_Glute_Bridge';
UPDATE exercises SET name = 'シングルレッグプッシュオフ', instructions = '["片足をボックスの上に置き、かかとを端に近づけて地面に立ちます。", "足をボックスの上に置き、腰と膝を伸ばしてできるだけ高さを上げようとします。", "同じ足でボックスの上に着地し、もう一方の足を開始位置に戻します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Single_Leg_Push-off';
UPDATE exercises SET name = 'シットアップ', instructions = '["床に横になり、足を動かないものの下に置くか、パートナーに足を支えてもらいます。足は膝のところで曲げる必要があります。", "両手を頭の後ろに置き、指を組んでロックします。これが開始位置です。", "太ももで仮想の V 字を描くように上体を起こします。エクササイズのこの部分を実行するときは、息を吐きます。", "収縮を一瞬感じたら、息を吸いながら上半身を開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Sit-Up';
UPDATE exercises SET name = 'シットスクワット', instructions = '["足を肩幅に開いて立ちます。これが開始位置になります。", "腰を後ろに向けて座り、膝と腰を曲げることから動きを始めます。", "途中でしゃがんで平行以上になるまで続け、開始位置に戻るまですぐに動きを逆にします。これを5〜10回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Sit_Squats';
UPDATE exercises SET name = 'スケート', instructions = '["ローラースケートは、心肺機能や筋持久力の向上に効果的な楽しいアクティビティです。比較的優れたバランスと調整が必要です。曲がる、止まるなどのスケートの基本を学び、怪我をしないように保護具を着用する必要があります。", "30分間続けて快適なペースでスケートをすることができます。有酸素運動にチャレンジしたい場合は、インターバル スケートを行ってください。スピード スケートは 5 分ごとに 2 分間行い、残りの 3 分を回復に使用します。体重 150 ポンドの人は、通常、早歩きと同じような快適なペースで 30 分間スケートをすると、約 175 カロリーを消費します。"]'::jsonb, category = '有酸素運動', equipment = 'その他' WHERE id = 'Skating';
UPDATE exercises SET name = 'スレッドドラッグ - ハーネス', instructions = '["まず、スレッドに希望の重量を載せ、引っ張りストラップを取り付けます。ハンドルを使って引っ張ったり、ハーネスを使用したり、引っ張りストラップをウェイトベルトに取り付けたりできます。", "前に引くときも後ろに引くときも、進行方向に体を傾け、腰と膝を伸ばして進みます。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Sled_Drag_-_Harness';
UPDATE exercises SET name = 'そり頭上後方歩行', instructions = '["ロープまたはチェーンで接続されたスレッドに二重ハンドルを取り付けます。スレッドに軽い重量を載せます。", "スレッドにある程度の張力がかかるまで後退しながらスレッドに向き合ってください。肘を伸ばして手を頭の真上に置きます。これが開始位置になります。", "腕を頭の上に上げたまま後ろ向きに歩きます。ぎくしゃくした動きは避けてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Sled_Overhead_Backward_Walk';
UPDATE exercises SET name = 'スレッドオーバーヘッドトライセップスエクステンション', instructions = '["チェーンまたはロープを使用して、デュアル ハンドルをスレッドに取り付けます。スレッドに適切な荷重を加えます。", "スレッドの反対側を向いて、ラインに張力がかかるまで離れます。両手を頭の上に上げ、手のひらを向かい合わせにして両手を合わせます。肘を曲げた状態で肘を上に向けます。これが開始位置になります。", "肘を通って腕を伸ばします。上腕が上腕三頭筋を分離する位置に留まるようにしてください。", "完全に伸ばしたら、前に踏み出してラインのたるみを取り除きます。安定性を高めるために、足をずらして置くこともできます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Sled_Overhead_Triceps_Extension';
UPDATE exercises SET name = 'そり押し', instructions = '["押しスレッドに希望の重量を積み込みます。", "アスレチックな姿勢を取り、腕を完全に伸ばしてスレッドに寄りかかり、ハンドルを握ります。股関節と膝を伸ばして後方鎖を強化することに重点を置き、できるだけ早くそりを押します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Sled_Push';
UPDATE exercises SET name = 'そりリバースフライ', instructions = '["ロープまたはチェーンで接続されたスレッドに二重ハンドルを取り付けます。スレッドに軽い重量を載せます。", "スレッドにある程度の張力がかかるまで後退しながらスレッドに向き合ってください。両方のハンドルを腰の高さで腕の長さで持ちます。膝を軽く曲げ、胸と頭を上げたままにします。これが開始位置になります。", "肘を曲げずに、ハンドルを上方に引いて離し、ある程度の外回転を伴うリバースフライを実行します。このとき、手のひらは前を向いている必要があります。", "開始位置に戻り、数歩下がってラインのたるみを取り除きます。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Sled_Reverse_Flye';
UPDATE exercises SET name = 'そり列', instructions = '["ロープまたはチェーンで接続されたスレッドに二重ハンドルを取り付けます。スレッドに適切な重量を載せます。スレッドにある程度の張力がかかるまで後退しながらスレッドに向き合ってください。", "両手にハンドルを持ち、膝を軽く曲げ、頭と胸を上げたまま、腕を伸ばした状態から始めます。", "動きを開始するには、肩甲骨を引っ込めるときに肘を曲げ、そりを自分の方に引っ張ります。", "1、2 歩下がってラインに張力を与え、これを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Sled_Row';
UPDATE exercises SET name = 'スレッジハンマースイング', instructions = '["この演習にはタイヤと大ハンマーが必要です。タイヤから約 2 フィート離れたところに、千鳥状の姿勢でタイヤの前に立ちます。大ハンマーを握ります。", "右利きの場合は、左手をハンドルの下部に置き、右手を頭の近くで絞めます。", "そりを持ち上げるとき、右手を頭の方にスライドさせます。スイングダウンすると、右手が滑り落ちて左手とつながります。タイヤにできるだけ強く叩きつけます。タイヤからのハンマーの跳ね返りを制御します。", "反対側でも繰り返します。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Sledgehammer_Swings';
UPDATE exercises SET name = 'スミス インクライン ショルダー レイズ', instructions = '["スミスマシンの下にインクラインベンチを置きます。横になって腕をほぼ完全に伸ばした状態で手の届く高さにバーベルを置きます。必要な重量を選択したら、インクラインベンチに横になり、肩がバーベルの真下に来るようにします。", "肩幅の回内（手のひらを前に出す）グリップを使用して、バーをラックから持ち上げ、肘をわずかに曲げて体の上にまっすぐ持ちます。これが開始位置になります。", "息を吐きながら、腕が完全に伸びるまでバーを持ち上げます。注: 収縮は肩の周囲で感じられるはずです。", "2 回目の一時停止の後、息を吸いながらバーを開始位置に戻します。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Smith_Incline_Shoulder_Raise';
UPDATE exercises SET name = '背中をすくめてスミス・マシン', instructions = '["バーを太ももの高さにして、適切な重量を負荷します。", "バーを後ろにして立ち、肩幅で回内姿勢でバーを握り、ウェイトのフックを外します。頭と胸を上げてまっすぐに立ち、腕を伸ばします。これが開始位置になります。", "肩をまっすぐ上にすくめて動きを開始します。動作中に腕や手首を曲げないでください。", "少し停止した後、ウェイトを開始位置に戻します。", "フックを掛けてウェイトをラックに掛ける前に、必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Behind_the_Back_Shrug';
UPDATE exercises SET name = 'スミスマシンベンチプレス', instructions = '["スミスマシンの下にフラットベンチを置きます。次に、横になって腕をほぼ完全に伸ばしたときに届く高さにバーベルを置きます。必要な体重を選択したら、フラットベンチに横になります。肩の幅よりも広い回内グリップを使用して、ラックからバーのロックを解除し、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の中央にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックにロックして戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Bench_Press';
UPDATE exercises SET name = 'スミス・マシン・ベント・オーバー・ロウ', instructions = '["スミスマシンに取り付けられたバーベルを膝から約2インチ下の高さに設定します。", "膝をわずかに曲げ、腰を曲げて胴体を前に出し、同時に背中が床とほぼ平行になるまでまっすぐに保ちます。ヒント: 頭を上げたままにしてください。", "次に、オーバーハンド (回内) グリップを使用してバーベルを握り、スミス マシン ラックからロックを解除します。次に、腕を床と胴体に対して垂直に伸ばして、それを体の正面にぶら下げます。これが開始位置です。", "胴体を静止させたまま、息を吐きながらバーベルを持ち上げます。肘を体の近くに保ち、ウェイトを保持する以外に前腕に力を入れないでください。一番上の収縮した位置で、背中の筋肉を締めて 1 秒間保持します。", "息を吸いながら、ゆっくりとウェイトを再び開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Bent_Over_Row';
UPDATE exercises SET name = 'スミスマシンカーフレイズ', instructions = '["スミスマシンのバーの下にブロックまたはウェイトプレートを置きます。バーを身長に合わせて最適な位置に設定します。適切な高さを選択し、バーに負荷をかけたら、足の指の付け根でプレートを踏み、バーを肩の後ろに置きます。", "両手を前に向けてバーを持ちます。バーを回転させてラックを外します。これが開始位置になります。", "足の指の付け根を押し出してかかとをできるだけ高く上げ、収縮の頂点でふくらはぎを曲げます。膝は伸ばしたままにしておく必要があります。元に戻り始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げながらゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Calf_Raise';
UPDATE exercises SET name = 'スミスマシン クローズグリップベンチプレス', instructions = '["スミスマシンの下にフラットベンチを置きます。横になって腕をほぼ完全に伸ばした状態で手の届く高さにバーベルを置きます。必要な体重を選択したら、フラットベンチに横になります。肩幅程度の閉じた回内グリップ (手のひらを前に向ける) を使用して、ラックからバーのロックを解除し、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の中央にバーを感じるまでゆっくりと下ろします。ヒント: 上腕三頭筋の働きを最大限に高めるために、通常のベンチプレスとは異なり、肘を常に胴体の近くに保つようにしてください。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、上腕三頭筋を使ってバーを押します。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックにロックして戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Close-Grip_Bench_Press';
UPDATE exercises SET name = 'スミスマシンデクラインプレス', instructions = '["バーが胸の上に来るようにディクラインベンチをラックに置きます。適切な重りを載せてベンチに座ります。", "バーを回転させてラックから外し、腕を完全に伸ばします。背中はわずかにアーチ状になり、肩甲骨が引き込まれます。これが開始位置になります。", "腕を曲げてバーを胸まで下げて動きを始めます。", "少し停止し、腕を伸ばしてウェイトを開始位置に戻します。", "希望の回数繰り返した後、バーを回転させてウェイトを持ち上げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Decline_Press';
UPDATE exercises SET name = 'スミスマシン ハングパワークリーン', instructions = '["バーを膝の高さに置き、適切な重量を加えます。", "肩幅の外側でバーを回内した状態でグリップし、バーをマシンから外します。頭と胸を上げて腕を完全に伸ばします。肩を後ろに下げて肘を向けます。腰が後ろに戻り、ハムストリングスに緊張がかかるはずです。これが開始位置になります。", "腰と膝を力強く伸ばして動きを開始し、バーに向かって加速します。動作のこの部分では腕をまっすぐに保つようにしてください。", "完全に伸ばしたら、腰と膝を曲げてレシーブ位置を下げます。", "この時点で腕を曲げて、肘をバーの周りで回転させて肩でバーを受け取ります。", "腰と膝を伸ばして立った姿勢になり、バーを肩に掛けて動作を完了します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Hang_Power_Clean';
UPDATE exercises SET name = 'スミスマシン ヒップ レイズ', instructions = '["Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine.これが開始位置になります。", "骨盤を回転させ、背骨を曲げて腰をベンチから持ち上げることから動きを開始します。動作中は膝を軽く曲げた状態を維持します。", "少し休憩した後、腰をベンチに戻します。", "必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Hip_Raise';
UPDATE exercises SET name = 'スミスマシンインクラインベンチプレス', instructions = '["スミスマシンの下にインクラインベンチを置きます。横になって腕をほぼ完全に伸ばした状態で手の届く高さにバーベルを置きます。必要な重量を選択したら、インクラインベンチに横になり、胸の上部がバーベルと一直線に並んでいることを確認します。肩の幅より広い回内グリップ (手のひらを前に向ける) を使用して、ラックからバーのロックを解除し、腕をロックした状態でバーを体の上にまっすぐ持ちます。これが開始位置になります。", "息を吸いながら、胸の上部にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。", "完了したら、バーをラックに戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Incline_Bench_Press';
UPDATE exercises SET name = 'スミスマシンレッグプレス', instructions = '["地面から数フィート離れたところにスミス マシン バーを置きます。安全装置の上に置かれていることを確認してください。バーに適切な重量を加えた後、バーの下に横たわります。足の中央をバーの上に置き、膝を胸に引き寄せます。これが開始位置になります。", "足を動かしてバーを上に動かし、腰と膝を伸ばすことから動きを始めます。膝をロックアウトしないでください。", "動作の先頭で、開始位置に戻る前に少し停止します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Leg_Press';
UPDATE exercises SET name = 'スミスマシン ワンアーム アップライト ロー', instructions = '["バーを太ももの高さにして、適切な重量を負荷します。", "バーを幅広に握り、ウェイトのフックを外し、反対側の手をバーから外します。頭と胸を上げてまっすぐに立ち、腕を伸ばす必要があります。これが開始位置になります。", "肘を曲げ、肘を向けた状態で上腕を上げることから動きを始めます。上腕が床と平行になるまで続けます。", "少し停止した後、ウェイトを開始位置に戻します。", "フックを掛けてウェイトをラックに掛ける前に、必要な回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_One-Arm_Upright_Row';
UPDATE exercises SET name = 'スミスマシン オーバーヘッド ショルダー プレス', instructions = '["まず、スミスマシンの下にフラットベンチ (できれば背もたれ付きのベンチ) を置きます。フラットベンチに座ったときに腕をほぼ完全に伸ばしてバーベルに届くような高さにバーベルを置きます。", "正しい高さになったら、鼻の先からバーベルまで一直線になるように、バーベルの少し後ろに座ります。足は動かないでください。手のひらを前に向けてバーベルを掴み、ロックを解除して腕を完全に伸ばすまで持ち上げます。これが開始位置です。", "息を吸いながら、あごの高さになるまでバーベルをゆっくりと下げ始めます。", "次に、息を吐きながら肩を使ってバーベルを持ち上げて開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Overhead_Shoulder_Press';
UPDATE exercises SET name = 'スミスマシンピストルスクワット', instructions = '["まず、自分の身長に最も適した位置にバーを設定します。その下に足を踏み入れ、バーを肩の後ろに置きます。", "手を前に向けてバーを持ち、ロックを解除し、足を伸ばしてラックから持ち上げます。 3", "片足をバーの前約12インチ前に動かします。もう一方の脚を前に伸ばし、地面から離します。常に前を向いて、背骨を中立かわずかにアーチ状に保ちます。これが開始位置になります。", "良い姿勢を維持し、膝と股関節を曲げて体を下げ、柔軟性が許す限り下げます。", "一番下で少し停止し、足のかかとを通って膝と股関節を伸ばして開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Pistol_Squat';
UPDATE exercises SET name = 'スミスマシン リバース カーフレイズ', instructions = '["スミスマシンのバーベルを身長に合わせて調整し、盛り上がったプラットフォームをバーの真下に合わせます。", "足のかかとを台の上に固定し、足の指の付け根を台の上から伸ばして台の上に立ちます。肩幅のスタンスでつま先を前に向けます。", "次に、上記の足の位置を維持しながら肩をバーベルの下に置き、胴体が直立するまで腰と膝を伸ばしてバーベルを押し上げます。膝は軽く曲げたままにしておく必要があります。決してロックされていません。これが開始位置になります。ヒント: 背中のバーベルはバランスを取るためだけにあります。", "息を吐きながら、つま先をできるだけ高く伸ばし、ふくらはぎを曲げて足の指の付け根を上げます。膝が常に動かないように注意してください。いかなるときも曲げてはいけません。元に戻り始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながら、足の指の付け根とつま先を下げて、ゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Reverse_Calf_Raises';
UPDATE exercises SET name = 'スミスマシンスクワット', instructions = '["まず、自分の身長に最も適した高さにバーを設定します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち（手のひらを前に向けます）、ロックを解除し、最初に脚で押しながら同時に胴体をまっすぐにしてラックから持ち上げます。", "足を肩幅の中くらいの幅でスタンスをとり、つま先をわずかに尖らせます。常に頭を上げて、背中もまっすぐに保ちます。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択できます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら足のかかとで床を押してバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Squat';
UPDATE exercises SET name = 'スミスマシンスティフレッグデッドリフト', instructions = '["まず、スミスマシンのバーを太ももの真ん中あたりの高さに設定します。正しい高さを選択し、バーに負荷をかけたら、肩の幅に開いた回内（手のひらを前に向けた）グリップを使用してバーを握ります。かなりの重量を使用する場合は、リストラップが必要になる場合があります。", "背中をまっすぐに保ちながら腕を完全に伸ばしてバーを持ち上げます。胴体を真っ直ぐにして立ち、両足の間隔を肩幅かそれより狭いスタンスにします。膝はわずかに曲がっている必要があります。これが開始位置です。", "膝を固定したまま、背中をまっすぐに保ちながら腰を曲げてバーベルを足の甲の上まで下げます。ハムストリングスが伸びていると感じるまで、床から何かを拾うような気持ちで前に進み続けます。この動きをしながら息を吐きます", "ハムストリングスが伸びていると感じたらすぐに腰と腰を伸ばし、開始位置に戻るまで胴体をまっすぐに上げ始めます。この動きをしながら息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Stiff-Legged_Deadlift';
UPDATE exercises SET name = 'スミスマシンアップライトロウ', instructions = '["まず、スミスマシンのバーを太ももの真ん中あたりの高さに設定します。正しい高さを選択し、バーに負荷をかけたら、肩の幅に開いた回内（手のひらを前に向けた）グリップを使用してバーを握ります。かなりの重量を使用する場合は、リストラップが必要になる場合があります。", "バーベルを持ち上げ、背中をまっすぐにして腕を完全に伸ばします。肘がわずかに曲がっているはずです。これが開始位置です。", "息を吐きながら、横の肩を使ってバーを持ち上げます。バーを上に動かすと、バーが体に近づく必要があります。あごに触れるくらいまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。バーを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "バーをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Machine_Upright_Row';
UPDATE exercises SET name = 'スミス シングルレッグ スプリット スクワット', instructions = '["まず、スミス マシンの 2 ～ 3 フィート後ろにフラット ベンチを置きます。次に、自分の身長に最も適した高さにバーを設定します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち（手のひらを前に向けます）、ロックを解除し、最初に脚で押しながら同時に胴体をまっすぐにしてラックから持ち上げます。", "片足をバーの下に少し前に置き、もう一方の足を後ろに伸ばして足の甲をベンチに置き、脚の位置を決めます。これが開始位置になります", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: エクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながらバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。", "脚を入れ替えて動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Smith_Single-Leg_Split_Squat';
UPDATE exercises SET name = 'スナッチ', instructions = '["両足を肩幅のスタンスで置き、バーベルをつま先と足の残りの部分との接続部の真上に置きます。", "手のひらを下に向けてグリップし、膝を曲げ、背中を平らに保ち、肩幅より広いグリップでバーを握ります。腰を下げて、椅子に座るかのように体を落とします。これが開始位置になります。", "動く台であるかのように足で床を押し始め、同時にバーベルを脚に近づけたまま持ち上げ始めます。", "バーが太ももの真ん中に達したら、脚で床を押し、爆発的な動きで体を完全に伸ばすまで持ち上げます。", "バーを持ち上げるときに、肩をすくめるような動きで肩を後ろに持ち上げます。同時に肘を横に持ち上げて、できるだけ長くバーの上に保ちます。", "非常に素早いながらも力強い動きで、バーベルが制御できる十分な高さまで達したら、体をバーベルの下に入れ、腕をロックしてバーベルを頭上に保持しながらスクワットの姿勢をとります。", "しゃがんだ姿勢から立ち上がり、リフトを終了して動きを終了します。リフト終了時には両足を一直線にし、腕を完全に伸ばしてバーベルを頭上に保持します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Snatch';
UPDATE exercises SET name = 'スナッチバランス', instructions = '["足を引っ張る位置に置き、バーを肩の後ろに置き、手を幅広のスナッチグリップに置きます。", "急激なディップと膝のドライブでバーをポップし、積極的にバーの下をドライブし、足をレシーブポジションに移行します。", "スクワットの底近くで頭上にロックアウトされたバーを受け取ります。胴体は垂直を保ち、脚の間の腰を下げます。", "そのまま最深部まで降り続け、立った位置に戻ります。慎重に重量を下げます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Snatch_Balance';
UPDATE exercises SET name = 'スナッチデッドリフト', instructions = '["スナッチデッドリフトはスナッチの最初の引きを強化します。バーベルをプラットフォームに置き、幅広のスナッチグリップから始めます。足は腰の真下にあり、足を外側に向けます。バーに向かってしゃがみ、頭を前に向けて背中を完全に伸ばした状態に保ちます。", "かかとを踏み込み、腰を上げて動きを開始します。バーが膝を通過するまで、背中の角度は同じに保つ必要があります。", "その時点で、仰向けになりながら腰をバーに通します。逆の動作でバーをプラットフォームに戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Snatch_Deadlift';
UPDATE exercises SET name = 'スナッチプル', instructions = '["バーベルをすねの近くの床に置いて、幅広のスナッチグリップを握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐに保つ必要があります。膝の上まで体重をコントロールしながら動かします。", "次に、2 番目のプルが行われます。これは、プルの加速の主な源です。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。", "体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、体を完全に伸ばし、わずかに後ろに傾く必要があります。完全な伸展は暴力的かつ突然である必要があり、必要以上に伸展を延長しないように注意してください。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Snatch_Pull';
UPDATE exercises SET name = 'スナッチシュラッグ', instructions = '["幅広のグリップで、バーを太ももの真ん中の位置にぶら下げて始めます。フックまたはオーバーハンドグリップを使用できます。背中はまっすぐで、わずかに前傾している必要があります。", "肩を耳に向かってすくめます。通常、このエクササイズにはスナッチよりも重いウェイトを負荷することができますが、実行が遅くなるほどの過負荷は避けてください。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Snatch_Shrug';
UPDATE exercises SET name = 'ブロックから奪い取る', instructions = '["希望の高さのボックスまたはスタンドにバーベルを載せて開始します。バーは幅広に握る必要があります。足は腰の真下にあり、必要に応じて足を外側に向けます。胸を張り、頭を前に向けて腰を下げます。肩はバーのすぐ前にあり、肘は向いている必要があります。これが開始位置になります。", "最初のプルは、かかとの前を通ってバーをボックスから持ち上げることから始めます。", "腰から膝、足首まで伸ばして 2 回目のプルに移行し、できるだけ早くバーを押し上げます。バーは体の近くにある必要があります。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足をレシーブポジションに移動するときに、バーを頭上に持ち上げながら、バーの下に力を入れて自分自身を引きます。必要に応じて、足は腰のすぐ外側に移動する必要があります。体をできるだけ低くし、腕を頭上に完全に伸ばしてバーを受け取ります。", "バーをかかとの前に合わせたまま、頭と胸を上げ、足のかかとを通って立った位置に移動します。慎重に重りを箱に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Snatch_from_Blocks';
UPDATE exercises SET name = 'スピードバンドオーバーヘッドトライセップス', instructions = '["この演習では、バンドを地面に固定します。私たちはインクラインベンチを使用し、ベンチの上に立ってバンドをベースに固定しました。あるいは、バンドの上に立ってこれを実行することもできます。", "まず、バンドを頭の後ろに引っ張り、回内グリップで肘を立てて持ちます。これが開始位置になります。", "この動きを行うには、肘から腕を伸ばして上腕を所定の位置に保ちます。", "一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Speed_Band_Overhead_Triceps';
UPDATE exercises SET name = 'スピードボックススクワット', instructions = '["地面近くにしっかりと固定されたバーにバンドを取り付けます。適切な張力を得るには、バンドを絞める必要がある場合があります。", "この演習では、適切な高さのボックスを使用してください。力は必要ですが、速度が損なわれるほど重くない程度の重量までバーに負荷をかけます。通常、これは 1 回の最大回数の 50 ～ 70% になります。", "バーを背中上部に置き、肩甲骨を引っ込め、背中をアーチ状にし、頭からつま先までしっかりと締めます。これが開始位置になります。", "バーのラックを外し、ボックスの前に位置します。ボックスに座るまで腰を落として座り、制御下で降下し、表面に衝突しないようにします。", "少し停止し、ボックスから爆発し、腰と膝を通って広がります。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Speed_Box_Squat';
UPDATE exercises SET name = 'スピードスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択できます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーを下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足のかかとで床を押しながら、勢いを使わずにできるだけ早くバーを上げ始めます。再び足を伸ばして開始位置に戻ります。注: これらのエクササイズは、完璧なフォームを崩さず、勢いを使わずに、できるだけ早く実行する必要があります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Speed_Squats';
UPDATE exercises SET name = 'スペルキャスター', instructions = '["回内グリップでダンベルを両手に持ちます。足を広くし、腰と膝を伸ばします。これが開始位置になります。", "両方のダンベルを腰の横の片側に引き、胴体を回転させることから動きを始めます。", "腕を真っ直ぐに保ち、ダンベルを地面と平行に保ち、胴体を回転させてウェイトを反対側に振ります。", "セットが完了するまで、一方の側からもう一方の側に回転しながら交互に続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Spell_Caster';
UPDATE exercises SET name = 'スパイダークロール', instructions = '["床にうつ伏せの姿勢から始めます。足を揃えて体をまっすぐにして、手とつま先で体重を支えます。腕は90度に曲げる必要があります。これが開始位置になります。", "片足を地面から上げて動きを開始します。脚を外旋し、膝を肘のほうにできるだけ前に近づけます。", "この脚を開始位置に戻し、反対側でも繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Spider_Crawl';
UPDATE exercises SET name = 'スパイダーカール', instructions = '["まず、説教師用ベンチの通常座っている部分にバーを設定します。バランスが取れて落ちないように、バーベルを適切に調整してください。", "プリーチャー ベンチの前側 (通常腕が置かれている部分) に移動し、胴体と腹部をプリーチャー ベンチの前側に押し付けて 45 度の斜めになるように体勢を整えます。", "足 (特につま先) が床に適切な位置にあることを確認し、プリーチャー ベンチの内側部分にあるパッドの上に上腕を置きます。", "腕を使って、回外グリップ（手のひらを上に向けて）で、肩幅程度に開くか、互いの幅をわずかに近づけてバーベルを掴みます。", "ゆっくりとバーベルを上に持ち上げ始め、息を吐きます。上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとバーベルを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'EZバー' WHERE id = 'Spider_Curl';
UPDATE exercises SET name = '脊椎ストレッチ', instructions = '["背中をまっすぐにし、足を床につけるように椅子に座ります。", "頭の後ろで指を組み、肘を突き出して顎を下げます。", "上半身を片側にできるだけ3回ほどひねります。次に、前傾して胴体をひねって、肘が膝の内側の床に届くようにします。", "直立姿勢に戻り、反対側でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Spinal_Stretch';
UPDATE exercises SET name = 'スプリットクリーン', instructions = '["バーベルをすねの近くの床に置き、脚のすぐ外側をオーバーハンドグリップで握ります。かかとに体重を集中させて腰を下げ、背筋を伸ばし、頭を前に向け、胸を上げ、肩をバーの直前に置きます。これが開始位置になります。", "最初のプルは、かかとを通って膝を伸ばすことから始めます。背中の角度は変えず、腕はまっすぐに保つ必要があります。膝の上まで体重をコントロールしながら動かします。", "次に、クリーンの加速の主な源である 2 番目のプルが始まります。バーが太ももの真ん中の位置に近づいたら、腰まで伸ばし始めます。ジャンプ動作では、腰、膝、足首を伸ばして加速し、スピードを利用してバーを上に動かします。体重を加速するために積極的に腕を引っ張る必要はありません。 2 回目の引っ張りの終わりには、腕は伸ばしたまま、体を完全に伸ばし、わずかに後ろに傾く必要があります。", "完全な伸展が達成されたら、積極的に肩をすくめ、肘を上げて外側に腕を曲げることにより、3番目のプルに移行します。伸展がピークに達したら、バーの下で肘を回転させながら、積極的に体を引き下げます。", "両足を広げてバーを受け取り、片足を前に、片足を後ろに積極的に動かします。バーは伸ばした肩に掛け、手をリラックスさせて喉に軽く触れます。一番下の位置まで下がり続けると、回復に役立ちます。", "かかとを通って体を直立させ、肘を立てたままにして、すぐに回復します。立ち上がるときに両足を揃えます。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Split_Clean';
UPDATE exercises SET name = 'スプリットジャーク', instructions = '["肩の前部に体重をかけて立ち、ディップから始めます。足を腰の真下に置き、腰を後ろに動かさずに膝を曲げます。", "ほんの少しだけ下に下がり、できるだけ力強く方向を反転します。かかとを使ってドライブすると、できるだけ多くのスピードと力が生まれ、バーが肩から離れるときに頭を邪魔にならないように移動してください。足が床から離れたこの瞬間、できるだけ早く足を受け取る位置に置かなければなりません。", "足が積極的にプラットフォームに向かって動いていない短い瞬間に、アスリートがバーを押し上げようとする努力によって足が下に押し下げられます。足は、片足を前に、片足を後ろに、膝を部分的に曲げたスプリットスタンスに移動する必要があります。腕を頭上に伸ばしてバーを受け取ります。", "足を揃えて立った姿勢に戻ります。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Split_Jerk';
UPDATE exercises SET name = 'スプリットジャンプ', instructions = '["膝を曲げて片足を前に出し、後ろの膝が地面にほぼ触れるランジスタンスの姿勢を想定します。", "前膝が足の正中線の上にあることを確認します。", "両脚を伸ばしてできるだけ高くジャンプし、腕を振って揚力を稼ぎます。", "ジャンプするときに両足を揃え、着地時に足を元の位置に戻します。", "開始位置に戻ることで衝撃を吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Split_Jump';
UPDATE exercises SET name = 'スプリットスナッチ', instructions = '["荷重をかけたバーベルを床に置いた状態から始めます。バーはすねに近いか、すねに触れている必要があり、バーを幅広に握る必要があります。足は腰の真下にあり、必要に応じて足を外側に向けます。胸を張り、頭を前に向けて腰を下げます。肩はバーの直前にある必要があります。これが開始位置になります。", "最初のプルは、かかとの前を通ってバーを地面から持ち上げることから始めます。バーが膝を通過するまで、背中の角度は同じに保つ必要があります。", "腰から膝、足首まで伸ばして 2 回目のプルに移行し、できるだけ早くバーを押し上げます。バーは体の近くにある必要があります。伸びがピークになったところで、肩をすくめ、肘を横に曲げます。", "足をレシーブポジションに移動するときに、バーを頭上に持ち上げながら、バーの下に力を入れて自分自身を引きます。両足は、片足を前に、もう片足を後ろに、開脚位置まで力強く動かす必要があります。体をできるだけ低くし、腕を頭上に完全に伸ばしてバーを受け取ります。", "バーをかかとの前に合わせたまま、頭と胸を上げ、足のかかとを通って立ち位置に移動し、両足を揃えます。", "慎重に体重を床に戻します。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Split_Snatch';
UPDATE exercises SET name = 'ダンベルを使ったスプリットスクワット', instructions = '["後ろ足を上げ、前足を前にして千鳥状の姿勢をとります。", "ダンベルを両手に持ち、体の側面にぶら下げます。これが開始位置になります。", "まず降り始め、膝と股関節を曲げて体を下げます。動作中は常に良い姿勢を維持してください。エクササイズを行うときは、前膝を足と一直線に保つようにしてください。", "動きの最後には、かかとを使って膝と股関節を伸ばし、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Split_Squat_with_Dumbbells';
UPDATE exercises SET name = 'スプリットスクワット', instructions = '["立った姿勢でいること。片足を前に、もう片足を後ろに、開脚の姿勢にジャンプし、膝を曲げて腰を少し下げます。", "降りたら、すぐに方向を変え、立ち上がってジャンプし、足の位置を逆にします。各脚で5〜10回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Split_Squats';
UPDATE exercises SET name = 'スクワットジャーク', instructions = '["肩の前部に体重をかけて立ち、ディップから始めます。足を腰の真下に置き、腰を後ろに動かさずに膝を曲げます。ほんの少しだけ下に下がり、できるだけ力強く方向を反転します。かかとを使ってドライブすると、できるだけ多くのスピードと力が生まれ、バーが肩から離れるときに頭を邪魔にならないように移動してください。", "足が床から離れたこの瞬間、できるだけ早く足を受け取る位置に置かなければなりません。足が積極的にプラットフォームに向かって動いていない短い瞬間に、アスリートがバーを押し上げようとする努力によって足が下に押し下げられます。必要に応じて、足は腰のすぐ外側まで力強く動かす必要があります。体を完全にしゃがみ、腕を頭上に完全に伸ばしてバーを受け取ります。", "バーをかかとの前に合わせたまま、頭と胸を上げ、足のかかとを通って立った位置に移動します。慎重に体重を床に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Squat_Jerk';
UPDATE exercises SET name = 'バンドを使ってスクワットする', instructions = '["適切な張力がかかるように、バンドを袖にセットし、バンドペグ、ラック、またはダンベルのいずれかに固定します。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足を広く開き、背中、臀筋、内転筋、ハムストリングスに重点を置きます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。できるだけ腰を後ろに向けて座ってください。理想的には、すねが地面に対して垂直である必要があります。バーの位置が低いと、バーをかかとの上に保つために、より大きな胴体の傾きが必要になります。平行を破るまで続けます。平行とは、股関節のしわが膝の上と一直線になることと定義されます。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きを主導しながら上向きに進みます。頭からつま先まで締め付けを維持しながら、開始位置に戻るまで上向きに進みます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Squat_with_Bands';
UPDATE exercises SET name = '鎖を使ってスクワットする', instructions = '["チェーンをセットアップするには、まずリーダー チェーンをバーのスリーブに巻き付けます。重いチェーンはスナップフックを使用して取り付けてください。ムーブメントの上部でいくつかのリンクが床に残るようにリードチェーンの長さを調整します。", "まずバーの下に足を踏み入れ、肩の後ろにバーを置きます。肩甲骨を寄せて肘を前方に回転させ、肩の上でバーを曲げるようにします。バーをラックから外し、腰にしっかりとしたアーチを作り、元の位置に戻ります。足を広く開き、背中、臀筋、内転筋、ハムストリングスに重点を置きます。頭を前に向けたままにしてください。", "背中、肩、体幹を引き締めて、膝とお尻を前に突き出し、下山を始めます。できるだけ腰を後ろに向けて座ってください。理想的には、すねが地面に対して垂直である必要があります。バーの位置が低いと、バーをかかとの上に保つために、より大きな胴体の傾きが必要になります。平行を破るまで続けます。平行とは、股関節のしわが膝の上と一直線になることと定義されます。", "かかとに体重を掛けたまま足と膝を外側に押し出し、頭で動きを主導しながら上向きに進みます。頭からつま先まで締め付けを維持しながら、開始位置に戻るまで上向きに進みます。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Squat_with_Chains';
UPDATE exercises SET name = 'プレートムーバーを使ったスクワット', instructions = '["まず、ラック上のバ​​ーを肩の高さのすぐ下に設定します。ラックから数フィート離れた地面にウェイト プレートを置きます。バーに負荷がかかったら、バーの下に踏み込み、肩の後ろをバーの上に置きます。", "両手でバーを持ち、最初に足で押してラックからバーを持ち上げ、同時に胴体をまっすぐにします。", "ラックから離れ、つま先をわずかに尖らせたワイドスタンスをとり、片足をウェイトプレートに置きます。常に頭を上げてください。これが開始位置になります。", "膝と腰を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます。", "息を吐きながら足のかかとで床を押し、腰と膝を伸ばしてバーを上げます。", "動きの頂点でサイドステップし、プレートの反対側で両足を揃えます。", "内側の足を使ってウェイトプレートを押し、床の上を今立っていた位置までスライドさせます。", "内側の足をウェイトプレートの上に置き、次の繰り返しではワイドスタンスを採用します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Squat_with_Plate_Movers';
UPDATE exercises SET name = 'スクワット - バンド付き', instructions = '["まず、エクササイズ バンドが体の左側と右側で均等に分割されていることを確認します。これを行うには、手でバンドの両側をつかみ、両足をバンドの中央に置きます。足は肩幅くらいに開いてください。", "バンドを持つときは、両側の高さが同じになるようにしてください。このエクササイズでは、回内グリップ (手のひらを前に向ける) を使用し、バンドのハンドルを顔の横に置く必要があります。これが開始位置です。", "ゆっくりと膝を曲げ始め、息を吐きながら太ももが床と平行になるように脚を下げます。", "息を吐きながら、足のかかとを使って体を開始位置まで押し上げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Squats_-_With_Bands';
UPDATE exercises SET name = '階段のマスター', instructions = '["まず、階段のマスターに足を踏み入れ、メニューから希望のオプションを選択します。手動設定を選択することも、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。", "確立されたリズムで脚を上下に動かし、ペダルを床まで下ろしません。転倒しないようにハンドルをしっかりと握り続けることをお勧めします。ハンドルを使用して心拍数を監視し、適切な強度を維持することができます。", "ステアマスターは利便性が高く、心臓血管にも効果があり、通常は外で走るよりも影響が少ないです。通常、他のカーディオ機器よりもはるかに硬いです。体重 150 ポンドの人は通常、30 分で 300 カロリー以上を消費しますが、ウォーキングでは約 175 カロリーを消費します。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Stairmaster';
UPDATE exercises SET name = 'スタンディングオルタネイトダンベルプレス', instructions = '["両手にダンベルを持って立ちます。手のひらを前に向け、肘を向けてダンベルを肩まで上げます。これが開始位置になります。", "片方の腕を伸ばしてダンベルをまっすぐ上に押し、反対側の手を所定の位置に保ちます。動作中に体重を傾けたり、急激に持ち上げたりしないでください。", "少し停止した後、ウェイトを開始位置に戻します。", "反対側でも繰り返し、腕を交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Alternating_Dumbbell_Press';
UPDATE exercises SET name = 'スタンディングバーベルカーフレイズ', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。正しい高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、バーを肩の後ろ（首の少し下）に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。膝は軽く曲げたままにしておく必要があります。決してロックされていません。これが開始位置になります。ヒント: 動きの範囲を広げるために、足の指の付け根を木製のブロックの上に置くこともできますが、このオプションにはより多くのバランスと頑丈なブロックが必要であるため注意してください。", "息を吐きながらかかとを上げ、足首をできるだけ高く伸ばし、ふくらはぎを曲げます。膝が常に動かないように注意してください。いかなるときも曲げてはいけません。下がり始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げ、ふくらはぎが伸びるまで足首を曲げてゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Barbell_Calf_Raise';
UPDATE exercises SET name = '首の後ろでスタンディングバーベルプレス', instructions = '["このエクササイズは、バーを拾いやすいようにスクワットラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。このエクササイズを行うときは、背中をまっすぐに保つ必要があります。これが開始位置になります。", "息を吐きながら腕を完全に伸ばしてバーベルを頭上に持ち上げます。", "収縮を 1 秒間保持し、息を吸いながらバーベルを開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Barbell_Press_Behind_Neck';
UPDATE exercises SET name = 'スタンディングベントオーバーワンアームダンベルトライセプスエクステンション', instructions = '["片手にダンベルを持ち、手のひらを胴体に向け、膝をわずかに曲げ、腰を曲げて胴体を前に出します。同時に、背中が床とほぼ平行になるまでまっすぐに保ちます。必ず頭を上げてください。", "上腕は胴体の近くで床と平行にし、手で体重を支えるときは前腕が床の方向を向くようにします。ヒント: 前腕と上腕の間には 90 度の角度が必要です。これが開始位置です。", "上腕を固定したまま、前腕が床と平行になり腕全体が伸びるまで、息を吐きながら上腕三頭筋を使ってウェイトを持ち上げます。他の多くの腕のエクササイズと同様、前腕のみが動きます。", "上部で 2 回目の収縮を行った後、息を吸いながらゆっくりとダンベルを開始位置に下げます。", "この動作を規定回数繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = 'スタンディングベントオーバーツーアームダンベルトライセップスエクステンション', instructions = '["両手にダンベルを持ち、手のひらを胴体に向けて、膝をわずかに曲げ、腰を曲げて胴体を前に出します。同時に、背中を床とほぼ平行になるまでまっすぐに保ちます。必ず頭を上げてください。上腕は胴体の近くで床と平行にし、手でウェイトを握るときは前腕が床の方向を向くようにします。ヒント: 前腕と上腕の間の角度は 90 度である必要があります。これが開始位置です。", "上腕を固定したまま、前腕が床と平行になり腕全体が伸びるまで、息を吐きながら上腕三頭筋を使ってウェイトを持ち上げます。他の多くの腕のエクササイズと同様、前腕のみが動きます。", "上部で 2 回目の収縮を行った後、息を吸いながらダンベルをゆっくりと元の位置に下げます。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = '立ち上腕二頭筋ケーブルカール', instructions = '["低いプーリーに取り付けられたケーブル カール バーを持ちながら、上体を直立させて立ちます。ケーブルバーを肩幅で握り、肘を胴体の近くに保ちます。手のひらは上を向く必要があります（回外グリップ）。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトをカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。筋肉を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながらゆっくりとカールバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Biceps_Cable_Curl';
UPDATE exercises SET name = '立って上腕二頭筋のストレッチ', instructions = '["手のひらを合わせて手を後ろで組み、腕をまっすぐにして手のひらが下を向くように回転させます。", "腕を上げて、上腕二頭筋が伸びていると感じるまで保持します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Standing_Biceps_Stretch';
UPDATE exercises SET name = 'スタンディングブラッドフォードプレス', instructions = '["負荷がかかったバーをラックの肩の高さに置きます。肩の幅で回内グリップを持ち、バーを肩の前にかけることから始めます。これが開始位置です。", "肘を伸ばしてバーを頭上に押し上げることでリフトを開始します。体重を頭の後ろに移動するときに肘をロックアウトしないようにします。", "肘が直角になるまでバーを頭の後ろまで下げます。", "肘を伸ばしてバーを頭の上に持ち上げます", "バーを開始位置まで下げます。", "推奨回数の繰り返しが完了するまで、この方法を交互に繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Bradford_Press';
UPDATE exercises SET name = 'スタンディングケーブルチェストプレス', instructions = '["デュアルプーリーを胸の高さに合わせて配置し、適切な重量を選択します。ケーブルの前に 1 ～ 2 フィート立ち、両手に 1 本ずつ持ちます。安定性を高めるためにスタンスをずらすことができます。", "肩甲骨を寄せて上腕を90度の角度に置きます。これが開始位置になります。", "体の残りの部分を静止させたまま、肘を通ってハンドルを前方に押し、ハンドルを前に引き寄せます。", "動作の先頭で一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Cable_Chest_Press';
UPDATE exercises SET name = 'スタンディングケーブルリフト', instructions = '["タワーの標準ハンドルを接続し、ケーブルをプーリーの最も低い位置に移動します。", "ケーブルに体を向けて片手でハンドルを掴み、タワーから離れます。ケーブルに重りの張力がかかる状態で、滑車から腕の長さほど離れた位置にいる必要があります。伸ばした腕がケーブルと一直線になるようにします。", "足を肩幅に開き、しゃがみ、両手でハンドルを握ります。腕は完全に伸ばしたままにしておく必要があります。", "1 回の動作でハンドルを上に引き上げ、腕を完全に伸ばして頭の上に置きます。", "背中を真っすぐに保ち、腕を体に近づけながら、後ろ足を回転させて脚をまっすぐにして、あらゆる範囲の動きを実現します。", "腕を引っ込めてから体を引っ込めます。ゆっくりと制御された方法でニュートラル位置に戻ります。", "失敗まで繰り返す。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Cable_Lift';
UPDATE exercises SET name = 'スタンディングケーブルウッドチョップ', instructions = '["標準ハンドルをタワーに接続し、ケーブルをプーリーの最も高い位置に移動します。", "ケーブルに体を向けて片手でハンドルを掴み、タワーから離れます。ケーブルに重りの張力がかかる状態で、滑車から腕の長さほど離れた位置にいる必要があります。伸ばした腕がケーブルと一直線になるようにします。", "足を肩幅に開き、もう片方の手で上に伸ばし、両手でハンドルを握ります。腕は完全に伸ばしたままにしておく必要があります。", "胴体を回転させながら、一度の動作でハンドルを体全体に沿って前膝まで引き下げます。", "背中と腕をまっすぐにして体幹を引き締めながら、後ろ足を回転させて膝を曲げて、あらゆる可動範囲を確保します。", "姿勢を維持し、腕をまっすぐに伸ばします。ゆっくりと制御された方法でニュートラル位置に戻ります。", "失敗まで繰り返す。", "次に、位置を変えて、反対側でも同じ一連の動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Cable_Wood_Chop';
UPDATE exercises SET name = 'スタンディングカーフレイズ', instructions = '["カーフレイズ マシンのパッド入りレバーを身長に合わせて調整します。", "付属のパッドの下に肩を置き、つま先を前に向けます（または、この章の冒頭で説明した他の 2 つの位置のいずれかを使用します）。足の指の付け根をふくらはぎブロックの上に固定し、かかとをふくらはぎから外します。胴体が直立するまで腰と膝を伸ばしてレバーを押し上げます。膝は軽く曲げたままにしておく必要があります。決してロックされていません。この章の冒頭で説明したように、つま先は前方、外側、または内側を向いている必要があります。これが開始位置になります。", "息を吐きながらかかとを上げ、足首をできるだけ高く伸ばし、ふくらはぎを曲げます。膝が常に動かないように注意してください。いかなるときも曲げてはいけません。下がり始める前に、収縮した位置を 1 秒間保持します。", "息を吸いながらかかとを下げ、ふくらはぎが伸びるまで足首を曲げてゆっくりと元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Standing_Calf_Raises';
UPDATE exercises SET name = 'スタンディングコンセントレーションカール', instructions = '["作業用の手にダンベルを持ち、前かがみになります。作業中の腕は、肘を外側に向けて地面に対して垂直に下げます。これが開始位置になります。", "肘を曲げてウェイトをカールさせ、上腕を静止させます。繰り返しの一番上で、上腕二頭筋を曲げて一時停止します。", "ダンベルを開始位置に下げます。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Concentration_Curl';
UPDATE exercises SET name = 'スタンディングダンベルカーフレイズ', instructions = '["2 つのダンベルを両手に持ち、胴体を直立させて脇に置きます。足の指の付け根を丈夫で安定した木の板（高さ約2～3インチ）の上に置き、かかとを伸ばして床に触れます。これが開始位置になります。", "つま先を真っ直ぐ（すべての部分を均等に当てるため）、内側（頭の外側を強調する場合）または外側（頭の内側を強調する場合）のいずれかに向けて、ふくらはぎを収縮させて息を吐きながらかかとを床から持ち上げます。上部の収縮を 1 秒間保持します。", "息を吸いながら、かかとをゆっくりと下げて開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Calf_Raise';
UPDATE exercises SET name = 'スタンディングダンベルプレス', instructions = '["足を肩幅に開いて立ち、両手にダンベルを持ちます。ダンベルを頭の高さまで上げ、肘を外側に約90度開きます。これが開始位置になります。", "足を動かしたり後ろに反ったりしたりせずに厳密なテクニックを維持し、肘を通って伸ばしてウェイトをまとめて頭の真上に持ち上げます。", "一時停止し、ゆっくりと体重を開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Press';
UPDATE exercises SET name = 'スタンディングダンベルリバースカール', instructions = '["まず、両手にダンベルを持ち、回内グリップを使用して（手のひらを下に向けて）まっすぐに立ちます。両足を肩幅に開きながら、腕を完全に伸ばします。これが開始位置です。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトをカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。筋肉を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながら、ゆっくりとダンベルを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Reverse_Curl';
UPDATE exercises SET name = 'スタンディングダンベルストレートアームフロントデルト頭上挙上', instructions = '["ダンベルを太ももの前に持ち、手のひらを太ももに向けます。", "腕をまっすぐに保ち、肘をわずかに曲げますが、ロックしたままにします。これが開始位置になります。", "息を吐きながら、ダンベルを腕の長さ分の頭上まで半円を描くように持ち上げます。", "息を吸いながら同じ軌道でゆっくりと開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head';
UPDATE exercises SET name = 'スタンディングダンベルトライセップスエクステンション', instructions = '["まず、ダンベルを両手に持って立ちます。足の間隔は肩幅くらいにする必要があります。ゆっくりと両手を使ってダンベルをつかみ、両腕が完全に伸びるまで頭の上に持ち上げます。", "抵抗は手のひらの上に置き、親指で抵抗を囲みます。手のひらは天井に向けて上に向けます。これが開始位置になります。", "肘を床に垂直にして上腕を頭の近くに保ち、前腕が上腕二頭筋に触れるまで頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさないようにし、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってダンベルを上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = 'スタンディングダンベルアップライトロウ', instructions = '["肩の幅よりわずかに狭い回内（手のひらを前に向けた）グリップで両手にダンベルを持ちます。ダンベルは太ももの上に置く必要があります。腕は肘を少し曲げて伸ばし、背中はまっすぐにします。これが開始位置になります。", "息を吐きながら、横の肩を使ってダンベルを持ち上げます。ダンベルを体に近づけるときはダンベルを体に近づけ、肘を使って動きを推進する必要があります。あごに触れそうになるまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。ダンベルを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "ダンベルをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Dumbbell_Upright_Row';
UPDATE exercises SET name = '立位で大腿四頭筋ストレッチ', instructions = '["まず、ベンチや段差から約 2 ～ 3 フィート離れたところに背中を向けて立ちます。", "片足を後ろに持ち上げ、足の甲または足の指の付け根のどちらか最も快適な方のステップに足を置きます。", "支えている膝をわずかに曲げたままにし、膝がつま先よりも外側に出ないようにしてください。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Standing_Elevated_Quad_Stretch';
UPDATE exercises SET name = '立ってフロントバーベルを頭上に上げる', instructions = '["まず、バーベルを手に持ってまっすぐに立ちます。バーは手のひらを下に向け、肩幅よりも狭い間隔でバーを握る必要があります。", "足は肩幅くらいに開いてください。肘は少し曲がっているはずです。これが開始位置です。", "息を吐きながら、バーベルが頭の真上に来るまで持ち上げます。各繰り返しを行うときは、肘をわずかに曲げたままにしてください。", "収縮を感じたら、息を吸いながらバーベルを元の位置まで下げ始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Front_Barbell_Raise_Over_Head';
UPDATE exercises SET name = '立った状態での腓腹筋ふくらはぎのストレッチ', instructions = '["膝を伸ばした状態で右かかとを段差の上に置き、前傾して右手で右足のつま先を掴みます。左膝をわずかに曲げ、背中をまっすぐにする必要があります。", "左脚で体重を支え、左手を左太腿に置きます。", "ふくらはぎが伸びるのを感じるまで、右のつま先を膝に向かって引っ張ります。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Gastrocnemius_Calf_Stretch';
UPDATE exercises SET name = '立ってハムストリングとふくらはぎのストレッチ', instructions = '["ベルト、バンド、またはロープを片足に巻き付けること。立った状態で、その足を前に出します。", "前の脚をまっすぐに保ちながら、後ろ脚を曲げます。次に、前足のつま先を地面から上げ、前傾します。", "ベルトを使用して足の甲を引っ張ると、ふくらはぎのストレッチが強化されます。 10〜20秒間保持し、もう一方の足でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'その他' WHERE id = 'Standing_Hamstring_and_Calf_Stretch';
UPDATE exercises SET name = 'スタンディングヒップサークル', instructions = '["垂直の支えをつかんで片足で立ち始めます。", "サポートされていない膝を90度まで上げます。これが開始位置になります。", "股関節をできるだけ開き、膝で大きな円を描くようにします。", "この動きをゆっくりと何回か繰り返し、反対側も同様に行います。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Standing_Hip_Circles';
UPDATE exercises SET name = '立っている股関節屈筋', instructions = '["背筋を垂直にしてまっすぐに立ち、左足を右足よりも少し前に出します。", "両膝を曲げ、右腰を前に押しながら後ろのかかとを床から持ち上げます。ただし、股関節屈筋を緩めながら同時に立つのは難しいため、この位置では徹底的に深くストレッチすることはできません。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Hip_Flexors';
UPDATE exercises SET name = 'スタンディング上腕二頭筋内側カール', instructions = '["両手にダンベルを持ち、腕を伸ばした状態で立ちます。肘は胴体の近くにある必要があります。足は肩幅くらいの幅にする必要があります。", "手のひらが中立の位置で内側を向くように回転させます。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトを丸めます。ウェイトを完全に上げたときにグリップが回外（手のひらが上を向く）になるように手首を回転する必要があります。", "前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。ヒント: 前腕を三角筋外側と一直線に保ちます。", "上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "息を吸いながらゆっくりとダンベルを開始位置に戻し始めます。重量を下げるときに手首を回転させてニュートラルなグリップに戻すことを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Inner-Biceps_Curl';
UPDATE exercises SET name = '立って横方向のストレッチ', instructions = '["膝をわずかに曲げて、腰より少し広いスタンスでスタンスを取ります。", "右手を右腰に置き、背骨を支えます。", "左腕を垂直に上げ、左手を頭の後ろに置きます。上体を右に傾けながら、その位置を保ちます。", "体重を両足に均等に分散させてください（左腰に寄りかからないようにしてください）。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Lateral_Stretch';
UPDATE exercises SET name = 'スタンディングレッグカール', instructions = '["身長に合わせてマシンのレバーを調整し、胴体を腰で前方に向けて約 30 ～ 45 度曲げて横になり (ハムストリングスを鍛えるには角度を付けた方が好ましいため)、レバーのパッドを右脚の後ろ (ふくらはぎの数インチ下) に置き、右脚の前部をマシンのパッドの上に置きます。", "胴体を前に曲げたまま、脚が完全に伸びていることを確認して、マシンのサイドハンドルを握ります。つま先をまっすぐに置きます。これが開始位置になります。", "息を吐きながら、上脚をパッドから持ち上げずに、右脚をできるだけ上に丸めます。完全に収縮した位置に到達したら、その状態を 1 秒間保持します。", "息を吸いながら足を元の位置に戻します。推奨回数だけ繰り返します。", "今度は左脚でも同じエクササイズを実行します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Standing_Leg_Curl';
UPDATE exercises SET name = '立ち幅跳び', instructions = '["このドリルは、砂やその他の柔らかい着地面で行うのが最適です。距離を測定できることを確認してください。足を肩幅に開き、部分的なスクワットスタンスで立ちます。", "腕を大きく振り、足を反対方向に動かすことを利用して、できるだけ遠くまで前方にジャンプします。", "足を前に出して着地し、足をできるだけ遠くまで伸ばしてください。", "着陸点から開始点までの距離を測定し、結果を追跡します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Standing_Long_Jump';
UPDATE exercises SET name = 'スタンディングロープーリーデルトイドレイズ', instructions = '["まず、低い滑車列の右側に立ってください。左手を使って体を横切り、回内グリップ (手のひらを下に向けた状態) で低いプーリーに取り付けられた 1 つのハンドルを掴みます。腕を前に置きます。サポートとバランスを良くするために、右手でマシンを掴む必要があります。", "背中がまっすぐで、足が肩幅に開いていることを確認してください。これが開始位置です。", "左手を使い始め、息を吐きながら肩の高さまで体を外側に向けます。", "上部が収縮するのを少し感じ、息を吸いながらハンドルをゆっくりと元の開始位置まで下げ始めます。", "推奨回数だけ繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Low-Pulley_Deltoid_Raise';
UPDATE exercises SET name = 'スタンディングロープーリーワンアームトライセップスエクステンション', instructions = '["左腕で低プーリーマシンの横にあるシングルハンドルをつかみます。腕を完全に伸ばした状態でハンドルを体の横に保ち、機械から背を向けます。次に、両手を使用して、手のひらを前に向けて単一のハンドルを頭の真上に持ち上げます。上腕を完全に垂直（床に対して垂直）に保ち、右手を左肘の上に置いて安定させます。これが開始位置です。", "上腕を頭の近く（肘を内側）に保ち、床に対して垂直に保ち、前腕が上腕二頭筋に触れるまで頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさないようにし、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってシングルハンドルを上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Low-Pulley_One-Arm_Triceps_Extension';
UPDATE exercises SET name = 'スタンディングミリタリープレス', instructions = '["まず胸の高さほどのバーベルをスクワットラックに置きます。ウェイトを選択したら、回内（手のひらを前に向けた）グリップを使用してバーベルを握ります。必ず肩幅より広めにバーを握り、お互いに離してください。", "膝を軽く曲げ、バーベルを鎖骨の上に置きます。バーベルを胸の上に置いたまま持ち上げます。一歩下がって、足を肩幅に広げて配置します。", "適切なグリップ長でバーベルを持ち上げたら、腕をロックしてバーベルを頭の上まで持ち上げます。肩の高さくらいで頭の少し前に持ちます。これが開始位置です。", "息を吸いながらゆっくりとバーを鎖骨まで下げます。", "息を吐きながらバーを元の位置まで持ち上げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Military_Press';
UPDATE exercises SET name = 'スタンディングオリンピックプレートハンドスクイーズ', instructions = '["まず、中立的なグリップ (手のひらを内側に向ける) を使用して、両手の腕の長さの尾根の近くでウェイト プレートを持ちながら、まっすぐに立ちます。両足は肩幅程度に開く必要があります。これが開始位置になります。", "指がほぼ伸びた状態でまだ重りを保持できるまでプレートを下げます。息を吸いながらプレートを下げます。", "手を閉じて息を吐きながら、プレートを元の位置に戻します。", "プログラムで規定されている推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Standing_Olympic_Plate_Hand_Squeeze';
UPDATE exercises SET name = 'スタンディングワンアームケーブルカール', instructions = '["まず、低プーリーマシンの横にあるシングルハンドルを掴みます。腕が重量を支えることができるように、マシンから十分に離れていることを確認してください。", "上腕が動かず、肘を内側に置き、手のひらを前に向けて床に対して垂直になるようにしてください。持ち上げていない側の腕が腰を掴んでいるはずです。そうすることでバランスを保つことができます。", "息を吐きながら前腕が上腕二頭筋に触れるまで上腕を動かさないようにしながら、シングルハンドルをゆっくりと上向きにカールさせ始めます。ヒント: 前腕のみを動かします。", "上腕二頭筋を締めながら収縮位置を保持し、息を吸いながらシングルハンドルを開始位置まで下げます。", "推奨回数だけ繰り返します。", "このエクササイズを実行しながら腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_One-Arm_Cable_Curl';
UPDATE exercises SET name = 'インクラインベンチ上でスタンディングワンアームダンベルカール', instructions = '["まるで誰かを監視するかのようにインクラインベンチの後ろ側に立ちます。ダンベルを片手に持ち、グリップを回外（手のひらを上）にしてインクラインベンチの上に置きます。", "持ち上げていない方の手をインクラインベンチの隅または側面に置きます。胸は傾斜の上部に押し付けられ、足は広いスタンスで床に押し付けられる必要があります。これが開始位置です。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ダンベルを上向きにカールさせます。前腕だけを動かす必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持します。", "息を吸いながらゆっくりとダンベルを開始位置に戻し始めます。", "推奨回数だけ繰り返します。", "このエクササイズを実行しながら腕を切り替えます。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench';
UPDATE exercises SET name = 'スタンディングワンアームダンベルトライセップスエクステンション', instructions = '["まず、片手にダンベルを持って立ちます。足の間隔は肩幅くらいにする必要があります。次に、ダンベルを頭の上に置き、腕を完全に伸ばします。ヒント: 手の小指は天井を向き、手のひらは前を向く必要があります。ダンベルは頭の上にあるはずです。", "これが開始位置になります。", "上腕を頭の近く（肘を内側）に保ち、床に対して垂直に保ち、前腕が上腕二頭筋に触れるまで、頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさず、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってダンベルを上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_One-Arm_Dumbbell_Triceps_Extension';
UPDATE exercises SET name = 'スタンディング・オーバーヘッド・バーベル・トライセプス・エクステンション', instructions = '["まず、バーベルまたは e-z バーを持ち、両手を肩幅よりも近づけて回内グリップ (手のひらを前に向ける) で持ち立ち、互いの幅を広げます。足は肩幅程度に開く必要があります。", "次に、腕が完全に伸びるまでバーベルを頭の上に上げます。肘を内側に置いておきます。これが開始位置になります。", "上腕を頭の近くに保ち、肘を床に対して垂直に保ち、前腕が上腕二頭筋に触れるまで頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさないようにし、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってバーベルを上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Overhead_Barbell_Triceps_Extension';
UPDATE exercises SET name = 'スタンディングパームインワンアームダンベルプレス', instructions = '["まずダンベルを片手に持ち、ニュートラルグリップで腕を横に完全に伸ばします。もう片方の腕を使ってインクラインベンチにつかまり、バランスを保ちます。", "足は肩幅くらいに開いてください。次に、腕と90度の角度ができるまでダンベルをゆっくりと持ち上げます。注: 前腕は床に対して垂直である必要があります。エクササイズ全体を通して、ニュートラルなグリップを維持し続けます。", "腕が完全に伸びるまでゆっくりとダンベルを持ち上げます。これが開始位置です。", "息を吸いながら、腕が再び90度の角度になるまで体重を下げます。", "収縮を少し感じてから、息を吐きながら体重を開始位置に向かって持ち上げます。エクササイズ中はバランスを保つためにインクラインベンチにつかまり、足の位置を保つことを忘れないでください。", "推奨回数だけ繰り返します。", "腕を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Palm-In_One-Arm_Dumbbell_Press';
UPDATE exercises SET name = 'スタンディングパームズインダンベルプレス', instructions = '["まず、両手にダンベルを持ち、ニュートラルグリップを使用して腕を横に完全に伸ばします。足は肩幅くらいに開いてください。次に、腕の角度が 90 度になるまでダンベルをゆっくりと持ち上げます。注: 前腕は床に対して垂直である必要があります。これが開始位置です。", "エクササイズ全体を通して、ニュートラルなグリップを維持し続けます。腕が完全に伸びるまでゆっくりとダンベルを持ち上げます。", "息を吸いながら、腕が再び90度の角度になるまでウェイトを下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Standing_Palms-In_Dumbbell_Press';
UPDATE exercises SET name = '手のひらを上にして立ち、バックの後ろでバーベルをリストカール', instructions = '["まずは真っ直ぐに立って、腕を伸ばした長さでお尻の後ろでバーベルを持ち、回内グリップを使用し（手のひらは臀筋から後ろを向きます）、両手を肩幅に開きます。", "両足を肩幅に開きながら、まっすぐ前を向いている必要があります。これが開始位置です。", "息を吐きながら、手首を天井に向かって半円を描くように曲げて、バーベルをゆっくりと上げます。注: このエクササイズでは手首だけを動かす必要があります。", "収縮を 1 秒間保持し、息を吸いながらバーベルを開始位置まで下げます。", "推奨回数だけ繰り返します。", "終了したら、膝を曲げてバーベルをスクワットラックまたは床まで下げます。ヒント: スクワットラックから拾うか、パートナーに手渡してもらうのが最も簡単です。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl';
UPDATE exercises SET name = '立った状態での骨盤の傾き', instructions = '["足を腰の幅に離して始めます。", "膝を軽く曲げて柔らかく弾力のある状態にします。", "このストレッチで尾骨を前方に保持する前に、骨盤を前後に数回動かしてみるとよいでしょう。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Pelvic_Tilt';
UPDATE exercises SET name = 'スタンディングロープクランチ', instructions = '["高滑車にロープを取り付け、適切な重さを選択します。", "ケーブルタワーに背を向けて立ちます。両手でロープを肩にかけ、胸の上部に当てます。これが開始位置になります。", "脊椎を曲げ、体重を可能な限り下げてこの動きを実行します。", "開始位置に戻る前に、収縮のピークをしばらく保持します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Standing_Rope_Crunch';
UPDATE exercises SET name = '立ってヒラメ筋とアキレス腱のストレッチ', instructions = '["足を腰の幅に広げて立ち、片方の足をもう一方の足の前に少し出します。", "後ろのかかとを床につけたまま、両膝を曲げます。サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Soleus_And_Achilles_Stretch';
UPDATE exercises SET name = 'スタンディング・トゥ・タッチ', instructions = '["前後にスペースを取って立ちます。", "リラックスして上半身を前に垂れるまで、脚をまっすぐに保ちながら腰を曲げます。腕と手を自然に垂らします。 10 ～ 20 秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Standing_Toe_Touches';
UPDATE exercises SET name = 'スタンディングタオル上腕三頭筋エクステンション', instructions = '["まず、両腕を頭の上に完全に伸ばして立ち、タオルの一端を両手で持ちます。肘を内側に置き、腕を床に対して垂直にし、手のひらを向かい合わせ、足を肩幅に開きます。これが開始位置です。", "次に、パートナーがタオルの反対側を握って抵抗を加えることができるように、パートナーとコミュニケーションを取ります。上腕を頭の近く（肘を内側）に保ち、床に対して垂直に保ち、前腕が上腕二頭筋に触れるまで頭の後ろで半円を描くように抵抗を下げます。ヒント: 上腕は動かさないようにし、前腕だけを動かします。このステップを実行するときに息を吸います。", "上腕三頭筋を使ってタオルを持ち上げて開始位置に戻ります。このステップを実行するときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Standing_Towel_Triceps_Extension';
UPDATE exercises SET name = '立ち両腕オーバーヘッドスロー', instructions = '["両手にメディシンボールを持ち、足を肩幅に開いて立ちます。まず、膝を軽く曲げて後ろにもたれながら、頭の後ろの奥深くにあるメディシン ボールに手を伸ばします。", "股関節を曲げて体全体を使って、ボールを前方に激しく投げます。", "メディシン ボールはパートナーや壁に投げて、跳ね返ってきたボールを受け取ることができます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Standing_Two-Arm_Overhead_Throw';
UPDATE exercises SET name = 'スタージャンプ', instructions = '["足を肩幅に開き、腕を体に近づけてリラックスした姿勢から始めます。", "動きを開始するには、半分しゃがみ、できるだけ高く爆発して元に戻ります。体全体を完全に伸ばし、脚と腕を体から離します。", "着地したら、手足を元に戻し、脚を通して衝撃を吸収します。"]'::jsonb, category = 'プライオメトリクス', equipment = '自重' WHERE id = 'Star_Jump';
UPDATE exercises SET name = 'ニーレイズでステップアップ', instructions = '["適切な高さの箱またはベンチに向かって両足を揃えて立ちます。これが開始位置になります。", "左足をベンチの上に置き、ステップアップして動作を開始します。前脚の腰と膝を伸ばしてボックスの上に立ちます。左足でボックスの上に立ち、右膝と股関節を曲げて膝をできるだけ高くします。", "この動作を逆にしてボックスから降り、反対側の足でも同じ手順を繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Step-up_with_Knee_Raise';
UPDATE exercises SET name = 'ステップミル', instructions = '["まず、ステップミルに乗り、メニューから希望のオプションを選択します。手動設定を選択することも、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。階段を上る際はつまずかないように注意してください。転倒しないようにハンドルをしっかりと握り続けることをお勧めします。", "ステップミルは利便性が高く、心臓血管への効果があり、通常、屋外でのランニングよりも影響が少なく、同じようなカロリー消費率を提供します。通常、他のカーディオ機器よりもはるかに硬いです。体重 150 ポンドの人は通常、30 分で 300 カロリー以上を消費しますが、ウォーキングでは約 175 カロリーを消費します。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Step_Mill';
UPDATE exercises SET name = 'スティフレッグドバーベルデッドリフト', instructions = '["オーバーハンド グリップ (手のひらを下に向けて) を使用してバーを握ります。かなりの重量を使用する場合は、リストラップが必要になる場合があります。", "胴体を真っ直ぐにして立ち、両足の間隔を肩幅かそれより狭いスタンスにします。膝はわずかに曲がっている必要があります。これが開始位置です。", "膝を動かさないようにし、背中をまっすぐに保ちながら腰を曲げてバーベルを足の甲の上まで下げます。ハムストリングスが伸びていると感じるまで、床から何かを拾うような気持ちで前に進み続けます。この動きをしながら息を吸います。", "開始位置に戻るまで腰を伸ばして、胴体を再びまっすぐに上げ始めます。この動きをしながら息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Stiff-Legged_Barbell_Deadlift';
UPDATE exercises SET name = 'スティッフレッグドダンベルデッドリフト', instructions = '["ダンベルをいくつかつかみ、腕を伸ばして体の横に置きます。", "胴体を真っ直ぐにして立ち、両足の間隔を肩幅かそれより狭いスタンスにします。膝はわずかに曲がっている必要があります。これが開始位置です。", "膝を固定したまま、背中をまっすぐに保ちながら腰を曲げてダンベルを足の甲の上まで下げます。ハムストリングスが伸びていると感じるまで、床から何かを拾うような気持ちで前に進み続けます。この動きをしながら息を吐きます", "開始位置に戻るまで腰と腰を伸ばして、胴体を再びまっすぐに上げ始めます。この動きをしながら息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Stiff-Legged_Dumbbell_Deadlift';
UPDATE exercises SET name = 'スティッフレッグバーベル おはようございます', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、肩幅の中程度のスタンスで脚を置きます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。", "脚を動かさずに、息を吸いながら腰を曲げて胴体を前に動かします。床と平行になるまで上体を下げます。", "息を吐きながら上半身を上げて開始位置に戻し、バーを上げ始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Stiff_Leg_Barbell_Good_Morning';
UPDATE exercises SET name = '胃の真空', instructions = '["まず、足を肩幅に広げてまっすぐに立ちます。手を腰に置きます。これが開始位置です。", "次に、できるだけ多くの空気をゆっくりと吸い込み、お腹をできるだけ凹ませてこの位置を維持しながら、できるだけ多くの空気を吐き始めます。おへそが背骨に触れているところをイメージしてみてください。", "1回の等尺性収縮は約20秒です。 20 秒間静止している間、普通に呼吸してみてください。次に、息を吸いながらお腹を元の位置に戻します。", "このエクササイズを練習したら、このエクササイズを 20 秒以上行うようにしてください。ヒント: 最長 40 ～ 60 秒まで作業を続けることができます。", "推奨セット数まで繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Stomach_Vacuum';
UPDATE exercises SET name = 'ストレートアーム ダンベル プルオーバー', instructions = '["ダンベルを平らなベンチの上に立って置きます。", "ダンベルがベンチの上部にしっかりと配置されていることを確認し、肩だけを表面に置き、ベンチに対して垂直に寝ます（十字架を作るように胴体を横切るようにします）。腰をベンチの下に置き、足を曲げて足を床にしっかりとつけます。頭もベンチから外れるだろう。", "ダンベルを両手で持ち、腕を伸ばして胸の上にまっすぐ持ちます。両手のひらでダンベルの側面の一方の下側を押す必要があります。これが開始位置になります。\n注意: このエクササイズに使用するダンベルがしっかりと固定されていることを常に確認してください。プレートが緩んだ状態でダンベルを使用すると、ダンベルがバラバラになって顔に落ちる可能性があります。", "腕をまっすぐに保ったまま、胸が伸びるのを感じるまで息を吸いながら、頭の後ろで弧を描くようにゆっくりと体重を下げます。", "この時点で、ウェイトを下げた円弧を使ってダンベルを開始位置に戻し、息を吐きながらこの動きを行います。", "最初の位置にウェイトを 1 秒間保持し、この動作を規定の回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Straight-Arm_Dumbbell_Pullover';
UPDATE exercises SET name = 'ストレートアームプルダウン', instructions = '["まず、プルダウン マシンの上部プーリーにある幅広のバーをつかみ、肩幅よりも広い回内 (手のひらを下に向けた) グリップを使用します。 2 フィートほど後ろに下がります。", "腕を前に完全に伸ばし、肘をわずかに曲げて、胴体を腰のところで前方に約 30 度曲げます。腕が完全に伸びていない場合は、伸びるまでもう少し後ろにステップする必要があります。腕を完全に伸ばし、胴体のウエストをわずかに曲げたら、広背筋を締めて準備完了です。", "腕をまっすぐに保ちながら、手が太ももの横に来るまで広背筋を収縮させてバーを引き下げます。このステップを実行するときに息を吐きます。", "腕をまっすぐに伸ばしたまま、息を吸いながら元の位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Straight-Arm_Pulldown';
UPDATE exercises SET name = 'ストレートバーベンチ ミッドロー', instructions = '["負荷がかかったバーベルをベンチの端に置きます。バーの後ろのベンチに立って、中程度の回内グリップを握ります。腰を後ろに向けて胸を上げて立ち、背骨を中立に保ちます。これが開始位置になります。", "肩甲骨を引っ込め、肘を曲げてバーを胴体まで漕ぎます。けいれんのない、制御された動きを使用してください。", "短い停止の後、バーをゆっくりと開始位置に戻し、確実に最後まで下げます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Straight_Bar_Bench_Mid_Rows';
UPDATE exercises SET name = 'インクラインベンチでのストレートレイズ', instructions = '["インクラインベンチの頭の後ろの地面にバーを置きます。", "ベンチにうつ伏せになって横になります。回内グリップで、腕をまっすぐに保ちながらバーベルを床から持ち上げます。バーをまっすぐ下に垂らします。これが開始位置になります。", "まず、腕を伸ばしたままバーベルを頭の前に上げます。", "開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Straight_Raises_on_Incline_Bench';
UPDATE exercises SET name = 'ストライドジャンプクロスオーバー', instructions = '["ボックスの側面に立ち、内側の足をボックスの端近くに置きます。", "まずは腕を上に振りながら上の脚を押し上げ、できるだけ高く上にジャンプします。反対側の膝を上に上げてみます。", "開始位置とは反対のボックスの反対側に着地します。最初にボックス上にあった足が地面に着き、反対側の足がボックス上に置かれます。", "この動作を繰り返し、反対側に渡ります。"]'::jsonb, category = 'プライオメトリクス', equipment = 'その他' WHERE id = 'Stride_Jump_Crossover';
UPDATE exercises SET name = '相撲デッドリフト', instructions = '["地面にバーを置いた状態から始めます。バーが足の中央と交差するようにバーに近づきます。足は襟の近くで非常に幅広に設定する必要があります。腰を曲げてバーを握ります。腕は肩の真下、脚の内側に置く必要があり、プロネーション グリップ、ミックス グリップ、またはフック グリップを使用できます。肩をリラックスさせると腕が長くなります。", "息を吸い、腰を下げ、胸を張って頭を前に向けます。足の後ろ半分に体重をかけて、両足を広げて床を走ります。腰と膝まで伸ばします。", "バーが膝を通過したら、後ろに傾き、腰をバーに押し込み、肩甲骨を引き寄せます。", "腰を曲げて体重をコントロールしながら、体重を地面に戻します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Sumo_Deadlift';
UPDATE exercises SET name = 'バンド付き相撲デッドリフト', instructions = '["短いバンドを使ってデッドリフトを行うには、開始前にバンドをバーに巻き付け、バンドに足を踏み入れてセットアップするだけです。足の後ろ半分の下、床に着地する場所のすぐ下にあることを確認してください。", "地面にバーを置いた状態から始めます。バーが足の中央と交差するようにバーに近づきます。足は襟の近くで非常に幅広に設定する必要があります。腰を曲げてバーを握ります。腕は肩の真下、脚の内側に置く必要があり、プロネーション グリップ、ミックス グリップ、またはフック グリップを使用できます。", "息を吸い、腰を下げ、胸を張って頭を前に向けます。足の後ろ半分に体重をかけて、両足を広げて床を走ります。腰と膝まで伸ばします。", "バーが膝を通過したら、後ろに傾き、腰をバーに押し込み、肩甲骨を引き寄せます。", "腰を曲げて体重をコントロールしながら、体重を地面に戻します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Sumo_Deadlift_with_Bands';
UPDATE exercises SET name = '鎖を使った相撲デッドリフト', instructions = '["チェーンをバーの袖に取り付けるか、バーの上に中央を垂らすだけで、持ち上げるときに重量が大きく増加します。ウェイトを下げるときにチェーンの端がプレートに当たらないように、チェーンの端をプレートから遠ざけるようにしてください。", "地面にバーを置いた状態から始めます。バーが足の中央と交差するようにバーに近づきます。足は襟の近くで非常に幅広に設定する必要があります。腰を曲げてバーを握ります。腕は肩の真下、脚の内側に置く必要があり、プロネーション グリップ、ミックス グリップ、またはフック グリップを使用できます。肩をリラックスさせると腕が長くなります。", "息を吸い、腰を下げ、胸を張って頭を前に向けます。足の後ろ半分に体重をかけて、両足を広げて床を走ります。腰と膝まで伸ばします。", "バーが膝を通過したら、後ろに傾き、腰をバーに押し込み、肩甲骨を引き寄せます。", "腰を曲げて体重をコントロールしながら、体重を地面に戻します。"]'::jsonb, category = 'パワーリフティング', equipment = 'バーベル' WHERE id = 'Sumo_Deadlift_with_Chains';
UPDATE exercises SET name = 'スーパーマン', instructions = '["まず、床またはエクササイズマットの上にまっすぐに横になり、うつ伏せになります。腕は前に完全に伸ばす必要があります。これが開始位置です。", "同時に腕、脚、胸を床から上げ、この収縮を 2 秒間保持します。ヒント: このエクササイズで最良の結果を得るには、腰を締めてください。この動作中に息を吐き出すことを忘れないでください。注: 収縮した位置を保持しているときは、飛行中のスーパーマンのように見えるはずです。", "息を吸いながら、ゆっくりと腕、脚、胸を下げ始め、開始位置に戻ります。", "プログラムで規定されている推奨回数だけ繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Superman';
UPDATE exercises SET name = '仰向け胸投げ', instructions = '["このドリルは、パートナーや十分な強度の壁がない場合の胸パスに最適です。膝を曲げて仰向けになって地面に横たわります。", "ボールを胸の上に置き、両手で下に置きます。", "肘を通って上向きに爆発して、ボールをできるだけ高く真上に投げます。", "落ちてくるボールを両手でキャッチします。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Supine_Chest_Throw';
UPDATE exercises SET name = '仰臥位片腕オーバーヘッドスロー', instructions = '["膝を曲げて仰向けになって地面に横たわります。片手でボールを持ち、腕を頭の後ろに完全に伸ばします。これが開始位置になります。", "肩から動きを開始し、座った状態でボールを前方に直接投げ、最大限の距離を目指します。", "ボールはパートナーに投げたり、壁に跳ね返ったりすることができます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Supine_One-Arm_Overhead_Throw';
UPDATE exercises SET name = '仰臥位両腕オーバーヘッドスロー', instructions = '["膝を曲げて仰向けになって地面に横たわります。", "両手でボールを持ち、腕を頭の後ろに完全に伸ばします。これが開始位置になります。", "肩から動きを開始し、座った状態でボールを前方に直接投げ、最大限の距離を目指します。", "ボールはパートナーに投げたり、壁に跳ね返ったりすることができます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'メディシンボール' WHERE id = 'Supine_Two-Arm_Overhead_Throw';
UPDATE exercises SET name = '中断されたフォールアウト', instructions = '["ハンドルが腰の高さより下の適切な高さになるようにストラップを調整します。", "立ってハンドルを握り始めます。ストラップに寄りかかり、傾斜腕立て伏せの姿勢に移動します。これが開始位置になります。", "腕を真っ直ぐに保ち、サスペンションストラップにさらに寄りかかり、体を地面に近づけて肩を伸ばし、腕を頭の上に上げます。", "背骨を中立に保ち、体の残りの部分をまっすぐに保ちます。肩だけが動くことができる関節です。", "収縮のピーク中に一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Suspended_Fallout';
UPDATE exercises SET name = 'サスペンデッドプッシュアップ', instructions = '["サスペンション ストラップをラックやその他の物の上部にしっかりと固定します。", "ストラップに寄りかかり、ハンドルを両手に持ち、腕立て伏せプランクの姿勢に移行します。腕を完全に伸ばし、正しい姿勢を維持しながら、できる限り地面と平行に近づける必要があります。", "胴体をまっすぐに堅く保ち、肘を曲げながらゆっくりと下降します。", "肘が90度に折れるまで続け、伸ばす前に一時停止して開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Suspended_Push-Up';
UPDATE exercises SET name = 'サスペンデッド・リバース・クランチ', instructions = '["ハンドルを地面から約 1 フィート浮かせた状態で、一連のサスペンション ストラップを固定します。ラックの反対側を向いて腕立て伏せプランクの姿勢に体を動かします。", "足をハンドルに置きます。腰が垂れないよう、まっすぐな姿勢を維持する必要があります。これが開始位置になります。", "膝と股関節を曲げ、膝を胴体に引き寄せることから動きを始めます。このとき、骨盤を前に傾けて背骨を曲げます。", "制御された動作が終了したら、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Suspended_Reverse_Crunch';
UPDATE exercises SET name = 'サスペンデッド・ロウ', instructions = '["胸の高さあたりでストラップを吊り下げます。両手にハンドルを持ち、後ろにもたれかかります。体を直立させ、頭と胸を上げてください。腕は完全に伸ばす必要があります。これが開始位置になります。", "動きを開始するには、肘を曲げることから始めます。このとき肩甲骨を引きます。", "動作が完了したら一時停止し、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Suspended_Row';
UPDATE exercises SET name = 'サスペンデッド・スプリット・スクワット', instructions = '["ハンドルが床から18～30インチの高さになるようにストラップを吊り下げます。", "セットアップとは反対側を向いて、後ろ足をハンドルに置きます。頭を前に向け、胸を張り、膝を軽く曲げます。これが開始位置になります。", "膝と股関節を曲げて地面に体を下ろします。足のかかとに体重をかけて、運動中は姿勢を維持してください。", "動きの最後では、動きを逆にして、腰と膝を通って開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Suspended_Split_Squat';
UPDATE exercises SET name = 'スベンドプレス', instructions = '["立った姿勢から始めます。", "2 枚の軽量プレートを手で押し合わせます。プレートを胸の近くで合わせて保持し、胸筋に等尺性の収縮を引き起こします。指は前に向ける必要があります。これが開始位置です。", "手のひらでプレートを握り、制御された動きで腕をまっすぐ前に伸ばします。", "動作の最高点で停止し、ゆっくりと開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Svend_Press';
UPDATE exercises SET name = 'ハンドル付きTバーロー', instructions = '["バーを地雷や隅に置いて動かないようにします。適切な重りを末端に負荷します。", "バーの上に立って、カラーの隣のバーの周りにダブル D 列ハンドルを配置します。腰と脚を使って立ち上がる。", "腰を後ろに引き、胸を張った広いスタンスを想定してください。腕を伸ばす必要があります。これが開始位置になります。", "肩甲骨を引いて肘を曲げて、体重を上腹部に引き寄せます。動作中にウェイトを急激に動かしたり、ごまかしたりしないでください。", "少し休憩した後、開始位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'T-Bar_Row_with_Handle';
UPDATE exercises SET name = 'テート・プレス', instructions = '["フラットベンチに横になり、両手にダンベルを太ももの上に置きます。手のひらは向かい合うようになります。", "太ももを使ってダンベルを持ち上げるのを助け、片腕ずつダンベルをきれいにし、ダンベルを肩幅で前に持てるようにします。注: ダンベルを前に持つときは、回内 (手のひらを前に向けた) グリップを使用して、腕を肩幅よりも広くしてください。肘を外側に向けます。これが開始位置です。", "上腕を固定したまま、息を吸いながらダンベルが胸の上部に触れるまで、半円を描くようにゆっくりとダンベルを上下に動かします。常にダンベルを完全に制御し、上腕を動かしたり、胸の上にダンベルを置かないでください。", "息を吐きながら、上腕三頭筋と同じ半円運動を逆に使ってダンベルを上に動かします。ダンベルを上げていくときに、ダンベルを一緒に保つようにしてください。腕を縮めた位置にロックし、1秒間保持してから、再びゆっくりと下ろし始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Tate_Press';
UPDATE exercises SET name = 'ザ・ストラドル', instructions = '["座って直立した姿勢から始めます。まずは足を前にV字に伸ばします。", "両手を床に置き、できるだけ前かがみになります。 10 ～ 20 秒間押し続けます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'The_Straddle';
UPDATE exercises SET name = '大腿部外転筋', instructions = '["まず、アブダクターマシンに座り、快適な重量を選択します。脚を適切な位置に配置したら、両側のハンドルを握ります。上半身全体（腰から上）は動かないようにします。これが開始位置です。", "息を吐きながら、脚でマシンをゆっくりと押して互いに遠ざけます。", "収縮を少し感じて、息を吸いながら脚を元の位置に戻し始めます。 注: 怪我を防ぐために、上半身を動かさないようにしてください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Thigh_Abductor';
UPDATE exercises SET name = '大腿内転筋', instructions = '["まず、内転筋マシンに座り、快適な重量を選択します。脚がマシンのレッグパッドに正しく配置されたら、両側のハンドルを握ります。上半身全体（腰から上）は動かないようにします。これが開始位置です。", "息を吐きながら、脚でマシンをゆっくりと押して互いに近づけます。", "収縮を一瞬感じて、息を吸いながら足を元の位置に戻し始めます。 注: 怪我の発生を防ぐために、上半身を静止した状態に保ち、急激なけいれん動作を避けることを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'マシン' WHERE id = 'Thigh_Adductor';
UPDATE exercises SET name = 'タイヤフリップ', instructions = '["タイヤの底部をトレッド上で握り、足を少し後ろに置きます。胸がタイヤに押し込まれるはずです。", "タイヤを持ち上げるには、腰、膝、足首を伸ばしてタイヤに打ち込みます。", "タイヤの角度が 45 度に達したら、前に踏み出して膝をタイヤに押し込みます。このとき、グリップをタイヤの上部に合わせて、できるだけ強く前に押してターンを完了します。必要に応じて繰り返します。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Tire_Flip';
UPDATE exercises SET name = 'トータッチャー', instructions = '["まず、床またはエクササイズマットの上に横になり、背中を床に押しつけます。腕は手のひらを下に向けて体の横に置きます。", "足は互いに触れているはずです。膝をわずかに曲げて、脚が床に対してほぼ垂直になるまでゆっくりと脚を空中に上げます。足は床と平行でなければなりません。", "腕を床から 45 度の角度で完全に伸ばすように動かします。これが開始位置です。", "腰を床に押し付けたまま、ゆっくりと上体を持ち上げ、手を使ってつま先に触れてみてください。エクササイズのこの部分を実行するときは、息を吐き出すことを忘れないでください。", "息を吸いながら、ゆっくりと胴体と腕を下げ始め、開始位置に戻ります。腕をまっすぐに伸ばしてつま先に向けることを忘れないでください。", "推奨回数だけ繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Toe_Touchers';
UPDATE exercises SET name = '胴体の回転', instructions = '["バランスボールを両手で持ち直立して立ちます。腕を伸ばしてボールがまっすぐ前に来るようにします。これが開始位置になります。", "体を片側に回転させ、動きながらボールから目を離さないでください。次に、反対方向に回転して戻します。 10〜20回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = 'exercise ball' WHERE id = 'Torso_Rotation';
UPDATE exercises SET name = 'トレイルランニング/ウォーキング', instructions = '["トレイルでのランニングやハイキングをすると、すぐに血液が循環し、心臓が鼓動します。良い靴を履いてください。ふくらはぎやお尻の筋肉を使って坂を登るとき、膝、関節、足首が下りてくる衝撃の大部分を吸収します。下り坂を歩くときは歩幅を小さくし、衝撃を和らげるために膝を曲げたままにし、転ばないように速度を落とします。", "体重 150 ポンドの人は、上り坂を 30 分間歩くと 200 カロリー以上を消費できますが、平らな場所では 175 カロリー以上消費できます。トレイルを走る場合、体重 150 ポンドの人は 30 分で 500 カロリーをはるかに超えるカロリーを消費できます。"]'::jsonb, category = '有酸素運動', equipment = NULL WHERE id = 'Trail_Running_Walking';
UPDATE exercises SET name = 'トラップバーデッドリフト', instructions = '["この演習では、六角バーとも呼ばれるトラップ バーを地面に適切な重量まで負荷します。装置の中央に立ち、両方のハンドルを握ります。", "腰を下げ、頭を前に向け、胸を張ります。", "かかとを通って動きを開始し、腰と膝を伸ばします。常に背中を丸めないようにしてください。", "動作が完了したら、コントロールしながら体重を地面に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Trap_Bar_Deadlift';
UPDATE exercises SET name = 'トライセップダンベルキックバック', instructions = '["両手にダンベルを持ち、手のひらを胴体に向けます。背中をまっすぐにして膝を軽く曲げ、腰を前に曲げます。胴体は床とほぼ平行になるようにしてください。必ず頭を上げてください。上腕は胴体に近く、床と平行でなければなりません。ウェイトを保持するときは、前腕を床の方向に向ける必要があります。前腕と上腕の間には 90 度の角度が形成されている必要があります。これが開始位置です。", "次に、上腕を固定したまま、息を吐きながら上腕三頭筋を使って腕が完全に伸びるまでウェイトを持ち上げます。前腕を動かすことに集中してください。", "上部の収縮で少し停止した後、息を吸いながらダンベルをゆっくりと下げて開始位置に戻します。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Tricep_Dumbbell_Kickback';
UPDATE exercises SET name = '上腕三頭筋のサイドストレッチ', instructions = '["上腕三頭筋が伸びると感じるまで、右腕を体全体に渡して左肩の上に置き、左手で肘を押さえます。次に、もう一方の腕でも繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Tricep_Side_Stretch';
UPDATE exercises SET name = 'ロープを使った上腕三頭筋のオーバーヘッドエクステンション', instructions = '["低い滑車にロープを取り付けます。適切な重さを選択したら、両手でロープを握り、ケーブルから背を向けます。", "手を頭の後ろに置き、肘をまっすぐ上に向けます。肘を曲げて開始し、スタンスをずらしてマシンからゆっくりと体を傾けると、安定性が高まります。これが開始位置になります。", "この動きを実行するには、上腕を所定の位置に保ちながら肘を通って伸ばし、手を頭の上に上げます。", "動きの一番上で上腕三頭筋を絞り、ゆっくりと体重を下げて開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Triceps_Overhead_Extension_with_Rope';
UPDATE exercises SET name = '上腕三頭筋プッシュダウン', instructions = '["まっすぐなバーまたは斜めのバーを高い滑車に取り付け、肩の幅でオーバーハンド グリップ (手のひらを下に向けて) で握ります。", "胴体をまっすぐにして前傾をわずかに傾けて直立し、上腕を体に近づけて床に垂直にします。バーを握るとき、前腕はプーリーに向かって上を向く必要があります。これが開始位置です。", "上腕三頭筋を使ってバーを太ももの前に触れるまで下ろし、腕を床に対して垂直に完全に伸ばします。上腕は常に胴体の隣で静止し、前腕だけを動かす必要があります。この動きをしながら息を吐きます。", "収縮した位置でもう一度保持した後、バーをゆっくりと開始点まで引き上げます。このステップを実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Triceps_Pushdown';
UPDATE exercises SET name = '上腕三頭筋プッシュダウン - ロープアタッチメント', instructions = '["ロープアタッチメントをハイプーリーに取り付け、ニュートラルグリップ（手のひらを向かい合う）で握ります。", "胴体をまっすぐにして前傾をわずかに傾けて直立し、上腕を体に近づけて床に垂直にします。手のひらを向かい合わせてロープを握るとき、前腕は滑車に向かって上を向く必要があります。これが開始位置です。", "上腕三頭筋を使用して、ロープの両側を太ももの側面に近づけながらロープを下ろします。動きの終わりに、腕は完全に伸びて床に対して垂直になります。上腕は常に胴体の隣で静止し、前腕だけを動かす必要があります。この動きをしながら息を吐きます。", "収縮した位置で 2 秒間保持した後、ロープをゆっくりと開始点まで引き上げます。このステップを実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Triceps_Pushdown_-_Rope_Attachment';
UPDATE exercises SET name = '上腕三頭筋プッシュダウン - V バー アタッチメント', instructions = '["V バーを高いプーリーに取り付け、肩の幅でオーバーハンド グリップ (手のひらを下に向けて) で握ります。", "胴体をまっすぐにして前傾をわずかに傾けて直立し、上腕を体に近づけて床に垂直にします。バーを握るとき、前腕はプーリーに向かって上を向く必要があります。親指は小指よりも高い位置にある必要があります。これが開始位置です。", "上腕三頭筋を使ってバーを太ももの前に触れるまで下ろし、腕を床に対して垂直に完全に伸ばします。上腕は常に胴体の隣で静止し、前腕だけを動かす必要があります。この動きをしながら息を吐きます。", "収縮した位置でもう一度保持した後、V バーをゆっくりと開始点まで引き上げます。このステップを実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Triceps_Pushdown_-_V-Bar_Attachment';
UPDATE exercises SET name = '上腕三頭筋のストレッチ', instructions = '["手を頭の後ろに伸ばし、肘をつかんで軽く引っ張ります。 10〜20秒間押し続けてから、サイドを切り替えます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Triceps_Stretch';
UPDATE exercises SET name = 'タッククランチ', instructions = '["まず、床またはエクササイズマットの上に横になり、背中を床に押しつけます。腕は手のひらを下に向けて体の横に置きます。", "一方の足首をもう一方の足首に巻き付けて脚を交差させます。膝をわずかに曲げて太ももが床に対して垂直になるまで、ゆっくりと脚を空中に上げます。注意: 膝とつま先は、太ももではなく床と平行になるようにしてください。", "腕を床から動かして交差させ、胸の上に置きます。これが開始位置です。", "腰を床に押し付けたまま、ゆっくりと上体を持ち上げます。エクササイズのこの部分を実行するときは、息を吐き出すことを忘れないでください。", "息を吸いながら、ゆっくりと上体を元の位置まで下げ始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Tuck_Crunch';
UPDATE exercises SET name = 'ツーアーム ダンベル プリーチャー カール', instructions = '["両腕でダンベルをつかみ、上腕をプリーチャーベンチまたはインクラインベンチの上に置きます。ダンベルは肩の長さで持つ必要があります。これが開始位置になります。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、ゆっくりとダンベルを下げます。", "息を吐きながら、上腕二頭筋を使ってウェイトを丸め、上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるようにします。", "収縮した位置で上腕二頭筋を 1 秒間強く絞り、推奨回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Two-Arm_Dumbbell_Preacher_Curl';
UPDATE exercises SET name = 'ツーアーム ケトルベル クリーン', instructions = '["2つのケトルベルを足の間に置きます。開始位置に立つには、お尻を後ろに押し出し、まっすぐ前を見てください。", "ケトルベルを肩に向かって持ち上げながら、脚と腰を通してケトルベルを肩まできれいにします。このとき手首を回転させます。", "ケトルベルを下げて開始位置に戻し、繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Two-Arm_Kettlebell_Clean';
UPDATE exercises SET name = 'ツーアームケトルベルジャーク', instructions = '["2 つのケトルベルを肩まできれいにします。ケトルベルを肩に向かって振りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。数インチしゃがみ、動きを逆にして、両方のケトルベルを頭上に上げます。最初に押した直後に、再びしゃがみ、ケトルベルの下に入ります。ケトルベルがロックアウトされたら、直立してエクササイズを完了します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Two-Arm_Kettlebell_Jerk';
UPDATE exercises SET name = 'ツーアーム ケトルベル ミリタリー プレス', instructions = '["2 つのケトルベルを肩まできれいにします。ケトルベルを肩に向かって振りながら、脚と腰を通してケトルベルを肩まできれいにします。このとき、手のひらが前を向くように手首を回転させます。", "ケトルベルを上下に押します。ケトルベルが頭の上を通過するときに、ケトルベルが頭の後ろにかかるようにウェイトに寄りかかります。安定性を高めるために、広背筋、お尻、お腹を必ず収縮させてください。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Two-Arm_Kettlebell_Military_Press';
UPDATE exercises SET name = 'ツーアームケトルベルロー', instructions = '["2つのケトルベルを足の前に置きます。膝を軽く曲げ、前かがみになるときにできるだけお尻を突き出して開始姿勢をとります。", "両方のケトルベルをつかんでお腹に引き寄せ、肩甲骨を引いて肘を曲げます。背中をまっすぐにしてください。下げて繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケトルベル' WHERE id = 'Two-Arm_Kettlebell_Row';
UPDATE exercises SET name = 'アンダーハンドケーブルプルダウン', instructions = '["上部のプーリーに幅広のバーが取り付けられたプルダウン マシンに座ります。身長に合わせてマシンの膝パッドを調整します。これらのパッドは、バーにかかる抵抗によって体が持ち上がるのを防ぎます。", "手のひらを胴体に向けてプルダウン バーを握ります (回外グリップ)。手を肩幅よりも近づけてください。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を反らせて胸を突き出しながら、胴体を約 30 度後ろに戻します。これが開始位置です。", "息を吐きながら、肩と上腕を下と後ろに引いて、バーが胸の上部に触れるまで引き下げます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中し、肘を体に近づけてください。バーを持ってくるとき、上半身は静止したままにし、腕だけを動かします。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で 1 秒後、息を吸いながら、腕を完全に伸ばし、広背筋が完全に伸びたら、ゆっくりとバーを開始位置に戻します。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Underhand_Cable_Pulldowns';
UPDATE exercises SET name = 'アッパーバックレッググラブ', instructions = '["座った状態で前かがみになり、両腕で太ももを下から抱きしめます。", "膝を閉じて脚を伸ばしたまま、胸を膝まで下げます。また、膝を抱きしめながら背中を膝から離すことで、背中の真ん中を伸ばすこともできます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Upper_Back-Leg_Grab';
UPDATE exercises SET name = '背中上部のストレッチ', instructions = '["親指を下に向けて指を組み、肩を丸めて手を前に伸ばします。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Upper_Back_Stretch';
UPDATE exercises SET name = 'アップライトバーベルロー', instructions = '["肩幅よりわずかに狭いオーバーハンドグリップでバーベルを握ります。腕を伸ばして肘を軽く曲げ、バーを太ももの上に置きます。背中もまっすぐでなければなりません。これが開始位置になります。", "次に、息を吐きながら肩の側面を使ってバーを持ち上げ、肘を上と横に上げます。バーを上げるときは、バーを体の近くに保ちます。バーが顎に触れそうになるまで持ち上げ続けます。ヒント: 肘が動きを推進する必要があり、常に前腕より高い位置にある必要があります。胴体を静止した状態に保ち、動作のトップで 1 秒間停止することを忘れないでください。", "バーをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Upright_Barbell_Row';
UPDATE exercises SET name = '直立ケーブル列', instructions = '["低いプーリーに取り付けられたストレート バー ケーブル アタッチメントを、肩の幅よりわずかに狭い回内 (手のひらを太ももに向ける) グリップで握ります。バーは太ももの上に置く必要があります。腕は肘を少し曲げて伸ばし、背中はまっすぐにします。これが開始位置になります。", "息を吐きながら、側肩を使ってケーブルバーを持ち上げます。バーを上に動かすと、バーが体に近づく必要があります。あごに触れるくらいまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。バーを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "バーをゆっくりと元の位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Upright_Cable_Row';
UPDATE exercises SET name = 'アップライトロウ - バンド付き', instructions = '["まず、エクササイズバンドの上に立ち、腕の長さで緊張が始まるようにします。肩の幅よりわずかに狭い回内（手のひらを太ももに向ける）グリップを使用してハンドルを握ります。ハンドルは太ももの上に置く必要があります。腕は肘を少し曲げて伸ばし、背中はまっすぐにします。これが開始位置になります。", "息を吐きながら、横の肩を使ってハンドルを持ち上げます。ハンドルを上に動かすと、ハンドルが体に近づくようになります。ハンドルが顎に触れそうになるまで持ち上げ続けます。ヒント: 肘で動作を推進する必要があります。ハンドルを持ち上げるときは、肘が常に前腕より高い位置にある必要があります。また、胴体を静止したままにして、動作の頂点で 1 秒間停止します。", "ハンドルをゆっくりと開始位置まで下げます。動きのこの部分を実行するときに息を吸います。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'チューブ・バンド' WHERE id = 'Upright_Row_-_With_Bands';
UPDATE exercises SET name = '上向きのストレッチ', instructions = '["両手を頭の上にまっすぐ伸ばし、手のひらを合わせます。", "背中をまっすぐに保ちながら、ゆっくりと手を上下に押し上げます。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Upward_Stretch';
UPDATE exercises SET name = 'Vバープルダウン', instructions = '["上部プーリーに V バーが取り付けられたプルダウン マシンに座ります。", "身長に合わせてマシンの膝パッドを調整します。これらのパッドは、バーにかかる抵抗によって体が持ち上がるのを防ぎます。", "手のひらを向かい合わせて V バーを握ります (ニュートラル グリップ)。広背筋をよりよく働かせるために、胸を突き出し、体を少し後ろに傾けます（約 30 度）。これが開始位置になります。", "広背筋を使って、肩甲骨を締めながらバーを引き下げます。胸が V バーにほとんど触れるまで続けます。この動作を実行しながら息を吐きます。ヒント: 動作中は胴体を動かさないようにしてください。", "収縮した位置をもう一度保持した後、息を吸いながらゆっくりとバーを開始位置に戻します。", "規定の回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'V-Bar_Pulldown';
UPDATE exercises SET name = 'Vバープルアップ', instructions = '["まず、V バーの中央を懸垂バーの中央に置きます (使用している懸垂ステーションにニュートラル グリップ ハンドルがないことが前提です)。 V バーのハンドルは下を向いており、ハンドルを使用して懸垂バーにぶら下がることができます。", "V バーをしっかりと配置したら、バーの両側を持ってぶら下がります。広背筋をよりよく働かせるために、胸を突き出し、体を少し後ろに傾けます。これが開始位置になります。", "広背筋を使って胴体を引き上げながら、懸垂バーにぶつからないように頭を少し後ろに傾けます。胸が V バーにほとんど触れるまで続けます。この動作を実行しながら息を吐きます。", "収縮した位置をもう一度保持した後、息を吸いながらゆっくりと体を下げて開始位置に戻します。", "規定の回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'V-Bar_Pullup';
UPDATE exercises SET name = '垂直スイング', instructions = '["ダンベルを腕の長さで脚の間にぶら下げ、両手で持ちます。背中をまっすぐにして頭を上げてください。", "脚の間でダンベルを振り、股関節を曲げ、膝をわずかに曲げます。", "腰、膝、足首を伸ばして動きを力強く反転させ、ダンベルを頭上で振りながら上向きに推進します。", "着地したら、脚を通して衝撃を吸収し、次の繰り返しの前にダンベルを胴体に引き寄せます。"]'::jsonb, category = 'プライオメトリクス', equipment = 'ダンベル' WHERE id = 'Vertical_Swing';
UPDATE exercises SET name = 'ウォーキング、トレッドミル', instructions = '["まず、トレッドミルに乗り、メニューから希望のオプションを選択します。ほとんどのトレッドミルには手動設定があり、実行するプログラムを選択することもできます。通常、年齢と体重を入力すると、運動中に消費されるカロリー量を推定できます。高度を調整してワークアウトの強度を変更できます。", "トレッドミルは利便性が高く、心臓血管にも効果があり、通常は外で歩くよりも影響が少ないです。歩くときは、ゆっくり歩くのではなく、中速～速歩で歩きましょう。ウォーキングは強度の低いアクティビティであるため、他のアクティビティほど多くのカロリーを消費しませんが、それでも大きなメリットがあります。体重150ポンドの人は、時速4マイルで30分間歩くと約175カロリーを消費しますが、2倍の速度で走ると450カロリーになります。歩行中は正しい姿勢を保ち、降車時や心拍数を確認するときなど、必要な場合にのみハンドルを握ります。"]'::jsonb, category = '有酸素運動', equipment = 'マシン' WHERE id = 'Walking_Treadmill';
UPDATE exercises SET name = '加重ボール過伸展', instructions = '["まず、エクササイズ ボールの上に横になり、胴体をボールに押し付けて床と平行にします。バランスを保つために、足の指の付け根を床に押し付ける必要があります。加重プレートをあごの下または首の後ろに置きます。これが開始位置です。", "腰と腰を曲げて上体をゆっくりと上げます。この動作中に息を吐き出すことを忘れないでください。", "腰の収縮を 1 秒間保持し、息を吸いながら胴体を開始位置まで下げます。", "プログラムで規定されている推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Weighted_Ball_Hyperextension';
UPDATE exercises SET name = '加重ボールサイドベンド', instructions = '["まず、エクササイズ ボールの上に横になり、胴体の左側 (腰、腰、肩) をボールに押し付けます。", "足を交差させてボールからぶら下がっている間、足は床に置く必要があります。右手で重りの付いたプレートを頭の右側に直接当てます。ヒント: プレートの滑らかな面が頭に当たるようにしてください。", "手のひらが腹斜筋の上に来るように、左腕を胴体に置きます。左前腕と上腕の間には直角が必要です。これが開始位置です。", "息を吐きながら腰を横に曲げて胴体の側面を持ち上げます。", "収縮を 1 秒間保持し、息を吸いながらゆっくりと開始位置まで体を下げます。", "推奨回数だけ繰り返します。", "側を切り替えてエクササイズを繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'exercise ball' WHERE id = 'Weighted_Ball_Side_Bend';
UPDATE exercises SET name = 'ウェイトベンチディップ', instructions = '["この演習では、ベンチを背中の後ろに、もう 1 つを前に配置する必要があります。ベンチを体に対して垂直にして、片方のベンチの端を持ち、両手を体の近くに置き、肩幅に開きます。腕は完全に伸ばす必要があります。", "脚はもう一方のベンチの上で前に伸ばします。脚は床と平行にし、胴体は床と垂直にする必要があります。パートナーにダンベルを膝の上に置いてもらいます。注意: このエクササイズは、膝の上に体重を乗せるのが難しく、補助なしでは怪我をする可能性があるため、パートナーと一緒に行うのが最適です。これが開始位置になります。", "息を吸いながら肘を曲げ、上腕と前腕の間の角度が 90 度よりわずかに小さい位置まで体を下げます。ヒント: 動作中は肘をできるだけ近づけてください。前腕は常に下を向いている必要があります。", "上腕三頭筋を使って上半身を再び起こし、息を吐きながら体を開始位置に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Weighted_Bench_Dip';
UPDATE exercises SET name = '加重クランチ', instructions = '["仰向けになって両足を地面に平らにつけるか、膝を90度に曲げてベンチに座ります。", "重りを胸に当てて保持することも、胴体の上に伸ばして保持することもできます。これが開始位置になります。", "次に、息を吐きながらゆっくりと肩を床から外し始めます。肩は床から約 4 インチ浮くようにし、腰は床につけたままにしてください。", "動きの頂点で腹部を曲げ、少しの間静止します。", "次に、息を吸いながらゆっくりと体を下ろし、元の位置に戻ります。"]'::jsonb, category = '筋力トレーニング', equipment = 'メディシンボール' WHERE id = 'Weighted_Crunches';
UPDATE exercises SET name = '加重ジャンプスクワット', instructions = '["軽く負荷をかけたバーベルを肩の後ろに置きます。このエクササイズでは、加重ベスト、サンドバッグ、またはその他の種類の抵抗を使用することもできます。", "速度が大幅に低下しない程度に重量を軽くする必要があります。足は肩幅のすぐ外側に置き、頭と胸を上げます。これが開始位置になります。", "反対の動きを使用して、部分的にしゃがみ、すぐに方向を反転して地面から爆発的に腰、膝、足首まで伸ばします。ジャンプ中は常に良い姿勢を維持してください。", "地面に戻るときは足で衝撃を吸収します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Weighted_Jump_Squat';
UPDATE exercises SET name = '加重懸垂', instructions = '["ディップベルトにウェイトを取り付けて腰に固定します。手のひらを前に向けて懸垂バーを握ります。中程度のグリップの場合は、手を肩幅に開く必要があります。選択したグリップでバーを持ち、両腕を前に伸ばします。", "腰を反らせて胸を突き出しながら、胴体を約 30 度戻します。これが開始位置になります。", "次に、息を吐きながら、頭が手の上に来るまで胴体を引き上げます。一番上の収縮位置に達したら、肩甲骨を後ろと下に絞ることに集中してください。", "収縮した上部の位置で少し待った後、息を吸いながらゆっくりと胴体を下げ、腕を伸ばし、広背筋を完全に伸ばした状態で開始位置に戻します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Weighted_Pull_Ups';
UPDATE exercises SET name = '加重シシースクワット', instructions = '["足を肩幅に開き、つま先を上げて直立し、片手でスクワットラックの梁をつかみ、反対側の腕で胸の上のプレートを持ちます。これが開始位置です。", "片腕で体を支えながら、膝を曲げ、骨盤と膝を前に出すことで胴体を地面に向かってゆっくりと下げます。息を吸いながら下降し、上肢と下肢がほぼ 90 度の角度になったところで停止します。ストレッチ位置を 1 秒間保持します。", "1 秒間ホールドした後、太ももの筋肉を使って胴体を開始位置に戻します。上に上がるときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Weighted_Sissy_Squat';
UPDATE exercises SET name = '加重腹筋運動 - バンド付き', instructions = '["まず、ディクラインベンチのベースにバンドを巻き付けます。ハンドルをディクラインベンチの内側に向けて配置し、横になったときに両方に手が届くようにします。", "足が固定されるまでデクラインマシンに通します。次に、両手でエクササイズバンドに手を伸ばします。ハンドルを握るには、回内 (手のひらを前に向けた) グリップを使用します。鎖骨の近くにそれらを配置し、手首を回転させてニュートラルグリップ（手のひらを胴体に向けます）にします。注: エクササイズ中は腕を動かさないでください。これが開始位置です。", "息を吐きながら、上半身が床に対して垂直になるまで胴体を上に動かします。収縮を 1 秒間保持し、息を吸いながら上半身を開始位置まで下げます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Weighted_Sit-Ups_-_With_Bands';
UPDATE exercises SET name = '加重スクワット', instructions = '["まず、2 つのフラットベンチを肩幅に離して配置します。その上に立って、心地よいと感じる重さのベルトを腰に巻き付けます。つま先が外側を向いていることを確認してください。", "脚の間に体重を掛けてまっすぐに立ったら、腕を体の横に完全に伸ばすように配置します。これが開始位置です。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げることから始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる仮想的な直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "再び足を伸ばして開始位置に戻りながら、主に足の指の付け根でフラットベンチの床を押して体を上に動かし始めます。エクササイズのこの部分を実行するときに息を吐きます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Weighted_Squat';
UPDATE exercises SET name = 'ワイドグリップバーベルベンチプレス', instructions = '["足を床にしっかりとつけて、平らなベンチに仰向けになります。肩幅から約 3 インチ離れた幅の回内 (手のひらを前に向けた) グリップを使用して (両手とも)、バーをラックから持ち上げ、腕をロックした状態でまっすぐに体の上に持ちます。バーは胴体と床に対して垂直になります。これが開始位置になります。", "息を吸いながら、胸の中央にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕をロックし、収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下がり始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wide-Grip_Barbell_Bench_Press';
UPDATE exercises SET name = 'ワイドグリップデクラインバーベルベンチプレス', instructions = '["デクラインベンチに仰向けになり、足をベンチの前でしっかりと固定します。肩幅から約 3 インチ離れた幅の回内 (手のひらを前に向けた) グリップを使用して (両手とも)、バーをラックから持ち上げ、腕をロックした状態でまっすぐに体の上に持ちます。バーは胴体と床に対して垂直になります。これが開始位置になります。", "息を吸いながら、胸の下部にバーを感じるまでゆっくりと下ろします。", "2 回目の停止の後、息を吐きながらバーを開始位置に戻し、胸の筋肉を使ってバーを押します。腕をロックし、収縮した位置で胸を絞り、1秒間保持してから、再びゆっくりと下がり始めます。ヒント: 下りる場合は、上がるよりも少なくとも 2 倍の時間がかかります。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wide-Grip_Decline_Barbell_Bench_Press';
UPDATE exercises SET name = 'ワイドグリップ デクライン バーベル プルオーバー', instructions = '["両足を所定の位置にしっかりと固定して、ディクラインベンチに横になります。回内グリップ（手のひらを外側に向ける）を使用して、頭の後ろでバーベルに手を伸ばします。このエクササイズでは、バーベルを肩幅より広めに握るようにしてください。腕を使ってバーベルを床からゆっくりと持ち上げます。", "適切な位置に置いた場合、腕は完全に伸びて床に対して垂直になります。これが開始位置です。", "まずバーベルを床に置くかのように半円を描くように下に動かしますが、腕が床と平行になったところで止めます。ヒント: 腕は常に完全に伸ばした状態にしてください。この動きは肩関節でのみ行われます。動きのこの部分を実行するときに息を吸います。", "次に、開始位置に戻るまで、息を吐きながらバーベルを上げます。常にバーベルを完全にコントロールできるようにしてください。", "トレーニング プログラムの規定回数だけこの動きを繰り返します。", "セットが終わったら、バーベルを頭と同じ高さになるまでゆっくりと下ろし、バーベルを放します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wide-Grip_Decline_Barbell_Pullover';
UPDATE exercises SET name = 'ワイドグリップ ラット プルダウン', instructions = '["上部のプーリーに幅広のバーが取り付けられたプルダウン マシンに座ります。身長に合わせてマシンの膝パッドを調整してください。これらのパッドは、バーにかかる抵抗によって体が持ち上がるのを防ぎます。", "所定のグリップを使用して、手のひらを前に向けてバーを握ります。グリップに関する注意: ワイドグリップの場合、両手の間隔は肩幅より広くする必要があります。中程度のグリップの場合は、両手の間隔を肩幅と同じにする必要があります。クローズグリップの場合は、肩の幅よりも狭い距離に手を置く必要があります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、腰を反らせて胸を突き出しながら、胴体を約 30 度後ろに戻します。これが開始位置です。", "息を吐きながら、肩と上腕を下と後ろに引いて、バーが胸の上部に触れるまで下げます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は静止したままにして、腕だけを動かします。前腕はバーを握る以外の仕事をしてはなりません。したがって、前腕を使ってバーを引き下げようとしないでください。", "肩甲骨を締めて収縮した位置で 1 秒間留まった後、腕を完全に伸ばし、広背筋が完全に伸びたら、バーをゆっくりと開始位置に戻します。動きのこの部分で息を吸います。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Wide-Grip_Lat_Pulldown';
UPDATE exercises SET name = '首の後ろのワイドグリッププルダウン', instructions = '["上部のプーリーに幅広のバーが取り付けられたプルダウン マシンに座ります。身長に合わせてマシンの膝パッドを調整してください。これらのパッドは、バーにかかる抵抗によって体が持ち上がるのを防ぎます。", "所定のグリップを使用して、手のひらを前に向けてバーを握ります。グリップに関する注意: ワイドグリップの場合、両手の間隔は肩幅より広くする必要があります。中程度のグリップの場合は、両手の間隔を肩幅と同じにする必要があります。クローズグリップの場合は、肩の幅よりも狭い距離に手を置く必要があります。", "両腕を前に伸ばし、選択したグリップ幅でバーを持ちながら、胴体と頭を前に出します。バーの中心から首の後ろまでの想像上の線を思い浮かべてください。これが開始位置です。", "息を吐きながら、肩と上腕を下と後ろに引いて、バーが首の後ろに触れるまで下げます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は静止したままにして、腕だけを動かします。前腕はバーを握る以外の仕事をしてはなりません。したがって、前腕を使ってバーを引き下げようとしないでください。", "肩甲骨を締めて縮めた状態で 1 秒間静止した後、腕を完全に伸ばし広背筋が完全に伸びたら、バーをゆっくりと開始位置に戻します。動きのこの部分で息を吸います。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ケーブル' WHERE id = 'Wide-Grip_Pulldown_Behind_The_Neck';
UPDATE exercises SET name = 'ワイドグリップ リア プルアップ', instructions = '["幅広のグリップを使用して、手のひらを前に向けて懸垂バーを握ります。", "両腕を前に伸ばしてバーを持ちながら、懸垂バーから首の後ろまで想像上の線ができるように胴体を前に倒し頭を出します。これが開始位置です。", "バーが首の後ろ近くに来るまで上体を引き上げます。これを行うには、頭を少し前に傾けながら、肩と上腕を下と後ろに引きます。動きのこの部分を実行するときに息を吐きます。ヒント: 完全に収縮した位置に達したら、背中の筋肉を絞ることに集中してください。上半身は空間を移動するときに静止したままにし、腕だけを動かす必要があります。前腕はバーを握る以外の仕事をしてはいけません。", "収縮した位置で 2 秒後、息を吸い始め、腕を完全に伸ばし広背筋が完全に伸びたら、胴体をゆっくりと開始位置に戻します。", "この動作を規定回数繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Wide-Grip_Rear_Pull-Up';
UPDATE exercises SET name = 'ワイドグリップスタンディングバーベルカール', instructions = '["幅広の外側ハンドルでバーベルを持ちながら、上体を直立させて立ちます。手のひらは前を向くようにしてください。肘は胴体の近くにある必要があります。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながら、ウェイトを前方にカールさせます。ヒント: 前腕のみを動かします。", "上腕二頭筋が完全に収縮し、バーが肩の高さになるまで動きを続けます。収縮した位置を 1 秒間保持し、上腕二頭筋を強く締めます。", "息を吸いながら、ゆっくりとバーを開始位置に戻し始めます。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wide-Grip_Standing_Barbell_Curl';
UPDATE exercises SET name = 'ワイドスタンスバーベルスクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。適切な高さを選択し、バーに負荷をかけたら、バーの下に踏み込み、肩の後ろ（首の少し下）をバーの上に置きます。", "両側の両腕を使ってバーを持ち、最初に脚で押し、同時に胴体をまっすぐにしてラックからバーを持ち上げます。", "ラックから離れ、足を肩幅より広く開き、つま先をわずかに向けます。下を向くとバランスが崩れるため、常に頭を上げ、背中をまっすぐに保ちます。これが開始位置になります。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーをゆっくりと下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら足のかかとで床を押してバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wide_Stance_Barbell_Squat';
UPDATE exercises SET name = 'ワイドスタンスで足が硬い', instructions = '["バーベルを床に置いた状態から始めます。ワイドスタンスで腰を曲げてバーを掴みます。腰をできるだけ後ろに置き、脚をほぼ真っすぐにします。背中をまっすぐにして、頭と胸を上げてください。これが開始位置になります。", "腕をまっすぐに垂らしながら腰を前に動かし、腰を動かすことから動きを始めます。真っすぐに立ち上がるまで続けてから、ゆっくりと体重を開始位置に戻します。連続して繰り返す場合、体重が床に触れる必要はありません。"]'::jsonb, category = 'ウエイトリフティング', equipment = 'バーベル' WHERE id = 'Wide_Stance_Stiff_Legs';
UPDATE exercises SET name = 'ウィンドスプリント', instructions = '["回内グリップを使用して懸垂バーにぶら下がります。腕と脚は伸ばす必要があります。これが開始位置になります。", "まずは片方の膝をできるだけ高く上げます。 Do not swing your body or your legs. 3", "すぐに動きを逆にして、その脚を開始位置に戻します。同時に反対側の膝をできるだけ高く上げます。", "セットが完了するまで交互に脚を動かし続けます。"]'::jsonb, category = '筋力トレーニング', equipment = '自重' WHERE id = 'Wind_Sprints';
UPDATE exercises SET name = '風車', instructions = '["腕を横に伸ばし、脚をまっすぐにして仰向けに寝ます。これが開始位置になります。", "片足を上げて素早く体の上で交差させ、反対側の手の近くの地面に触れようとします。", "開始位置に戻り、反対の足でも繰り返します。交互に10〜20回繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Windmills';
UPDATE exercises SET name = '世界最大のストレッチ', instructions = '["これは3部構成のストレッチです。前足を地面に平らにし、後ろ足のつま先を立てて、前方に突進することから始めます。膝を曲げた状態で、膝が地面につく寸前までしゃがみます。胴体を直立させ、この位置を 10 ～ 20 秒間保持します。", "次に、腕を前脚と同じ側に置き、肘を足の横に置きます。ストレッチのこの部分で体をサポートできるように、もう一方の手はリード脚と平行に地面に置きます。", "10 ～ 20 秒後、前足の両側に手を置きます。前足のつま先を地面から上げ、脚をまっすぐにします。そのためには、後ろ足の位置を変える必要があるかもしれません。 10 ～ 20 秒間押し続けてから、反対側でも同じ手順を繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = NULL WHERE id = 'Worlds_Greatest_Stretch';
UPDATE exercises SET name = 'リストサークル', instructions = '["まず、両足を肩幅に開き、まっすぐに立ちます。腕が完全に伸びて肩と均等な高さで床と平行になるまで、腕を体の横に上げます。ヒント: 胴体と腕は「T」の字を形成する必要があります。手のひらは下を向く必要があります。これが開始位置です。", "手首を除いて体全体を静止させたまま、両手首を円を描くように前方に回転させ始めます。ヒント: 手をブラシとして使用して円を描こうとしているふりをします。このエクササイズを行うときは、普通に呼吸してください。", "推奨回数だけ繰り返します。"]'::jsonb, category = 'ストレッチ', equipment = '自重' WHERE id = 'Wrist_Circles';
UPDATE exercises SET name = 'リストローラー', instructions = '["まず、まっすぐに立って、回内グリップ (手のひらを下に向けて) を使用してリスト ローラーをつかみます。足は肩幅に開く必要があります。", "両腕が完全に伸びて、前の床と平行になるまでゆっくりと持ち上げます。注: ロープがローラーに巻きつかないように注意してください。前腕を除いて体全体が静止している必要があります。これが開始位置です。", "手首を片方ずつ上向きに回転させ、ローラーの周りにロープを転がして重りをバーまで持ち上げます。", "ウェイトがバーに到達したら、ウェイトが開始位置に到達するまで、手首を下向きに回転させてゆっくりとウェイトを下げ始めます。", "プログラム内で規定の回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'その他' WHERE id = 'Wrist_Roller';
UPDATE exercises SET name = 'ストレートバーを使用した手首の回転', instructions = '["両手でバーベルを持ち、手のひらを下に向けます。両手は肩幅くらいに開きます。これが開始位置になります。", "新聞紙を丸めるように手首を伸ばして両手を交互に動かします。失敗するまで交互に繰り返し続けます。", "手首を曲げて反対方向に回転させることで、動きを逆にします。失敗するまで交互の動きを続けます。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Wrist_Rotations_with_Straight_Bar';
UPDATE exercises SET name = 'ヨークウォーク', instructions = '["ヨークは通常ヨーク​​装置を使用して行われますが、冷蔵庫やその他の重量物で見られることもあります。", "まず、装置を肩の後ろに掛けます。頭を前に向け、背中をアーチ状にして、かかとを通ってヨークを持ち上げます。", "できるだけ早く、短く素早い歩幅で歩き始めます。ヨークのサイドポストを持って、ヨークを安定させ、所定の位置に保持することができます。指定された距離をできるだけ速く走り続けます (通常は 75 ～ 100 フィート)。"]'::jsonb, category = 'ストロングマン', equipment = 'その他' WHERE id = 'Yoke_Walk';
UPDATE exercises SET name = 'ザーチャースクワット', instructions = '["このエクササイズは、安全のためにスクワット ラック内で行うのが最適です。まず、自分の身長に最も適したラックにバーを設置します。正しい身長は、腰より上、胸より下のどこかである必要があります。適切な高さを選択し、バーに負荷をかけたら、両手をロックし、前腕と上腕の間の腕の上にバーを置きます。", "バーを持ち上げて前腕の上に置きます。バーを正しく持っている場合は、腕を組んでバーが腕を横切っているように見えるはずです。", "ラックから離れ、肩幅の中程度のスタンスで脚を置き、つま先をわずかに尖らせます。下を向くとバランスが崩れてしまうので、常に頭を上げて、背中をまっすぐに保ってください。これが開始位置になります。 (注: この説明では、全体的な開発を目的とした上記の中間スタンスを使用します。ただし、足のスタンスのセクションで説明した 3 つのスタンスのいずれかを選択することもできます)。", "頭を上げてまっすぐな姿勢を維持しながら、膝を曲げてバーを下げ始めます。脚の上部とふくらはぎの間の角度が 90 度よりわずかに小さくなるまで下げ続けます (脚の上部が床と平行になる点です)。動きのこの部分を実行するときに息を吸います。ヒント: このエクササイズを正しく実行すると、膝の前部がつま先と前部に対して垂直になる想像上の直線を描くはずです。膝が想像上の線を超えている場合 (つま先を超えている場合)、膝に過度のストレスがかかっており、エクササイズは間違って行われています。", "息を吐きながら、主に足の指の付け根で床を押しながらバーを上げ始め、再び脚を伸ばして開始位置に戻ります。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'バーベル' WHERE id = 'Zercher_Squats';
UPDATE exercises SET name = 'ゾットマンカール', instructions = '["胴体を直立させ、両手にダンベルを腕の長さで持ちながら立ちます。肘は胴体の近くにある必要があります。", "手のひらが向かい合うようにしてください。これが開始位置になります。", "上腕を固定したまま、息を吐きながら上腕二頭筋を収縮させながらウェイトをカールさせます。前腕だけを動かす必要があります。手首を回転させて、グリップを回外（手のひらを上）にした状態にする必要があります。上腕二頭筋が完全に収縮し、ダンベルが肩の高さになるまで動きを続けます。", "上腕二頭筋を締めながら、収縮した位置を 1 秒間保持します。", "次に、収縮した位置で、親指が小指より高い位置にある回内（手のひらが下を向く）グリップになるまで手首を回転させます。", "回内グリップを使用してゆっくりとダンベルを下ろし始めます。", "ダンベルが太ももを閉じるときに、手首を回転させ始めて、ニュートラルなグリップ (手のひらを体に向ける) に戻します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Zottman_Curl';
UPDATE exercises SET name = 'ゾットマン プリーチャー カール', instructions = '["両手にダンベルを持ち、上腕をプリーチャーベンチまたはインクラインベンチの上に置きます。ダンベルは肩の高さで持ち、肘を曲げます。手のひらを下に向けてダンベルを持ちます。これが開始位置になります。", "息を吸いながら、上腕が伸びて上腕二頭筋が完全に伸びるまで、手のひらを下に保ちながらダンベルをゆっくりと下げます。", "動きの一番下に来たら、手のひらが上を向くように手首を回転させます。", "息を吐きながら、上腕二頭筋を使ってウェイトを完全に収縮させ、ダンベルが肩の高さになるまで巻き上げます。繰り返しますが、完全に収縮させるには、小指を親指よりも高くする必要があることを覚えておいてください。", "収縮した位置で上腕二頭筋を 1 秒間強く絞り、手のひらが再び下を向くように手首を回転します。", "推奨回数だけ繰り返します。"]'::jsonb, category = '筋力トレーニング', equipment = 'ダンベル' WHERE id = 'Zottman_Preacher_Curl';
